INSERT INTO m260_art VALUES
(0,0,$m260$الديباجة$m260$,$m260$اللائحة التنفيذية لقانون تنظيم التعاقدات التى تبرمها الجهات العامة الصادر بالقانون رقم 182 لسنة 2018$m260$,'fb4d9583b60c36e00b170dbd6da73c53'),
(1,0,$m260$المادة 1$m260$,$m260$يكون للتعاريف الواردة بقانون تنظيم التعاقدات التى تبرمها الجهات العامة المعنى ذاته فى تطبيق أحكام هذه اللائحة.
ويقصد فى تطبيق أحكام هذه اللائحة بالكلمات والعبارات التالية المعنى المبين قرين كل منها:
القانون: قانون تنظيم التعاقدات التى تبرمها الجهات العامة الصادر بالقانون رقم 182 لسنة 2018.
الوظائف القيادية: وظائف المستويات الثلاثة التالية للسلطة المختصة والتى يرأس شاغلوها وحدات تقسيمات تنظيمية بالجهة الإدارية من مستوى إدارة عامة أو إدارة مركزية أو قطاعات وذلك بالجهات المخاطبة بقانون الخدمة المدنية الصادر بالقانون رقم (81) لسنة 2016، أو ما يعادل تلك الوظائف بالجهات الأخرى غير المخاطبة بالقانون المشار إليه.
إدارة التعاقدات: التقسيم الإدارى المنشأ بموجب حكم المادة (3) من القانون أيا كان مستواه الوظيفى بالهيكل التنظيمى للجهة الإدارية الذى يتبعها.
الادارة الطالبة/المستفيدة: الإدارة المسئولة عن تحديد المتطلبات المرتبطة بمحل التعاقد طبقا لمهامها أو احتياجاتها.
مجتمع الأعمال: المتعاملون مع الجهات الإدارية من الموردين والمقاولين ومقدمى الخدمات والاستشاريين والمتزايدين وغيرهم.
مستندات الطرح: ما تعده الجهة الإدارية من كراسة الشروط والمواصفات، طلب المعلومات، طلب ابداء الاهتمام، طلب التأهيل المسبق وغير ذلك.
الاعتماد المالى: المبلغ المخصص للجهة الإدارية من وزارة المالية والمدرج بموازنتها لتوفير احتياجاتها.
صاحب العطاء: كل شخص طبيعي أو معنوي يقدم عرضا بغرض التعاقد مع الجهة الإدارية وفقا لأحكام القانون وهذه اللائحة.
مقدم العطاء: صاحب العطاء أو من يفوضه فى تقديم عطائه للجهة الإدارية.
العطاء الفائز: العطاء الأفضل شروطا والأقل سعرا أو الذى يتم ترجيحه وفقا لنظام النقاط والذى تم اخطاره بترسية العملية عليه.
العملية: ما طرحته الجهة الإدارية بإحدى طرق التعاقد المنصوص عليها بالقانون.
طريق التعاقد: المناقصة أو الممارسة أو المزايدة بأنواعهم المختلفة أو الاتفاق المباشر.
لجنة البت: اللجنة المسئولة عن فحص وتفريغ ومراجعة ودراسة العروض الفنية والمالية المقدمة فى العمليات المطروحة والتحقق من مطابقتها لشروط الطرح والتوصية بالبت فيها بالإرساء أو الاستبعاد أو الإلغاء.
تكلفة دورة الحياة: معيار تقييم لقياس تكلفة محل العقد، بما فى ذلك تكلفة التعاقد وتكاليف الإنشاء أو التركيب أو التشغيل أو الصيانة طوال العمر الافتراضي له، وقيمته البيعيه بعد استهلاكه.
التعاقد المستدام: توفير احتياجات الجهة الإدارية بطريقة تحقق القيمة الأفضل للمال العام على مدار دورة حياة محل العقد مع مراعاة سياسات الدولة الاقتصادية والاجتماعية والبيئية.$m260$,'2ac1d0200d0578e7ad673a115710442a'),
(2,0,$m260$المادة 2$m260$,$m260$تتولى الهيئة العامة للخدمات الحكومية أداء المهام والاختصاصات الآتية:
1- الإعداد والاشراف على بوابة التعاقدات العامة وتحديثها.
2- اعداد مقترحات لتطوير السياسات والتشريعات الخاصة بالتعاقدات وعرضها على وزير المالية.
3- إصدار التوجيهات والإرشادات والتعليمات ذات الصلة بالتعاقدات العامة وفقا لأحكام القانون وهذه اللائحة وتعميمها على كافة الجهات الإدارية للعمل بمقتضاها.
4- القيام بمراجعة إجراءات التعاقد بالجهات الادارية للتأكد من سلامتها وفقا لأحكام القانون وهذه اللائحة، من خلال زيارات ميدانية وفقا لخطة عمل سنوية أو كلما استدعى الأمر ذلك، على أن يتم إعداد تقارير بنتائج المراجعة فور إتمامها وإخطار السلطة المختصة بالجهات الإدارية بها؛ لاتخاذ الإجراءات اللازمة بشأنها ومتابعة تنفيذها إذ تطلب الأمر ذلك، علي أن ترفع الهيئة تقريرا ربع سنوي بشأن ما تسفر عنه تلك المراجعات لوزير المالية.
5- جمع البيانات المتعلقة بالتعاقدات التى تقوم بها الجهات العامة بشكل منتظم وتحليلها واستخراج التقارير والمعلومات الخاصة بها ونشر نتائجها على بوابة التعاقدات العامة.
6- وضع البرامج التدريبية ومناهجها لمقدمى خدمات التدريب والمراكز التدريبية، اللازمة لشغل وظائف التعاقدات بالجهات الإدارية أو الاستمرار فيها، والتنسيق بشكل مستمر معهما قبل بداية كل سنة مالية بشأن الخطة السنوية التدريبية وكافة الترتيبات التنظيمية ذات الصلة، على أن يعتمدها وزير المالية وترفع الهيئة تقريرا ربع سنوي بأداء الخطة التدريبية لوزير المالية.
7- نشر كل ما تخطر به مما يدخل ضمن التصنيف الصادر عن الاتحاد المصرى لمقاولى التشييد والبناء، والمعتمد من وزير الإسكان والمرافق والمجتمعات العمرانية وذلك على بوابة التعاقدات العامة.
8- نشر القانون وهذه اللائحة وأى تعديلات تطرأ عليهما، وكذلك المنشورات العامة والكتب الدورية والقرارات، وغيرها المتعلقة بتطبيقهم فور صدورها، وذلك على بوابة التعاقدات العامة.
9- إعداد نماذج خطة الاحتياجات السنوية للجهات الخاضعة لأحكام القانون والتنسيق مع قطاع الموازنة العامة للدولة بوزارة المالية بشأنها.
10- إصدار نماذج كراسات الشروط والمواصفات، وأنماط العقود النموذجية والأدلة الإرشادية، وغيرها التى تعدها الوزارات والجهات المعنية وفقا لاختصاصاتها وطبيعة عملها، على أن تقوم بتحديثها بشكل دوري ونشرها على بوابة التعاقدات العامة.
11- إعداد نماذج محاضر فتح المظاريف والبت والممارسة والمزايدة وأوامر التوريد وأوامر الإسناد وغير ذلك من النماذج المنصوص عليها بهذه اللائحة أو التى تتخذها الجهات ذات الصلة.
12- إعداد نماذج وتحديد معايير تقييم أداء المتعاقدين مع الجهات الإدارية، ونماذج استقصاء المتعاقدين مع الجهات الإدارية بالتنسيق مع الوزارات والجهات المعنية وفقا لاختصاصاتها وطبيعة عملها واتاحتهما على بوابة التعاقدات العامة، وكذا تحليل نتائج التقييم والاستقصاء واتخاذ ما يلزم بشأنهما ونشرهما على بوابة التعاقدات العامة.
13- إعداد نماذج حصر للعقارات المملوكة للجهات الادارية وإدخال ما يرد لها من بيانات بقاعدة البيانات المركزية المنشأة لديها وتحديثها بصفة دورية.
14- إمساك سجل مركزي للمتعاملين مع الجهات الإدارية أو الممنوعين من التعامل معها وتسجيل بيانات من يتم إخطارها بشطبهم أو إعادة قيدهم وفقا للإجراءات الواردة بهذه اللائحة ونشر قرار الشطب أو إعادة القيد بإصدار كتاب دوري يعمم بطريق النشرات المصلحية وينشر على بوابة التعاقدات العامة.
15- التنسيق مع الجهات التى تسرى عليها أحكام القانون وهذه اللائحة بشأن إجراءات التصرف فى العقارات لتحقيق اعتبارات المصلحة العامة وبين مهام اللجنة العليا للتقييم بها.
ويتعين على الهيئة أن تؤدي مهامها واختصاصاتها باستقلالية وشفافية وحيادية كاملة، ويتعين على كافة العاملين بها تجنب تضارب المصالح بكافة أشكاله، ويحظر عليهم الدخول في المناقصات والممارسات والمزايدات بأنواعها، سواء بالذات أو بالواسطة مع أي من الجهات الادارية إلا إذا كانت الأصناف المشتراة لاستعمالهم الخاص، وكانت مطروحة للبيع عن طريق جهات عامة أخرى.$m260$,'2eb5e0ca7cf9f98f97034fb781410f89'),
(3,0,$m260$المادة 3$m260$,$m260$على السلطة المختصة مراجعة الهياكل التنظيمية بالجهات العامة للتأكد من وجود إدارة للتعاقدات بكل منها يتناسب تشكيلها الوظيفى مع أداء مهامها الواردة بالقانون وهذه اللائحة، وفى حال عدم وجودها بالهيكل التنظيمى، تتخذ الإجراءات اللازمة لإنشائها، وفى جميع الأحوال يجب الفصل بين اختصاصاتها واختصاصات أية إدارات أخرى.
ويتعين لشغل وظائف إدارة التعاقدات أو الاستمرار في شغلها اجتياز التدريب والحصول على الشهادات اللازمة، ويتعين على العاملين بها أن يؤدوا مهامهم بفعالية وكفاءة، ويراعى التأكد من تمتعهم بصفات النزاهة والأمانة وحسن السمعة.
وبمراعاة المهام الواردة بالقانون وهذه اللائحة تتولى إدارة التعاقدات القيام بالآتي:
1- التنسيق والتكامل مع كافة الإدارات بالجهة الإدارية في كل ما يتعلق بالتعاقدات، والتواصل مع الجهات الإدارية الأخرى ذات الصلة بإجراءات التعاقد.
2- التواصل مع المتعاملين والمتعاقدين مع الجهة الإدارية.
3- توثيق كافة المكاتبات، وإمساك السجلات ذات الصلة، وحفظ المستندات.
4- تسجيل المتعاملين وتحديث بياناتهم، وتوثيقها أولا بأول.
5- إعداد دراسات الجدوى الاقتصادية تمهيدا للطرح إذا تطلبت طبيعة العملية ذلك.
6- التعامل مع بوابة التعاقدات العامة.
7- تخطيط التعاقدات، بما في ذلك إعداد خطة الاحتياجات السنوية للجهة، وخطط التعاقدات وعمليات التعاقد.
8- الإعلان أو الدعوة عن العمليات المزمع طرحها.
9- التأكد من توافر الاعتمادات المالية المطلوبة للعمليات محل الطرح.
10- إعداد وإتاحة مستندات الطرح وغيرها المنصوص عليها بالقانون وهذه اللائحة.
11- إعداد قوائم مختصرة وقوائم المؤهلين مسبقا في الحالات التى تتطلب ذلك.
12- استلام العطاءات وغيرها، وحفظها والحفاظ عليها.
13- اقتراح تشكيل اللجان المنصوص عليها بالقانون وهذه اللائحة واعتمادها من السلطة المختصة، والتنسيق مع رؤسائها لمعاونتهم فى أداء مهام لجانهم.
14- عرض أسلوب تقييم العطاءات لاعتماده من السلطة المختصة.
15- إعداد الإخطارات وغيرها المنصوص عليها بالقانون وهذه اللائحة.
16- إعداد العقود، ومتابعة تنفيذها مع الإدارة الطالبة أو المستفيدة.
17- تقييم أداء المتعاقدين في تنفيذ تعاقداتهم أولا بأول.
18- اتاحة نماذج الاستقصاء للمتعاقدين مع الجهة الإدارية.
19- إعداد التقارير المنصوص عليها بالقانون وهذه اللائحة، وغيرها ذات الصلة التى تطلبها السلطة المختصة.
20- التعامل مع الشكاوي بالرد عليها، وتقديم المعلومات، واتخاذ الاجراءات اللازمة بشأنها.
21- تحديد احتياجات التدريب للعاملين بالإدارة والتنسيق بشأنها مع الهيئة العامة للخدمات الحكومية أو من تحددهم.$m260$,'1f23ec348ac8541de4b38d7a025a251a'),
(4,0,$m260$المادة 4$m260$,$m260$تخضع إجراءات وطرق وأساليب التعاقد لمبادئ الشفافية، وحرية المنافسة، والمساواة، وتكافؤ الفرص.
ويلتزم العاملون بالجهات الإدارية بإنفاذ ما ورد بأحكام القانون وهذه اللائحة من معايير ومبادئ الشفافية، ويحظر تعارض المصالح فيما يؤدونه من إجراءات التعاقد، وعليهم مراعاة مدونة السلوك الوظيفى التى تصدر عن وزير المالية.
ويجب على كافة المتعاملين من مجتمع الأعمال مراعاة ممارسات الأعمال الجيدة والمعايير المتعارف عليها فى مجالات التعاقدات، وذلك فى كافة تعاملاتهم أثناء مراحل إجراءات التعاقد بما في ذلك دراسة وإعداد وتقديم العطاءات وتنفيذ العقود، ويسأل قانونيا كل من يخالف القوانين واللوائح النافذة ذات الصلة.$m260$,'129d2ef5b9a6b15f8b9bab3fc1ad6842'),
(5,0,$m260$المادة 5$m260$,$m260$تلتزم إدارة التعاقدات بدراسة الشكاوى المقدمة لها، ويجوز لها الاستعانة بمن تراه من المختصين بحسب طبيعة الشكوى المقدمة، وترفع تقريرا مفصلا للسلطة المختصة بنتيجة ما انتهت إليه دراستها من قرارات لاعتمادها وذلك كله خلال مدة لا تجاوز خمسة أيام من تاريخ استلام الشكوى المستوفاة.
وفى حال صحة الشكوى يجب أن يتضمن القرار المعتمد من السلطة المختصة التدابير الواجب تنفيذها لإزالة اسبابها واتخاذ أى إجراءات يوصى بها.
وفور اعتماد السلطة المختصة لقرارات نتيجة دراسة الشكوى تلتزم إدارة التعاقدات بإخطار مقدم الشكوى بها، كما يخطر مكتب شكاوى التعاقدات العمومية بتلك القرارات، بالإضافة إلى نشرها على بوابة التعاقدات العامة.$m260$,'feaa0f98eb1f74a9f7e8f9f829d0ecf1'),
(6,0,$m260$المادة 6$m260$,$m260$اللغة العربية هي اللغة المعتمدة فى كراسة الشروط والمواصفات والعقود وجميع المحاضر والمراسلات وغيرها من المستندات ذات الصلة بموضوع الطرح والتعاقد.
وفى العمليات التى يتعذر فيها وضع المواصفات الفنية باللغة العربية بمستندات الطرح يجوز أن تكون المواصفات الفنية بلغة أخرى، بناء على رأى اللجنة الفنية المختصة بوضعها فى تقريرها متضمنا الأسباب التى أدت إلى ذلك، وأن تقدم المواصفات الفنية بالعطاءات بذات اللغة الأخرى.
وفى حالة طرح عمليات بالخارج تكون مستندات الطرح بلغة أخرى أو أكثر مع ترجمتها إلى العربية مع ذكر أن النص العربى هو المعول عليه فى حالة الخلاف أو الالتباس فى مضمونها.$m260$,'bf66569bee443cfb612345d9c73961c0'),
(7,0,$m260$المادة 7$m260$,$m260$يجب أن تكون كافة المخاطبات والمراسلات المتبادلة من وإلى الجهات الإدارية والمتعاملين والمتعاقدين معها بما فى ذلك الإخطارات والقرارات، ومحاضر الجلسات، وغيرها كتابة وبشكل يمكن الرجوع إليه لاحقا، على أن تكون صادرة من الأشخاص المخول لهم ذلك من الطرفين، ويجب الاحتفاظ بما يثبت تسلمها، ويكون تبادلها بالوسائل الواردة بالقانون وهذه اللائحة والمنصوص عليها مسبقا بمستندات الطرح.
ويتعين على الجهة الإدارية عند التواصل مع المتعاملين أو المتعاقدين معها تضمين الطلبات ومستندات الطرح وغيرها البيانات الآتية:
1- شكل المخاطبات والمراسلات.
2- الوسائل المستخدمة في إيصال المعلومات.
3- الوسائل التي يمكن استخدامها لعقد الجلسات.
4- طريقة حصول المتعاملين من مجتمع الأعمال على المعلومات اللازمة عن اجراءات تقديم العطاءات الكترونيا، بما في ذلك أية تدابير تتعلق بتكنولوجيا المعلومات.
وبمراعاة البنود المنصوص عليها فى الفقرة الثانية من هذه المادة يتعين على إدارة التعاقدات عدم التمييز بين المتعاملين والمتعاقدين مع الجهة الإدارية فى اختيار وسيلة وأسلوب التواصل وإيصال المعلومات ومحتواه، وتلتزم بنشر بيانات الاتصال بها على بوابة التعاقدات العامة من عنوان، وتليفون، ورقم فاكس، وبريد الكرتوني واسم المخول له التواصل مع المتعاملين والمتعاقدين، وفى حالة تعديل تلك البيانات يجب إعادة نشرها بذات الوسيلة لإعلامهم بها، كما يلتزم المتعاملون والمتعاقدون مع الجهة العامة بإخطار إدارة التعاقدات بأى تعديل يطرأ على بياناتهم المسجلة لديها فور التعديل.
وأنه حال ميكنة أى من الإجراءات المتبعة فى القانون وهذه اللائحة يتم استبدالها بالإجراءات التى جرى ميكنتها.$m260$,'5d7420a102eb26a07bdbbfcb4f8a26bb'),
(8,0,$m260$المادة 8$m260$,$m260$يجب على الجهة الإدارية عند تطبيق أحكام القانون وهذه اللائحة اتخاذ ما يلزم من تدابير لضمان تحقيق معايير ومبادئ تكافؤ الفرص وتعزيز الشفافية والنزاهة والعدالة والمساواة فى المنافسة، ويتعين بصفة خاصة الالتزام بالآتي:
1- إتاحة الفرصة لكافة الراغبين من المتعاملين المستوفين للشروط الواردة بالقانون وهذه اللائحة للمشاركة في المناقصات والممارسات، والمزايدات بأنواعها والاتفاق المباشر، وطلب المعلومات، وإبداء الاهتمام، والتأهيل المسبق، والمسابقة، وأن تستند الإجراءات على مبادئ العلانية والمساواة وتكافؤ الفرص؛ إعمالا لحكم المادة (85) من القانون.
2- المساواة بين المتقدمين فى المعاملة وعدم التحيز لأى منهم أو التمييز بينهم، وافساح المجال للمنافسة بين من تتوافر فيهم الشروط المطلوبة للتقدم وفقا للاشتراطات التي تحدد مسبقا بمستندات الطرح.
3- إعداد كراسة للشروط والمواصفات تتضمن الإحالة لجميع القواعد والأحكام والإجراءات والشروط المنصوص عليها بالقانون وهذه اللائحة، وكذلك الحال عند التعاقد بطريق الاتفاق المباشر إذا تطلبت طبيعة العملية وذلك قبل الإعلان أو الدعوة للاشتراك فى جميع طرق التعاقد الواردة بالقانون.
4- النشر عن العمليات التى يتم طرحها بجميع طرق التعاقد المنصوص عليها بالمادة (7) من القانون على بوابة التعاقدات العامة، عدا العمليات التى تتطلب اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة، على أن يتضمن النشر طريق التعاقد وشروطه والأسباب المبررة لاتباع هذا الطريق، وأسلوب التقييم الفنى والمالى، وغيرها من البيانات التى يحددها القانون وهذه اللائحة.
5- عند إدخال تعديلات على كراسة الشروط والمواصفات إذا اقتضت المصلحة العامة ذلك أو بناء على جلسة الاستفسارات، إخطار من قاموا بشرائها ومقدمى الاستفسارات بتلك التعديلات دون الإفصاح عن مقدميها، بالإضافة إلى نشرها على بوابة التعاقدات العامة.
6- تحديد أسباب القرارات الصادرة بشأن أي من إجراءات التعاقد ونشرها على موقع بوابة التعاقدات العامة.$m260$,'24c2a2be37f785785c1e3b9e9b1fd0b7'),
(9,0,$m260$المادة 9$m260$,$m260$يجب على الجهة الادارية عند التخطيط للتعاقدات والاعداد لها أن تأخذ في الاعتبار المبادئ والأسس الآتية:
1- بدء التخطيط للتعاقدات منذ نشأة الحاجة لمحل التعاقد.
2- تحديد طريق وأسلوب التعاقد، والمؤهلات والاشتراطات المطلوبة فى المتعاقد، ومعايير دراسة السوق وإعداد القيمة التقديرية.
3- وضع برنامج زمنى متوقع لإجراءات العملية محل الطرح، على أن يتضمن توقيتات واقعية وغير مبالغ فيها أخذا فى الاعتبار وضع حد زمني أدنى وأقصى لكل خطوة من خطواته بما فى ذلك الاستفسارات، وتعديل مستندات العملية، إذا لزم الأمر، وتبادل المخاطبات والمراسلات ذات الصلة وبما يتماشى مع أحكام القانون وهذه اللائحة.
4- تعظيم العائد الاقتصادي والكفاءة إلى أقصى حد ممكن من خلال تحليل الاحتياجات بدقة، أو توقيتات التعاقد عليها، أو المفاضلة بين الاساليب المختلفة لتوفيرها، أو تجميع الاحتياجات فى مجموعات متجانسة، وغيرها من الاجراءات ذات الصلة.
5- تحديد مدة التوريد أو التنفيذ والتي يتم تضمينها مسبقا بشروط العملية لتكون ملبية لاحتياجاتها وبناء على محددات واضحة، وأن تكون واقعية تسمح للمتعاقد التنفيذ الجيد لبنود العقد، وأن تأخذ فى الاعتبار الظروف السائدة في موقع التنفيذ.$m260$,'de54d34043431c000f16292668770d3d'),
(10,0,$m260$المادة 10$m260$,$m260$على إدارة التعاقدات لترجيح الاختيار بين الشراء أو الاستئجار أن تستند فى توصياتها على دراسة تحليلية تتضمن العوامل المؤثرة فيها، بما في ذلك طبيعة محل التعاقد والغرض منه والجدوى الاقتصادية ومدة ومعدلات استخدامه واستهلاكه وتكلفة تشغيله وغيرها، والمقارنة بين التكاليف الكلية للعقد حال الشراء أو الاستئجار والعرض على السلطة المختصة بهذه الدراسة لتقرير ما تراه بشأنها.$m260$,'335f8b2da1bac80ee7aab40c30c4d6f0'),
(11,0,$m260$المادة 11$m260$,$m260$يتعين على الجهة الإدارية مراعاة سياسات الدولة الاقتصادية والاجتماعية والبيئية المعلنة من مجلس الوزراء بدءا من مرحلة تحديد الاحتياجات، مرورا بإعداد المواصفات الفنية ودراسة السوق والقيمة التقديرية، ومستندات الطرح ومعايير التأهيل والتقييم ومتابعة تنفيذ العقود بغرض تحقيق التنمية المستدامة الاقتصادية والاجتماعية والبيئية.$m260$,'44cb58358216d1149ae7430b879500d2'),
(12,0,$m260$المادة 12$m260$,$m260$يجب على إدارة التعاقدات مخاطبة كافة القطاعات والإدارات والوحدات وغيرها التابعة للجهة الإدارية لحصر احتياجاتها المطلوبة للسنة المالية التالية وفقا للنماذج التى تعدها الهيئة العامة للخدمات الحكومية لهذا الغرض، ويجب التأكد من أن الاحتياجات المطلوبة فعلية وضرورية لسير العمل أو الإنتاج بناء على دراسات واقعية وموضوعية، وذلك كله بعد اتخاذ واستيفاء ما يلزم من دراسات السوق وطلب المعلومات لتحديد احتياجاتها بكل دقة من حيث الكميات والمواصفات والاعتمادات المالية المطلوبة لها دون تزايد أو مبالغة، وبعد مراجعة مستويات التخزين ومعدلات الاستهلاك ومقررات الصرف والقيام بتجميع الاحتياجات وتقسيمها إلى مجموعات متجانسة، ويحظر تضمين خطة الاحتياجات أصناف يوجد بالمخازن أنواع مماثلة لها أو بديلة عنها تفي بالغرض.
ويكون تقدير قيمة الاحتياجات المدرجة بالخطة وفقا للأسس المنصوص عليها بالمواد (26)، (27)، (152) من هذه اللائحة وبما يتماشى مع طبيعة العملية.
ويجب على إدارة التعاقدات الانتهاء من اعداد خطة احتياجات الجهة العامة قبل تقديم مشروع موازنتها لوزارة المالية بوقت كاف، وعرضها على السلطة المختصة لاعتمادها، ويتم نشرها على بوابة التعاقدات العامة، وتخطر وزارة المالية بخطة الاحتياجات المعتمدة لمناقشتها وإدراجها ضمن موازنة الجهة الإدارية وذلك فى الموعد المحدد لتقديم مشروع الموازنة.
وعلى إدارة التعاقدات تعديل خطة احتياجاتها فى ضوء ما يتم تخصيصه وإقراره لها من اعتمادات مالية، وإعادة عرضها على السلطة المختصة لاعتمادها في شكلها النهائي ونشرها على بوابة التعاقدات العامة فور بداية السنة المالية، وتخطر الهيئة العامة للخدمات الحكومية بهذه الخطة لإعمال شئونها.
ويستثنى من النشر على بوابة التعاقدات العامة الحالات التى تقتضى اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة.
وعلى الجهة الإدارية مراعاة عدم تجاوز الاعتمادات المخصصة لها لتدبير احتياجاتها وفقا لخطتها، والالتزام بالفترات الزمنية المحددة للطرح وطرق التعاقد الواردة بها.$m260$,'219b422fa2ba03fe7c5651845b852314'),
(13,0,$m260$المادة 13$m260$,$m260$يتعين عند التخطيط والإعداد لأي عملية الاخذ في الاعتبار العوامل والخطوات الآتية:
1- التحقق من الحاجة إلى محل التعاقد وبالتنسيق مع القطاعات والادارات والوحدات وغيرها داخل الجهة وتحديد متطلباتها بشكل واضح، ويشمل ذلك التحقق من توافر محل التعاقد بمخازن الجهة أو الجهات التابعة لها، أو توفيرها بموجب أية اتفاقية إطارية ذات صلة متى كانت شروطها تسمح بذلك.
2- إجراء دراسات السوق لتحديد مختلف الحلول الفنية وحجم المسجلين المتخصصين أو المؤهلين المشتغلين بالنشاط موضوع التعاقد وتحديد أفضل الشروط التعاقدية المواكبة لآليات السوق والمناسبة للجهة، ويشمل ذلك أيضا الرجوع إلى العمليات السابقة سواء بالجهة ذاتها أو غيرها من الجهات للاسترشاد.
3- التأكد من وجود تقديرات مالية محدثة ودقيقة لمحل التعاقد، وتوافر التمويل المطلوب لها بموازنة الجهة.
مراعاة سياسات الدولة الاقتصادية والاجتماعية والبيئية المعلنة من مجلس الوزراء، واعتبارات الجودة والتكلفة، وتحقيق أفضل قيمة للمال العام على أساس كامل دورة الحياة لموضوع التعاقد، وتضمين متطلبات التعاقد المستدام، شروط ومعايير التأهيل والتقييم الفنى والمالى ومؤشرات الأداء وغيرها.
ويقصد بتحقيق أفضل قيمة للمال العام تحقيق أكبر قدر من المنفعة للجهة الإدارية مقابل المال المدفوع لمحل التعاقد، من خلال إدارة عملية التعاقد بكفاءة وفعالية.
4- النظر في تقسيم الاحتياجات إلى مجموعات متجانسة فى العملية الواحدة، إن أمكن، لتعظيم المنافسة وتوسيع المشاركة، وبصفة خاصة مشاركة المشروعات المتوسطة والصغيرة والمتناهية الصغر.
5- اختيار الطريق الامثل للتعاقد وفقا لأحكام القانون وهذه اللائحة.
6- تحديد معايير تقييم العطاءات من الناحية الفنية والمالية، وغيرها بهدف تعظيم القيمة مقابل المال.
7- تحديد المهام غير النمطية المطلوبة من إدارة التعاقدات لموضوع التعاقد.
8- تحديد خطوات التعاقد وتحديثها إن تطلب الأمر ذلك، ويجب أن تتضمن كحد أدنى ما يلي:
أ- وصفا واضحا لمحل التعاقد.
ب- اختيار نموذج كراسة الشروط والمواصفات، ونمط العقد النموذجي المراجع من إدارة الفتوى المختصة بمجلس الدولة وإضافة أى اشتراطات أخرى يرى تضمينها بهما، وبما يتناسب مع طبيعة العملية محل الطرح.
ج- إعداد الجدول الزمني المتوقع لإجراءات العملية.$m260$,'22895db9acfbe944a272ff2ae76dd03b'),
(14,0,$m260$المادة 14$m260$,$m260$يحظر على الجهات الخاضعة لأحكام القانون وهذه اللائحة النشر على بوابة التعاقدات العامة والإعلان أو توجيه الدعوات، بحسب الأحوال، لأى عملية للتعاقد على شراء أو استئجار المنقولات أو العقارات أو التعاقد على مقاولات الأعمال أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية ما لم يكن لها اعتماد مالي.
ويجوز للجهة الإدارية في الحالات الطارئة أو العاجلة أو التكليفات التى تقتضيها المصلحة العامة أن تجري التعاقدات ذات الصلة بالتنسيق أولا مع وزارة المالية أو التخطيط، بحسب الأحوال، والتأكد من توافر التمويل اللازم.
ويجوز إبرام عقود التوريدات والخدمات الدورية لمدة تجاوز السنة المالية بشرط ألا يترتب عليها زيادة الالتزامات فى إحدى السنوات المالية التالية عما هو مقرر فى سنة التعاقد.
ويكون التعاقد بالنسبة للمشروعات الاستثمارية المدرجة بالخطة فى حدود التكاليف الكلية المعتمدة، على أن يتم الصرف فى حدود الاعتمادات المالية المقررة.
ويحظر اتخاذ أى من إجراءات التعاقد في الشهر الأخير من السنة المالية بقصد استنفاد الاعتمادات المالية، إلا فى الحالات الاستثنائية التى تقتضيها ضرورة العمل، وبموافقة السلطة المختصة.$m260$,'57908d88fdae84f54f6d8f5880b55c60'),
(15,0,$m260$المادة 15$m260$,$m260$على الجهة الإدارية قبل طرح العملية للتعاقد الحصول على الموافقات والتصاريح والتراخيص اللازمة ذات الصلة بموضوع الطرح من الجهات المعنية وفقا للقوانين والقرارات التى تقضى بذلك.$m260$,'9a170b7ee08adb0ca181235fe4ea5da4'),
(16,0,$m260$المادة 16$m260$,$m260$يجوز لإدارة التعاقدات أن تصدر طلبا بدون مقابل للحصول على المعلومات أو المقترحات أو المواصفات المستجدة فى السوق، بما يمكنها من اتخاذ القرار المناسب لتحديد احتياجات الجهة الإدارية بدقة أو لإعداد خطة الاحتياجات السنوية، ولا يجوز أن يؤدى طلب المعلومات إلى الإخلال بمبادئ عدم التمييز أو الشفافية أو الحد من عدد المشاركين حال الطرح، وعلى الجهة العامة الحفاظ على سرية المعلومات المقدمة.
وتشكل بقرار من السلطة المختصة لجنة تضم الخبرات المطلوبة بحسب طبيعة محل طلب المعلومات، ويضم لها عضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع الطلب، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها.
ويتم النشر عن طلب المعلومات على بوابة التعاقدات العامة والإعلان عنه بإحدى الصحف اليومية واسعة الانتشار، أو توجيه الدعوة لأكبر عدد ممكن من المشتغلين بنوع النشاط المطلوب من المسجلين المتخصصين على بوابة التعاقدات العامة، بحسب الأحوال، ويكون إصدار طلب المعلومات وفقا للنموذج الذى تعده الهيئة العامة للخدمات الحكومية وأن تتخذ إدارة التعاقدات ما يلزم لتضمينه موضوع الطلب والشروط والقواعد اللازمة لتقديمه والبيانات الأساسية المطلوبة من المشتغلين بنوع النشاط محل طلب المعلومات، على أن يتضمن الطلب بصفة خاصة البيانات الآتية:
1- الغرض من طلب المعلومات.
2- المعلومات الفنية والمالية والادارية المطلوبة من مقدم المعلومات.
3- الموعد والمكان المحددين لتلقى الردود.
4- أية معلومات أو بيانات إضافية تري الجهة الإدارية أهمية الحصول عليها.
وتتولى إدارة التعاقدات استلام وحصر ما يرد لها من ردود؛ وتسليمها للجنة لدراستها، ويجوز للجنة استيضاح ما تراه مع من قام بالرد على طلب المعلومات؛ وذلك بغرض استكمال دراستها.
ويتعين على إدارة التعاقدات توثيق كافة ما تم اتخاذه من إجراءات، وإعمال شئونها في ضوء ما تعتمده السلطة المختصة من نتائج أعمال اللجنة.$m260$,'db54a5c26e1f22914bd170d8bcf6caa6'),
(17,0,$m260$المادة 17$m260$,$m260$لإدارة التعاقدات حال رغبتها فى معرفة المشاركين المحتملين أو المهتمين بالدخول فى عملية معينة تنوى طرحها بأى من طرق التعاقد أن تصدر طلبا بدون مقابل لإبداء الاهتمام قبل الشروع فى طرح العملية.
وتشكل بقرار من السلطة المختصة لجنة تضم عناصر فنية ومالية وقانونية ويضم لها عضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع الطلب، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها.
ويتم الإعلان عن طلب إبداء الاهتمام بإحدى الصحف اليومية واسعة الانتشار، وذلك بالإضافة للنشر عنه على بوابة التعاقدات العامة، ويكون اصدار طلب ابداء الاهتمام وفقا للنموذج الذى تعده الهيئة العامة للخدمات الحكومية على أن تتخذ إدارة التعاقدات ما يلزم لتضمينه الآتى:
1- الغرض من طلب ابداء الاهتمام.
2- الشروط والقواعد اللازمة لتقديم الطلب.
3- البيانات الأساسية المطلوبة من المشتغلين بالنشاط محل ابداء الاهتمام.
4- الإشارة إلى أن طلب ابداء الاهتمام لا يترتب عليه أى حقوق لمن قاموا بالرد.
5- أى بيانات تراها الجهة الإدارية لازمة.
وتتولى إدارة التعاقدات استلام وحصر ما يرد إليها من ردود، وتسليمها للجنة لفحصها ودراسة المستندات المرفقة بها وفقا للأسس والمعايير المحددة مسبقا لإبداء الاهتمام بما يتناسب مع طبيعة العملية، وترفع اللجنة تقريرا للسلطة المختصة بنتائج أعمالها مرفقا به بيان بالمشاركين المحتملين أو المهتمين، فإذا ما تقدم عدد كاف منهم فيتم الإعلان عن العملية حال طرحها، وفى غير ذلك فيتم اعداد قائمة مختصرة بالمشتغلين اللذين تتناسب قدراتهم وخبراتهم مع موضوع الطلب.
ويتعين على إدارة التعاقدات توثيق كافة ما تم اتخاذه من إجراءات، وإعمال شئونها في ضوء ما تعتمده السلطة المختصة من نتائج أعمال اللجنة، وإخطار المشاركين المحتملين أو المهتمين بالدخول فى العملية بنتيجة طلب ابداء الاهتمام بالإضافة إلى النشر عن ذلك على بوابة التعاقدات العامة.$m260$,'c3c7fe7bd0700b8162dd89be7c49361e'),
(18,0,$m260$المادة 18$m260$,$m260$تشكل بقرار من السلطة المختصة لجنة فنية متخصصة من العاملين بالجهة الإدارية من ذوى الخبرة الفنية ذات الصلة بموضوع التعاقد، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى أو من المكاتب الاستشارية، على ألا يقل عدد أعضاء اللجنة عن ثلاثة أعضاء ولا يجاوز سبعة وبما يتناسب مع طبيعة وحجم موضوع التعاقد – ما لم تري السلطة المختصة غير ذلك بناء على أسباب واضحة وموثقة، وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها.
وتتولى اللجنة وضع المواصفات الفنية وعليها فى أداء عملها مراعاة معايير التنمية المستدامة والجودة والخصائص الفنية والنوعية المطلوبة لموضوع التعاقد، بما فى ذلك الاختبارات وأسلوب تقييم العطاءات، وأى بيانات أخرى ترى اللجنة أنها لازمة لمحل التعاقد وبما يلبى احتياجات الجهة الإدارية بفعالية وكفاءة.
وتعد اللجنة تقريرا بنتائج أعمالها متضمنا الأسباب التى ارتأتها والمعايير التى استندت إليها فى عملها، ويتم التوقيع عليه من جميع أعضاءها، وتسلمه إلى إدارة التعاقدات لإعمال شئونها.
ويجوز لإدارة التعاقدات بعد موافقة السلطة المختصة طرح عملياتها ذات الطبيعة النمطية طبقا للمواصفات القياسية الموحدة.$m260$,'8562e6915dd18b48f4adf38473af0e63'),
(19,0,$m260$المادة 19$m260$,$m260$بمراعاة طبيعة الأصناف المطلوبة يجب أن تشتمل المواصفات الفنية على الخصائص الوظيفية أو الفنية أو الكيميائية أو معايير الأداء المطلوبة لها أو غيرها، ونوع ومدة الصيانة طوال فترة استهلاكها وخدمات ما بعد البيع والتدريب وما يلزم توفيره من ضمان وقطع غيار، وما يلزم تقديمه بالعرض الفنى من كتالوجات أو عينات وشهادات الجودة مع تحديد الاختبارات المطلوبة للفحص الفنى.
وفى الحالات التى يتم فيها الطرح على أساس عينات فيجب النص على وزنها أو مقاسها أو حجمها، وفى الأصناف التى يلزم توريدها داخل عبوات يجب بيان نوع هذه العبوات وسعتها ومواصفاتها.
ويتعين تجنب الإشارة إلى علامة تجارية معينة أو اسم تجارى أو براءة اختراع أو تصميم أو نوع أو منتج أو بلد معين أو الرقم الوارد فى قوائم الموردين أو مواصفات تنطبق على نماذج خاصة أو مميزة أو إدراج إشارة إلى أى منها، ويستثنى من ذلك الأصناف التى يتعذر توصيفها بإضافة عبارة ما يعادلها أو ما يماثلها أو ما يكافئها فى الأداء.
وفي العمليات التى تتطلب طبيعتها توريدا وتركيبا وتشغيلا وتدريبا فيجب تحديد وتوصيف كافة المهام ذات الصلة من النواحي الفنية وغيرها لكل جزء، وكذا في العمليات التى تتطلب طبيعتها التعاقد مع طرف آخر للقيام بإجراءات الفحص أو الاستلام لمحل التعاقد فيجب تضمين التفاصيل الفنية ذلك ضمن شروط الطرح.$m260$,'2b9871fe29824eb7fefc0c77635e3cdf'),
(20,0,$m260$المادة 20$m260$,$m260$يجب توصيف العقار المطلوب شراءه أو استئجاره توصيفا فنيا دقيقا، بما فى ذلك الموقع وحدود المساحة ومستوى التجهيزات والتشطيبات المطلوبة، وذلك كله بما يتناسب مع الغرض من الاستخدام.$m260$,'a475cc62e91c96993886354a52d4a4d5'),
(21,0,$m260$المادة 21$m260$,$m260$يكون التعاقد على مقاولات الأعمال بناء على رسومات أو مواصفات فنية دقيقة ومفصلة، ومن ذلك الرسومات المساحية والمعمارية والإنشائية والكهربائية والصحية والميكانيكية وغيرها بحسب طبيعة العملية، وجداول كميات الأعمال المطلوبة بشكل تفصيلي من واقع الرسومات ولجميع بنود المقايسة، وتحديد مدة التنفيذ أو البرنامج الزمنى اللازم للتنفيذ، والبنود المتغيرة أو مكوناتها إذا تطلبت طبيعة العملية ذلك وفقا للقائمة التى تصدرها وزارة الاسكان والمرافق والمجتمعات العمرانية، وبما يتناسب مع طبيعة موضوع التعاقد، ويجب تجنب وضع بنود بالمقطوعية قدر الإمكان.$m260$,'7f5a21d4d1e17c2889024bcba9f7f838'),
(22,0,$m260$المادة 22$m260$,$m260$يجب توصيف الخدمة أو العمل الفنى موضوع التعاقد توصيفا عاما، وأن يشمل المهام والتوقيتات المحددة لها ومعايير الأداء والجودة المطلوبة للتنفيذ، والظروف التى سيتم التنفيذ فيها، والاشتراطات المطلوبة فى طاقم التنفيذ أو التدريب أو الإشراف، وتحديد معايير الجودة التى يمكن على أساسها تقييم التنفيذ، وغيرها طبقا لطبيعة العملية.$m260$,'89f0d606a7abf1e625b1b95e77001054'),
(23,0,$m260$المادة 23$m260$,$m260$فى حالات البيع أو التأجير للمنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو بالاستغلال تشكل بقرار من السلطة المختصة لجان متخصصة لتصنيف وتلطيط وتوصيف موضوع التعاقد من ذوى الخبرة الفنية ذات الصلة بموضوع التعاقد، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى أو من المكاتب الاستشارية، على ألا يقل عدد أعضاء اللجنة عن ثلاثة أعضاء ولا يجاوز سبعة وبما يتناسب مع طبيعة وحجم موضوع التعاقد، ما لم تري السلطة المختصة غير ذلك بناء على أسباب واضحة وموثقة، وتحدد السلطة المختصة موعد انتهاء تلك اللجان من أعمالها.$m260$,'af97400aa134a632c41c15d9c1ec4f2f'),
(24,0,$m260$المادة 24$m260$,$m260$فى حالات بيع المنقولات يجب تقسيم الأصناف المعروضة للبيع إلى لوطات من أصناف متجانسة وإعطاء توصيف كاف ودقيق لمنع أى تغيير يمكن أن يحدث فى مكونات اللوطات، ويراعى فى تقسيم الأصناف إلى لوطات أن يكون حجم كل لوط مناسبا بحيث يسمح باشتراك أكبر عدد من المتزايدين بما يحول دون قيام احتكارات.$m260$,'56c20728e4a3bfea362bc780363e18ec'),
(25,0,$m260$المادة 25$m260$,$m260$فى حالة بيع أو تأجير العقارات أو الترخيص بالانتفاع أو باستغلال العقارات والمشروعات التى ليس لها الشخصية الاعتبارية، بما فى ذلك المنشآت السياحية والمقاصف يجب وضع وصف دقيق لموضوع التعاقد ومراعاة أهمية وتميز موقع محل التعاقد ومساحته وحالته وعمره وتكلفة انشائه واستهلاكاته واسم الشهرة إن وجد.$m260$,'40eca949dc1143be416edebf3a7fc9cd'),
(26,0,$m260$المادة 26$m260$,$m260$تشكل بقرار من السلطة المختصة لجنة تضم عناصر فنية ومالية من العاملين بالجهة الإدارية من أهل الخبرة بموضوع التعاقد، ويجوز لها الاستعانة بمن تراه مناسبا لأداء مهمتها من الجهات الإدارية الأخرى أو من المكاتب الاستشارية، لدراسة السوق ووضع القيمة التقديرية أو الثمن الأساسى وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها شريطة مراعاة حظر تعارض المصالح.
وتتولى اللجنة إعداد القيمة التقديرية أو الثمن الأساسى للعملية محل الطرح وفقا لدراسة السوق والأسعار المعلنة والسائدة وقت إعدادها ومؤشرات التطور المحتمل فيها، ومقارنة الأسعار للعمليات المماثلة السابق التعاقد عليها، على أن يؤخذ فى الاعتبار تكلفة المواد والعمالة والتكاليف الأخرى، بما في ذلك المعدات والنقل وغيرها من الرسوم والضرائب والتأمينات وأي مصاريف أخرى لها ارتباط بالعملية، ويكون لها أن تأخذ فى الاعتبار ما انتهت إليه أعمال اللجان الخاصة بطلب المعلومات المنصوص عليها بالمادة (16) من هذه اللائحة.
وتعد اللجنة تقريرا بنتائج أعمالها موقعا من أعضاءها، يتضمن الإجراءات التى اتخذتها والأسس والمعايير التى استندت إليها للوصول للقيمة التقديرية أو الثمن الأساسى، والنصاب المنصوص عليه بالمادة (29) من القانون لاشتراك ممثل عن وزارة المالية أو عضو من إدارة الفتوى المختصة بمجلس الدولة، بحسب الأحوال، وترفع اللجنة تقريرها للسلطة المختصة للاعتماد مع مراعاة سريته عند اتخاذ إجراءات العرض عليها، ويحفظ تقرير اللجنة بعد اعتماده فى ظرف مغلق بطريقة محكمة يسلم لمدير إدارة التعاقدات ولا يفتح إلا بمعرفة رئيس لجنة البت عند دراسة العروض المالية، وفى المزايدات يفتح ظرف الثمن الأساسى بمعرفة رئيس لجنة المزايدة ويكشف عن الثمن الأساسى لمحل التزايد لأعضاء اللجنة بعد انتهاء عملية التزايد عليه، ثم ما يليه بالتتابع إن وجد.
على أن تقوم السلطة المختصة بإخطار إدارة التعاقدات لإعمال شئونها المنصوص عليها بالمادة (59) من هذه اللائحة إذا كانت العملية محل الطرح تتطلب اشتراك ممثل عن وزارة المالية أو عضو من إدارة الفتوى المختصة بمجلس الدولة بحسب الأحوال.$m260$,'e800c7b052a41249aa34074ca1102ebd'),
(27,0,$m260$المادة 27$m260$,$m260$يكون تحديد القيمة التقديرية لشراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية بما يتماشى مع طبيعة كل عملية وفقا للأسس الآتية:
1- تحليل سعر الوحدة من حيث التكلفة المباشرة وغير المباشرة بما فى ذلك تكلفة المواد، العمالة، النقل، والتكنولوجيا وأية تكاليف أخرى.
2- معايير القيمة مقابل المال المدفوع.
3- المدة الزمنية لتنفيذ العقد.
4- المنافسة المتوقعة عند طرح العملية.
5- توافر خدمات ما بعد البيع.
6- مخاطر وهامش الربح والرسوم والضرائب والتأمين وأى مصروفات أخرى.
7- ما إذا كان محل العقد متوافرا بالأسواق أم ينتج خصيصا للجهة الإدارية.
وغير ذلك من معايير ترى اللجنة أخذها فى الاعتبار.
وتكون القيمة التقديرية على هيئة بنود فى حالة ترسية العملية كل بند على حدة، وتكون إجمالية فى الحالات التى تقتضى طبيعتها ذلك.
وفى حالات شراء أو استئجار العقارات يجب تحديد القيمة التقديرية وفقا لتميز وصقع الموقع ومستوى تجهيزات العقار، ومساحته مع الأخذ فى الاعتبار قيمة الأرض المقام عليها العقار.$m260$,'5410130facac01eb13a7d351d2ce41f8'),
(28,0,$m260$المادة 28$m260$,$m260$يتم تحديد الثمن الأساسى لبيع أو تأجير المنقولات وفقا لحالة محل العقد وتكلفة الحصول عليه وعمره الاستعمالى والاسترشاد بأسعار البيع أو التأجير السابقة.
وفى حالات بيع أو تأجير العقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات، بما فى ذلك المنشآت السياحية والمقاصف يكون تحديد الثمن الأساسى وفقا لتميز وصقع الموقع ومستوى التجهيزات، ومساحته وحالته وعمره الاستعمالى وتكلفة إنشاءه واستهلاكاته واسم الشهرة إن وجد وقيمة التجهيزات والمحتويات والعائد الذى يدره تشغيله أو استغلاله وغيرها من العناصر المؤثرة فى تحديد الثمن الأساسى بما يتماشى مع طبيعة محل التعاقد.$m260$,'76089787d4c2024a816fb3398dcb2f76'),
(29,0,$m260$المادة 29$m260$,$m260$فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية والدراسات الاستشارية يكون مبلغ التأمين المؤقت بأى قيمة بما يتماشى مع طبيعة العملية وحجمها شريطة ألا يصل الحد الأقصى له ما يجاوز نسبة (1.5%) من القيمة التقديرية.
وفى عمليات شراء أو استئجار العقارات يكون مبلغ التأمين المؤقت بأى قيمة شريطة ألا يصل الحد الأقصى له ما يجاوز نسبة (0.5%) من القيمة التقديرية.
وفى عمليات بيع وتأجير المنقولات والعقارات والترخيص بالانتفاع أو باستغلال العقارات والمشروعات التى ليس لها الشخصية الاعتبارية يكون تحديد مبلغ التأمين المؤقت حسب طبيعة وأهمية المزايدة.
وفى جميع الحالات يجب عدم المبالغة فى تحديد التأمين المؤقت لإتاحة الفرصة لأكبر عدد من المشتغلين بنوع النشاط للمشاركة فى العملية محل الطرح، وعلى لجنة اعداد القيمة التقديرية أو الثمن الأساسى، بحسب الاحوال، اقتراح مبلغ التأمين المؤقت بكتاب مستقل موقع من رئيسها وأعضاءها يرفق بتقريرها، ويتم تحديد مبلغ التأمين المؤقت واعتماده من السلطة المختصة ويخطر به مدير إدارة التعاقدات لاتخاذ الإجراءات اللازمة، على أن يتم تضمين مستندات الطرح مبلغ التأمين المؤقت.$m260$,'c833d6af8ad2707f553718b41af971fa'),
(30,0,$m260$المادة 30$m260$,$m260$يؤدى التأمين المؤقت بأى من الوسائل التى يصدر بتحديدها قرار من وزير المالية، ومنها وسائل الدفع الإلكترونى من خلال منظومة الدفع والتحصيل الإلكترونى أو بأية صورة من الصورتين الآتيتين:
1- بموجب خطاب ضمان مصدرا من أحد المصارف المحلية المعتمدة وألا يقترن بأى قيد أو شرط وأن يقر فيه المصرف بأن يدفع تحت أمر الجهة الإدارية مبلغا يوازى التأمين المطلوب.
وعندما يرد لإحدى الجهات الإدارية خطابات ضمان عن التأمين المستحق من أحد المصارف المرخص لها فى إصدار خطابات الضمان أو أحد فروعها عليها أن تتحقق من أن المصرف أو الفرع قد أعطى إقرارا على خطابات الضمان بأنه لم يجاوز الحد الأقصى المحدد لمجموع خطابات الضمان المرخص للمصرف فى إصدارها.
فإذا تبين عند مراجعة الإخطارات لدى البنك المركزى أن المصرف قد تعدى الحد الأقصى المحدد له أخطرت الجهة الإدارية فورا لمطالبة المصرف بأن يؤدى إليها فى ميعاد لا يجاوز ثلاثة أيام عمل قيمة خطاب الضمان.
وتقبل خطابات الضمان من البنوك الخارجية بشرط التأشير عليها بالقبول من أحد المصارف المحلية المعتمدة على أن يتعهد المصرف المحلى بأن يدفع للجهة الإدارية مبلغا يوازى التأمين المطلوب وأنه ملتزم بأدائه بأكمله عند أول طلب منها دون الالتفات إلى أى معارضة من صاحب العطاء.
2- يجوز لصاحب العطاء طلب سداد التأمين المؤقت خصما من مستحقاته التى تقر الجهة العامة صلاحيتها للصرف من عمليات أخرى فى ذات الجهة الإدارية وفى تاريخ جلسة فتح المظاريف الفنية.
كما يجوز بموافقة السلطة المختصة وبناء على طلب صاحب العطاء استبدال التأمين المؤقت المسدد منه بأحد صور السداد الأخرى المنصوص عليها بهذه المادة بشرط ألا تنقطع مدة سريان التأمين وعدم الإخلال بمسئوليته طبقا للغرض المقدم عنه التأمين.
ويتم رد التأمين المؤقت فى الحالات المنصوص عليها بالقانون وهذه اللائحة بذات الوسيلة التى تم أدائه بها.
ويجب أن تتضمن مستندات الطرح صور سداد ورد التأمين المؤقت على وجه التحديد.$m260$,'97135dd58b40703195335d9932beead9'),
(31,0,$m260$المادة 31$m260$,$m260$تتولى إدارة التعاقدات إعداد مذكرة للعرض على السلطة المختصة متضمنة موضوع وطريق التعاقد المناسب والإدارة الطالبة أو المستفيدة منه، والإجراءات السابق اتخاذها للإعداد للعملية محل الطرح، للموافقة على اتخاذ إجراءات الطرح وفقا للآتى:
1- توافر الاعتماد المالى.
2- الإعلان عن العملية أو الدعوة إليها.
3- مقترح تشكيل لجنة الرد على الاستفسارات إذا تطلب الأمر، واللجان المختصة بمباشرة إجراءات طرح العملية، على أن يتضمن قرار تشكيل تلك اللجان مواعيد انتهاءها من عملها.
4- البرنامج الزمنى المقترح لإجراءات العملية.
5- إمكانية السماح بصرف دفعة مقدمة من قيمة التعاقد، مع تحديد نسبتها.
6- تحديد أسلوب تقييم العطاءات وأسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول فى حالة التقييم بنظام النقاط.
7- مدة صلاحية سريان العطاءات.
8- البنود المتغيرة أو مكوناتها فى مقاولات الأعمال فى العمليات التى تتطلب ذلك.
9- استخدام اسلوب الاتفاقية الاطارية إذا رأت الجهة العامة ذلك ونمطها ومدتها.
10- تضمين كراسة الشروط والمواصفات البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن إذا تطلبت طبيعة العملية ذلك.
11- ثمن نسخة كراسة الشروط والمواصفات وفقا للشرائح المحددة بالمادة (35) من هذه اللائحة.
12- تقصير مدة تقديم العطاءات إذا تطلب موضوع التعاقد ذلك مع بيان السبب.
13- مدة توريد أو تنفيذ العقد.
14- تحديد آلية تسوية المنازعات والخلافات وفقا لحكم المادة (91) من القانون.
وغير ذلك من بيانات تراها إدارة التعاقدات يلزم عرضها على السلطة المختصة.
على أن ترفق بمذكرة الطرح الآتى:
1- صورة من نموذج خطة الاحتياجات المعتمدة، والمتضمنة العملية محل الطرح.
2- صورة الموافقات والتراخيص اللازمة ذات الصلة بالعملية محل الطرح.
3- نسخة من تقرير لجنة اعداد المواصفات الفنية.
4- نسخة من مستندات الطرح، وصيغة الإعلان أو خطابات الدعوة.$m260$,'6575948f94420342a126e2b15fc7bcfe'),
(32,0,$m260$المادة 32$m260$,$m260$تلتزم إدارة التعاقدات بكراسات الشروط والمواصفات النموذجية الصادرة عن الهيئة العامة للخدمات الحكومية، وأن تكون كراسات الشروط والمواصفات كاملة وواضحة ومرتبة ومرقمة بالتسلسل وأن تتضمن تحديد ما إذا كانت العملية قابلة للتجزئة من عدمه، وتحديد مراحل وتوقيتات تقديم الشكاوى وآلية تسوية الخلافات والمنازعات، والحظر المنصوص عليه بالمادة (33) من القانون، وما يفيد أن يكون صاحب العطاء أو المتزايد بحسب الأحوال لديه الامكانيات والقدرة على تنفيذ كافة التزاماته الواردة بكراسة الشروط والمواصفات بما فى ذلك تلبية كافة اشتراطات مزاولة النشاط موضوع التعاقد وعنوانه الدائم ويعتبر إعلامه صحيحا متى تم مخاطبته عليه فيما لو رست عليه العملية محل الطرح على أن يتم نشرها على بوابة التعاقدات العامة عدا العمليات التى تتطلب اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة.
ويرد ثمن كراسة الشروط والمواصفات لمن قام بشرائها متى توافرت أى من حالات إلغاء العملية المنصوص عليها بالمادة (37) من القانون، فيما عدا الحالات التى يتبين وجود تواطؤ أو ممارسات احتيال أو فساد أو احتكار فيها.
وفي العمليات التى تقتضى طبيعتها المعاينة التامة النافية للجهالة يتم تضمين ذلك بكراسة الشروط والمواصفات ويتعين فى هذه الحالة قيام إدارة التعاقدات بالتنسيق مع الإدارات الطالبة أو المستفيدة بالجهة الإدارية لتحديد موعد زيارة لمكان التوريد أو التنفيذ أو موقع المشروع أو مكان تواجد محل البيع أو التأجير أو الترخيص على أن يكون موعد المعاينة قبل انعقاد جلسة فتح المظاريف الفنية أو جلسة المزايدة بوقت كاف، بما يمكن من قام بشراء كراسة الشروط والمواصفات من اعداد عطائه بشكل جيد.
وتلتزم إدارة التعاقدات بإخطار أو موافاة، بحسب الأحوال، لجنة تفضيل المنتج الصناعى المصرى بنسخة من شروط ومواصفات الطرح أو العقود وفقا لما هو منصوص عليه بأحكام القانون رقم 5 لسنة 2015 فى شأن تفضيل المنتجات المصرية فى العقود الحكومية.$m260$,'f959c36cc48a00c7fc0a899f3458c513'),
(33,0,$m260$المادة 33$m260$,$m260$تلتزم إدارة التعاقدات بتضمين كراسة الشروط والمواصفات فى عمليات شراء أو استئجار المنقولات والعقارات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية، بحسب الأحوال، البيانات الآتية:
1- ما يفيد توافر الاعتماد المالى المخصص للعملية محل الطرح.
2- وسيلة وأسلوب التواصل مع الجهة، بما في ذلك عنوان وتليفون ورقم فاكس وبريد الكرتوني واسم المخول له التواصل مع المتعاملين.
3- البيانات الواجب توافرها فى أصحاب العطاءات ومعايير التحقق من توافر شروط الكفاءة الفنية والملاءة المالية وحسن السمعة لهم، والتصنيف المطلوب للمقاولين في مقاولات الاعمال وشهادات مزاولة النشاط ذات الصلة.
4- وصفا لموضوع التعاقد بما في ذلك أي وصف فني ضروري، والمخرجات المطلوبة ومستويات الأداء وغيرها من المواصفات والبيانات الإحصائية لمعدلات الطلب، ومعدلات الاستهلاك التاريخية، والمؤشرات المستقبلية الاسترشادية لمحل الطرح والتعاقد أو أطر الأعمال أو الخدمات، بحسب الأحوال.
5- أسلوب تقييم العطاءات وأسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول فى حالة التقييم بنظام النقاط.
6- معايير ومحددات دورة الحياة التى يمكن تقيمها عند البت ووفقا لطبيعة العملية.
7- صور سداد ورد التأمين المؤقت ومبلغه والتأمين النهائى ونسبته.
8- إقرار التأمين على العمالة إذا تطلبت طبيعة العملية ذلك.
9- تحديد البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن إذا تطلبت طبيعة العملية ذلك، وكذا المحددات والاشتراطات الأخرى ذات الصلة.
10- شروط تطبيق أفضلية المنتج المحلي عن توريدات مستوفية لنسبة المكون الصناعى المصرى، أو الخدمات أو الأعمال الفنية التى تقوم بها جهات مصرية؛ إعمالا لحكم المادة (35) من القانون.
11- المدة اللازمة لصلاحية سريان العطاءات.
12- مدة التوريد أو التنفيذ أو أداء الخدمة.
13- نسبة الدفعة المقدمة إن وجدت، وطلب تحديد أوجه صرفها.
14- تحديد البنود المتغيرة أو مكوناتها بالنسبة لمقاولات الأعمال فى العمليات التى تتطلب ذلك.
15- تحديد مدة الضمان، ومدة الصيانة ونوعها، شاملة أو غير شاملة قطع الغيار، فى الحالات التى تتطلب ذلك.
16- ما يفيد تعديل حجم العقد بالزيادة أو النقص إذا طرأت مستجدات تستوجب ذلك وبما لا يجاوز النسب ووفقا للأحكام الواردة بالقانون.
17- النص على استخدام اسلوب الاتفاقية الاطارية ونمطها فى العمليات التى يتقرر فيها ذلك.
18- التأكيد على أن جميع التعاقدات تكون بالجنيه المصري ما لم يذكر صراحة غير ذلك، وأنه يجوز فى حالة تقديم العطاء من فرد أو شركة فى الخارج أن تكتب الأسعار بالعملة الأجنبية، ولغرض المقارنة تتم معادلتها بالجنيه المصري بالسعر المعلن بالبنك المركزي المصري فى تاريخ فتح المظاريف الفنية.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة بما يتماشى مع طبيعة العملية.$m260$,'929c00d4065562ee52842de6df334c03'),
(34,0,$m260$المادة 34$m260$,$m260$تلتزم إدارة التعاقدات بتضمين كراسة الشروط والمواصفات لبيع وتأجير المنقولات والعقارات، والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف البيانات الآتية:
1- توصيف محل التعاقد.
2- الاشتراطات الواجب توافرها فى المتزايدين.
3- صور سداد ورد التأمين المؤقت ومبلغه والتأمين النهائى ونسبته.
4- طلب التراخيص اللازمة في حالة بيع الأصناف التى تتطلب ذلك مثل المخلفات الإلكترونية والخطرة وما يماثلها.
5- تحديد البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن إذا تطلبت طبيعة العملية ذلك، وكذا المحددات والاشتراطات الأخرى ذات الصلة.
6- طلب تحديد القيمة الإيجارية أو مقابل الترخيص بالانتفاع أو بالاستغلال وتاريخ سدادهما، والإجراءات التى تتخذ حال عدم السداد فى المواعيد المحددة.
7- ما يفيد أن الكميات والأوزان المعروضة للبيع تحت العجز والزيادة والعبرة بما يسفر عنه التسليم الفعلي.
8- الموعد المحدد لاستلام الأصناف المباعة وقيمة المصروفات التى سيتحملها المتعاقد فى حالة تأخره عن هذا الموعد.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة بما يتماشى مع طبيعة العملية.$m260$,'9e691409cee5e3882caae8fb64a0a000'),
(35,0,$m260$المادة 35$m260$,$m260$على الجهة الإدارية تحديد ثمن كراسة الشروط والمواصفات وفقا للشرائح الأتية:
مبلغ التأمين المؤقت (بالألف جنيه مصرى) | ثمن شراء كراسة الشروط والمواصفات (بالجنيه المصرى)
حتى 100 | 299
أكثر من 100 وحتى 200 | 399
أكثر من 200 وحتى 300 | 499
أكثر من 300 وحتى 400 | 599
أكثر من 400 وحتى 500 | 699
أكثر من 500 وحتى 600 | 799
أكثر من 600 وحتى 700 | 899
أكثر من 700 وحتى 800 | 999
أكثر من 800 وحتى 900 | 1500
أكثر من 900 وحتى مليون | 2000
أكثر من مليون | من 3000 إلى 50000
وفى العمليات التى يكون مبلغ التأمين المؤقت فيها أكثر من مليون جنيه يجب عدم المغالاة فى تحديد ثمن كراسة الشروط والمواصفات لإتاحة الفرصة لاشتراك أكبر عدد ممكن من المتعاملين فى العملية محل الطرح.$m260$,'e7eeea12c0f1772fc1c691875b2f25eb'),
(36,0,$m260$المادة 36$m260$,$m260$بمراعاة أحكام المادة (20) من القانون يجب على إدارة التعاقدات فور موافقة السلطة المختصة على ما تضمنته مذكرة الطرح النشر عن العملية على بوابة التعاقدات العامة، وكذا الإعلان عنها أو الدعوة إليها، بحسب الأحوال، على أن يتضمن الإعلان أو الدعوة البيانات الآتية:
1- اسم الجهة الإدارية الطارحة، وعنوان إدارة التعاقدات بها ورقم التليفون والفاكس والبريد الإلكترونى للإدارة.
2- أسم العملية ورقمها وطريق التعاقد.
3- وصفا موجزا وواضحا لموضوع التعاقد.
4- مكان وميعاد الحصول على كراسة الشروط والمواصفات وثمنها، والإشارة إلى إمكانية الاطلاع على بيانات العملية ومستندات الطرح الخاصة بها على بوابة التعاقدات العامة دون مقابل.
5- موعد ومكان انعقاد جلسة الاستفسارات إن وجدت، وجلسة فتح المظاريف أو الممارسة أو جلسة المزايدة، بحسب الأحوال.
6- مبلغ التأمين المؤقت ونسبة التأمين النهائى.
وإذا تقرر طرح أكثر من عملية فى تاريخ واحد أو تواريخ متقاربة فعلى إدارة التعاقدات مراعاة الإعلان عنها فى إعلان واحد.$m260$,'b178b9268893e2e95d47c939aff3d8b9'),
(37,0,$m260$المادة 37$m260$,$m260$يجوز فى العمليات التى تتطلب طبيعتها التأكد من توافر القدرات الفنية والإمكانيات المالية والإدارية والبشرية وغيرها لدى الموردين أو المقاولين أو مقدمى الخدمات أو الاستشاريين للقيام بتنفيذ أحد العقود بالكفاءة المطلوبة قبل دعوتهم لتقديم العطاءات حال الطرح أن تقوم إدارة التعاقدات بإصدار طلب للتأهيل المسبق دون مقابل للمشتغلين بنوع النشاط محل العملية المزمع طرحها، على أن يتم الإعلان عن التأهيل المسبق بإحدى الصحف اليومية واسعة الانتشار، بالإضافة للنشر عنه على بوابة التعاقدات العامة، ويجب أن يتضمن الإعلان الآتى:
1- اسم ورقم العملية المطلوب التأهيل لها كما هو مدرج في خطة الاحتياجات السنوية.
2- اسم الجهة الإدارية الطارحة، وعنوان إدارة التعاقدات بها ورقم التليفون والفاكس والبريد الإلكترونى للإدارة.
3- وصفا موجزا وواضحا للعملية المطلوب التأهيل لها.
4- بيان كيفية الحصول على مستندات التأهيل المسبق، والإشارة إلى إمكانية الاطلاع عليها على بوابة التعاقدات العامة دون مقابل.
5- مكان وأخر موعد لتلقى الطلبات.
6- تحديد الخبرات المطلوبة.$m260$,'82aab586be1a6f357892202cdc7cd7cb'),
(38,0,$m260$المادة 38$m260$,$m260$تشكل بقرار من السلطة المختصة لجنة تضم عناصر فنية ومالية وقانونية ويضم لها عضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع التأهيل المسبق، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها، وتختص بالآتي:
1- إعداد مستندات التأهيل المسبق، ووضع معاييره، وبيان المستندات اللازمة له.
2- الرد على استفسارات طالبى التأهل، مع إتاحة مضمون الرد لكافة طالبى التأهل فى العملية المزمع طرحها دون الافصاح عن مقدم الاستفسار الذي طلب التوضيح.
3- دراسة طلبات التأهيل المسبق بعد استيفائها، وتحديد المؤهل منها طبقا لمعايير التأهيل الموضوعة واستبعاد الغير مؤهل.$m260$,'25710a934b1621db3d8e4c350a089f3f'),
(39,0,$m260$المادة 39$m260$,$m260$يكون إصدار طلب التأهيل المسبق وفقا للنموذج الذى تعده الهيئة العامة للخدمات الحكومية على أن تتخذ لجنة التأهيل المسبق ما يلزم لتضمينه المعايير التى يمكن على أساسها تنفيذ العملية المزمع طرحها، من متطلبات الأهلية والتأهيل، والمعلومات والمستندات الواجب تقديمها من مقدمي طلبات التأهيل لإثبات استيفائهم لهذه المتطلبات، والخبرات المطلوبة لهم، بما فى ذلك خبرات العنصر البشرى أو التكنولوجي، وحجم المشاركة فى عمليات مماثلة، والكفاءة الفنية والملاءة المالية، وغير ذلك من المتطلبات الفنية والمالية والإدارية والبشرية، على أن يراعى الآتى:
1- عمليات توريد المنقولات:
أ- سابقة الخبرة فى توريدات مماثلة كمتعاقد أو متعاقد من الباطن.
ب- كفاءة المهنيين المشاركين في أعمال التركيبات إذا كانت طبيعة العملية تتطلب ذلك.
ج- إمكانية التشغيل دون أعطال للأصناف.
د- أعمال الصيانة، والضمان، وخدمة ما بعد البيع، وتوافر قطع الغيار.
2- التعاقد على مقاولات الأعمال:
أ- القدرات المهنية وكذا الملاءة المالية.
ب- سابقة الأعمال فى عقود مماثلة فى الطبيعة والتكنولوجيا الإنشائية للعملية المزمع طرحها، وسابقة التقاضي، والخبرة الإجمالية للعمليات السابق تنفيذها كمتعاقد أو متعاقد من الباطن.
ج- التصنيف وفقا للاتحاد المصرى لمقاولى التشييد والبناء طبقا لحجم الأعمال وطبيعتها.
د- متوسط حجم الأعمال المنفذة سنويا.
ه- توافر المعدات وحالتها التشغيلية المناسبة.
و- توافر الكوادر الفنية المؤهلة بشكل مناسب للوظائف الرئيسية المذكورة في مستندات طلب التأهيل.
3- عمليات تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية:
أ- الخبرة الأكاديمية والعملية للعنصر البشرى كمتعاقد أو متعاقد من الباطن.
ب- الخبرة المؤسسية والأداء وسابقة الخبرة في الاعمال المماثلة.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة.$m260$,'43d5783e2867e5babc5c3a887367e074'),
(40,0,$m260$المادة 40$m260$,$m260$يجب على المتقدمين للتأهيل المسبق استيفاء نموذج طلب التأهيل وتقديم المستندات والوثائق المطلوبة والمذكورة في طلب التأهيل، ويجب تقديم الطلبات في ظرف مغلق في الوقت والمكان المحددين في الاعلان، ويرفض الطلب في حال عدم تقديم المعلومات والوثائق المطلوبة في مستندات التأهيل المسبق.
وتتولى إدارة التعاقدات تلقى طلبات التأهيل المسبق، وقيدها فى السجل المعد لذلك بحسب تاريخ تقديمها، ويسلم مدير إدارة التعاقدات رئيس لجنة التأهيل المسبق الطلبات الواردة لفحصها، والتأكد من استيفائها للبيانات والمستندات المطلوبة.
ويجوز للجنة التأهيل المسبق وبما لا يخل بمبدأ تكافؤ الفرص أن تطلب كتابة الإيضاحات والمستندات التى تراها لازمة لدراسة طلبات التأهيل المقدمة على أن يتضمن طلب اللجنة تحديد موعد نهائى للرد عليه، كما يجوز لها أن تستطلع رأى الجهات الإدارية السابق تعاملهم معها، وإجراء الزيارات الميدانية إذا تطلب الأمر ذلك.
يجب أن تكون توصيات لجنة التأهيل المسبق باستبعاد طلبات التأهيل غير المستوفاة لمعايير التأهيل الموضوعة مسببه، وعلى إدارة التعاقدات بعد اعتماد السلطة المختصة لتوصيات اللجنة بالقبول أو الاستبعاد إخطار المتقدمين بنتيجة التأهيل بالإضافة إلى النشر عن ذلك على بوابة التعاقدات العامة، ويجوز لمن لم يتم تأهيلهم التقدم بشكواهم وفقا للقواعد المعمول بها بشأن الشكاوى.
ويتم توجيه الدعوة لمقدمي الطلبات الذين اجتازوا مرحلة التأهيل المسبق للمشاركة في العملية حال الطرح، وتقديم عطاءاتهم على أن لا يقل العدد عن ثلاثة مؤهلين، ويجوز للسلطة المختصة في حالة ما اذا كان عدد المؤهلين اقل من ثلاثة اعادة اجراءات التأهيل المسبق بعد اعادة النظر في متطلبات التأهيل السابقة.
ويتعين على إدارة التعاقدات توثيق كافة ما تم اتخاذه من إجراءات.$m260$,'407983da700ce43d647e8e54f04a8000'),
(41,0,$m260$المادة 41$m260$,$m260$يجب أن تتضمن كراسة الشروط والمواصفات مواعيد تقديم الايضاحات والرد عليها، على أن يؤخذ في الاعتبار التاريخ المحدد لتقديم العطاءات ومراعاة إتاحة الفرصة لإجراء الزيارات الميدانية اللازمة، إذا تطلبت طبيعة العملية ذلك.
ولصاحب العطاء المحتمل أو من قاموا بشراء كراسة الشروط والمواصفات الحق في طلب أى إيضاحات كتابة بشأن ما ورد بها بداية من تاريخ النشر عن العملية على موقع بوابة التعاقدات العامة وبحد أقصى عشرة أيام قبل التاريخ المحدد لانعقاد جلسة فتح المظاريف والموضح بمستندات الطرح.
وعلى إدارة التعاقدات الرد قبل موعد فتح المظاريف الفنية بمدة لا تقل عن سبعة أيام.$m260$,'acd6c78fc253415d7374dd87e81fbc4d'),
(42,0,$m260$المادة 42$m260$,$m260$يجب على السلطة المختصة فى الحالات التى تقرر فيها عقد جلسة للاستفسارات أن تقوم بتشكيل لجنة من عناصر فنية ومالية وقانونية وعضو من إدارة التعاقدات، تكون مهمتها تلقى الاستفسارات كتابة وذلك قبل الموعد المحدد لانعقاد جلسة الاستفسارات، ووفقا للمدد الزمنية المحددة لذلك بكراسة الشروط والمواصفات.
وتتولى اللجنة المشار إليها دراسة ما يقدم إليها من استفسارات ويتعين عليها أن تعد محضرا للجلسة يتضمن الأسئلة والايضاحات التي أثيرت خلالها، وما تم الرد بشأنه، وبناء على ما تسفر عنه نتيجة دراستها تقوم برفع محضرها بما انتهت إليه متضمنا أى تعديلات بكراسة الشروط والمواصفات أو الجدول الزمنى إذا تطلب الأمر ذلك.
وفور اعتماد السلطة المختصة لمحضر اللجنة يجب على إدارة التعاقدات اخطار مقدمى الاستفسارات أو الايضاحات ومن قاموا بشراء كراسة الشروط والمواصفات كتابة، دون الافصاح عن مقدم الاستفسار الذي طلب التوضيح، وذلك خلال ثلاثة أيام على الأكثر من تاريخ إجراء التعديلات أو جلسة الاستفسارات ولا يجوز أن تقل المدة بين الإخطار والموعد المحدد لفتح المظاريف الفنية عن سبعة أيام شاملا ما يلزم من إيضاحات وتعديلات وكذا نشرها على بوابة التعاقدات العامة على أن تعتبر هذه التعديلات جزءا لا يتجزأ من كراسة الشروط والمواصفات، وتسرى فى مواجهة جميع أصحاب العطاءات.$m260$,'003a7653f80cb7394139edb2ce4aa19d'),
(43,0,$m260$المادة 43$m260$,$m260$يتحمل صاحب العطاء كافة تكاليف إعداد وتقديم عطائه، وكل ما يتعلق به من مهام، ولا تتحمل الجهة الإدارية بأي حال من الأحوال أية مسئولية عن تلك التكاليف بغض النظر عن نتيجة العملية.
وتقدم العطاءات موقعة من أصحابها وفقا للشروط المحددة بمستندات الطرح ويجب تقديمها على نموذج العطاء المدرج بكراسة الشروط والمواصفات، ويجب أن يثبت على كل من مظروفي العطاء الفنى والمالى نوعه من الخارج، ويوضع المظروفين داخل ظرف مغلق بطريقة محكمة ويوضح عليه اسم الجهة الإدارية وعنوان إدارة التعاقدات وما يفيد أن ما بداخله المظروف الفنى والمظروف المالى ويذكر اسم العملية ورقمها وتاريخ جلسة فتح المظاريف الفنية كما يذكر أسم صاحب العطاء.$m260$,'9de10d3be0cbdf0dd5589bfb4e42d9d7'),
(44,0,$m260$المادة 44$m260$,$m260$تسلم العطاءات لإدارة التعاقدات قبل التاريخ أو الموعد المحدد لفتح المظاريف الفنية إما باليد أو عن طريق البريد السريع من خلال الهيئة القومية للبريد أو عن طريق الوسائل الإلكترونية إذا ما سمحت بذلك شروط العملية.
وعلى صاحب العطاء عدم شطب أى بند من بنود العطاء أو من المواصفات الفنية أو إجراء تعديل فيه مهما كان نوعه بعد تسليمه، وإذا رغب فى إبداء أية ملاحظات خاصة بالنواحي الفنية فيثبتها فى كتاب مستقل ويسلمها لإدارة التعاقدات قبل الموعد المحدد لفتح المظاريف الفنية، ويبقى العطاء نافذ المفعول وغير جائز الرجوع فيه من وقت تسليمه بغض النظر عن ميعاد استلامه بمعرفة الجهة الإدارية وحتى نهاية المدة المحددة لسريان العطاءات.
وفي حالة تقديم العطاء من صاحبه أو من يفوضه شريطة تقديم التفويض الدال على ذلك أو وكيله، فيتعين على إدارة التعاقدات التوقيع على ايصال يفيد الاستلام يحدد به موعد وتاريخ استلام العطاءات، وفى حالة استلام إدارة التعاقدات العطاءات عن طريق البريد السريع من خلال الهيئة القومية للبريد، فيجب على موظف الإدارة التوقيع على ايصال الهيئة بالاستلام والاحتفاظ بصورة منه.$m260$,'55cf21b066db1dda000dba3772924927'),
(45,0,$m260$المادة 45$m260$,$m260$على إدارة التعاقدات عند تحديد مدة تقديم العطاءات أن تراعى اعطاء الوقت الكافى لأصحاب العطاءات لدراستهم لكراسة الشروط والمواصفات واستيفاء المستندات اللازمة لتقديم عطاءاتهم ووفقا لطبيعة وحجم العملية محل الطرح، على أن يتم تحديد مدة تقديم العطاءات وفقا للآتى:
1- المناقصة العامة والممارسة العامة والمزايدة العلنية العامة والمزايدة بالمظاريف المغلقة خلال مدة لا تقل عن عشرين يوما تحتسب من تاريخ الإعلان بإحدى الصحف اليومية، ويجوز استثناء بموافقة السلطة المختصة فى حالة الاستعجال المبررة والموثقة تقصير تلك المدة بحيث لا تقل عن أربعة عشر يوما.
2- المناقصة المحدودة والمناقصة المحلية والممارسة المحدودة والمزايدة المحدودة والمزايدة المحلية خلال مدة لا تقل عن أربعة عشر يوما تحتسب من تاريخ توجيه الدعوة ويجوز استثناء بموافقة السلطة المختصة فى حالة الاستعجال المبررة والموثقة تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام.$m260$,'d6e25c7387d56e4b4366e0d8e5b0de7e'),
(46,0,$m260$المادة 46$m260$,$m260$يجوز للجهة الإدارية، إذا ارتأت ضرورة، أن تقوم بتأجيل موعد فتح المظاريف أو المزايدة، بحسب الأحوال.
كما يجوز لمن قام بشراء كراسة الشروط والمواصفات قبل التاريخ المحدد لفتح المظاريف الفنية أو جلسة المزايدة بثلاثة أيام على الأقل أن يتقدم كتابة لإدارة التعاقدات بطلب مسبب لمد مدة تقديم العطاءات، وتلتزم إدارة التعاقدات بالعرض على السلطة المختصة بنتيجة دراستها والحصول على موافقتها حال اقتراح مد المدة وتأجيل موعد فتح المظاريف أو المزايدة، بحسب الأحوال، أو الأسباب التى تراها مناسبة لعدم تأجيل الموعد.
وفى جميع حالات تأجيل تاريخ فتح المظاريف أو المزايدة، بحسب الأحوال، يتعين الحصول على موافقة السلطة المختصة وإعادة النشر على بوابة التعاقدات العامة والإعلان أو توجيه الدعوات، بحسب الأحوال، على ألا تقل مدة التأجيل عن نصف المدة المحددة مسبقا لفتح المظاريف الفنية من تاريخ الإعلان أو الدعوة.$m260$,'37d1aa3a5167ed6d1535a23ee0a408b6'),
(47,0,$m260$المادة 47$m260$,$m260$على مدير إدارة التعاقدات التأكد من أن جميع العطاءات والعينات التى استلمها محفوظة بطريقة أمنة لا تسمح بالاطلاع على مضمونها أو فتحها ولو بطريق الخطأ، ويحظر فتح العطاءات قبل الموعد المحدد لجلسة فتح المظاريف، ولا يجوز الكشف عن عدد العطاءات المستلمة أو أية معلومات بشأن أصحاب العطاءات قبل انعقاد جلسة فتح المظاريف الفنية.
ويتعين على مدير إدارة التعاقدات تسليم العينات لإدارة المخازن لحفظها، وينبغي أن يتم التعامل معها بطريقة سرية ومضمونة لا تؤدى إلى الكشف عن خصائصها قبل فتح المظاريف.$m260$,'16bb7aee28183a56b53ec074abbb7991'),
(48,0,$m260$المادة 48$m260$,$m260$فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية يجب أن يحتوى المظروف الفنى على ما يفيد سداد التأمين المؤقت المطلوب بالإضافة إلى البيانات والمستندات المنصوص عليها بكراسة الشروط والمواصفات، وعلى الأخص وبحسب طبيعة العملية المطروحة الآتى:
1- بيان الشكل القانوني لصاحب العطاء والمستندات الدالة على ذلك.
2- بيانات القيد فى السجلات الخاصة بالنشاط موضوع التعاقد كالقيد فى السجل التجاري أو الصناعى أو سجل المستوردين وغيرها من السجلات التى يكون القيد فيها واجبا قانونا.
3- بيانات وخبرات صاحب العطاء ومن قد يعهد إليهم ببعض بنود العملية من الباطن وفقا لما تضمنته كراسة الشروط والمواصفات.
4- المستندات الدالة على سابقة الأعمال لذات موضوع التعاقد.
5- بيانات عن أسماء ووظائف وخبرات الكوادر التى سيسند إليها التنفيذ والإشراف على تنفيذ العملية.
6- المستندات الدالة على وجود مركز صيانة معتمد ساري.
7- بيان مصادر ونوع المواد والمهمات والأجهزة التى تستخدم فى التنفيذ.
8- البطاقة الضريبية سارية، وأخر إقرار ضريبي.
9- بطاقة الاتحاد المصرى لمقاولى التشييد والبناء سارية.
10- تعهد بألا تقل نسبة المكون الصناعى المصرى عن (40%) فى عقود مقاولات الأعمال.
11- إقرار الالتزام بالتأمين على العمالة إذا تطلبت طبيعة العملية ذلك.
12- إقرار بالالتزام بما جاء بكراسة الشروط والمواصفات ومحتوياتها.
13- ما يفيد شراء كراسة الشروط والمواصفات.
14- نسبة الدفعة المقدمة المطلوبة لتنفيذ محل العقد وأوجه صرفها إذا نصت كراسة الشروط والمواصفات على ذلك.
15- طريقة التنفيذ والبرنامج الزمنى للتوريد أو التنفيذ ومدته.
16- الكتالوجات والبيانات الخاصة بمصادر ونوع المواد والمهمات والمعدات والأجهزة المقدمة عن العرض.
17- قائمة بقطع الغيار ومستلزمات التشغيل مع بيان معدلات استهلاكها.
18- معاملات تغير الأسعار للبنود أو مكوناتها الواردة بكراسة الشروط والمواصفات فى عقود مقاولات الأعمال التى تتطلب ذلك.
وغير ذلك من بيانات تضمنتها كراسة الشروط والمواصفات.$m260$,'310e36396851db699bfd15251d606d22'),
(49,0,$m260$المادة 49$m260$,$m260$فى عمليات شراء أو استئجار العقارات يجب أن يحتوى المظروف الفنى على الآتى:
1- صورة معتمدة من المستندات الدالة على الملكية.
2- شهادة سلبية تفيد خلو العقار من أية رهون أو حجوزات أو حقوق للغير.
3- تقرير معتمد من مهندس استشاري يفيد سلامة العقار من كافة النواحى الإنشائية والمعمارية وصلاحيته للغرض المطلوب من أجله.
4- صورة من التراخيص الصادرة من الجهات المختصة بإنشاء العقار.
5- نسخة من الرسومات الهندسية معتمدة من مهندس استشاري تفيد أنها تطابق ما هو موجود على الطبيعة ومقدم عنه العرض.
6- شهادة من الجهة الإدارية المختصة بشئون التخطيط والتنظيم الواقع بدائرتها العقار تفيد عدم وجود أية مخالفات على العقار.
7- بيان بمواصفات العقار المعروض وما يشتمل عليه من تجهيزات.
8- المدة التى يتم خلالها تسليم العقار للجهة الادارية صالحا للاستخدام وفقا لمتطلباتها.
9- اقرار بتحمل صاحب العقار المسئولية عن سلامة العقار بالكامل، والموافقة على تنفيذ أى تعديلات أو أعمال إضافية على العقار قد تطلبها الجهة الإدارية بغرض توحيد المسئولية، وأن يلتزم بتنفيذ هذه الأعمال وفقا لتعليمات الجهات الفنية المختصة، وأن تتم المحاسبة استرشادا بأسعار السوق.
وغير ذلك من بيانات تضمنتها كراسة الشروط والمواصفات.$m260$,'22ab886926c9e78caafc79f80c673603'),
(50,0,$m260$المادة 50$m260$,$m260$فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية يجب أن يحتوى المظروف المالى على الآتى:
1- قوائم الأسعار وجداول الفئات وكمياتها.
2- أسلوب السداد وقيم الصيانة وقطع الغيار ومستلزمات التشغيل وغيرها من العناصر التى تؤثر فى القيمة المالية للعرض.
3- شهادة استيفاء نسبة المكون الصناعى المصرى سارية فى عقود شراء المنقولات.
وغير ذلك من بيانات تضمنتها كراسة الشروط والمواصفات.$m260$,'3f62ef1c66b89508d00411aac734ea5c'),
(51,0,$m260$المادة 51$m260$,$m260$فى عمليات شراء أو استئجار العقارات يجب أن يحتوى المظروف المالى على الآتى:
1- سعر البيع أو القيمة الإيجارية وملحقاتها التى تتحملها الجهة الإدارية.
2- طريقة السداد.
وغير ذلك من بيانات تضمنتها كراسة الشروط والمواصفات.$m260$,'ffb03363ea8810f20bb6e4503627a76e'),
(52,0,$m260$المادة 52$m260$,$m260$فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية على صاحب العطاء عند إعداده لقائمة الأسعار وجدول الفئات التى يتم وضعها داخل المظروف المالى مراعاة الآتى:
1- كتابة الأسعار رقما وحروفا باللغة العربية ويكون سعر الوحدة فى كل صنف بحسب ما هو مدون بجدول الفئات عددا أو وزنا أو مقاسا أو غير ذلك دون تغيير أو تعديل فى الوحدة.
ويجوز فى حالة تقديم العطاء من فرد أو شركة فى الخارج أن تكتب الأسعار بالعملة الأجنبية ولغرض المقارنة تتم معادلتها بالجنيه المصري بالسعر المعلن بالبنك المركزي المصري فى تاريخ فتح المظاريف الفنية.
2- أن تكون قائمة الأسعار وجداول الفئات مؤرخة وموقعة من صاحب العطاء.
3- عدم الكشط أو المحو أو التحشير فى جدول الفئات، وكل تصحيح فى الأسعار أو غيرها يجب إعادة كتابته رقما وحروفا والتوقيع بجانبه.
4- إذا سكت صاحب العطاء فى عرضة المالى عن تحديد سعر صنف من الأصناف المطلوب توريدها بقائمة الأسعار المقدمة منه فيعتبر ذلك امتناعا منه عن الدخول فى هذا الصنف، أما فى مقاولات الأعمال فللجهة الإدارية مع الاحتفاظ بحقها فى استبعاد العطاء أن تضع للبند الذى سكت صاحب العطاء عن تحديد فئته أعلى فئة لهذا البند فى العطاءات المقبولة وذلك للمقارنة بينه وبين سائر العطاءات فإذا أرسيت عليه العملية فيعتبر أنه ارتضى المحاسبة على أساس أقل فئة لهذا البند فى العطاءات المقبولة دون أن يكون له حق المنازعة فى ذلك.
5- الفئات التى حددها صاحب العطاء بجدول الفئات تشمل وتغطى جميع المصروفات والالتزامات أيا كان نوعها التى يتكبدها بالنسبة إلى كل بند من البنود وكذلك تشمل القيام بإتمام توريد الأصناف وتنفيذ محل العقد وتسليمها للجهة العامة والمحافظة عليها أثناء مدة الضمان طبقا لشروط العقد وتتم المحاسبة النهائية بالتطبيق لهذه الفئات بصرف النظر عن تقلبات السوق والعملة والتعريفة الجمركية وغيرها من الضرائب والرسوم الأخرى.
وفي جميع الأحوال لن يلتفت إلى أى ادعاء من صاحب العطاء بحصول خطأ فى عطائه إذا قدم بعد فتح المظاريف الفنية.$m260$,'f3fae34aed53fc8cbdd61ffb78f3e36b'),
(53,0,$m260$المادة 53$m260$,$m260$يكون توريد الأصناف الواردة من الخارج فى المواعيد والأماكن المبينة بقائمة الأسعار وفقا لشروط الطرح وعلى صاحب العطاء أن يراعى عند وضع أسعاره شروط التجارة الدولية (INCOTERMS) ومنها على سبيل المثال الآتى:
1- إذا كان تسليم الأصناف بميناء الشحن على ظهر المركب فوب (FOB) فيجب أن يشمل السعر المبين بالعطاء العبوات بكافة أنواعها وكذا مصروفات النقل إلى ظهر المركب.
2- إذا كان التسليم C&F أو CIF أو بميناء الوصول فيشمل السعر علاوة على المبين بالبند (1) نولون الشحن البحري أو الجوي ومصروفات التفريغ من المركب أو الطائرة كما يشمل قيمة التأمين فى حالة CIF أو ميناء الوصول.
وفى كلتا الحالتين إذا اشترط صاحب العطاء قيام الجهة الإدارية بدفع الثمن بموجب اعتماد مستندي يفتح بواسطتها لحسابه أو لحساب عملائه فى الخارج أو فى الداخل فإنه يتحمل مصاريف فتح الاعتماد المستندي وعليه أن يبين المبالغ المطلوب تحويلها إلى الخارج مع بيان نوع العملة والجهة التى سيتم الاستيراد منها.
ومع ذلك يجوز للسلطة المختصة بعد عرض لجنة البت الموافقة على تحمل الجهة العامة بمصروفات فتح الاعتماد المستندي إذا اشترط صاحب العطاء ذلك على أن يؤخذ هذا الشرط فى الاعتبار عند المقارنة والمفاضلة بين مختلف العروض من حيث الشروط المقدمة والأسعار.
وإذا كان التسليم بمخازن الجهة الإدارية فيجب أن يشمل السعر علاوة على المبين بالبند (2) رسوم الجمارك وجميع أنواع الرسوم الأخرى وضريبة القيمة المضافة وغيرها من الضرائب السارية وقت تقديم العطاء ومصروفات النقل الداخلي بحيث تسلم الأصناف لمخازن الجهة العامة خالصة من جميع الضرائب والرسوم والمصروفات.$m260$,'ed49e906a068cb93e754cfac3ab05bad'),
(54,0,$m260$المادة 54$m260$,$m260$فى حالة وفاة صاحب العطاء إذا كان شخصا طبيعيا، أو مالك شركة الشخص الواحد، أو الشريك مع الغير بحصة حاكمة تسمح له بالتأثير فى اتخاذ قرار ذى صلة بالعطاء قبل البت، جاز للسلطة المختصة بعد عرض ادارة التعاقدات استبعاد العطاء المقدم منه ورد التأمين المؤقت، أو السماح للورثة بالاستمرار فى الإجراءات بشرط أن يعينوا عنهم وكيلا بتوكيل مصدقا على التوقيعات فيه، وتوافق عليه السلطة المختصة، ويظل هو دون غيره مسئولا أمام الجهة العامة عن تنفيذ الإجراءات.$m260$,'a0a625e9bde23e902a3e617db5f4e293'),
(55,0,$m260$المادة 55$m260$,$m260$فى العمليات التى ترى الجهة الإدارية مناسبة إسناد المتعاقد لبعض بنودها من الباطن، فعلى إدارة التعاقدات من واقع دراستها للسوق ووفقا لطبيعة العملية تضمين كراسة الشروط والمواصفات البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن، على ألا تمثل تلك البنود الجانب الأكبر أو الجوهري من العملية، وبما يتفق مع المحددات والاشتراطات الواردة بكراسة الشروط والمواصفات ومنها الآتى:
1- بيانات وخبرات من سيعهد إليه من الباطن والمستندات الدالة على ذلك.
2- تحديد ما إذا كانوا من المشروعات المتوسطة أو الصغيرة أو المتناهية الصغر مع تقديم ما يثبت ذلك.
3- ألا يكون من المسجلين بسجل قيد أسماء الممنوعين من التعامل الذى تمسكه الهيئة العامة للخدمات الحكومية.
4- أن يكونوا من المؤهلين والمصرح لهم بمزاولة العمل محل التعاقد.
5- إقرار يفيد الالتزام بالتأمين على العمالة وفقا لقوانين التأمينات السائدة إذا تطلبت طبيعة العملية ذلك.
وغير ذلك من المحددات والاشتراطات التى تراها الجهة الإدارية لازمة.
ويجوز للمتعاقد أثناء فترة التعاقد أن يقوم بتغيير من أسند إليهم بعض بنود من الباطن إذا وجد مبررات لذلك، شريطة أن يكون بذات الكفاءة الفنية والخبرة وأن توافق عليه السلطة المختصة.
ولا يعفى المتعاقد من مسئوليته التعاقدية ويظل مسئولا وحدة عن أية أفعال أو أعمال أو أخطاء فى تنفيذ العقد، كما يلتزم باطلاع من أسند إليهم بعض بنود العملية من الباطن على ما يخصهم من شروط العقد.$m260$,'f4f698321123d38009db7d6db2bef268'),
(56,0,$m260$المادة 56$m260$,$m260$عند تعاقد الجهة الإدارية مع أحد الموظفين أو العاملين بها على شراء كتب من تأليفهم أو تكليفهم بأعمال فنية أو شرائها منهم إذا كانت ذات صلة بالأعمال المصلحية يتعين مراعاة الحدود والقواعد الآتية:
1- إتاحة الفرصة لهم ولغيرهم لتقديم عروضهم.
2- عدم وجود من يمكنه أداء العمل المطلوب من بين الموظفين أو العاملين ويدخل فى نطاق أعماله الوظيفية.
3- ألا يدخل العمل المطلوب ضمن الاختصاص الوظيفى للموظف أو العامل ولا يعتبر امتدادا له.
4- الحصول على الموافقة اللازمة من السلطة المختصة فيما لا يجاوز عشرين ألف جنيه وبعد أخذ رأى الهيئة العامة للخدمات الحكومية فيما يزيد على ذلك، وبالنسبة للكتب الدراسية فيكون لوزير التربية والتعليم سلطة الموافقة على شرائها طبقا لأحكام هذه اللائحة ما لم يكن الموظف أو العامل قد باع حق الطبع والنشر إلى مكتبة أو فرد بعقد ثابت التاريخ قبل الشراء بستة أشهر على الأقل.
وبالنسبة لشراء حق المؤلف أو الطبع أو النشر فيشترط أن يكون المؤلف وثيق الصلة بأعمال الجهة الإدارية وأن تكون الحاجة ماسة إلى الحصول عليه وألا تقل النسخ اللازمة منه عن ثلاث ألاف نسخة – ما لم يكن المؤلف قد وضع خصيصا بناء على طلب الجهة الإدارية فيجوز عند الضرورة أن يقل العدد عن ذلك - كما يشترط قيام لجنة تشكل من أخصائيين فى المادة التى تناولها المؤلف بفحص الكتاب وتقدير قيمته العلمية واقتراح المبلغ الذى تقدره مقابل هذا الشراء على أن يراعى فى تقدير القيمة عدد النسخ المطلوبة ومدة الانتفاع بهذا الحق ويصدر بهذا الشراء قرار من السلطة المختصة فيما لا يجاوز عشرين ألف جنيه، وبعد أخذ رأى الهيئة العامة للخدمات الحكومية فيما يزيد على ذلك.
ويكون شراء حق المؤلف أو الترجمة أو الطبع أو النشر بالنسبة إلى الأزهر الشريف ووزارة التربية والتعليم وفقا للقواعد التى يصدر بها قرار من رئيس مجلس الوزراء.$m260$,'58ea71a409eb75f69947409fc3f890ed'),
(57,0,$m260$المادة 57$m260$,$m260$بمراعاة المدد المنصوص عليها بالمادة (27) من القانون، تلتزم إدارة التعاقدات من خلال تنسيقها مع اللجان المعنية تضمين كراسة الشروط والمواصفات المدة المناسبة واللازمة لسريان العطاءات بحيث تكون كافية ومناسبة بحسب طبيعة وحجم العملية لتمكين اللجان الفنية والمالية من إتمام فحص ودراسة وتقييم ومقارنة العطاءات بالقدر الذى يمكنها من إتمام إجراءات الطرح والتعاقد وفقا للبرنامج الزمنى المحدد، وبما يتناسب مع التوقيتات اللازمة لتوفير محل العقد.$m260$,'df490255f72ae811ab688e82fe3994e8'),
(58,0,$m260$المادة 58$m260$,$m260$يكون تشكيل اللجان وفقا لما نصت عليه المادة (28) من القانون على أن تكون برئاسة موظف تتناسب درجته الوظيفية وخبراته مع قيمة وأهمية وطبيعة العملية ويضم إليها عضو من إدارة التعاقدات، وعضو من الإدارة الطالبة أو المستفيدة، ويجوز للسلطة المختصة ضم عضو أو أكثر من الجهة الإدارية أو غيرها وبحد أقصى ثلاثة أعضاء حسب طبيعة وأهمية العملية، وفى جميع الحالات يجب ألا يجاوز عدد أعضاء اللجنة خمسة عشر عضوا وتكون للجان البت أمانة فنية من ضمن أعضائها.
ويتعين على إدارة التعاقدات اخطار من تم ترشيحه بموافقة السلطة المختصة كتابة للبدء في إعمال شئونه، على أن يتضمن الإخطار موضوع العملية، موعد ومكان انعقاد اللجان، والجدول الزمنى للانتهاء من أعمالها.$m260$,'6421f932c86d26ded7f9f2714cb03a8e'),
(59,0,$m260$المادة 59$m260$,$m260$بمراعاة النصاب المالى المنصوص عليه بالمادة (29) من القانون يتم الرجوع للهيئة العامة للخدمات الحكومية بالنسبة لطلبات ترشيح ممثلي وزارة المالية فى لجان فتح المظاريف والبت فى المناقصات ولجنة الممارسة بأنواعهما وكذا لجان البيع أو التأجير أو الترخيص بالانتفاع أو بالاستغلال والتى تنعقد بكافة الجهات الإدارية والمصالح الواقعة داخل نطاق محافظات القاهرة والجيزة والقليوبية.
وبالنسبة لدواوين الوزارات ووحدات الإدارة المحلية والجامعات الإقليمية والكليات التابعة لها وفروع الهيئات العامة بالمحافظات وغيرها من الجهات الإدارية الواقعة فى نطاق كل محافظة بخلاف محافظات القاهرة والجيزة والقليوبية فيتم الترشيح فيها بمعرفة السادة المراقبين الماليين للوزارات والمديرين الماليين للمحافظات بحسب الأحوال.
ويتعين الأخذ فى الاعتبار تناسب المستوى الوظيفى والخبرة لممثلي وزارة المالية مع أهمية وطبيعة كل عملية والتأكد من الفصل بين عضوية وزارة المالية فى اللجان ومراجعة إجراءاتها، وعليهم التحقق من سلامة إجراءات التعاقد التى تقوم بها الجهات الادارية وفقا لأحكام القانون وهذه اللائحة.
ويجب على إدارة التعاقدات إخطار ممثل وزارة المالية أو عضو إدارة الفتوى المختصة بمجلس الدولة بحسب الأحوال أو ممثل وزارة الاسكان بالمواعيد المحددة لعمل تلك اللجان قبل الموعد المحدد لانعقادها بعشرة أيام على الأقل للبدء في إعمال شئونهم، على أن يرفق بالإخطار صورة من مستندات العملية وأن يتضمن تاريخ وساعة ومكان انعقاد اللجنة، وبالنسبة للمواعيد الخاصة باستكمال أعمال اللجنة فيراعى تحديدها كتابة بالتنسيق معهم قبل الموعد المحدد لانعقاد هذه اللجان بوقت كاف.
وفى حالة عدم صحة انعقاد اللجنة فى الموعد المحدد يتم استلام العطاءات والاحتفاظ بها مغلقة لدى مدير إدارة التعاقدات وإثبات ذلك فى محضر يوقع عليه من رئيس اللجنة وأعضاءها يرفع إلى السلطة المختصة لطلب تعديل موعد انعقاد اللجنة ليوم العمل التالى مباشرة مع إخطار أعضاء اللجنة وأصحاب العطاءات بالموعد الجديد بالإضافة للنشر على بوابة التعاقدات العامة.$m260$,'a8a45fb558ea277cc0e1c9393a623c1c'),
(60,0,$m260$المادة 60$m260$,$m260$يكون فتح المظاريف الفنية فى الوقت والمكان المحددين بكراسة الشروط والمواصفات فى جلسة علنية عامة بحضور من يرغب من أصحاب العطاءات، ويجوز لهم تفويض من يرونه لحضور الجلسة بدلا منهم شريطة تقديم التفويض الدال على ذلك.
ويقوم مدير إدارة التعاقدات بتسليم رئيس لجنة فتح المظاريف ملف العملية والعطاءات المحفوظة لديه، ويلتزم أعضاء اللجنة بالاطلاع على محتويات ملف العملية قبل بدء الجلسة للتحقق من صحة وسلامة الإجراءات التى سبق اتخاذها من إدارة التعاقدات، وعلى اللجنة اتخاذ الإجراءات الآتية:
1- يقوم رئيس اللجنة بفتح المظاريف فى الوقت والمكان المحددين بكراسة الشروط والمواصفات، وإثبات الحالة التى وردت عليها العطاءات بعد التحقق من سلامتها.
2- التحقق من تقديم العطاء من صاحبه أو من يفوضه شريطة تقديم التفويض الدال على ذلك.
3- القيام بحصر العطاءات وإثبات عددها فى محضر فتح المظاريف.
4- التحقق من وجود مظروفين منفصلين مقدمين عن كل عطاء أحدهما للعرض الفنى والآخر للعرض المالى وإثبات ذلك فى محضر فتح المظاريف.
5- ترقيم العطاءات على هيئة كسر اعتيادي بسطه رقم العطاء ومقامه عدد العطاءات الواردة، وإثبات رقم كل عطاء على المظروف الفنى وعلى المظروف المالى الذى يتم التحفظ عليه مغلقا.
6- إعادة تسليم المظاريف المالية بعد التوقيع عليها دون فتحها إلى مدير إدارة التعاقدات لحفظها لديه.
7- فتح المظاريف الفنية بالتتابع وكل مظروف يفتح يثبت رئيس اللجنة رقم العطاء عليه وعلى كل ورقة بداخله.
8- ترقيم الأوراق بداخل كل مظروف وإثبات عدد تلك الأوراق.
9- قراءة اسم صاحب العطاء وقيمة التأمين المؤقت وطريقة أدائه وغيرها من محتويات المظروف الفنى على الحاضرين من أصحاب العطاءات أو من يفوضونهم.
10- التوقيع من رئيس اللجنة ومن أعضائها على المظروف الفنى وكل ورقة بداخله.
11- التأشير بدائرة حمراء حول كل كشط أو تصحيح فى البيانات الواردة بالمظروف الفنى ويجب إثبات كل كشط أو تصحيح وضع حوله دائرة حمراء تفصيلا والتوقيع من رئيس اللجنة وجميع أعضائها على هذه التأشيرات.
12- التوقيع من رئيس اللجنة ومن جميع أعضائها على محضر اللجنة بعد إثبات كافة الخطوات المتقدمة فى السجل المعد لذلك.
13- تسليم خطابات الضمان أو إشعارات سداد التأمين المؤقت أو الإقرارات البديلة عن التأمين المؤقت إلى العضو المالى باللجنة لإعمال شئونه.
14- إرفاق المظاريف الفنية وجميع الأوراق المقدمة بها بمحضر اللجنة وتسليمها لمدير إدارة التعاقدات وذلك لحفظها لديه.
15- مراجعة العينات السابق تقديمها من أصحاب العطاءات على الكشف الذى دونت به عند ورودها بعد التأكد من سلامة أختامها وأغلفتها ويوقعها رئيس اللجنة مع جميع أعضائها كما يوقعون على العينات التى ترد مع المظاريف الفنية بعد إثباتها فى كشف خاص وتسلم جميع العينات إلى مدير إدارة التعاقدات أسوة بأوراق العطاءات.
ويجب أن تتم لجنة فتح المظاريف الفنية عملها بأكمله فى الجلسة ذاتها، ولا يحق لها أن تستبعد أى عطاء أو أن تطلب من أصحاب العطاءات تصحيح الأخطاء أو تلافى الملاحظات الواردة فى عطاءاتهم، أو اتخاذ أى قرارات تتعلق بالعطاءات المقدمة وينحصر دورها في توثيق محتويات المظاريف وأية مخالفات فى الإجراءات السابقة على عملها.
وعلى إدارة التعاقدات نشر محضر فتح المظاريف الفنية على بوابة التعاقدات العامة فور الانتهاء من أعمال اللجنة وبعد التأكد من توقيع رئيس اللجنة وأعضاءها عليه.$m260$,'893e34e2ebbb3d4a4cf7454ae85fbce3'),
(61,0,$m260$المادة 61$m260$,$m260$أى عطاء يرد بعد موعد فتح المظاريف الفنية المحدد بكراسة الشروط والمواصفات يجب تقديمه فور وروده إلى رئيس لجنة فتح المظاريف للتأشير عليه بساعة وتاريخ وروده دون فتحه ثم يدرج فى كشف العطاءات المتأخرة، ويتم ترقيمه على هيئة كسر اعتيادي بسطه رقم العطاء ومقامه عدد العطاءات المتأخرة.
وتستبعد لجنة البت العطاءات المتأخرة ويتم ردها إلى أصحابها بمعرفة إدارة التعاقدات خلال مدة لا تجاوز يومين من قرار اللجنة.$m260$,'4524883d5094a5d7dc5e6b60d9ba0b78'),
(62,0,$m260$المادة 62$m260$,$m260$تتولى إدارة التعاقدات بالتنسيق مع إدارة المخازن فرز عينات كل صنف وقيده بالسجل الخاص بالعينات ويجب أن يبين بهذا السجل تاريخ العملية ونوعها وعلى مدير إدارة التعاقدات أن يرسل فورا أو فى خلال اليومين التاليين على الأكثر من تاريخ قيام لجنة البت بالفحص الشكلي ما يقتضى إرساله منها إلى الجهة الفنية المختصة؛ حتى يتسنى إجراء الفحص الفنى المطلوب على وجه السرعة ومراعاة مدة صلاحية العطاءات والوقت المطلوب لإتمام إجراءات البت والاخطار بالترسية، وعند ورود التقارير الخاصة بها تدون جميع البيانات بالسجل المذكور أمام كل عينة ليعرض على لجنة البت.
ويجب التحقق من مطابقة العينات المقدمة مع العطاءات للمواصفات ومدى ملاءمتها للغرض المطلوبة من أجله وذلك بالفحص النظري أو الفنى أو بالتحليل المعملي أو بالتجربة العملية، بحسب الأحوال، وذلك بمعرفة الجهة الإدارية أو بأى من الجهات الخاضعة لأحكام القانون - وعلى مدير إدارة التعاقدات أن يضع على العينات أرقاما سرية مع مراعاة تعليمات الجهة الفاحصة، ويرسل معها كشفا تفصيليا ببيان مفرداتها والغرض الذى من أجله يراد توريد الصنف ومقدار الكمية المطلوبة منه.
ويجب توضيح ما قد يوضع عليها من أرقام سرية وأختام وتوقيعات لتميزها ولضمان عدم استبدال غيرها بها مع ذكر التاريخ المحدد للبت فى العملية وذلك لكى تقوم الجهة الفاحصة بفحصها وموافاة إدارة التعاقدات بالنتيجة قبل التاريخ المذكور بوقت كاف يسمح بدراسة العطاءات على ضوء نتيجة فحص العينات ورفع التوصيات اللازمة للجنة البت فى العملية فى الميعاد المحدد، وعلى جهة الفحص الفنى أن تقوم بفحص العينات واختبارها بالتتابع، وأن تختمها وتضع عليها أرقاما سرية أخرى لتميزها، وترسل عنها تقريرا وافيا بالنتيجة من حيث مطابقتها للمواصفات من عدمه، ويبين به نسبة الجودة مئوية لكل عينة تم تحليلها وعلى مدير إدارة التعاقدات أن يتحقق من حفظ تقارير المعمل الفنى التى ترد تباعا بملفات العمليات بعد إثباتها فى السجل الخاص بذلك وقبل عرضها على لجنة البت وكذلك التأشير أمام كل تقرير برقم الملف المحفوظة فيه.$m260$,'1191c7eaeb426674966bf2371902935a'),
(63,0,$m260$المادة 63$m260$,$m260$يقوم مدير إدارة التعاقدات بتسليم رئيس لجنة البت العطاءات المحفوظة لديه ومحضر فتح المظاريف الفنية، وعلى اللجنة اتخاذ الإجراءات الآتية:
1- الفحص الشكلي للعطاءات والتأكد من أنها قد استوفت الشكل القانوني وفقا لمتطلبات شروط الطرح.
2- استبعاد العطاءات المتأخرة، وغيرها من عطاءات غير صالحة للنظر فيها، ومنها العطاءات غير الموقعة من أصحابها، أو الغير مكتملة وفقا للشروط، أو العطاءات غير المستوفاة للتأمين المؤقت، أو العطاءات التى يتبين أن أصحابها من غير المسجلين على بوابة التعاقدات العامة، أو أنهم من المسجلين بسجل قيد أسماء الممنوعين من التعامل الذى تمسكه الهيئة العامة للخدمات الحكومية، أو العطاءات التى لم تضمن معاملات تغير الأسعار في مقاولات الأعمال طبقا لشروط الطرح، أو العطاءات المقدمة بالمخالفة للحظر المنصوص عليه بالمادة (33) من القانون.
وتعد لجنة البت محضرا بنتيجة الفحص الشكلي، متضمنا أسباب استبعاد العطاءات، يتم توقيعه من رئيس اللجنة وأعضاءها ويحفظ بملف العملية.
3- يكلف رئيس لجنة البت الأمانة الفنية للقيام بتفريغ العروض الفنية للعطاءات المستوفية للشكل القانوني، وذلك على الاستمارة المعدة لذلك من ثلاث صور على أن يتم حفظ العروض الفنية محل التفريغ فى آخر كل يوم لحين الانتهاء من تفريغها، وتدون جميع ملاحظات واشتراطات أصحاب العطاءات، وتعمل مطابقة للعروض على كشوف التفريغ من اثنين من أعضاء لجنة البت يحددهما رئيسها وتوقع بما يفيد هذه المطابقة، ويجب أن يتم ذلك فى أقل وقت ممكن؛ حتى يتسنى البت فى العملية قبل انقضاء مدة سريان العطاءات، وتقدم الأمانة الفنية كشوف تفريغ العروض الفنية إلى رئيس لجنة البت.$m260$,'d402a2606e59976597a0f139d7acbab9'),
(64,0,$m260$المادة 64$m260$,$m260$على لجنة البت الاطلاع على كشوف تفريغ العروض الفنية للعطاءات المستوفية للشكل القانوني، وتتولى الإجراءات الآتية:
1- التأكد من توافر الكفاءة الفنية وفقا للمعايير المحددة بكراسة الشروط والمواصفات، من خلال الاطلاع على سابقة الأعمال، ومعدلات الأداء فيما تم توريده أو تنفيذه، وعدد العمليات المشترك فيها حاليا صاحب العطاء.
2- التحقق من توافر الملاءة المالية لصاحب العطاء وما إذا كان لديه المقدرة المالية من سيولة وغيرها من عدمه لتنفيذ العملية من خلال دراسة ميزانيته وقائمة المركز المالى، والتدفقات النقدية بحسب طبيعة محل التعاقد، وغيرها من أمور ذات صلة.
ويجب عند دراسة العروض الفنية مراعاة ما ورد بكراسة الشروط والمواصفات ومنها:
أ- مدى قدرة صاحب العطاء على الالتزام بالتوريد أو التنفيذ بالمواعيد المحددة بشروط الطرح.
ب- الالتزام بمدة سريان العطاءات المنصوص عليها بشروط الطرح.
ج- مدى تلبية العطاءات للمواصفات الفنية الجوهرية أو لمعايير الاداء المحددة بشروط الطرح.
د- الالتزام بالبنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن، وكذا المحددات والاشتراطات الأخرى ذات الصلة.
وفى جميع الحالات يتعين على اللجنة للوقوف على قدرة وكفاءة أصحاب العطاءات وبما لا يخل بمبدأ تكافؤ الفرص أن تستطلع رأى الجهات الإدارية السابق تعاملهم معها، وإجراء الزيارات الميدانية إذا تطلب الأمر ذلك.
إذا تبين للجنة البت أن صاحب العطاء قد استعمل بنفسه أو بواسطة غيره الغش أو التلاعب فى تعامله مع الجهة الإدارية للحصول على العقد وجب على اللجنة استبعاد عطائه، ويصبح التأمين المؤقت من حق الجهة الإدارية، ويتم شطب اسمه من سجل المتعاملين بعد أخذ رأى إدارة الفتوى المختصة بمجلس الدولة، وتخطر الهيئة العامة للخدمات الحكومية بذلك لنشر قرار الشطب بطريق النشرات المصلحية وعلى بوابة التعاقدات العامة.
ويجوز للجنة البت أن تشكل من بين أعضاءها أو غيرهم من أهل الخبرة لجنة فنية فرعية تعهد إليها باتخاذ الإجراءات السابقة، على أن ترفع تقريرا بنتائج دراستها للعروض الفنية إلى لجنة البت خلال المدد المحددة لها بالبرنامج الزمنى.$m260$,'ad130b38f951b6a53dea238d9ce0787c'),
(65,0,$m260$المادة 65$m260$,$m260$يجوز لإدارة التعاقدات بناء على طلب لجنة البت استيفاء البيانات أو المستندات التى تساعد اللجنة على استيضاح ما غمض من أمور فنية من أصحاب العطاءات بما يعينها فى اعداد التقرير الفنى اللازم وذلك خلال مدة لا تجاوز ثلاثة أيام من تاريخ اخطارهم ودون أن يخل ذلك بمبدأ تكافؤ الفرص والمساواة بين جميع أصحاب العطاءات.
ولا يعتد بأي توضيح يقدم من صاحب العطاء اذا لم تطلبه اللجنة، ويجب ان يكون طلب استيفاء البيانات أو المستندات اللازمة لاستيضاح الامور الفنية والرد عليه كتابة، وان لا يؤدي أو يوحي أو يسمح ذلك بأي تغيير في العطاء المقدم أو طبيعته.
وفي حالة عدم استجابة صاحب العطاء لطلب استيفاء البيانات أو المستندات لاستيضاح الامور الفنية بعطائه خلال المدة المحددة من اللجنة والموضحة بطلبها اليه، يتم استبعاد عطائه باعتباره غير واضح أو غير قابل للمقارنة مع العطاءات الأخرى.$m260$,'f9ad2bf878faac4cab9c6deca708f4ae'),
(66,0,$m260$المادة 66$m260$,$m260$تقوم لجنة البت بإعداد محضر يتضمن ما انتهت إليه توصياتها بناء على دراستها من قبول، أو استبعاد للعطاءات مع ذكر أسباب عدم القبول تفصيلا وترفع محضرها للسلطة المختصة للاعتماد.$m260$,'4fa1c11cc7b4333f6809b8311e02ee0f'),
(67,0,$m260$المادة 67$m260$,$m260$على إدارة التعاقدات فور اعتماد السلطة المختصة لتوصيات لجنة البت اخطار أصحاب العطاءات بنتائج قرارات اللجان بالقبول أو أسباب الاستبعاد، أو الإلغاء بخطابات ترسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد مع تعزيزه فى الوقت ذاته بالبريد الإلكترونى، أو الفاكس، بحسب الأحوال، وفقا لعناوينهم وبياناتهم الواردة بالعطاء ويكون لهم الحق فى التقدم بشكواهم كتابة خلال سبعة أيام تبدأ من اليوم التالى لإخطارهم بالقرار.
وفور ارسال الإخطارات يتم نشر النتيجة فى لوحة الإعلانات المخصصة لهذا الغرض ولمدة سبعة أيام، كما يتم النشر على بوابة التعاقدات العامة، وبعد انقضاء هذه المدة يتم اخطار أصحاب العطاءات المقبولة فنيا بموعد ومكان جلسة فتح المظاريف المالية ما لم يكن هناك شكاوى محل دراسة.$m260$,'710b0a3d717a056e56538d4d19e49582'),
(68,0,$m260$المادة 68$m260$,$m260$تجتمع لجنة فتح المظاريف بتشكيلها السابق ذاته فى الموعد والمكان المحددين لفتح المظاريف المالية للعروض المقبولة فنيا فقط، وتتولى اللجنة مباشرة إجراءاتها فى جلسة علنية عامة بحضور من يرغب من أصحاب العطاءات المقبولة عروضهم الفنية، ويجوز لهم تفويض من يرونه لحضور الجلسة شريطة تقديم التفويض الدال على ذلك.
ويقوم مدير إدارة التعاقدات بتسليم رئيس اللجنة المظاريف المالية وعليه التحقق من سلامتها ووجود رقم العطاء وتوقيع أعضاء اللجنة السابق إثباته على كل مظروف بجلسة فتح المظاريف الفنية، وعلى اللجنة اتخاذ الإجراءات الآتية:
1- فتح المظاريف المالية بالتتابع وكل ظرف يفتح يثبت رئيس اللجنة عدد أوراقه التى بداخله.
2- التوقيع من رئيس اللجنة وأعضائها على كل ورقة بداخل المظروف المالى.
3- التأشير بدائرة حمراء حول كل كشط أو تصحيح أو تحشير فى الأرقام أو الإجماليات الواردة بالظرف والتوقيع بجانبه من رئيس اللجنة وأعضائها على هذه التأشيرات.
4- قراءة اسم صاحب العطاء ومحتويات المظروف المالى على الحاضرين من أصحاب العطاءات أو من يفوضونهم.
5- التوقيع من رئيس اللجنة وجميع أعضاءها على محضر اللجنة بعد اثبات كافة الخطوات السابقة.
6- إرفاق المظاريف المالية وجميع الأوراق المقدمة بها بمحضر اللجنة وتسليمها لمدير إدارة التعاقدات، وذلك لحفظها لديه.
ويجب أن تتم لجنة فتح المظاريف المالية عملها بأكمله فى الجلسة ذاتها، ولا يحق لها أن تستبعد أى عطاء، أو أن تطلب من أصحاب العطاءات تصحيح الأخطاء، أو تلافى الملاحظات الواردة فى عطاءاتهم أو اتخاذ أى قرارات تتعلق بالعطاءات المقدمة، وينحصر دورها فى تنفيذ الإجراءات المنصوص عليها بهذه المادة وتوثيق محتويات المظاريف.
وعلى إدارة التعاقدات نشر محضر فتح المظاريف المالية على بوابة التعاقدات العامة فور الانتهاء من أعمال اللجنة وبعد التأكد من توقيع رئيس اللجنة وأعضاءها عليه.$m260$,'884ecfdf9f0a173b6a99974032a68028'),
(69,0,$m260$المادة 69$m260$,$m260$تجرى عملية تفريغ العروض المالية وفقا للبند (3) من المادة (63) من هذه اللائحة بالنسبة لتفريغ العروض الفنية.
ويكلف رئيس لجنة البت اثنين من أعضاء اللجنة لمراجعة العروض المالية بعد تفريغها مراجعة حسابية تفصيلية والتوقيع عليها بما يفيد هذه المراجعة، وتكون نتيجة هذه المراجعة هي الأساس الذى يعول عليه فى تحديد سعر العطاء، وإذا تبين من المراجعة وجود أخطاء حسابية فيجب تصحيحها وفقا لأى من الحالات الآتية:
1- اختلاف بين سعر الوحدة وإجمالي سعر الوحدات يعول على سعر الوحدة.
2- اختلاف بين السعر المبين بالتفقيط وبين السعر المبين بالأرقام يعول على السعر المبين بالتفقيط.
3- تقديم أكثر من نسخة للعطاء طبقا للكراسة وتبين وجود اختلاف فى السعر بين النسخ المقدمة يعول على ما جاء بالنسخة الأصلية.$m260$,'e461f933b43cea955e745bd8c8ae6c1d'),
(70,0,$m260$المادة 70$m260$,$m260$بعد الانتهاء من تفريغ ومراجعة العروض المالية تقوم لجنة البت بإعمال شئونها، ويجوز لها أن تعهد إلى لجنة مالية فرعية متخصصة من بين أعضائها أو غيرهم بدراسة وتحليل وتقييم العروض ماليا، واعداد تقرير بنتيجة أعمالها يقدم إلى لجنة البت، وعليها القيام بإجراء المقارنة والمفاضلة بين العروض بعد توحيد أسس المقارنة من جميع النواحى الفنية والمالية مع مراعاة تكاليف دورة حياة المنتج وفقا لما هو وارد بكراسة الشروط والمواصفات، وكذا أى اشتراطات أخرى وردت بها وبحسب ظروف وطبيعة موضوع التعاقد مع الأخذ فى الاعتبار الآتى:
1- شروط السداد والاستلام، والضمان، والصيانة وقطع الغيار ومستلزمات التشغيل، وغيرها من العناصر التى تؤثر فى تحديد القيمة المالية المقارنة للعطاءات.
2- تقييم العناصر غير السعرية وتحويلها إلى قيمة مالية مثل تكاليف التشغيل، القدرات، الكفاءة، الأداء وفقا لما هو وارد بكراسة الشروط والمواصفات.
3- حساب نسبة الدفعة المقدمة وذلك بغرض المقارنة والمفاضلة بإضافة فائدة تعادل سعر الفائدة المعلن من البنك المركزى فى تاريخ جلسة فتح المظاريف الفنية إلى قيمة العطاءات المقترنة بالدفعة المقدمة إذا أقرت كراسة الشروط والمواصفات ذلك، وذلك عن المبالغ المطلوب دفعها مقدما وتحسب الفائدة عن المدة من تاريخ أداء هذه المبالغ حتى تاريخ استحقاقها الفعلي.
4- حساب نسبة الأفضلية الممنوحة للمنتج المستوفى لنسبة المكون الصناعى المصرى.
5- حساب نسبة الأفضلية الممنوحة للخدمات أو الأعمال الفنية التى تقوم بها جهات مصرية.
6- فى حالة تقديم العطاء بعملات أجنبية يتم معادلتها بالعملة المصرية بالسعر المعلن من البنك المركزى فى تاريخ فتح المظاريف الفنية.
7- إذا سكت صاحب العطاء فى عرضة المالى عن تحديد سعر صنف من الأصناف المطلوب توريدها بقائمة الأسعار المقدمة منه فيعتبر ذلك امتناعا منه عن الدخول فى هذا الصنف، أما فى مقاولات الأعمال فللجهة الإدارية مع الاحتفاظ بالحق فى استبعاد العطاء أن تضع للبند الذى سكت صاحب العطاء عن تحديد فئته أعلى فئة لهذا البند فى العطاءات المقبولة وذلك للمقارنة بينه وبين سائر العطاءات فإذا أرسيت عليه العملية فيعتبر أنه ارتضى المحاسبة على أساس أقل فئة لهذا البند فى العطاءات المقبولة دون أن يكون له حق المنازعة فى ذلك.
8- لا يعتد بالعطاء المبنى على خفض نسبة مئوية عن قيمة أقل عطاء مقدم فى العملية.
9- فى حالة تساوى الأسعار بين عطاءين أو أكثر من المقبولين ماليا فيحق للجنة البت ترجيح أحداهما وفقا لمبررات تبديها بمحضرها بناء على ما اشتمل عليه كل عطاء، ويجوز تجزئة المقادير المعلن عنها بين مقدميها إذا كان ذلك فى مصلحة العمل وتضمنت مستندات الطرح ما يفيد ذلك.
وغيرها من العناصر التى تؤثر فى تحديد القيمة المقارنة للعطاءات بحسب ظروف وطبيعة موضوع التعاقد وفقا لما هو وارد بكراسة الشروط والمواصفات.$m260$,'b78b7bf961bed67192d0f6b4a625a6b2'),
(71,0,$m260$المادة 71$m260$,$m260$يجوز لإدارة التعاقدات بناء على طلب لجنة البت أن تستوفى البيانات، أو المستندات التى تساعد اللجنة على استيضاح ما غمض من أمور مالية من أصحاب العطاءات المقبولة عروضهم فنيا بما يعينها فى اعداد التقرير المالى اللازم، وذلك خلال مدة لا تجاوز ثلاثة أيام من تاريخ اخطارهم ودون أن يخل ذلك بمبدأ تكافؤ الفرص والمساواة بين جميع أصحاب العطاءات.
ولا يعتد بأي توضيح يقدم من صاحب العطاء اذا لم تطلبه اللجنة، ويجب ان يكون طلب استيفاء البيانات، أو المستندات اللازمة لاستيضاح الامور المالية والرد عليه كتابة، وان لا يؤدي، أو يوحي، أو يسمح ذلك بأي تغيير في الأرقام والمبالغ وشكل العطاء المقدم، أو طبيعته.
وفي حالة عدم استجابة صاحب العطاء لطلب استيفاء البيانات أو المستندات المطلوبة لاستيضاح الامور المالية بعطائه خلال المدة المحددة من اللجنة والموضحة بطلبها اليه، يتم استبعاد عطائه باعتباره غير واضح، أو غير قابل للمقارنة مع العطاءات الأخرى.$m260$,'4753157d2ee93dab6d3a085685313a4c'),
(72,0,$m260$المادة 72$m260$,$m260$فى حالات التعاقد التى تتطلب الطبيعة الفنية فيها تقييم العروض بنظام النقاط يتم تضمين شروط الطرح أسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول ومنها على سبيل المثال وبحسب طبيعة العملية الآتى:
1- المواصفات الفنية أو معايير الأداء.
2- خدمة ما بعد البيع.
3- مدة الخبرة فى المجال المطلوب تنفيذه.
4- الكوادر الفنية والإدارية العاملة لدى صاحب العطاء بشكل دائم.
5- المشروعات التى تم تنفيذها بنجاح، وقيمة أعلى مشروع.
6- الملاءة المالية لصاحب العطاء من خلال ميزانية مدققة.
7- المعدات والآلات والأجهزة المتوفرة لدى صاحب العطاء، والضرورية لإنجاز العمل المطلوب.
8- أى بيانات أو معلومات ترى الجهة الإدارية أنها ضرورية وتكون محل تقييم.
وغيرها من أسس وعناصر تراها الجهة الإدارية وفقا لطبيعة كل عقد.
ويكون البت المالى وفقا لألية التقييم المحددة بشروط الطرح ومنها ترتيب أولوية العطاءات بقسمة القيمة المالية المقارنة لكل عطاء على مجموع النقاط الفنية الحاصل عليها، وذلك للحصول على تكلفة الدرجة الفنية لكل عطاء ويتم الترسية على العطاء الذى حصل على أقل قيمة مقارنة.$m260$,'d6218859ff54bbccf322de90bf3ce9e5'),
(73,0,$m260$المادة 73$m260$,$m260$على مدير إدارة التعاقدات عند دراسة العروض المالية تسليم رئيس لجنة البت ظرف القيمة التقديرية المحفوظ لديه، ويلتزم أعضاء اللجنة بالاطلاع عليه قبل بدء أعمالها للتحقق من غلقة بطريقة محكمة، والتأكد من توقيع أعضاء لجنة وضع القيمة التقديرية واعتماد السلطة المختصة لها.
ويجب أن تقوم لجنة البت باستبعاد العطاءات غير المطابقة للشروط، وتتولى المقارنة بين قيمة العطاءات المقبولة بما يناظره بالقيمة التقديرية، مع مراعاة الإجراءات المنصوص عليها بالمواد (68)، (69)، (70)، (71)، و(72) من هذه اللائحة.$m260$,'b5a286a1bcbef920f1e5dc1e0abb7b13'),
(74,0,$m260$المادة 74$m260$,$m260$إذا ما تبين للجنة البت عند دراسة العروض المالية أن العطاء الأقل سعرا منخفض انخفاضا غير عادي مقارنة بالعطاءات الأخرى والقيمة التقديرية فعليها أن توثق ذلك فى محضرها.
ولغرض ضمان تنفيذ محل العقد تطلب من إدارة التعاقدات مخاطبة صاحب العطاء المنخفض كتابة لموافاتها بتفاصيل ومعلومات عطائه والأسس التى استند عليها فى وضع أسعاره وغيرها من العناصر التى أثرت فى إعداد عطائه.
وعلى صاحب العطاء خلال مدة لا تجاوز ثلاثة أيام من تاريخ إخطاره موافاة إدارة التعاقدات بكافة التفاصيل والمعلومات التى استند عليها فى التسعير كتابة، وعلى اللجنة دراسة ما ورد منه، فإذا ما تبين لها أن الأسس التى استند عليها مقبولة يمكنها قبول العطاء، وإذا ما تبين لها أن الأسس التى استند عليها غير واقعية ويتعذر التوريد أو التنفيذ بها، وجب عليها التوصية باستبعاد عطائه والترسية على العطاء التالى فى الترتيب بشرط أن يكون مناسبا للقيمة التقديرية.$m260$,'9fd2c164ed060080b133fb12b3465945'),
(75,0,$m260$المادة 75$m260$,$m260$بمراعاة الحالة المبينة بالبند (3) من المادة (37) من القانون على لجنة البت قبل التوصية باتخاذ قرار الإلغاء دراسة الآثار المترتبة عليه أخذا فى الاعتبار الآتى:
1- جدوى إعادة الطرح.
2- احتمالات الوصول إلى سعر أقل من عدمه.
3- ما يمكن أن تتكبده الجهة الإدارية من نفقات لإعادة الطرح.
وغير ذلك من اعتبارات تؤثر فى قرار الإلغاء.
وعلى اللجنة أن تضمن محضرها ما اتخذته من اجراءات وتوصيات إما باستكمال إجراءات إلغاء العملية أو ارسائها.$m260$,'b07cd3d5d248e942b1112c8c0046ca4c'),
(76,0,$m260$المادة 76$m260$,$m260$على إدارة التعاقدات فور اعتماد السلطة المختصة لمحضر لجنة البت اتباع الإجراءات ذاتها المنصوص عليها بالمادة (67) من هذه اللائحة.$m260$,'2f6b6c40e35139540d717a4a27893328'),
(77,0,$m260$المادة 77$m260$,$m260$بمراعاة إجراءات البت المالى، وبعد التأكد من عدم وجود أية شكاوى لم يفصل فيها، سواء عن طريق الجهة الإدارية أو مكتب شكاوى التعاقدات العمومية، ترفع لجنة البت محضرا بتوصياتها النهائية للسلطة المختصة بإرساء العملية على صاحب العطاء الفائز للاعتماد أو تقرير ما تراه.$m260$,'6120a134d45e91ef328b6281a5f7c522'),
(78,0,$m260$المادة 78$m260$,$m260$تتولى إدارة التعاقدات بعد انقضاء السبعة أيام المنصوص عليها بالمادة (39) من القانون وخلال مدة لا تجاوز يومين إخطار صاحب العطاء الفائز بترسية العملية عليه، وكذا إخطار باقى أصحاب العطاءات بذلك على أن يتضمن الإخطار البيانات الآتية:
1- طريق التعاقد ورقم واسم العملية.
2- تاريخ فتح المظاريف الفنية.
3- اسم صاحب العطاء الفائز وعنوانه.
4- قيمة الترسية.
5- التأمين النهائى المطلوب سداده.
وعلى صاحب العطاء الفائز سداد قيمة التأمين النهائى خلال المدة المحددة لذلك، وفور سداده يتم اخطاره بأمر التوريد، أو أمر الإسناد، بحسب الأحوال، والموعد المحدد للتوقيع على العقد.$m260$,'a3061ead958f44cec7acbe38fe3f29cb'),
(79,0,$m260$المادة 79$m260$,$m260$فى عقود شراء أو استئجار المنقولات، أو العقارات، أو التعاقد على مقاولات الأعمال، أو تلقى الخدمات، أو الأعمال الفنية، أو الدراسات الاستشارية وحال عدم التزام صاحب العطاء الفائز بأداء التأمين النهائى خلال المدة المحددة لسداده على إدارة التعاقدات إعداد مذكرة للعرض على السلطة المختصة باقتراح منح صاحب العطاء الفائز مهلة إضافية بما لا يجاوز عشرة أيام عمل.
وإذا لم يقم صاحب العطاء الفائز بسداد التأمين النهائى يتم اتخاذ أحد الإجراءين التاليين وبما يحقق مصلحة الجهة الإدارية وهما:
1- الغاء العقد.
2- التنفيذ بواسطة أحد العطاءات التالية له فى الترتيب بشرط أن يكون فى حدود القيمة التقديرية.
وفى جميع حالات عدم سداد التأمين النهائى يكون التأمين المؤقت من حق الجهة الإدارية، كما يكون لها أن تخصم قيمة أية خسائر فعليه تلحق بها تسبب فيها صاحب العطاء الفائز وفى حالة عدم كفايتها لديها؛ يتم خصمها لدى أية جهة إدارية أخرى مع عدم الإخلال بحقها فى الرجوع عليه قضائيا بما لم تتمكن من استيفائه من حقوق بالطريق الإدارى.$m260$,'99fc60daea7f43b7411510d03ecc677e'),
(80,0,$m260$المادة 80$m260$,$m260$يكون التأمين النهائى ضامنا لتنفيذ العقد، ويتم الاحتفاظ به إلى أن يتم تنفيذ العقد بصفة نهائية بما فى ذلك مدة الضمان طبقا للشروط، ويتم سداده بأية وسيلة يصدر بشأنها قرار من وزير المالية ومنها وسائل الدفع الإلكترونى من خلال منظومة الدفع والتحصيل الإلكترونى أو بأية صورة من الصورتين الآتيتين:
1- بموجب خطاب ضمان صادر من أحد المصارف المحلية المعتمدة وألا يقترن بأى قيد، أو شرط وأن يقر فيه المصرف بأن يدفع تحت أمر الجهة الإدارية مبلغا يوازى التأمين المطلوب.
وعندما يرد لإحدى الجهات الإدارية خطابات ضمان عن التأمين المستحق من أحد المصارف المرخص لها فى إصدار خطابات الضمان أو أحد فروعها عليها أن تتحقق من أن المصرف أو الفرع قد أعطى إقرارا على خطابات الضمان بأنه لم يجاوز الحد الأقصى المحدد لمجموع خطابات الضمان المرخص للمصرف فى إصدارها.
فإذا تبين عند مراجعة الإخطارات لدى البنك المركزى أن المصرف قد تعدى الحد الأقصى المحدد له أخطرت الجهة الإدارية فورا لمطالبة المصرف بأن يؤدى إليها فى ميعاد لا يجاوز ثلاثة أيام عمل قيمة خطاب الضمان.
وتقبل خطابات الضمان من البنوك الخارجية بشرط التأشير عليها بالقبول من أحد المصارف المحلية المعتمدة على أن يتعهد المصرف المحلى بأن يدفع للجهة الإدارية مبلغ يوازى التأمين المطلوب وأنه ملتزم بأدائه بأكمله دون الالتفات إلى أى معارضة من صاحب العطاء.
2- يجوز لصاحب العطاء الفائز سداد التأمين النهائى خصما من مستحقاته الصالحة للصرف من عمليات أخرى فى ذات الجهة الإدارية وفى الوقت المحدد للسداد.
ويكون التأمين النهائى ساريا لمدة تبدأ من وقت إصداره إلى ما بعد انتهاء مدة العقد بثلاثة أشهر إلا إذا اتفق على غير ذلك.
كما يجوز بموافقة السلطة المختصة وبناء على طلب صاحب العطاء استبدال التأمين النهائى المسدد منه بأحد صور السداد الأخرى المنصوص عليها بهذه المادة بشرط ألا تنقطع مدة سريان التأمين وعدم الإخلال بمسئوليته طبقا للغرض المقدم عنه التأمين.
ويتم رد التأمين النهائى فى الحالات المنصوص عليها بالقانون وهذه اللائحة بالوسيلة ذاتها التى تم أداؤه بها.
ويجب أن تتضمن مستندات الطرح صور سداد ورد التأمين النهائى على وجه التحديد.$m260$,'32689c9724ff8cbe84dd3b401fcaed8f'),
(81,0,$m260$المادة 81$m260$,$m260$على الجهات الإدارية تضمين شروط الطرح الحظر المنصوص عليه بالمادة (33) من القانون، وفى حالة مخالفته يجب على الجهة الإدارية استبعاد العطاءات المخالفة وأيلولة التأمين المؤقت لصالح الجهة الإدارية، أو فسخ العقد، أو تنفيذه على حساب المتعاقد وأيلولة التأمين النهائى للجهة الإدارية وتحميل المتعاقد بأى خسائر تلحق بها، وإخطار جهاز حماية المنافسة ومنع الممارسات الاحتكارية بأية مخالفة لهذا الحظر، أو أى من المخالفات ذات الصلة المنصوص عليها بأحكام قانون حماية المنافسة ومنع الممارسات الاحتكارية الصادر بالقانون رقم 3 لسنة 2005 ولائحته التنفيذية على أن يتضمن الإخطار بيان المخالفة التى تبينت للجهة الإدارية وما يدعمها من أدلة إن وجدت وكامل مستندات العملية وخاصة الآتى:
1- صورة من كراسة الشروط والمواصفات.
2- صورة الإعلان أو الدعوة بحسب الأحوال.
3- صورة قرار السلطة المختصة بتشكيل لجان العملية.
4- قائمة بأسماء من حصل على كراسة الشروط.
5- قائمة بمقدمي العطاءات موضحا بها المنسحبين أو المستبعدين.
6- صورة من العطاءات المقدمة.
7- صورة من محاضر اللجان.
8- قائمة بأسماء العاملين بإدارة التعاقدات.
9- الإفادة بكون العطاء متكرر من عدمه، وفى حالة كون العطاء متكرر يجب توفير صورة من العطاءات السابقة المتقدمة فى العمليات وتاريخ تقدم هذه العطاءات وأرقامها.$m260$,'3a478a1cbc6dc3586a6b62b585bcc7e9'),
(82,0,$m260$المادة 82$m260$,$m260$لا يعتد بأى عطاء أو تعديل فيه يرد بعد الموعد المحدد لجلسة فتح المظاريف الفنية، ويحظر التعديل فى أسعار العطاءات المقدمة بعد هذا الموعد، ويسرى هذا الحظر على صاحب العطاء الفائز.$m260$,'f4f96f1eb9931d61f70d1cf4089480c3'),
(83,0,$m260$المادة 83$m260$,$m260$إذا اختلف أعضاء لجنة البت فى الرأي حول قبول أو رفض أى من العطاءات فيتم إثبات ذلك تفصيلا فى محضر اللجنة ويكون الفصل فيه للسلطة المختصة.$m260$,'b7a0c8ac4c9d4d749a4f7c1e77cab0e6'),
(84,0,$m260$المادة 84$m260$,$m260$يجب على مدير إدارة التعاقدات عقد اجتماع لمن يطلب من أصحاب العطاءات غير المقبولة بعد انتهاء أعمال لجنة البت لإيضاح أسباب عدم قبولهم، وذلك بغرض تلافى كل منهم الأسباب التى أدت إلى ذلك ولتحسين أدائهم فى العمليات اللاحقة.$m260$,'a14869fcc5afdfc1b72fad03eeb5d27d'),
(85,0,$m260$المادة 85$m260$,$m260$يجوز أن تصدر السلطة المختصة قرارا بتكليف من تراه مناسبا من ذوى الخبرة بالجهة الإدارية لإدارة العقد فى العمليات التى تم التعاقد عليها، وله الاستعانة بمن يرى من ذوي الخبرات والتخصصات المختلفة لمعاونته في مهامه ويتعين على إدارة التعاقدات اخطار المتعاقد كتابة بهذا القرار.
وبمراعاة المادة (43) من القانون يتولى مسئول إدارة العقد المهام الآتية:
1- مراجعة شروط العقد والبرنامج الزمنى للتوريد، أو التنفيذ والتأكد من تنفيذه وفقا للشروط والمواصفات الفنية والمتطلبات الأخرى وفى المواعيد المحددة به.
2- التأكد من قيام المتعاقد بالوفاء بالتزاماته التعاقدية وحل أى خلافات تطرأ أولا بأول.
3- حل المشاكل الفنية والمالية والقانونية ذات الصلة بالعقد ودون تأخير.
4- الحفاظ على علاقات عمل جيدة بين طرفى العقد.
5- التأكد من أن إجراءات استلام المستحقات المالية تتم دون تأخير وفى حالة التأخير يقوم برفع مذكرة للسلطة المختصة مبينا فيها مبررات التأخير ومقترح إزالة أسبابه.
6- دراسة كل المراسلات أثناء تنفيذ العقد والرد عليها وفقا لصلاحيته الممنوحة له من السلطة المختصة وفى كل الأحوال يجب ألا تتعارض الردود مع أحكام القانون وهذه اللائحة.
7- المحافظة على الوثائق الخاصة بتنفيذ العقد.
8- توثيق كافة المراسلات بين طرفى العقد.
9- القيام بكافة الإجراءات وفقا للقانون وهذه اللائحة.
وأية مهام أخري ذات صلة يكلف بها من السلطة المختصة.$m260$,'8e33263ea6327a7ce5a5bb808081836e'),
(86,0,$m260$المادة 86$m260$,$m260$على إدارة التعاقدات قبل إبرام العقد أو الاتفاق، بحسب الأحوال، التأكد من عدم وجود أية شكاوى لم يفصل فيها، سواء عن طريق الجهة الإدارية أو مكتب شكاوى التعاقدات العمومية.
وتلتزم السلطة المختصة خلال مدة لا تجاوز خمسة عشر يوما من تاريخ سداد التأمين النهائى بتوقيع العقد، أو الاتفاق مع المتعاقد.
وتحرر العقود متى بلغت قيمة التعاقد مائة ألف جنيه فأكثر أما فيما يقل عن ذلك فيجب ابرام اتفاق بين المتعاقد والجهة الإدارية متضمنا كافة الضمانات اللازمة للتنفيذ، وذلك كله وفقا للنماذج الصادرة عن الهيئة العامة للخدمات الحكومية، ويحرر العقد أو الاتفاق من أصل وأربع نسخ على الأقل يسلم الأصل للإدارة المالية مرفقا به كافة المستندات، ونسخة لإدارة التعاقدات لحفظها بملف العملية، ونسخة للمتعاقد، ونسخة للإدارة الطالبة أو المستفيدة، ونسخة للإدارة المشرفة على التنفيذ بحسب الأحوال.
ويجب على إدارة التعاقدات إبلاغ مصلحة الضرائب المصرية بقيمة العقد، أو الاتفاق ومدة تنفيذهما، على أن يتضمن الإخطار الآتى:
1- اسم المتعاقد ثلاثيا وصفته وعنوانه بالكامل.
2- الرقم القومى.
3- رقم السجل التجاري أو الصناعى، أو سجل المستوردين، أو بيانات القيد فى الاتحاد المصرى لمقاولى التشييد والبناء.
4- رقم التسجيل بمصلحة الضرائب المصرية.
5- قيمة العقد ونوعه.
كما يجب إبلاغ المصلحة بأى تعديلات تطرأ على قيمة، أو مدة تنفيذ العقد، أو الاتفاق وجميع المبالغ التى تصرف للمتعاقد بمجرد صرفها كما يجب على إدارة التعاقدات إبلاغ مصلحة الجمارك بالبيانات المشار إليها بالنسبة للعقود أو الاتفاقات التى يدخل فى مشمولها أصناف أو مهمات مستوردة.$m260$,'da2603bf7f1ff4dafec5a38635be4a43'),
(87,0,$m260$المادة 87$m260$,$m260$يجب على المسئولين الماليين وممثلي وزارة المالية بالوحدات الحسابية فى الجهات الإدارية المختلفة قبل صرف مستحقات المتعاقدين مع تلك الجهات التحقق من تحصيل، أو سداد جميع مستحقات الخزانة العامة من ضرائب ودمغات ورسوم جمركية وتأمينات اجتماعية ومقابل التأخير وغيرها من المستحقات الواجب سدادها وفقا للقوانين والقرارات المنظمة لذلك.$m260$,'10416cdb13b98ea3535de8881a106a53'),
(88,0,$m260$المادة 88$m260$,$m260$مع مراعاة أحكام المادة (95) من هذه اللائحة، يعتبر سعر العقد ثابتا طوال مدة تنفيذه.$m260$,'c107bcb84a9883559747b433d4ffa4d2'),
(89,0,$m260$المادة 89$m260$,$m260$فى حال حدوث تغيير فى التعريفة الجمركية، أو الرسوم، أو الضرائب الأخرى التى تحصل عن الأصناف الموردة وفقا للعقد فى المدة الواقعة بين تقديم العطاء وآخر موعد للتوريد، وكان التوريد قد تم فى غضون المدة المحددة له فيسوى الفرق تبعا لذلك بشرط أن يثبت المورد أنه أدى الرسوم والضرائب على الأصناف الموردة على أساس الفئات المعدلة بالزيادة، أما فى حالة ما إذا كان التعديل بالنقص فتخصم قيمة الفرق من العقد إلا إذا أثبت المورد أنه أدى الرسوم على أساس الفئات الأصلية قبل التعديل.
وفى حالة التأخير فى التوريد عن المواعيد المحددة فى العقد، وكان تعديل فئات الضرائب والرسوم قد تم بعد هذه المواعيد فإن المورد يتحمل عن الكميات المتأخرة كل زيادة فى الرسوم والضرائب المشار إليها إلا إذا أثبت أن التأخير يرجع إلى القوة القاهرة أما النقص فيها فتخصم قيمته من قيمة العقد.$m260$,'826fec720a45053fe8c222c851249a18'),
(90,0,$m260$المادة 90$m260$,$m260$يجوز بموافقة السلطة المختصة صرف دفعة مقدمة فى العقود التى تتطلب طبيعتها ذلك وفقا لشروط الطرح، وعلى النحو الآتى:
1- بما لا يجاوز (25%) من قيمة التعاقد فى التعاقدات التى ترى الجهة الإدارية ضرورة لذلك.
2- بما لا يجاوز (50%) من قيمة التعاقد فى التعاقدات التى تتم مع المشروعات المتوسطة والصغيرة ومتناهية الصغر.
على أن تكون الدفعة المقدمة مقابل خطاب ضمان بنكى معتمد بالقيمة والعملة ذاتهما وغير مقترن بأى قيد أو شرط ويكون ساري المفعول حتى تاريخ الاستحقاق الفعلي لتلك المبالغ.
3- بما لا يجاوز (25%) من قيمة التعاقد فى التعاقدات التى تتم وفقا للمادة (74) من القانون.
4- بما لا يجاوز (25%) من قيمة التعاقد فى التعاقدات التى تتم وفقا للمادة (78) من القانون.
ويجوز تجاوز النسب الواردة بهذه المادة فى الحالات التى ترى الجهة الإدارية ضرورة لذلك شريطة الحصول على موافقة وزير المالية قبل الطرح.
ويجب على الجهة الإدارية تضمين نسبة الدفعة المقدمة بكراسة الشروط والمواصفات وطلب تحديد أوجه صرفها وفى حالة عدم تضمينها فيعد ذلك بمثابة عزوف منها عن مبدأ إقرارها ويتعين على أصحاب العطاءات عدم تجاوز تلك النسبة، ويستبعد كل عطاء يخالف ذلك، وفى حالة إذا ما تبين للجهة الإدارية أثناء التنفيذ عدم الالتزام بأوجه الصرف المحددة للدفعة المقدمة يتم تسييل خطاب الضمان مقابل الدفعة المقدمة، ويراعى فى مقاولات الأعمال عدم صرف فروق الأسعار لما يتم شراؤه من قيمة الدفعة المقدمة فى العقود التى تتطلب ذلك.
وفى الحالات التى تكون فيها بداية العقد معلقة على تحقق أكثر من واقعة من بينها صرف الدفعة المقدمة فيراعى ألا يتم صرفها إلا بعد تحقق جميع الوقائع الأخرى، ويجب فى جميع الحالات أن تكون الدفعة المقدمة فى حدود الاعتمادات المدرجة بموازنة الجهة الإدارية عن السنة المالية التى يتم فيها التعاقد، وعليها التأكد من ذلك مسبقا وقبل الطرح.$m260$,'6d30f05e8649cd8c438a5518dcd74f0e'),
(91,0,$m260$المادة 91$m260$,$m260$تلتزم إدارة التعاقدات بمتابعة تنفيذ العقود للتأكد من توريد أو تنفيذ محل التعاقد والتحقق من إجراءات الفحص والاستلام وتسجيل الفواتير والمستندات ومتابعة إرسالها إلى الإدارة المالية لاتخاذ إجراءات الصرف.
ويصرف ثمن الأصناف الموردة، أو الخدمات المؤداة فى أقرب وقت ممكن، وبما لا يجاوز ثلاثين يوما تحسب من تاريخ الفحص والقبول والاعتماد، وفى الحالات التى يتضمن فيها التعاقد أن يتم سداد الثمن مقابل استلام الأصناف، فيجب على الجهة الإدارية اتخاذ ما يلزم نحو إجراء فحص الأصناف والتحقق من مطابقتها للمواصفات المتعاقد على أساسها وذلك قبل الاستلام وسداد الثمن.
وفى مقاولات الأعمال تصرف للمقاول دفعات تحت الحساب تبعا لتقدم العمل وذلك خلال ستين يوما من تاريخ تقديمه المستخلص لها تلتزم خلالها بمراجعة المستندات على النحو الوارد بشروط التعاقد وفى حالة قبولها الوفاء بقيمة ما يتم اعتماده، ويكون صرف الدفعات تحت الحساب على النحو الآتى:
1- بواقع نسبة (95%) من القيمة المقررة للأعمال التى تم تنفيذها فعلا مطابقة للشروط والمواصفات وذلك من واقع الفئات الواردة بالجدول المقدم من صاحب العطاء، ويجوز صرف نسبة ال(5%) الباقية والمحتجزة لمواجهة أية عيوب أو ملاحظات فى الأعمال يقصر المقاول فى اصلاحها، أو تلافيها لحين الاستلام المؤقت وذلك نظير خطاب ضمان معتمد من أحد البنوك المحلية ينتهى سريانه بعد مضى ثلاثين يوما من تاريخ حصول الاستلام المؤقت.
2- بواقع نسبة (75%) من القيمة المقررة للمواد التى وردها المقاول لاستعمالها فى العمل الدائم والتى يحتاجها العمل فعلا وفقا للبرنامج الزمنى المتفق عليه بالعقد بشرط أن تكون مطابقة للشروط وموافقا عليها، وأن تكون مشونة بموقع العمل فى حالة جيدة بعد إجراء الجرد الفعلي اللازم، وذلك من واقع فئات العقد، وتعامل كالمشونات المواد التى تورد لموقع العمل صالحة للتركيب إلى أن يتم تركيبها.
3- بعد استلام الأعمال مؤقتا تقوم اللجنة المختصة بالإشراف بتحرير الكشوف الختامية بقيمة جميع الأعمال التى تمت فعلا ويصرف للمقاول عقب ذلك مباشرة ما تستحقه بعد خصم المبالغ التى سبق صرفها على الحساب أو أى مبالغ أخرى مستحقة عليه.
وعند استلام الأعمال نهائيا بعد مدة الضمان وتقديم المقاول المستندات الدالة على ذلك يسوى الحساب النهائى ويدفع للمقاول باقى حسابه بما فى ذلك التأمين النهائى أو ما تبقى منه.
أما بالنسبة لباقى العقود يكون الصرف وفقا لما اشتملت عليه شروط التعاقد.
وفى جميع الأحوال، إذا لم يتم الوفاء بالمبالغ المستحقة للمتعاقد فى المواعيد المحددة بالعقد تلتزم الجهة الإدارية بأن تؤدى للمتعاقد ما يعادل تكلفة التمويل لقيمة المطالبة، أو المستخلص المعتمد عن فترة التأخير وفقا لسعر الائتمان والخصم المعلن من البنك المركزى وقت المحاسبة شريطة تقديم مستندات رسمية بالمبلغ المطالب به، ويحال المتسبب للتحقيق مع تحميله بقيمة ذلك.$m260$,'d24396f531b58c6630f5f8bab46e084f'),
(92,0,$m260$المادة 92$m260$,$m260$فى عقود بيع المنقولات يجب على من يرسو عليه المزاد أن يسدد (30%) من ثمن البيع بمجرد رسو المزاد، وفى حالة عدم السداد يكون التأمين المؤقت من حق الجهة الإدارية، ويسدد باقى الثمن خلال خمسة عشر يوما من تاريخ اليوم التالى لرسو المزاد عليه، فيما عدا الحالات التى تتطلب بحسب طبيعتها أن يتم تسليم المبيع على دفعات فيتم سداد قيمة كل دفعة بالكامل قبل الموعد المحدد لاستلامها ولا تسوى نسبة ال(30%) المشار إليها بالبند السابق إلا عند استلام آخر دفعة من المبيع على أن ينص على ذلك فى شروط المزايدة.
وفى عقود بيع العقارات والمشروعات التى ليس لها الشخصية الاعتبارية يجب على من يرسو عليه المزاد سداد (10%) من القيمة الراسى بها عملية البيع فور الرسو عليه ويستكمل باقى الثمن خلال فترة لا تجاوز ثلاثة أشهر من تاريخ إخطاره باعتماد البيع.
ويجوز استثناء وبموافقة السلطة المختصة بالنسبة للعقارات والمشروعات الكبرى أن تتضمن شروط الطرح سداد باقى الثمن على دفعات يتم تحديدها وفى هذه الحالة يستحق عنها عائد يعادل سعر الفائدة المعلن من البنك المركزى وقت السداد وذلك عن المدة من تاريخ الاستحقاق وحتى تاريخ السداد مع مراعاة عدم اتخاذ إجراءات نقل الملكية إلا بعد سداد كافة مستحقات الجهة الإدارية.
فإذا تأخر من رسا عليه المزاد عن أداء باقى الثمن خلال المدة المحددة بهذه المادة يصبح العقد مفسوخا دون حاجة إلى اتخاذ أى إجراءات قضائية مع تحميله بمقابل تأخير يعادل الفائدة وفقا للقواعد المقررة فى القانون المدني فى تاريخ السداد، وفى حالة عدم السداد يتم اتخاذ الإجراءات المنصوص عنها بالمادة (51) من القانون، ودون الإخلال بحق الجهة الإدارية فى الرجوع على المشترى بالتعويض اللازم.$m260$,'4c298e9b713b470328df0080bbdc13f3'),
(93,0,$m260$المادة 93$m260$,$m260$فى عقود تأجير المنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية، أو الترخيص بالانتفاع، أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف يجب على من يرسو عليه المزاد فى العقود التى لا تزيد مدتها عن ثلاث سنوات أن يقدم تأمينا نهائيا بما يعادل (10%) من القيمة الكلية الراسى بها المزاد عن مدة العقد بالكامل وذلك فور رسو المزاد، ويجب أن يظل التأمين ساريا طوال مدة العقد، فإذا زادت مدة العقد على ثلاث سنوات يحسب التأمين النهائى الواجب تقديمه بواقع (10%) من قيمة العقد عن الثلاث سنوات الأولى، ويجدد هذا التأمين قبل بداية الثلاث سنوات التالية أو الفترة المتبقية من العقد أيهما أقل، وذلك بمراعاة الزيادة السنوية فى قيمة التعاقد المنصوص عليها بالعقد.
ويراعى تضمين شروط الطرح طريقة سداد القيمة الإيجارية، أو مقابل الانتفاع، أو الاستغلال على أن يتم السداد خلال ثلاثة أيام عمل على الأكثر من بداية المدة المحددة لذلك، وفى حالة تجاوز هذه المهلة تستحق الجهة الإدارية تعويضا يعادل الفائدة وفقا للقواعد المقررة فى القانون المدني، وذلك عن الفترة من تاريخ الاستحقاق وحتى تاريخ السداد، وفى حالة عدم السداد يتم اتخاذ الإجراءات المنصوص عنها بالمادة (51) من القانون، ودون الإخلال بحق الجهة الإدارية فى الرجوع على المتعاقد بالتعويض اللازم.$m260$,'0cd35bd96d6b6678329a592ac9c6283e'),
(94,0,$m260$المادة 94$m260$,$m260$يجب على الجهة الإدارية تحديد احتياجاتها الفعلية والضرورية لسير العمل على أساس دراسة واقعية وموضوعية، ومع ذلك إذا استجد أثناء التنفيذ ما يوجب تعديل العقد فيتم التعديل بما لا يجاوز (25%) من كمية كل بند لعقود المقاولات، وبما لا يجاوز (15%) من كمية كل بند لباقى العقود مع تضمين شروط الطرح مضمون ذلك مع تعديل المدة المناسبة أو البرنامج الزمنى، بحسب الأحوال، للتوريد، أو التنفيذ وبما يتناسب مع حجم التعديل على أن تراعى إدارة التعاقدات الآتى:
1- وجود ضرورة وأسباب داعمة لتلك التعديلات.
2- الحصول على موافقة السلطة المختصة، أو مجلس الوزراء، بحسب الأحوال، على التعديل.
3- أن تكون تلك التعديلات على بنود العقد الأصلى ذاته وبالشروط والمواصفات ذاتها والأسعار المتعاقد عليها.
4- إعداد ملحق للعقد متضمنا تلك التعديلات.
5- الحصول من الادارة المالية على سماح البند فى حالة التعديل بالزيادة.
6- أن يكون التعديل خلال مدة تنفيذ العقد، ولا يدخل فيها مدة الضمان.
7- على ألا يؤثر ذلك على أولوية المتعاقد فى ترتيب عطائه.
على أن تتولى إدارة التعاقدات توثيق تلك التعديلات والمستندات المؤيدة لها وحفظها بملف العملية، ويتم النشر عن القيمة النهائية للعقد بعد التعديل على بوابة التعاقدات العامة.$m260$,'0cda4dc0c17d5e099356374102470cb8'),
(95,0,$m260$المادة 95$m260$,$m260$فى عقود مقاولات الأعمال التى تكون مدة تنفيذها ستة أشهر فأكثر، تلتزم إدارة التعاقدات فى نهاية كل ثلاثة أشهر تعاقدية بتعديل قيمة العقد وفقا للزيادة، أو الخفض فى تكاليف بنود العقد التى طرأت بعد التاريخ المحدد لفتح المظاريف الفنية، أو بعد تاريخ التعاقد المبنى على أمر الإسناد بالاتفاق المباشر، بحسب الأحوال، ويكون هذا التعديل ملزما للطرفين ويقع باطلا كل اتفاق يخالف ذلك.
ويكون حساب التغير فى الأسعار ومحاسبة المقاول على فروق الأسعار رفعا أو خفضا وفقا للتعريفات والمعادلة والقواعد الآتية:
أولا: التعريفات:
مدة التنفيذ: المدة المحددة لإنجاز الأعمال محسوبة من تاريخ تسليم الموقع خاليا من الموانع أو استلام المقاول الدفعة المقدمة، أو الرسومات المعتمدة اللازمة لبدء التنفيذ أيهما أبعد.
البنود المتغيرة: البنود أو مكوناتها الخاضعة للتعديل التى تحددها إدارة التعاقدات بمستندات الطرح (عمالة – مواد خام ......إلخ) من واقع القائمة التى تعدها وزارة الاسكان.
المعامل: النسبة التى يحددها المقاول بعطائه لكل بند أو مكوناته من البنود المتغيرة، بمراعاة ألا تساوى (صفرا) ويقل مجموعها عن 100% أو الواحد الصحيح بالنسبة لكل بند أو مشتملاته.
قيمة التعويض أو الخصم: المبلغ المستحق للمقاول، أو المبلغ الواجب خصمه من مستحقاته نتيجة احتساب التغير فى أسعار البنود المتغيرة ارتفاعا، أو انخفاضا.
نسبة الزيادة أو الخفض فى الأسعار: الرقم القياسي لسعر البند، أو مكوناته عند المحاسبة مطروحا منه الرقم القياسي للسعر عند تاريخ فتح المظاريف الفنية، أو الإسناد المباشر، بحسب الأحوال، مقسوما على الرقم القياسي للسعر عند فتح المظاريف الفنية، أو الإسناد المباشر، بحسب الأحوال، وذلك من واقع نشرة الأرقام القياسية للمنتجين الصادرة من الجهاز المركزى للتعبئة العامة والإحصاء.
ثانيا: المعادلة:
قيمة التعويض أو الخصم= قيمة الأعمال الخاضعة للتعديل من واقع عطاء المقاول عند التعاقد x معاملاتها × نسبة الزيادة أو الخفض فى الأسعار.
ثالثا: قواعد المحاسبة على فروق الأسعار:
1- تقوم إدارة التعاقدات بتحديد البنود المتغيرة، أو مكوناتها ضمن شروط الطرح من واقع القائمة التى تصدرها وزارة الاسكان، وفى حالة عدم تحديدها تلغى المناقصة أو الممارسة، أو أمر الإسناد المباشر قبل البت فيها.
2- يجب أن يتضمن عطاء المقاول فى المظروف الفنى معاملات تمثل أوزان عناصر التكلفة للبنود المتغيرة أو مكوناتها والتى حددتها إدارة التعاقدات ضمن شروط الطرح ويتم التعاقد على أساسها، وفى حالة عدم تضمين المقاول عطاءه تلك المعاملات يتم استبعاد العطاء.
3- تصرف قيمة المستخلص المعتمد فى المواعيد المحددة وفقا لأسعار العقد دون انتظار لتطبيق معادلة فروق الأسعار.
4- يحاسب المقاول على التعديل فى الأسعار رفعا، أو خفضا بالنسبة للبنود المتغيرة، أو مكوناتها كل ثلاثة أشهر تعاقدية من تاريخ فتح المظاريف الفنية، أو الإسناد المباشر، بحسب الأحوال، مع مراعاة البرنامج الزمنى للتنفيذ وتعديلاته الذى يتفق عليه الطرفان.
5- يحاسب المقاول على فروق الأسعار رفعا، أو خفضا خلال ستين يوما على الأكثر من تاريخ تقديم المطالبة، يتم خلالها مراجعة وصرف تلك الفروق، ويجب احتساب اولوية المتعاقد فى ترتيب عطائه وذلك بعد تطبيق المعادلة ذاتها على باقى العطاءات الأخرى.
6- لا تسرى معادلة تغير الأسعار وقواعد تطبيقها فى أى من الحالات الآتية:
أ- العقود التى تكون مدة تنفيذها أقل من ستة أشهر ويتأخر تنفيذها لسبب يرجع إلى المقاول.
ب- العقود التى تكون مدة تنفيذها أقل من ستة أشهر، ويتأخر تنفيذها لسبب يرجع إلى الجهة الإدارية، وفى هذه الحالة، تتم محاسبة المقاول على الكميات التى تم تنفيذها بعد الستة أشهر وفقا لمعدلات التضخم الصادرة من الجهاز المركزى للتعبئة العامة والإحصاء.$m260$,'31e54ff10e574fe7ca0b0c2b3865e880'),
(96,0,$m260$المادة 96$m260$,$m260$يتعين على مسئول إدارة العقد، بقدر الإمكان، العمل على إزالة أية عقبات أو مشكلات قد تؤدى إلى التأخير فى تنفيذ العقد سواء كان بسبب راجع للجهة الإدارية أو المتعاقد، وفى حالة حدوث تأخير فى البرنامج الزمنى، أو فى تنفيذ العقد خارج عن إرادة المتعاقد فيجوز للسلطة المختصة لدواعى المصلحة العامة إعطائه مهلة لإتمام التنفيذ دون تحصيل مقابل تأخير منه، أما إذا كان التأخير راجع للمتعاقد فيحصل منه مقابل للتأخير يحسب من بداية المهلة وبما لا يجاوز النسب الواردة بالقانون وذلك على النحو الآتى:
1- فى مقاولات الأعمال:
أ- إذا لم تجاوز مدة التأخير نسبة (1%) من المدة الكلية للتنفيذ يحصل مقابل تأخير بنسبة (1%) من قيمة الأعمال أو الختامي، أو من قيمة الجزء المتأخر بحسب الأحوال.
ب- تزاد نسبة تحصيل مقابل التأخير من قيمة الأعمال أو الختامي، أو من قيمة الجزء المتأخر، بحسب الأحوال، بنسبة مدة التأخير ذاتها وإلى أن تصل إلى (10%) من المدة الكلية للتنفيذ.
ج- إذا جاوزت مدة التأخير نسبة (10%) من المدة الكلية للتنفيذ يحصل مقابل التأخير بنسبة (15%) من قيمة الأعمال أو الختامي، أو من قيمة الجزء المتأخر بحسب الأحوال.
2- فى باقى العقود:
أ- إذا لم تجاوز مدة التأخير نسبة (3%) من المدة الكلية لتنفيذ محل العقد يحصل مقابل تأخير بنسبة (1%) من قيمة العقد، أو من قيمة الجزء المتأخر بحسب الأحوال.
ب- إذا لم تجاوز مدة التأخير نسبة (6%) من المدة الكلية لتنفيذ محل العقد يحصل مقابل تأخير بنسبة (2%) من قيمة العقد، أو من قيمة الجزء المتأخر بحسب الأحوال.
ج- إذا لم تجاوز مدة التأخير نسبة (10%) من المدة الكلية لتنفيذ محل العقد يحصل مقابل تأخير بنسبة (3%) من قيمة العقد، أو من قيمة الجزء المتأخر بحسب الأحوال.
د- إذا جاوزت مدة التأخير نسبة (10%) من المدة الكلية لتنفيذ محل العقد يحصل مقابل التأخير بنسبة (5%) من قيمة العقد، أو من قيمة الجزء المتأخر بحسب الأحوال.$m260$,'3f3f676475bab1f2b8df6c0a1e6f3d18'),
(97,0,$m260$المادة 97$m260$,$m260$يجب على الجهة الإدارية استلام محل التعاقد فى المواعيد المحددة بالعقد حال مطابقتها للمواصفات والشروط المتفق عليها بالعقد، وللمتعاقد حال تقاعس الجهة المتعاقدة عن الاستلام التقدم بطلب للسلطة المختصة لتشكيل لجنة محايدة لدراسة أسباب التقاعس، وصورة منه لمكتب شكاوى التعاقدات العمومية وذلك للمتابعة.
وتلتزم السلطة المختصة خلال سبعة أيام من تاريخ استلامها للطلب بتشكيل لجنة ثلاثية متخصصة من جهات محايدة منها الوزارات، أو الهيئات، أو النقابات المهنية وغيرها من جهات، ويكون اختيار أعضاء اللجنة بناء على ترشيح من جهة عملهم ويراعى ألا يكونوا قد سبق أن أبدوا رأيا فى العملية ولو فى هيئة تقرير استشاري، وألا يكون قد اتصل عملهم بالعملية خلال جميع مراحلها، وتكون الجهة المتعاقدة طرفا فى اللجنة، ويجب أن يتضمن قرار السلطة المختصة موعد انتهاء اللجنة من أعمالها.
تبدأ اللجنة أعمالها فور صدور قرار تشكيلها وسداد المتعاقد الأتعاب التى تحددها الجهات الخارجية المشاركة فيها وتخطره الجهة بها، وتقدم اللجنة تقريرها خلال مدة زمنية أقصاها ثلاثون يوما من تاريخ تشكيلها ما لم تتطلب طبيعة العملية وحجمها مدة تتجاوز ذلك، ولها فى سبيل أداء عملها طلب أى بيانات، أو معلومات، أو الاطلاع على مستندات واستيضاح ما تراه من طرفى التعاقد، كما يجوز لها أن تقوم بمعاينة محل العقد إذا تطلب الأمر ذلك، ويكون تقريرها ملزما للطرفين.
وتعرض اللجنة تقريرها بنتيجة عملها على السلطة المختصة لاعتماده وإصدار القرار فى ضوء ما انتهى إليه، وتتولى إدارة التعاقدات فور صدور القرار إخطار المتعاقد بكتاب يرسل بالبريد السريع عن طريق الهيئة القومية للبريد، ويعزز فى الوقت ذاته بالبريد الإلكترونى أو الفاكس، بحسب الأحوال، ومتابعة الإجراءات اللازمة لتنفيذ قرار السلطة المختصة وإنهاء إجراءات الاستلام فى مدة زمنية لا تجاوز مدة الفحص والاستلام المتفق عليها مسبقا بشروط الطرح والتعاقد، على أن يرد للمتعاقد أتعاب اللجنة حال تبين تقاعس الجهة الإدارية، مع إحالة المتسبب للتحقيق وتحميله بأتعاب اللجنة.
وإذا تبين للجنة عدم التزام المتعاقد، تتخذ الجهة الإدارية حياله الإجراءات ذات الصلة الواردة بالقانون وهذه اللائحة.$m260$,'e663e8c0ecf8c06a3cf5407ebfed9de2'),
(98,0,$m260$المادة 98$m260$,$m260$يجب على المتعاقد مع الجهة الإدارية تجنب موجبات فسخ العقد، وبصفة خاصة الآتى:
1- تقديم أى بيانات أو مستندات غير صحيحة بالذات أو الواسطة وذلك بغرض الغش أو التلاعب.
2- المخالفة للحظر المنصوص عليه بالمادة (33) من القانون أو التورط فى أية ممارسات احتيال، أو فساد، أو احتكار ومن ذلك التواطؤ، أو منع أية منافسة لأحد أصحاب العطاءات الآخرين، أو الاتفاق معهم على أغراض غير مشروعة، وذلك بما يخل بعدالة المنافسة المشروعة والاخلال بمبادئ الشفافية والمنافسة وتكافؤ الفرص، وغير ذلك من ممارسات تخل بتطبيق أحكام القانون وهذه اللائحة.
تتولى إدارة التعاقدات فسخ التعاقد تلقائيا فى هاتين الحالتين واعداد مذكرة للسلطة المختصة لمخاطبة إدارة الفتوى المختصة بمجلس الدولة للوقوف على رأيها فى شطب أسم المتعاقد، على أن تتولى الإدارة فور ورود رأى مجلس الدولة إخطار الهيئة العامة للخدمات الحكومية بقرار الشطب لتتولى الهيئة إصدار كتاب دوري متضمنا الآتى:
أ- أسم الجهة مصدرة القرار وتاريخ صدوره.
ب- أسباب الشطب.
ج- بيانات كتاب إدارة الفتوى المختصة بمجلس الدولة من رقم وتاريخ ورقم الملف ورقم السجل.
د- أسم صاحب العطاء أو المتعاقد المشطوب وبياناته.
وغير ذلك من البيانات التى تراها الهيئة لازمة.
وتنشر الهيئة العامة للخدمات الحكومية الكتاب الدوري من خلال النشرات المصلحية وعلى بوابة التعاقدات العامة وقيده فى سجل الممنوعين من التعامل، وتلتزم جميع الجهات الإدارية بقيد الممنوعين من التعامل فى السجل الخاص بذلك ويحظر التعامل معهم.
ويتم بناء على طلب المتعاقد الذى شطب اسمه إعادة قيده إذا انتفى سبب الشطب بصدور قرار من النيابة العامة بألا وجه لإقامة الدعوى الجنائية ضده أو بحفظها إداريا، أو بصدور حكم نهائى ببراءته مما نسب إليه، على أن يعرض قرار إعادة القيد على الهيئة العامة للخدمات الحكومية لنشره بطريق النشرات المصلحية وعلى بوابة التعاقدات العامة.$m260$,'d7f5ec88443c2e3938d76c39c0fe7cd4'),
(99,0,$m260$المادة 99$m260$,$m260$يتعين على المتعاقد بذل أقصى جهد للالتزام بتنفيذ التزاماته التعاقدية وفقا لما اشتمل عليه العقد، وفى حاله إخلاله بأى شرط جوهرى تضمنته شروط العقد، فعلى إدارة التعاقدات استنفاد كافة البدائل الممكنة للوصول إلى حلول تتفق مع شروط العقد، وفى حالة عدم إمكانية التوصل إلى حلول منطقية فعلى الإدارة المذكورة بما يحقق المصلحة العامة اتخاذ أحد الإجراءين الآتيين:
1- فسخ العقد وفى هذه الحالة فلا يجوز إعادة طرح العملية فى السنة المالية ذاتها المقرر التنفيذ فيها.
2- التنفيذ على حساب المتعاقد ما دام أن الحاجة إلى تنفيذ هذه العملية ما زالت قائمة على أن يتم التنفيذ بالشروط والمواصفات ذاتها المعلن عنها والمتعاقد على أساسها، وذلك بإحدى الطرق القانونية المنصوص عليها بالمادة (7) من القانون.$m260$,'e756c7982b5a11d7e0a6f12873aaa2d8'),
(100,0,$m260$المادة 100$m260$,$m260$فى حالة فسخ العقد، أو التنفيذ على الحساب يتم عمل جرد وتحرير كشف بالأعمال التى تمت وبالآلات والأدوات التى استحضرت والمهمات التى لم تستعمل والتى يكون قد وردها المتعاقد بمكان العمل، ويتم ذلك الجرد خلال شهر من تاريخ موافقة السلطة المختصة على الفسخ أو التنفيذ على الحساب ويكون بمعرفة مسئول إدارة العقد، من الجهة الإدارية أو مندوبيها، بحسب الأحوال، وبحضور المتعاقد بعد إخطاره بالحضور هو أو من يفوضه، ويثبت هذا الجرد بموجب محضر يوقعه كل من مسئول إدارة العقد، أو مندوبي الجهة الإدارية، بحسب الأحوال، والمتعاقد، أو من يفوضه فإذا لم يحضر، أو لم يرسل مندوبا عنه فيجرى الجرد فى غيابه، وفى هذه الحالة يخطر المتعاقد بنتيجة الجرد، فإذا لم يبد ملاحظاته خلال أسبوع من تاريخ وصول الإخطار إليه كان ذلك بمثابة إقرار منه بصحة البيانات الواردة فى محضر الجرد، والجهة الإدارية غير ملزمة بأخذ شئ من هذه المهمات إلا بالقدر الذى يلزم لإتمام الأعمال فقط شريطة أن تكون صالحة للاستعمال أما ما يزيد على ذلك فيكلف المتعاقد بنقله من محل العمل.
وفى حالة عدم قيام المتعاقد بنقل المتبقي من مهماته فتقوم الجهة الإدارية ببيعها لحسابه وخصم ما تكبدته من مصروفات فى سبيل ذلك.$m260$,'0cc48a3d090615ed4acd48817c1c7ff8'),
(101,0,$m260$المادة 101$m260$,$m260$فى حالة وفاة المتعاقد أثناء تنفيذ العقد، يحق للجهة الإدارية إنهاء العقد ورد التأمين النهائى للورثة ما لم يكن لها مطالبات قبل المتعاقد.
وتشكل بقرار من السلطة المختصة لجنة لحصر الأعمال المنجزة وتكلفتها وتحديد المبالغ المنصرفة حتى تاريخ الوفاة والمبالغ المتبقية له والأعمال المتبقية فى العقد، ويدعى لحضور أعمال اللجنة ممثل عن ورثة المتوفى.
ويجوز السماح للورثة أو ممثلهم حال تقديمه طلب بذلك وتوافر المقدرة الفنية والمالية للاستمرار فى تنفيذ العقد بالشروط والمواصفات ذاتها المحددة به، شريطة أن يعينوا عنهم وكيلا خلال فترة لا تتجاوز شهر من تاريخ الوفاة لإتمام الجزء غير المنفذ من العقد، وفى حالة عدم مقدرتهم أو عدم رغبتهم فى اتمام العقد يتم محاسبتهم وتنفيذ الجزء المتبقي عن طريق طرح عملية أخرى وفقا لأحكام القانون وهذه اللائحة.
أما إذا كان العقد مبرم مع أكثر من متعاقد كشريك وتوفى احدهم، جاز للجهة الإدارية انهاء العقد مع رد التأمين النهائى ما لم يكن لها مطالبات أو السماح لبقية الشركاء بتنفيذ بنود العقد.
وفى جميع الحالات يكون إنهاء العقد دون الحاجة إلى اتخاذ أى إجراءات أخرى أو الالتجاء إلى القضاء.$m260$,'b61921e378f18e376c3cb5302fc6afda'),
(102,0,$m260$المادة 102$m260$,$m260$فى عقود التوريدات تبدأ المدة المحددة للتوريد من اليوم التالى لإخطار المورد سواء بالداخل أو بالخارج بأمر التوريد إلا إذا اتفق على خلاف ذلك، على أن يتضمن أمر التوريد الأصناف والكميات والفئات ومكان التسليم ومواعيد بدء التوريد وانتهائه.
وتبدأ المدة المحددة لتنفيذ عقود الأعمال من التاريخ الذى يسلم فيه الموقع للمقاول خاليا من الموانع إلا إذا اتفق على خلاف ذلك، ويكون التسليم بموجب محضر يوقع من الطرفين ومحرر من أصل وأربعة نسخ يسلم الأصل للإدارة المالية، ونسخة لإدارة التعاقدات لحفظها بملف العملية، ونسخة للمقاول، ونسخة للإدارة الطالبة أو المستفيدة، ونسخة للإدارة المشرفة على التنفيذ، وإذا لم يحضر المقاول أو من يفوضه لتسلم الموقع فى التاريخ الذى تحدد له فى أمر الإسناد فيحرر محضر بذلك ويعتبر هذا التاريخ موعدا لبدء تنفيذ العمل.
أما بالنسبة لباقى العقود فتبدأ المدة المحددة لتنفيذ العقد وفقا لما تضمنته كراسة الشروط والمواصفات، والعقد.$m260$,'44e4937d64ff8194a7e9594c99505cfb'),
(103,0,$m260$المادة 103$m260$,$m260$يلتزم المتعاقد بتنفيذ محل العقد فى الميعاد، أو المواعيد المحددة بأمر التوريد، أو الإسناد، وعليه اتباع جميع القوانين واللوائح الحكومية والمحلية ذات الصلة بتنفيذ موضوع التعاقد كما يكون مسئولا عن حفظ النظام بموقع العمل وتنفيذ أوامر الجهة الإدارية بإبعاد كل من يهمل، أو يرفض تنفيذ التعليمات، أو يحاول الغش، أو يخالف ذلك.
كما يلتزم المتعاقد باتخاذ كل ما يكفل منع الإصابات، أو حوادث الوفاة للعمال، أو أى شخص آخر، أو الإضرار بممتلكات الدولة، أو الأفراد وتعتبر مسئوليته فى هذه الحالات مباشرة دون تدخل للجهة الإدارية، وعليه أن يتحرى بنفسه طبيعة الأعمال وعمل كل ما يلزم لذلك من اختبارات وغيرها للتأكد من صلاحية المواصفات والرسومات والتصميمات المعتمدة وعليه إخطار الجهة الإدارية فى الوقت المناسب بملاحظته عليها ويكون مسئولا تبعا لذلك عن صحة وسلامة جميع ما ورد بها كما لو كانت مقدمة منه.
وفى حالة إخلاله بتلك الالتزامات يكون للجهة الإدارية الحق اتخاذ الإجراءات المنصوص عليها بالقانون وهذه اللائحة.$m260$,'7aa7dfa8168b19da40cec44be70bf196'),
(104,0,$m260$المادة 104$m260$,$m260$مع عدم الإخلال بحقوق الغير حسن النية فإن جميع المواد والمشونات المعتمدة والقطع والأدوات والآلات التى تكون قد استحضرت بمعرفة المتعاقد لمنطقة العمل، أو على الأرض المشغولة بمعرفته بقصد استعمالها فى تنفيذ محل العقد وكذلك جميع الأعمال والمنشآت الوقتية الأخرى تظل كما هي، ولا يجوز نقلها، أو التصرف فيها إلا بإذن الجهة الإدارية إلى أن يتم الاستلام المؤقت على أن تبقى فى عهدة المتعاقد وتحت حراسته ومسئوليته وحده ولا تتحمل الجهة الإدارية فى شأنها أية مسئولية بسبب الضياع، أو التلف، أو السرقة، أو غير ذلك.
ويجب على المتعاقد أن يهيئ مكانا صالحا لتشوين المواد القابلة للتلف بسبب العوامل الجوية وذلك لوقايتها منها بطريقة توافق عليها الجهة الإدارية.$m260$,'4077671cc9f59248187cd944c1ad72a9'),
(105,0,$m260$المادة 105$m260$,$m260$تصدر السلطة المختصة قرارا بتشكيل لجنة لفحص الأصناف الموردة برئاسة مدير المخازن أو مسئول القسم المختص على أن تضم عضوا فنيا، أو أكثر، وعضوا عن الإدارة الطالبة، أو المستفيدة وأمين المخزن المختص، ويجوز للجنة الفحص الاستعانة بفني، أو أكثر من الجهات الفنية المختصة إذا رأت ضرورة لذلك، على أن يحدد القرار مواعيد انتهاء اللجنة من أعمالها، ولا يجوز أن يشارك فى أعمال الفحص من سبق وشارك فى اعداد الشروط، أو المواصفات الفنية، أو إجراءات لجان البت، ويمكن الاستئناس برأيهم إذا تطلب الأمر ذلك.
ويكون الفحص وفقا للمتطلبات ذات الصلة الواردة بشروط الطرح والعقد.
وتفصل السلطة المختصة فى الخلافات التى تنشأ بين أعضاء لجنة الفحص، ولها أن تسترشد فى ذلك برأي لجنة فحص أخرى أو الرجوع إلى الجهة التابع لها العضو الفنى.$m260$,'0cc5cb3282fc52d7ae77fcce00bc0661'),
(106,0,$m260$المادة 106$m260$,$m260$يلتزم مدير المخازن طبقا لأحكام العقد بمتابعة ورود الأصناف واستلامها وإجراءات الفحص وتسجيل الفواتير والمستندات المخزنية ومتابعة إرسال المستندات إلى الإدارة المالية لاتخاذ إجراءات الصرف وبمراعاة أحكام هذه اللائحة.
وفى حالة إخلال المورد بأى شرط من شروط التوريد يتعين على مدير المخازن إخطار إدارة التعاقدات فورا بذلك لاتخاذ الإجراءات اللازمة وفقا لأحكام هذه اللائحة.$m260$,'800b5ff62ee748ada4d44e8c15ad2629'),
(107,0,$m260$المادة 107$m260$,$m260$يلتزم المورد بتوريد الأصناف المتعاقد عليها فى الميعاد، أو المواعيد المحددة بالعقد خالصة جميع المصروفات والرسوم ومطابقة لأمر التوريد وللمواصفات، أو العينات المعتمدة ويتسلم أمين المخزن المختص ما يتم توريده بالعدد، أو الوزن، أو المقاس بحضور المورد أو من يفوضه ويعطى عنه إيصالا مؤقتا مختوما بخاتم الجهة الإدارية موضحا به اليوم والساعة التى تم التوريد فيها ويقرر فيه حالة الأصناف من حيث سلامتها، وتجتمع لجنة الفحص فى موعد أقصاه يوم العمل التالى لاستلام الأصناف ويخطر المورد بموعد اجتماع اللجنة ليتمكن من حضور إجراءات الفحص والاستلام النهائى، وعلى أمين المخزن المختص فور تسلمه الأصناف الموردة إخطار رئيس لجنة الفحص بذلك لاتخاذ اللازم.
ويلتزم بأن يقدم فاتورة الأصناف الموردة من أصل وصورتين، وفى حالة قيامه بالتوريد بناء على طلب الجهة الإدارية إلى جهة غير الجهة المتعاقد على التوريد إليها يجب إرفاق الفواتير مستندات تثبت قيمة مصروفات النقل الإضافية حتى يمكن رد هذه المصروفات إليه.
كما يلتزم على حسابه بإحضار العمال اللازمين لفتح الطرود وتسليمها إلى أمين المخزن أو لجنة الفحص بحضوره، أو بحضور من يفوضه فى الموعد المحدد وفى حالة تخلفه فيكون لمدير المخازن، أو لجنة الفحص الحق فى اتخاذ الإجراءات اللازمة على حساب المورد لتسلم الأصناف وتسليمها إلى المخازن وتصحيح الفاتورة إذا اقتضى الأمر ذلك دون أن يكون للمورد حق الاعتراض.$m260$,'51bd874841bcba4197fec0fc82bf5f44'),
(108,0,$m260$المادة 108$m260$,$m260$تقوم لجنة الفحص بفحص نسب مئوية مختلفة تحدد بمعرفتها وتحت مسئوليتها حسب أهمية الصنف وبحيث تكون العينة ممثلة له وتعتبر اللجنة مسئولة عن مطابقته من جميع الوجوه للمواصفات وللعينة المختومة، وتحرر محضر الفحص على النموذج المعد لذلك من أصل وصورتين تبين فيه النسب المئوية لمقادير الفحص التى فحصتها وأسماء ومواصفات ومقادير الأصناف وأسباب التوصية بالقبول، أو الرفض ثم يقدم المحضر إلى السلطة المختصة للتصرف.
ويجب على الجهات التى تقوم بفحص الأصناف أن تبين فى تقارير الفحص ما أسفر عنه عملها مقارنا بما هو مدون بالشروط والمواصفات المتعاقد على أساسها وتلتزم الجهة الإدارية بالأخذ دائما بهذه النتائج ورفض الأصناف التى لا تطابق المواصفات أو العينات المتعاقد على أساسها.
وفى حالة اعتماد قبول الصنف يرسل أصل محضر الفحص وفاتورة المورد وصورة أمر التوريد مع إذن الإضافة على النموذج المعد لذلك إلى الإدارة المالية وتحفظ صورة من محضر الفحص مع صورة الفاتورة فى ملف خاص بإدارة المخازن وترسل الصورة الثانية مع صورة إذن الإضافة إلى وحدة رقابة المخزون.$m260$,'df0199bfab1c2ee6bd5e4d0cd3a0d178'),
(109,0,$m260$المادة 109$m260$,$m260$عند ورود أصناف للمخازن ويكون قد سبق إرسال عينات عنها عند تقديم العطاءات للفحص بالجهات المختصة فتؤخذ عينة منها وتقسم إن أمكن قسمتها إلى قسمين وإلا فتختار عينتان من هذه الأصناف بحضور لجنة الفحص والمورد أو من يفوضه، ويحتفظ بإحداها لدى رئيس لجنة الفحص بعد ختمها بخاتم الجهة الإدارية وخاتم المورد، أما العينة الأخرى فتختم بخاتم الجهة الإدارية ويوقعها عضوان من أعضاء لجنة الفحص ويعمل محضر توقعه اللجنة والمورد أو من يفوضه بأن هذه العينة مطابقة للعينة المحفوظة لدى رئيس لجنة الفحص ثم ترسل إلى الجهة الفنية المختصة بعد إعطائها رقما سريا مع ذكر رقم وتاريخ نتيجة الفحص للعينة الأصلية للاسترشاد بها عند الفحص وعند ورود نتيجة الفحص لعينة التوريد ترفق مع مستندات الصرف.
فإذا تلفت العينة نتيجة الفحص فتتحمل الجهة الإدارية قيمتها متى كانت مطابقة للمواصفات، أما إذا ثبت عدم مطابقتها فليس للمورد أن يطالب الجهة بقيمتها.
وإذا رفضت الأصناف الموردة الموضوع عليها اسم الجهة الإدارية فيمحى اسم الجهة منها قبل ردها للمورد.$m260$,'03d9b002a78fadc3dfa39d012e1e6252'),
(110,0,$m260$المادة 110$m260$,$m260$يجوز قبول الأصناف إذا كانت نسبة التباين لا تزيد على (10%) عما هو مطلوب بالمواصفات المتعاقد على أساسها بشرط أن تكون الحاجة ماسة لقبول الصنف أو الأصناف رغم ما بها من تباين وأن يكون السعر بعد الخفض مناسبا لمثيله فى السوق.
ويجب أن تقرر لجنة الفحص صلاحية الأصناف للأغراض المطلوبة من أجلها وأنه لن يترتب على قبولها ضرر بالجهة الإدارية ولا يكون قد سبق رفض عطاءات للسبب ذاته، كما تحدد اللجنة مقدار الخفض فى الثمن المقابل للتباين.
ويجوز للجنة الفحص الاستعانة بفني أو أكثر من الجهات الفنية المختصة إذا رأت ضرورة لذلك ويراعى الآتى:
1- الأصناف التى تكون نسبة التباين فى مواصفاتها حتى (2%) يكون قبولها بخصم مقدار الخفض فى الثمن الذى قدرته اللجنة.
2- الأصناف التى تكون نسبة التباين فى مواصفاتها أكثر من (2%) حتى (5%) يكون قبولها بخصم مقدار الخفض فى الثمن الذى قدرته اللجنة مضافا إليه مقابل تباين مقداره (50%) من هذا المقدار.
3- الأصناف التى تكون نسبة التباين فى مواصفاتها أكثر من (5%) حتى (10%) يكون قبولها بخصم مقدار الخفض فى الثمن الذى قدرته اللجنة مضافا إليه مقابل تباين مقداره (100%) من هذا المقدار.
على أن يكون القبول بموافقة لجنة البت والسلطة المختصة وبشرط أن يقبل المورد كتابة هذا الخصم وإلا فيرفض الصنف وتطبق أحكام القانون وهذه اللائحة.$m260$,'08c17e6864255a33587c1b2825021d71'),
(111,0,$m260$المادة 111$m260$,$m260$إذا رفضت لجنة الفحص صنفا أو أكثر من الأصناف الموردة أو وجد فيها نقص أو مخالفة للمواصفات، أو العينات المعتمدة يخطر المتعاقد بذلك كتابة بأسباب الرفض وبوجوب سحب الأصناف المرفوضة وتوريد بدل عنها ويجب أن يتم ذلك الإخطار فور صدور قرار اللجنة فى ذات اليوم أو اليوم التالى على الأكثر ويلتزم المتعاقد بسحب الأصناف المرفوضة خلال سبعة أيام على الأكثر من تاريخ اليوم التالى لإخطاره، فإذا تأخر فى سحبها فيكون للجهة الإدارية الحق فى تحصيل مصروفات تخزين بواقع (5%) من قيمة الأصناف عن كل أسبوع تأخير أو جزء منه لمدة أقصاها أربعة أسابيع وبعد انتهاء هذه المدة تتخذ إجراءات بيعها لحساب المتعاقد وتخصم من الثمن ما يكون مستحقا لها ويكون البيع وفقا لأحكام القانون وهذه اللائحة.$m260$,'c45ac482b99b52f16fc833f69b4565ec'),
(112,0,$m260$المادة 112$m260$,$m260$عند ورود أصناف مباشرة من الخارج تقوم لجنة الفحص بمراجعتها على الوارد بالفاتورة بعد التأكد من سلامة الأختام والعلامات أو الصناديق الواردة بداخلها الأصناف ويحرر محضر فحص عن ذلك على النموذج المعد لذلك تثبت فيه ما قد تجده من نقص، أو كسر، أو تلف ثم يحرر عنه محضر خاص على طلب خصم الأصناف التالفة، أو المفقودة على النموذج المعد لذلك لاتخاذ الإجراءات اللازمة نحوه مع مراعاة المواعيد التى تحددها شركات التأمين فى حالة التأمين على البضاعة حفظا لحق الجهة الإدارية فى استيفاء قيمة التأمين وإلا التزم به المتسبب فى فوات هذه المواعيد.
وتضاف الأصناف بالمخزن حسب الوارد بالفاتورة بغض النظر عما تجده اللجنة فيها من نقص، أو كسر، أو تلف.
على أن يخصم مقدار النقص من العهدة بموجب طلب وإذن صرف على النموذج المعد لذلك وتجرى التسويات الحسابية اللازمة وفقا للقواعد المالية المعمول بها.
وفى حالة تعذر فتح الصناديق وإضافتها حسب الوارد بالفاتورة لأسباب اضطرارية تقرها كتابة السلطة المختصة يتبع الآتى:
1- تضاف تلك الصناديق بأذون إضافة مؤقتة بالحالة التى هي عليها إجمالا بعهدة موظفين مسئولين بعد ختمها بخاتم مدير المخازن بطريقة تضمن سلامة الأختام حتى يعاد فتحها.
2- عند استخراج أذون الإضافة المؤقتة السابق الإشارة إليها ترافق صورة منها مستندات الصرف لإمكان إزالة المبالغ السابق الخصم بها من الحساب المختص.$m260$,'65cbef768bd42c8459e712ac99ebc2dc'),
(113,0,$m260$المادة 113$m260$,$m260$بعد اعتماد السلطة المختصة لأعمال اللجنة تتخذ إجراءات التعاقد على نقل الملكية أو الاستئجار وفقا للقوانين والقرارات المنظمة لذلك.
وتشكل لجنة متخصصة تضم العناصر الفنية لاستلام العقار محل التعاقد، وعليها التأكد من مطابقته من جميع الوجوه لما تم التعاقد عليه.$m260$,'94f094510d137bc7efecac74cd33fd8a'),
(114,0,$m260$المادة 114$m260$,$m260$يلتزم المقاول بأن يتحرى بنفسه طبيعة الأعمال وعمل كل ما يلزم لذلك من اختبارات والجسات وغيرها للتأكد من صلاحية المواصفات الفنية والرسومات الهندسية والتصميمات المعتمدة وعليه إخطار إدارة التعاقدات فى الوقت المناسب بملاحظاته عليها ويكون مسئولا تبعا لذلك عن صحة وسلامة جميع ما ورد بها كما لو كانت مقدمة منه.$m260$,'dacbb93100314eca9550dfd146b0326a'),
(115,0,$m260$المادة 115$m260$,$m260$المقادير والأوزان الواردة بجداول الفئات هي مقادير وأوزان تقريبية قابلة للزيادة أو النقص تبعا، لطبيعة العملية والغرض منها هو بيان مقدار العمل بصفة عامة والمبالغ التى تسدد للمقاول تكون على أساس الكميات التى تنفذ فعلا سواء أكانت تلك الكميات أقل أم أكثر من الواردة بالمقايسة، أو الرسومات وسواء نشأت الزيادة، أو العجز عن خطأ فى حساب المقايسة الابتدائية، أو عن تغييرات أدخلت فى العمل طبقا لبنود العقد.
ويجب فى جميع الحالات ألا يؤثر ذلك على أولوية المقاول فى ترتيب عطائه.
ويعتبر المقاول مسئولا عن التحري بنفسه عن صحة المقادير والأوزان وتعتبر كل فئة من الفئات المدرجة بجدول الفئات ملزمة للمقاول أثناء العقد وغير قابلة لإعادة النظر لأى سبب ولا يكون للمقاول حق طلب مبالغ زيادة أو تعويضات بشأنها.
ويقوم مهندس الجهة الإدارية بعملية القياس أو الوزن للأعمال أثناء سير العمل بالاشتراك مع المقاول، أو مهندسه، أو من يفوضه، ويتم التوقيع بصحة المقاسات والأوزان من الاثنين، فإذا تخلف المقاول، أو من يفوضه بعد إخطاره يلزم بالمقاسات والأوزان التى يجريها مهندس الجهة الإدارية.
على أنه بالنسبة للجهات التى لا يتوافر فيها العنصر الفنى اللازم فينتدب مهندس من مديرية الإسكان المختصة ويكون مهندس الجهة الإدارية، أو مديرية الإسكان مسئولا عن صحة وسلامة ما يثبته من بيانات فى هذا الشأن.$m260$,'70712c08a78cc75626b2ea5b5ed94878'),
(116,0,$m260$المادة 116$m260$,$m260$على المقاول بمجرد إتمام العمل أن يخلى الموقع من جميع المواد والأتربة والبقايا وأن يمهده، وإلا كان للجهة الإدارية الحق بعد إخطاره فى تنفيذ ذلك على حسابه، ويخطر عندئذ بالموعد الذى حدد لإجراء المعاينة ويحرر محضر الاستلام المؤقت بعد إتمام المعاينة ويوقعه كل من المتعاقد أو من يفوضه بذلك بتوكيل مصدق عليه ومسئول إدارة العقد من الجهة الإدارية أو مندوبيها، بحسب الأحوال، الذين يخطر المقاول بأسمائهم ويكون هذا المحضر من أصل وأربع نسخ يسلم الأصل للإدارة المالية، ونسخة لإدارة التعاقدات لحفظها بملف العملية، ونسخة للإدارة الطالبة أو المستفيدة، ونسخة للإدارة المشرفة على التنفيذ، وتسلم نسخة للمتعاقد وفى حالة عدم حضوره هو أو من يفوضه فى الميعاد المحدد تتم المعاينة ويوقع المحضر من مندوبي الجهة الإدارية وحدهم وإذا تبين من المعاينة أن العمل قد تم على الوجه المطلوب اعتبر تاريخ إخطار المتعاقد للجهة الإدارية باستعداده للتسليم المؤقت موعد إنهاء العمل وبدء مدة الضمان وإذا ظهر من المعاينة أن العمل لم ينفذ على الوجه الأكمل فيثبت هذا فى المحضر ويؤجل الاستلام إلى أن يتضح أن الأعمال قد تمت بما يطابق الشروط مع عدم الإخلال بمسئولية المتعاقد طبقا لأحكام القانون المدني وتبدأ من تاريخ المعاينة الأخيرة مدة الضمان.
وبعد إتمام الاستلام المؤقت يرد للمتعاقد إذا لم توجد قبله مطالبات للجهة المتعاقدة، أو لأية جهة إدارية أخرى ما زاد من قيمة التأمين النهائى على النسبة المحددة من قيمة الأعمال التى تمت فعلا وتحتفظ الجهة المتعاقدة بهذه النسبة لحين انتهاء مدة الضمان وإتمام الاستلام النهائى.$m260$,'2ad2753174e8952e93b7666ddad7e20a'),
(117,0,$m260$المادة 117$m260$,$m260$يضمن المتعاقد الأعمال موضوع العقد وحسن تنفيذها على الوجه الأكمل لمدة سنة واحدة من تاريخ الاستلام المؤقت وذلك دون إخلال بمدة الضمان المنصوص عليها فى القانون المدني أو أى قانون آخر، والمتعاقد مسئول عن بقاء جميع الأعمال سليمة أثناء مدة الضمان طبقا لشروط التعاقد فإذا ظهر بها أى خلل أو عيب يقوم بإصلاحه على نفقته وإذا قصر فى إجراء ذلك فللجهة الإدارية أن تجريه على نفقته وتحت مسئوليته.$m260$,'eb8c2ec6a08a47cf3cfac68cf9a1ba60'),
(118,0,$m260$المادة 118$m260$,$m260$قبل انتهاء مدة الضمان بوقت مناسب يخطر المتعاقد الجهة الإدارية كتابة للقيام بتحديد موعد للمعاينة.
ومتى تبين أن الأعمال قد نفذت مطابقة للمواصفات بحالة جيدة فيتم تسلمها نهائيا بموجب محضر من أصل وأربع نسخ يوقعه كل من مندوبي الجهة الإدارية والمتعاقد، أو من يفوضه، ويسلم الأصل للإدارة المالية، وتسلم نسخة للمتعاقد، ونسخة لإدارة التعاقدات لحفظها بملف العملية، ونسخة للإدارة الطالبة أو المستفيدة، ونسخة للإدارة المشرفة على التنفيذ وإذا ظهر من المعاينة أن المتعاقد لم يقم ببعض الالتزامات فيؤجل الاستلام النهائى لحين قيامه باستكمال التزاماته، هذا مع عدم الإخلال بمسئوليته طبقا لأحكام القانون المدني أو أى قانون آخر.
وعند إتمام الاستلام النهائى يدفع للمتعاقد ما قد يكون مستحقا له من مبالغ ويرد إليه التأمين النهائى أو ما تبقى منه.$m260$,'07ea59a7fd6cd038ab44b4a5e3bcd84e'),
(119,0,$m260$المادة 119$m260$,$m260$يعمل فى شأن التعاقد بطريق المناقصة العامة على شراء أو استئجار المنقولات والعقارات، والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية بالإجراءات المنظمة لمرحلة ما قبل الطرح ومرحلة الطرح ومرحلة الترسية والتعاقد المنصوص عليها فى هذه اللائحة.$m260$,'1f8848d109484d44200cbe9e6af980a0'),
(120,0,$m260$المادة 120$m260$,$m260$فيما عدا التعاقد على الدراسات الاستشارية يكون التعاقد بطريق الممارسة العامة على شراء أو استئجار المنقولات والعقارات، والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية فى الحالات التى تتوافر فيها الشروط المنصوص عليها بالمادة (54) من القانون مجتمعة، ويجب النشر عنها على بوابة التعاقدات العامة والإعلان بإحدى الصحف اليومية واسعة الانتشار بمدة لا تقل عن عشرين يوما قبل الموعد المحدد لفتح المظاريف ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير تلك المدة بحيث لا تقل عن أربعة عشر يوما تحتسب من تاريخ الإعلان.
ويجوز لتطبيق الشرط المنصوص عليه بالبند (3) من المادة المشار إليها، إصدار الجهة الإدارية طلب ابداء الاهتمام أو طلب تأهيل مسبق إذا تطلبت طبيعة العملية ذلك.$m260$,'e3450e4ca8979d64dbbc9edc924a22f8'),
(121,0,$m260$المادة 121$m260$,$m260$فيما عدا التعاقد على الدراسات الاستشارية يكون اللجوء إلى طريق الممارسة المحدودة فى أى من الحالات المنصوص عليها بالمادة (55) من القانون، مع مراعاة الشرطين (1)، (2) من المادة (54) من القانون مجتمعين، ويجوز لتطبيق الشرط المنصوص عليه بالبند (1) من المادة (55) المشار إليها، إصدار الجهة الإدارية طلب ابداء الاهتمام أو طلب تأهيل مسبق بما يتفق مع طبيعة العملية.
ويجب النشر عن الممارسة المحدودة على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد ممكن من المسجلين عليها المتخصصين أو المؤهلين المشتغلين بالنشاط موضوع الطرح، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لفتح المظاريف الفنية، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.$m260$,'5db27adce0c7d2f304f4696327e0c8bd'),
(122,0,$m260$المادة 122$m260$,$m260$تتولى لجنة الممارسة المشكلة بقرار من السلطة المختصة فتح المظاريف المالية للعروض المقبولة فنيا فقط وممارسة مقدميها، أو من يفوضونهم فى جولة، أو عدة جولات فى الجلسة المحددة للوصول لأفضل الشروط وأقل الأسعار، أو الذى يتم ترجيحه وفقا لنظام النقاط المحددة أسسه وعناصره والوزن النسبى بشروط الطرح والحد الأدنى للقبول وذلك بعد توحيد أسس المقارنة بين العروض من جميع النواحى الفنية والمالية للوصول إلى أقل قيمة مقارنة مع الأخذ فى الاعتبار العناصر التى تؤثر فى تحديد القيمة المالية المقارنة للعطاءات بحسب ظروف موضوع التعاقد وطبيعته.
وفى جميع الحالات يحظر إعادة فتح باب التمارس مرة أخرى لما تم الانتهاء عليه من التمارس.
ويحظر الترتيب بين المتمارسين قبل أو بعد تقديم عطاءاتهم أو أثناء جلسة الممارسة لتحقيق غرض غير مشروع أو للإخلال بمبدأي تكافؤ الفرص وحرية المنافسة بما فى ذلك التأثير بشكل مباشر، أو غير مباشر على تصرفات طرف آخر، بهدف تقسيم العقود أو تثبيت الأسعار بشكل غير تنافسى، وفى حالة ما إذا تبين ذلك فيتم إعمال أحكام المادة (50) من القانون.$m260$,'1d38ac2588c54c00e966434a0c51fc9c'),
(123,0,$m260$المادة 123$m260$,$m260$يجب النشر عن المناقصة المحدودة على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد ممكن من المسجلين عليها المتخصصين أو المؤهلين المشتغلين بالنشاط موضوع الطرح، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لفتح المظاريف الفنية، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.$m260$,'169def2ddc464839cf877536c4d30bf3'),
(124,0,$m260$المادة 124$m260$,$m260$يجوز للجهة الإدارية شراء أو استئجار المنقولات أو العقارات أو التعاقد على مقاولات الأعمال أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية بطريق المناقصة ذات المرحلتين شريطة توافر أى من الحالات المنصوص عليها بالمادة (58) من القانون.
وتشكل بقرار من السلطة المختصة لجنة تضم عناصر فنية ومالية وقانونية تكون مهمتها اعداد كراسة شروط ومواصفات أولية على أن تتضمن بحسب طبيعة العملية الآتى:
1- الغرض من التعاقد.
2- الأداء المتوقع.
3- الخطوط العريضة للمواصفات الفنية أو معايير الأداء المطلوبة.
4- الميزات والمهام والمواصفات التى ترغب الجهة الإدارية فى التعاقد عليها.
5- المؤهلات المطلوبة لتنفيذ العقد.
6- محددات التعامل مع الأمور المتعلقة بحقوق الملكية الفكرية.
وغير ذلك من بيانات ومعلومات قد تساعد مقدمى العروض على تقديم عروضهم الفنية الأولية بدون أسعار وكذا ملاحظاتهم على شروط العقد المقترحة وأية شروط أخرى قد يرون إضافتها.
وتتبع فى المرحلة الأولى من المناقصة ذات المرحلتين الإجراءات ذاتها المحددة فى هذه اللائحة فيما يخص تشكيل لجنة اعداد القيمة التقديرية ولجنة الرد على الاستفسارات إن وجدت، ولجنة فتح المظاريف الفنية، وتحديد مبلغ التأمين المؤقت فى الحدود المقررة قانونا.
ويجب النشر عن المناقصة ذات المرحلتين على بوابة التعاقدات العامة والإعلان عنها بإحدى الصحف اليومية واسعة الانتشار، أو توجيه الدعوة للمسجلين على بوابة التعاقدات العامة المتخصصين أو المؤهلين المشتغلين بالنشاط محل الطرح، وفى هاتين الحالتين يجب ألا تقل مدتهما عن عشرين يوما قبل الموعد المحدد لفتح العروض الفنية الأولية، وتتبع الإجراءات ذاتها المنصوص عليها بهذه اللائحة بشأن محتويات الإعلان أو الدعوة بما لا يتعارض مع طبيعة المناقصة ذات المرحلتين.
ويجوز قبل طرح المناقصة ذات المرحلتين إجراء تأهيل مسبق إذا ارتأت الجهة الإدارية مناسبة ذلك وفقا للإجراءات المنصوص عليها بهذه اللائحة.$m260$,'347c3e36186b3c3c0daf0d4f2c2930ed'),
(125,0,$m260$المادة 125$m260$,$m260$يجوز فى المرحلة الأولى تلقى الاستفسارات فى الموعد المحدد إذا تضمنت شروط الطرح ذلك، ومناقشة مقدمى العروض لتوضيح موضوع العملية والوقوف على مدى استجابة عروضهم للمتطلبات والشروط التعاقدية المطلوبة، على أن يتم توثيق كافة الاستفسارات والمناقشات والرد عليها وحفظها في ملف العملية، وعلى إدارة التعاقدات إخطار كافة مقدمى العروض بالتغييرات التي تقرها الجهة الإدارية بناء على الاستفسارات.
وتشكل بقرار من السلطة المختصة لجنة لتلقى العروض الفنية الأولية ودراستها واعداد تقرير بنتائج أعمال الدراسة والمراجعة والمناقشات التى تم التوصل إليها مع مقدمى العروض المستجيبة للحد الأدنى من المتطلبات والشروط التعاقدية الواردة بكراسة الشروط وبما لا يخل بمبدأ تكافؤ الفرص بينهم، وترفع اللجنة تقريرها للسلطة المختصة لاتخاذ أى من القرارات الآتية:
1- تكليف اللجنة الفنية التي تولت إعداد كراسة الشروط والمواصفات الأولية بإعداد كراسة الشروط النهائية وفقا للنتائج التي تم التوصل إليها، وتدقيق المواصفات الفنية ومعايير التقييم وشروط العقد.
2- إلغاء إجراءات الطرح إذا كانت العروض المقدمة والتعديلات المقترحة تتطلب المزيد من التخطيط ودراسة السوق والمراجعة الفنية لموضوع الطرح على أن يتم إخطار مقدمى العروض بذلك.
وفي نهاية المرحلة الأولى يتم استبعاد العروض الفنية غير المستجيبة للمتطلبات الأساسية، وتتبع الإجراءات ذاتها المنصوص عليها بهذه اللائحة بشأن الإعلان عن النتائج وتلقى الشكاوى.$m260$,'28171cad03103f94483c85760ddd70ef'),
(126,0,$m260$المادة 126$m260$,$m260$بعد إعداد كراسة الشروط والمواصفات بصورة مدققة ومتكاملة وفقا لنتائج المرحلة الأولى يجب التأكد من الآتى:
1- توافر الاعتماد المالى للعملية.
2- تدقيق القيمة التقديرية ومبلغ التأمين المؤقت فى ضوء الشروط النهائية التى تم اعدادها.
3- أن كافة المتطلبات قد تم استيعابها.
وتقوم إدارة التعاقدات فى المرحلة الثانية بتوجيه إخطار لكافة المتقدمين المستجيبين للتقدم بعطاءات متضمنة عروض فنية ومالية نهائية طبقا لكراسة الشروط والمواصفات النهائية المدققة.
وتتبع الإجراءات ذاتها المحددة في هذه اللائحة فيما يخص فتح المظاريف ودراسة وتقييم العطاءات والبت فيها، وإعلان النتائج.$m260$,'7b9621a5456b3424d0f1ad6ae856f89a'),
(127,0,$m260$المادة 127$m260$,$m260$يجب النشر عن المناقصة المحلية على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد ممكن من المسجلين عليها المتخصصين أو المؤهلين المشتغلين بنوع النشاط المزمع طرحه، والذين يقع نشاطهم داخل نطاق المحافظة التى يتم فيها تنفيذ موضوع التعاقد، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لفتح المظاريف الفنية، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.
ويجوز بموافقة السلطة المختصة بالجهة الإدارية حال قصر الطرح على المشروعات المتوسطة والصغيرة ومتناهية الصغر تضمين كراسة الشروط والمواصفات نموذج إقرار بديل عن التأمين المؤقت مفادة الالتزام بالسير فى الإجراءات ويقوم صاحب العطاء بالتوقيع عليه وإرفاقه بمظروفه الفنى، وفى حالة تقاعس صاحب العطاء الفائز عن الوفاء بسداد نسبة التأمين النهائى فيتم خصم قيمة التأمين المؤقت من مستحقاته لدى الجهة الإدارية وفى حالة عدم كفايتها تلجأ إلى خصمها من مستحقاته لدى أى جهة إدارية أخرى أيا كان سبب الاستحقاق، ودون الحاجة إلى اتخاذ أى اجراء آخر يجوز لها إلغاء العقد أو تنفيذه بواسطة أحد أصحاب العطاءات التالية لعطائه بحسب ترتيب أولويتها كما يكون لها أن تخصم منه قيمة كل خسارة تلحق بها، مع عدم الإخلال بحق الجهة الإدارية فى الرجوع عليه قضائيا بما لم تتمكن من استيفائه من حقوق بالطريق الإدارى ويخطر جهاز تنمية المشروعات المتوسطة والصغيرة والمتناهية الصغر بعدم الالتزام بسداد التأمين النهائى لأخذ ذلك فى الاعتبار مستقبلا.
كما يجوز بموافقة السلطة المختصة صرف دفعة مقدمة للعطاء الفائز من تلك المشروعات وفقا للنسبة وفى الحدود المنصوص عليها بالمادة (90) من هذه اللائحة وذلك مقابل خطاب ضمان بنكى معتمد بالقيمة والعملة ذاتهما وغير مقترن بأى قيد أو شرط ويكون ساري المفعول حتى تاريخ الاستحقاق الفعلي لتلك المبالغ على أن تتضمن شروط الطرح نسبة الدفعة المقدمة وطلب تحديد أوجه صرفها.
وعلى إدارة التعاقدات بالجهة الإدارية قبل عرض مذكرة الطرح على السلطة المختصة مخاطبة فرع جهاز تنمية المشروعات المتوسطة والصغيرة والمتناهية الصغر الواقع بالمحافظة التى يتم بدائرتها تنفيذ التعاقد لإعمال شئونه وإخطار أصحاب تلك المشروعات لتسجيل بياناتهم وتحديثها على بوابة التعاقدات العامة على أن يقوم فرع الجهاز بموافاة الجهة الإدارية بأسماء وبيانات المهتمين منهم بالدخول فى العملية محل الطرح لدعوتهم وذلك خلال موعد أقصاه خمسة أيام من تاريخ تسلمه اخطار الجهة الإدارية.$m260$,'4aeff79535e5feeb500a6e802852b33b'),
(128,0,$m260$المادة 128$m260$,$m260$تسرى على كل من المناقصة المحدودة والمناقصة ذات المرحلتين والمناقصة المحلية والممارسة بنوعيها، الأحكام الخاصة بالمناقصة العامة فيما لم يرد فى شأنه نص خاص فى هذه اللائحة.$m260$,'f86a369d587e15faaed0f1423b15579a'),
(129,0,$m260$المادة 129$m260$,$m260$تسرى على شراء أو استئجار العقارات ذات الأحكام المنظمة لشراء أو استئجار المنقولات، وبما لا يتعارض مع طبيعتها.$m260$,'e8a0c9d50061935d0d2ed4837023a71e'),
(130,0,$m260$المادة 130$m260$,$m260$تتولى إجراءات التعاقد بالاتفاق المباشر على شراء، أو استئجار المنقولات، أو التعاقد على مقاولات الأعمال، أو تلقى الخدمات، أو الأعمال الفنية، أو الدراسات الاستشارية لجنة تشكل بقرار من السلطة المختصة تضم عناصر فنية ومالية وقانونية وعضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع الطلب ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، ويكون اعتماد أعمالها من السلطة المختصة دون غيرها.
على إدارة التعاقدات عرض مذكرة على السلطة المختصة تتضمن الأسباب التى أدت إلى اقتراح التعاقد بهذا الطريق وفقا للحالات الواردة بالمادة (62) من القانون كما ترفق بها صورة من خطة الاحتياجات فيما عدا الحالات المبينة قرين البنود (1)، و(4)، و(5) من المادة ذاتها.
وفور موافقة السلطة المختصة، تتولى إدارة التعاقدات النشر عن التعاقد بالاتفاق المباشر على بوابة التعاقدات العامة وفقا لما تقضى به أحكام المادة (20) من القانون على أن يتضمن النشر وصف موجز لموضوع التعاقد والمواصفات الفنية المطلوبة.
ويجوز إعداد كراسة للشروط والمواصفات لمحل التعاقد إذا تطلبت طبيعة العملية ذلك.
وعلى لجنة الاتفاق المباشر تحديد رقم مسلسل لكل عرض واثبات تاريخ ووقت استلامه ويقع على عاتقها مسئولية التحقق من مطابقة محل التعاقد من النواحى الفنية المطلوبة ومناسبة الأسعار مقارنة بأسعار السوق السائدة وقت التعاقد أو لتحديد أقل العروض سعرا، والذى يلبى جميع الشروط والمتطلبات التى حددتها الجهة الإدارية فى طلبها وذلك من واقع العرض المقدم، أو ما يتم الحصول عليه من عروض أسعار، بحسب الأحوال، وكذا أسس اختيار المتعاقد معه.
وعلى اللجنة اعداد محضر بنتيجة أعمالها تعرضه على السلطة المختصة للاعتماد وفقا لسلطات الترخيص المنصوص عليها بالمادة (63) من القانون، وتتولى إدارة التعاقدات نشر نتيجة التعاقد فور اعتماده على بوابة التعاقدات العامة واستكمال باقى الاجراءات المقررة قانونا وتوثيقها.$m260$,'2c83f4cfc5ecbb6ee54130aa10c44532'),
(131,0,$m260$المادة 131$m260$,$m260$تقوم إدارة التعاقدات فى حالات التعاقد بالاتفاق المباشر بطلب عرض أو عروض أسعار من المشتغلين بنوع النشاط المطلوب التعاقد عليه ينشر عنه على بوابة التعاقدات العامة على أن يتضمن البيانات الآتية:
1- اسم الجهة الإدارية، وعنوان إدارة التعاقدات بها ورقم التليفون والفاكس والبريد الإلكترونى للإدارة.
2- أسم العملية ورقمها.
3- مكان الحصول على كراسة الشروط والمواصفات وثمنها إن وجدت.
4- ما يفيد حجز نسبة (5%) فى الحالات التى تطلب طبيعتها ضمان المتعاقد لسلامة محل العقد.
5- وصف كامل للأصناف أو الأعمال أو الخدمات المراد التعاقد عليها حسب الاقتضاء وفقا لطبيعة التعاقد، على النحو المبين بالمادة (14) من القانون.
6- الكمية، أو حجم الأعمال أو المهام المطلوبة، والبرنامج الزمنى للتوريد، أو للتنفيذ بحسب الأحوال.
7- جميع العناصر الخاصة بالسعر ويشمل ذلك شروط التسليم وتكلفة دورة الحياة إذا كانت طبيعة العملية تتطلب ذلك وتم تضمينها بشروط الطرح.
8- مدة الارتباط بالأسعار.
9- ايضاح ما إذا كانت الترسية ستتم لكل بند على حده أم لمجموعة بنود مجمعة.
10- أسلوب ومعايير تقييم العروض.
11- طريقة تقديم العروض والموعد النهائى لتقديمها.
12- حظر التقدم بأكثر من عرض، أو تقديم تعديل للأسعار فى العرض المقدم.
13- تحديد البنود المتغيرة، أو مكوناتها بالنسبة لمقاولات الأعمال فى العقود التى تتطلب ذلك.
14- تحديد البنود التى يجوز أن يعهد بها إلى الغير من الباطن إذا تطلبت طبيعة العملية ذلك، وكذا المحددات والاشتراطات الأخرى ذات الصلة.$m260$,'506d9c4b90b391b54870ffa76f884cbe'),
(132,0,$m260$المادة 132$m260$,$m260$لوزير الصحة التعاقد بطريق الاتفاق المباشر بالنسبة للأمصال واللقاحات والعقاقير ذات الطبيعة الاستراتيجية وألبان الأطفال على أن تعد إدارة التعاقدات بوزارة الصحة دليل إجرائي بذلك تعتمده الهيئة العامة للخدمات الحكومية.
ويشكل وزير الصحة لجنة متخصصة تضم عناصر فنية ومالية وقانونية تتولى مباشرة إجراءات التعاقد ويقع على عاتقهم مسئولية التحقق من مطابقة الأصناف من حيث النوع والمواصفات والشروط للغرض المطلوبة من أجله وأن الأسعار مناسبة لسعر السوق من واقع ما يتم الحصول عليه من عروض متى توافرت، وترفع اللجنة تقريرا بنتائج أعمالها لوزير الصحة تضمنه كافة ما قامت به من إجراءات مع بيان أسباب ما تنتهى إليه من توصيات للاعتماد.$m260$,'46d5d91635dfe1e0f89195db32024cb7'),
(133,0,$m260$المادة 133$m260$,$m260$بمراعاة حكم المادة (10) من القانون يكون التعاقد بالاتفاق المباشر على شراء، أو استئجار المنقولات، أو الأعمال، أو تلقى الخدمات منخفضة القيمة اللازمة لتسيير متطلبات العمل وفقا للضوابط الآتية:
1- أن يكون اتباع هذا الطريق هو الأمثل من بين طرق التعاقد الأخرى.
2- ألا يكون محل التعاقد ضمن اتفاقية اطارية، ولا يمكن التعاقد عليه من خلال طريق الممارسة بنوعيها.
3- الأخذ فى الاعتبار عنصر الوقت لتلبية الاحتياجات المطلوبة.
4- التحقق من مناسبة السعر لأسعار السوق السائدة وقت التعاقد من خلال دراسة السوق أو استرشادا بالأسعار السابق التعاقد بها.
5- مطابقة محل التعاقد من النواحى الفنية المطلوبة.
6- أن يتم التعاقد مع أحد المسجلين لدى مصلحة الضرائب ويستثنى من ذلك العمليات التى تكون طبيعتها لا تتطلب ذلك.
7- التحقق من أن التعاقد لا يخل بالمنافسة ويحقق معايير القيمة مقابل المال المدفوع.
على أن تتولى إجراءات التعاقد بالاتفاق المباشر لجنة دائمة تشكل بقرار من السلطة المختصة تضم عناصر فنية ومالية وقانونية وعضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع الطلب ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، ويكون اعتماد أعمالها من السلطة المختصة، ويقع على عاتقها مسئولية التحقق من الالتزام بالإجراءات المنصوص عليها فى هذه المادة وتحديد أقل العروض سعرا، والذى يلبى جميع الشروط والمتطلبات التى حددتها الجهة الإدارية وذلك من واقع ما يتم الحصول عليه من عرض أو عروض أسعار، مع مراعاة عدم تكرار التعاقد مع المتعاقد ذاته فى العملية ذاتها.$m260$,'74c3470d5096ce277c34eb271ef23a29'),
(134,0,$m260$المادة 134$m260$,$m260$يجوز للجهة الإدارية شراء أو استئجار العقارات فى الحالات الطارئة، أو العاجلة، أو لدواعى المصلحة العامة، وذلك باتباع الإجراءات ذاتها المنصوص عليها بالمادة (130) من هذه اللائحة والمنظمة للتعاقد بالاتفاق المباشر على شراء أو استئجار المنقولات، أو التعاقد على مقاولات الأعمال، أو تلقى الخدمات، أو الأعمال الفنية أو الدراسات الاستشارية.$m260$,'8e1a497173f663154f366a6f5ef9fcd9'),
(135,0,$m260$المادة 135$m260$,$m260$يكون التعاقد بأسلوب الاتفاقية الاطارية فى أى من الحالات المنصوص عليها بالمادة (65) من القانون وصولا إلى تحديد الشروط والأسعار التى تحكم أوامر التوريد، أو الإسناد المزمع إصدارها بحسب الأحوال.
وبمراعاة أحكام المادة (19) من القانون والأحكام المنظمة لإعداد كراسة الشروط والمواصفات المنصوص عليها بهذه اللائحة يجب أن تتضمن كراسة الشروط والمواصفات الخاصة بالمناقصة، أو الممارسة بأنواعهما، أو الاتفاق المباشر بحسب الأحوال الآتى:
1- الإشارة إلى أن الإجراءات سوف تنتهى بإبرام اتفاقية اطارية مع من يتم الترسية عليه، أو عليهم.
2- الجهات الإدارية المشاركة فى الاتفاقية الاطارية والاشتراطات ذات الصلة.
3- تحديد نمط الاتفاقية الاطارية إما مفتوحة، أو مغلقة، وفى حالة الاتفاقية الاطارية المفتوحة يجب تحديد الحد الأدنى لمن سيسمح لهم بالاشتراك فيها.
4- صيغة وأحكام وشروط ومدة الاتفاقية وبما لا يقل عن عامين ماليين واستثناء يجوز مدها لمدة أخرى بما لا يجاوز أربعة أعوام شريطة موافقة السلطة المختصة بالجهة الإدارية الطارحة وتضمين كراسة الشروط والمواصفات المدة المحددة وضوابطها.
5- البيانات الاحصائية لمعدلات الطلب ومعدلات الاستهلاك التاريخية، والمؤشرات المستقبلية الاسترشادية لمحل الطرح والتعاقد.
6- أطر الأعمال، أو الخدمات، أو الدراسات الاستشارية، بحسب الأحوال.
7- تحديد ما إذا كانت الاتفاقية سوف تبرم مع واحد أو أكثر من أصحاب العطاءات الفائزين وذلك إذا كانت العملية قابلة للتجزئة.
8- ما يفيد أن التأمين المؤقت سوف يتم تأديته وفقا لما تحدده السلطة المختصة بالجهة الطارحة بناء على البيانات الاحصائية لمعدلات الطلب ومعدلات الاستهلاك التاريخية، والمؤشرات المستقبلية الاسترشادية التى سيتم تضمينها بشروط الطرح، وأن التأمين النهائى سوف يتم تأديته للجهة الإدارية مصدرة أمر التوريد، أو الاسناد بحسب الأحوال وفقا للنسبة المنصوص عليها بالقانون.$m260$,'0715cd3c4c96bf6d848adfc878195709'),
(136,0,$m260$المادة 136$m260$,$m260$يكون تحديد نمط الاتفاقية الاطارية وفقا لاحتياجات الجهة، أو الجهات الإدارية بناء على دراسة السوق لمحل الاتفاق، ووفقا للآتى:
1- الاتفاقية الاطارية المغلقة يتم اختيارها لتوفير الاحتياجات بأقل الأسعار والتى تغطى مدى زمنى مستقبلي، أو يكون التوريد، أو التنفيذ على دفعات، ولا يجوز طوال مدة سريانها اشتراك غير من تم الترسية عليه، أو عليهم طوال مدة تنفيذها.
2- الاتفاقية الاطارية المفتوحة ويتم اختيارها لتوفير الاحتياجات السريعة والشائعة بشكل فعال بأقل الأسعار، ويجوز طوال مدة سريانها السماح باستلام عطاءات من الموردين، أو المقاولين، أو مقدمى خدمات، أو الاستشاريين، للدخول فيها على أن يتم اخطارهم بنتيجة دراسة الجهة الإدارية لعروضهم الفنية والمالية، ويتم تنفيذ الاتفاقية الاطارية المفتوحة من خلال المنظومة الإلكترونية حال اكتمالها وانتظامها.$m260$,'10335b11b4dbb41fbb4188df9b2dee4f'),
(137,0,$m260$المادة 137$m260$,$m260$تتولى إدارة التعاقدات رفع مذكرة للسلطة المختصة للموافقة على التعاقد على عمل ابتكاري بأسلوب المسابقة.
وتشكل بقرار من السلطة المختصة لجنة فنية للتحكيم متخصصة ومحايدة ويجوز لها الاستعانة بذوي الخبرة من جهات إدارية أخرى لها خبرة بموضوع المسابقة، وتتولى اللجنة اعداد مستندات المسابقة متضمنة توصيف دقيق لموضوعها والغرض منه والجوائز، أو المكافآت، أو الامتيازات الممنوحة للفائزين وكيفية التعامل مع حقوق الملكية الفكرية للمتسابقين، واعداد أسس ومعايير الاختيار وأسلوب التواصل مع المتسابقين.
وتتولى ادارة التعاقدات الإعلان عن المسابقة مرة واحدة بإحدى الصحف اليومية واسعة الانتشار بالإضافة للنشر عنها على بوابة التعاقدات العامة، على أن يتضمن الإعلان البيانات الآتية:
1- موضوع المسابقة والغرض منها.
2- مكان وموعد الحصول على مستندات المسابقة والإشارة إلى إمكانية الاطلاع عليها على بوابة التعاقدات العامة.
3- موعد ومكان تقديم عروض المتسابقين.
4- معايير وأسس تقييم المتسابقين.
5- الجوائز أو المكافآت الممنوحة للفائزين.
وغيرها من البيانات التى تراها الجهة الإدارية ضرورية.
تتولى إدارة التعاقدات استلام وحصر العروض المقدمة من المتسابقين وإثبات عددها بموجب محضر يعد لذلك.
وتسلم العروض المقدمة من المتسابقين إلى لجنة التحكيم وذلك دون الإفصاح عن هوية المتسابقين.
تتولى لجنة التحكيم دراسة العروض المقدمة من المتسابقين طبقا للأسس والمعايير المحددة مسبقا، ولها فى سبيل ذلك طلب أى إيضاحات من المتسابقين وذلك بمعرفة إدارة التعاقدات على أن تعد اللجنة تقريرا متضمنا نتيجة دراستها للعروض المقدمة من قبول، أو استبعاد على أن يكون قرارها نافذا بعد اعتماد السلطة المختصة له.
وتتولى إدارة التعاقدات نشر نتائج المسابقة على بوابة التعاقدات العامة فور اعتماد السلطة المختصة لتلك النتائج ويجب أن توثق كافة الإجراءات التى تمت.$m260$,'2c689c68c82bedb7fba2ac81bc7f822e'),
(138,0,$m260$المادة 138$m260$,$m260$على الجهة الإدارية ألا تبقى بالمخازن أصناف زائدة عن حاجتها، أو مستغنى عنها، أو بطل استعمالها، أو يخشى عليها من التلف، أو غير صالحة للاستعمال، ويتم تحديد المسئولية فى حالة بقاء الأصناف التى يتقرر الاستغناء عنها لمدة تزيد على سنة من تاريخ تقرير الاستغناء عنها دون العرض على السلطة المختصة بذلك، تجنبا لتراكم الأصناف بالمخازن.
ويتعين على إدارة التعاقدات التنسيق مع إدارة المخازن لإعداد حصر بالأصناف المستغنى عنها، يتم عرضه على السلطة المختصة متضمنا مقترح التصرف، وفى حالة إذا ما قررت السلطة المختصة التصرف بالبيع تتولى إدارة التعاقدات إعداد توقيتات للتصرف بالبيع، أو التأجير، والترخيص بالانتفاع، أو بالاستغلال يتم نشرها على بوابة التعاقدات العامة، ويجوز للجهة الإدارية الاتفاق مع الهيئة العامة للخدمات الحكومية لقيامها بتولي الإجراءات نيابة عن الجهة الإدارية فى حدود أحكام القانون وهذه اللائحة.
وإذا كانت الجهة الإدارية متعاقدة مع مقدم خدمة للقيام بعملية البيع، أو التأجير، أو الترخيص بالانتفاع، أو بالاستغلال فإنه يقوم بإجراءات الإعلان على حسابه طبقا لشروط تعاقده مع الجهة الإدارية، على أن يكون من المقيدين بسجل الخبراء المثمنين، وتقتصر مهمته على القيام بأعمال الدلالة فقط دون الاشتراك فى أعمال لجان وضع الثمن الأساسى، ويراعى أن يتم التعاقد مع مقدم الخدمة فى حدود أحكام القانون وهذه اللائحة.$m260$,'f91e585f277b8e3f2eb8f7cbdb9474c5'),
(139,0,$m260$المادة 139$m260$,$m260$يعمل فى شأن التعاقد بطريق المزايدة العلنية العامة على بيع وتأجير المنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف بالإجراءات المنظمة لمرحلة ما قبل الطرح ومرحلة الطرح ومرحلة الترسية والتعاقد المنصوص عليها فى هذه اللائحة.$m260$,'b767a8f419b39977740011a2c40006de'),
(140,0,$m260$المادة 140$m260$,$m260$تسرى على المزايدة المحدودة والمحلية إجراءات المزايدة العلنية العامة ذاتها فيما لم يرد بشأنه نص خاص فى هذه اللائحة.$m260$,'0a97f72325e498b7589eadd996e9c839'),
(141,0,$m260$المادة 141$m260$,$m260$على لجنة المزايدة أن تعلن للمتزايدين فى بداية جلسة المزايدة العلنية العامة البيانات والمواصفات الكافية عن موضوع البيع، أو التأجير، أو الترخيص بالانتفاع، أو بالاستغلال دون ذكر الثمن الأساسى، ثم تتولى إجراءات التزايد مع المتزايدين من خلال جولة أو عدة جولات فى الجلسة ذاتها للوصول لأعلى سعر مستوفى للشروط.
ويجوز فى الحالات الاستثنائية أن تكون جلسة التزايد على أكثر من يوم لكل مجموعة أو أكثر على حده، شريطة أن تتضمن شروط الطرح ذلك وأن تكون لكل مجموعة ثمن أساسي منفصل فى ظروف مغلقة.
وفى جميع الحالات يحظر إعادة فتح باب التزايد مرة أخرى لما تم الانتهاء من التزايد عليه.
كما يحظر الاتفاق بين المتزايدين قبل أو أثناء جلسة المزايدة لتحقيق غرض غير مشروع أو للإخلال بمبدأي تكافؤ الفرص وحرية المنافسة بما فى ذلك التأثير بشكل مباشر أو غير مباشر على تصرفات طرف آخر، بهدف تقسيم العقود أو تثبيت الأسعار بشكل غير تنافسى، وفى حالة تبين ذلك يتم اعمال حكم المادة (50) من القانون.
ويكون ترسية المزايدة على أعلى سعر مستوفى للشروط بشرط ألا يقل عن الثمن الأساسى، وتحرر لجنة المزايدة محضرا بإجراءاتها تبين فيه قيمة التأمينات المؤقتة المؤداة من المتزايدين وما تم رده وما تم مصادرته، ويتم التوقيع من جميع أعضاء اللجنة ورئيسها على المحضر.
وتعتمد قرارات وتوصيات لجنة المزايدة من السلطة المختصة.$m260$,'c566a81d5d21b1df7e7b91dc6a97500e'),
(142,0,$m260$المادة 142$m260$,$m260$فى حالة إجراء البيع، أو التأجير، أو الترخيص بطريق المزايدة بالمظاريف المغلقة تطبق الشروط والقواعد ذاتها والإجراءات المنصوص عليها بهذه اللائحة بشأن التعاقد بطريق المناقصة العامة، وبما لا يتعارض مع طبيعة البيع، أو التأجير، أو الترخيص.$m260$,'494b220bee673c175e20dbfaabe10937'),
(143,0,$m260$المادة 143$m260$,$m260$يجب النشر عن المزايدة المحدودة على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد من المسجلين عليها المتخصصين، أو المؤهلين المشتغلين بنوع النشاط المزمع طرحه، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لجلسة المزايدة، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.$m260$,'9664e809f89ddaecbdf18be96b35e71b'),
(144,0,$m260$المادة 144$m260$,$m260$يجب النشر عن المزايدة المحلية على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد ممكن من المسجلين عليها المتخصصين، أو المؤهلين المشتغلين بنوع النشاط المزمع طرحه، والذين يقع نشاطهم داخل نطاق المحافظة التى يقع فى دائرتها موضوع البيع، أو التأجير، أو الترخيص، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لجلسة المزايدة، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.
ويجوز لإدارة التعاقدات بالجهة الإدارية قبل عرض مذكرة الطرح على السلطة المختصة إخطار فرع جهاز تنمية المشروعات المتوسطة والصغيرة والمتناهية الصغر الواقع بالمحافظة التى يتم بدائرتها موضوع البيع، أو التأجير، أو الترخيص، لحث أصحاب تلك المشروعات المتخصصين، أو المؤهلين المشتغلين بنوع النشاط المزمع طرحه لتسجيل بياناتهم، أو تحديثها على بوابة التعاقدات العامة، على أن يقوم فرع الجهاز بموافاة الجهة الإدارية بأسماء وبيانات المهتمين منهم للدخول فى المزايدة لدعوتهم وذلك خلال موعد أقصاه خمسة أيام من تاريخ تسلمه اخطار الجهة الإدارية.$m260$,'cb7629678b25a4421accdfbbe29553cd'),
(145,0,$m260$المادة 145$m260$,$m260$تسرى على بيع وتأجير المنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع، أو استغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف ذات القواعد والإجراءات المنظمة لشراء المنقولات، أو استئجارها فيما لم يرد بشأنه نص خاص، وذلك كله بما لا يتعارض مع طبيعة البيع، أو التأجير، أو الترخيص أو الاستغلال.$m260$,'244c0d60a4344d3aba75cfcd1e1952ca'),
(146,0,$m260$المادة 146$m260$,$m260$يكون التعاقد على بيع أو تأجير المنقولات أو العقارات أو المشروعات التى ليس لها الشخصية الاعتبارية أو الترخيص بالانتفاع أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف بطريق الاتفاق المباشر وفقا لأحكام المادة (71) من القانون، وباتباع الإجراءات ذاتها المنصوص عليها بالمادة (130) من هذه اللائحة، وبما لا يتعارض مع طبيعة البيع أو التأجير أو الترخيص.
ويشترط فى جميع الحالات ألا تقل قيمة البيع، أو التأجير، أو الترخيص عن الثمن الأساسي التى قدرتها لجنة وضع الثمن الأساسى.$m260$,'92c55fed03d469f8736bf3bbd14f0db3'),
(147,0,$m260$المادة 147$m260$,$m260$يكون تسليم الأصناف المباعة بمعرفة لجنة تشكل بقرار من السلطة المختصة يرأسها موظف مسئول وعضوية أمين المخزن المختص وعضو يندبه مدير المخازن من غير أمناء المخازن بالإضافة لمن ترى السلطة المختصة أهمية ضمهم لعضوية اللجنة، وعلى اللجنة مراعاة أن يكون التسليم حسب التقسيم الذى أجرته لجنة التصنيف من حيث الكمية والمواصفات وما أسفرت عنه قرارات البيع.
ويكون تسليم محل البيع، أو التأجير، أو الترخيص بالنسبة لغير المنقولات بمعرفة لجنة يصدر بتشكيلها قرار من السلطة المختصة برئاسة موظف مسئول وتضم فى عضويتها عناصر فنية ومالية وقانونية بحسب أهمية وطبيعة محل التسليم، وعلى اللجنة أن تراعى عند التسليم التحقق من تنفيذ ما أسفرت عنه من قرارات البيع، أو التأجير، أو الترخيص.$m260$,'647141221da547a945e1295b68557171'),
(148,0,$m260$المادة 148$m260$,$m260$فى عمليات تأجير المنقولات والعقارات والمشروعات والترخيص بالانتفاع أو باستغلال العقارات والمشروعات التى ليس لها الشخصية الاعتبارية يجب الحصول على موافقة السلطة المختصة بالجهة الإدارية متضمنة المدة الاقتصادية للتعاقد والأسس التى استند إليها فى تحديدها وفقا للدراسة الفنية والمالية لموضوع التعاقد.
ويجب تضمين شروط الطرح الآتى:
1- طبيعة النشاط محل الطرح بشكل محدد.
2- مدة التعاقد واشتراطات مدها إذا ارتأت الجهة الإدارية مناسبة ذلك مع بيان الحد الأقصى للمد والأسس الاقتصادية التى استندت إليها الجهة الإدارية فى تحديدهما، وفى حالات المشروعات ذات الطبيعة الخاصة التى تتطلب استثمارات ضخمة لإنجازها واستغلالها يتعين على الجهة الإدارية اعداد دراسة جدوى اقتصادية لها توضح بها الأسس التى استندت إليها فى تحديدها لمدة التعاقد والحد الأقصى لمدها، وذلك كله دون الإخلال بمبادئ العلانية والشفافية والنزاهة وحرية المنافسة وتكافؤ الفرص.
3- مواعيد السداد وجزاء عدم الالتزام بها.
4- زيادة المقابل سنويا بنسبة مئوية من قيمة التعاقد التراكمية.
5- حظر التنازل للغير عن محل العقد أو اتاحته للغير من الباطن بعد التعاقد.
6- النص على التزام المتعاقد وعلى نفقته بإجراء ما يلزم من تجهيزات وأعمال تطوير وصيانة مستمرة لمحل التعاقد ضمانا لإعادته للجهة المالكة بحالة جيدة فى نهاية المدة.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة بما يتماشى مع طبيعة العملية.
ويجوز أن تتضمن شروط الطرح تقديم تسهيلات وبما يتفق مع محل العقد وتحقيقا لاقتصاديات المشروع.
ويتعين قبل نهاية مدة التأجير أو الترخيص اتخاذ إجراءات الطرح من جديد فى الوقت المناسب بإحدى الطرق المنصوص عليها بالمادة (7) من القانون وفى حدود القواعد والإجراءات المنصوص عليها بهذه اللائحة وأن تقوم الجهة الإدارية بحصر ما تم من تجهيزات وغيرها فى نهاية كل مدة وقبل اعادة الطرح وأخذ ذلك فى الاعتبار عند تحديد القيمة الإيجارية أو مقابل الانتفاع.$m260$,'a64db6406556dce4ffec30f970895b63'),
(149,0,$m260$المادة 149$m260$,$m260$يكون التعاقد على الدراسات الاستشارية وفقا لأحكام المادة (73) من القانون، ويتعين على إدارة التعاقدات اتباع طريق المناقصة المحدودة، أو المناقصة ذات المرحلتين أو المناقصة المحلية، ويكون التعاقد مع من تتوافر بشأنهم شروط الكفاءة الفنية والملاءة المالية وحسن السمعة من استشاريين.
ويجوز استثناء التعاقد بطريق المناقصة العامة، أو المحلية، أو الاتفاق المباشر على الدراسات الاستشارية فى العمليات ذات الطبيعة الروتينية، أو البسيطة، أو النمطية، أو التى لها أطر فنية ثابته، ومن ذلك أعمال المراجعة، إعداد التصميم، وغيرها من أعمال غير معقدة.
كما يجوز التعاقد مع أحد الاستشاريين بذاته من خلال مناقصة محدودة، أو مناقصة محلية، أو اتفاق مباشر، وذلك عندما يكون المؤهل والخبرة شرطين أساسيين في العملية.$m260$,'a58699f36eacc07a985f13b0e0272160'),
(150,0,$m260$المادة 150$m260$,$m260$يجوز لإدارة التعاقدات إجراء تأهيل مسبق للاستشاريين المحتمل دعوتهم للاشتراك فى العملية المزمع طرحها، وذلك باتباع الإجراءات المنصوص عليها بالمادة (21) من القانون، والمواد أرقام (37)، (38)، (39)، (40) من هذه اللائحة، وبما لا يتعارض مع طبيعة الدراسات الاستشارية، مع اعداد قائمة مختصرة بمن تم تأهلهم ممن لديهم القدرة على أداء المهمة المطلوبة وفقا لمتطلبات التأهيل حال الطرح.$m260$,'e6fe0e42b14e3bb3bf28eaff5618f64e'),
(151,0,$m260$المادة 151$m260$,$m260$يتعين على الجهة الادارية أن تضمن مستندات الطرح متطلباتها واشتراطاتها وإطار أعمال الدراسات الاستشارية، على أن يكون من بينها البيانات الآتية:
1- وصف عام للعملية والغرض منها وأهدافها بما يتلاءم مع احتياجات الجهة الإدارية.
2- نطاق الدراسة والمهام المطلوب من الاستشاري تنفيذها والعناصر الأساسية لها والاختصاصات وغيرها من متطلبات.
3- المخرجات المطلوب تقديمها بما فى ذلك التقارير، أو البيانات، أو المعلومات، أو الخرائط، أو الاحصائيات، أو التصميمات وغيرها، والجدول الزمنى لتقديم كل منها.
4- وصف للتكنولوجيا، أو الخبرات المطلوب استخدامها فى تنفيذ موضوع التعاقد وكيفية تدريب العاملين بالجهة الإدارية عليها.
5- بيان مفصل ببيانات الكوادر الفنية الاساسية المطلوبة ومهامهم ومؤهلاتهم وخبراتهم وحجم المهام المسندة لكل منهم في العملية.
6- محل تنفيذ العملية موضوع التعاقد.
7- المدخلات والتسهيلات الفنية التى ستقدمها الجهة الإدارية المتعاقدة للاستشاري.
8- المدد الزمنية لتنفيذ المهام محل العملية على أن تكون محددة بعدد الأيام، أو الأشهر، أو السنوات بحسب طبيعة العملية، والتاريخ المقترح للبدء والانتهاء من المهام كاملة.
9- شكل التقارير المطلوب تقديمها وإجراءات وشروط تقديمها.
10- الاطار العام لمعايير التقييم.
وغيرها من البيانات التى ترى الجهة الإدارية أهمية تضمينها.
ويراعى عدم المبالغة فى التفاصيل الغير ضرورية أو وضع متطلبات مقيدة، وبما يمكن أصحاب العطاءات من تقديم عروضهم بشكل ابتكاري يحقق للجهة الادارية متطلباتها بالجودة المرجوة.$m260$,'282e5e5d60182a6788f58503aa0d1833'),
(152,0,$m260$المادة 152$m260$,$m260$يكون تحديد القيمة التقديرية لعقود الدراسات الاستشارية على أساس تقدير التكاليف الكلية لأداء الاستشاري للمهمة المطلوبة، ومنها تكاليف فريق العمل والكوادر والوقت المستغرق فى تنفيذ العقد وغير ذلك من تكاليف وفقا لطبيعة العملية، ويتم تحديدها على سبيل المثال وفقا لأى من الأسس الآتية:
1- التعاقد على أساس مبلغ مقطوع، وذلك فى المهام التي يكون فيها مضمون ومدة الخدمات والنتائج المطلوبة من الاستشاري محددة، ومن ذلك على سبيل المثال عمليات التخطيط البسيطة، دراسات الجدوى، التصميمات الهندسية.
2- التعاقد المبنى على الوقت، وذلك في المهام التي يكون من الصعب تحديد نطاق الخدمات وطول مدة التنفيذ بدقة، ومن ذلك الدراسات التى تتطلب أكثر من تخصص، الإشراف على تنفيذ الأعمال، مهام التدريب، ويجب أن تتضمن هذه العقود حد أقصى لإجمالي قيمة العقد، وبصفة عامة يتطلب هذا النوع من العقود وجود فريق اشراف لديه القدرة والخبرة على تقييم الاداء.
3- التعاقد على أساس النسبة المئوية، وذلك في المهام التى منها الفحص، والمراجعة، والتدقيق، ويكون فيه احتساب النسبة وفقا لما هو سائد ومتعارف عليه في السوق لمحل موضوع التعاقد.$m260$,'e7c6c104cd0ab91d0a3d6f6e8dab2465'),
(153,0,$m260$المادة 153$m260$,$m260$بمراعاة أحكام المادة (19) من القانون وكراسات الشروط النموذجية الصادرة من الهيئة العامة للخدمات الحكومية تلتزم إدارة التعاقدات بتضمين كراسات شروط عمليات التعاقد على الدراسات الاستشارية بحد أدني البيانات الآتية:
1- تحديد طريق التعاقد المناسب وفقا لما تضمنته المادة (73) من القانون.
2- وسيلة وأسلوب التواصل مع الجهة الإدارية بما في ذلك عنوان وتليفون ورقم فاكس وبريد الكرتوني واسم المخول له التواصل مع المتعاملين.
3- ما يفيد توافر الاعتماد المالى المخصص للعملية.
4- البيانات الواجب توافرها فى أصحاب العطاءات ومعايير التحقق من توافر شروط الكفاءة الفنية والملاءة المالية وحسن السمعة.
5- صور سداد التأمين المؤقت ومبلغه والتأمين النهائى ونسبته.
6- المدة المناسبة لصلاحية سريان العطاءات.
7- توصيف المهمة وإطار الاعمال الاستشارية والمتطلبات والاشتراطات وفقا لما تضمنته المادة (151) من هذه اللائحة.
8- طلب بيان بأسماء ووظائف وخبرات الكوادر التى ستقوم بالمهمة.
9- شهادات ترخيص سارية للمكاتب الاستشارية.
10- تحديد مراحل تنفيذ العمل للمهمة حسب طبيعة كل عملية (التصميم، الإشراف...إلخ).
11- تحديد التسهيلات التى ستقدم للاستشاريين، وامكانية اتاحة الفرصة لهم للاطلاع على كافة البيانات والمعلومات اللازمة لتنفيذ المهمة.
12- تحديد أسلوب السداد وفقا لطبيعة العملية وتوقيتاته.
13- تحديد المدخلات والمستلزمات التى توفرها الجهة الإدارية للاستشاري أثناء أدائه واجباته.
14- تحديد المخرجات المطلوبة من تقارير، أو بيانات، أو خرائط، أو دراسات استقصائية وغيرها من مخرجات مع تحديد الجدول الزمنى لتسليمها وتقديم التقارير المطلوبة والتاريخ الذى يبدأ فيه الاستشاري الفائز بتقديم خدماته.
15- أسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول.
16- تحديد البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن إذا تطلبت طبيعة العملية ذلك، وكذا المحددات والاشتراطات الأخرى ذات الصلة.
17- تقديم إقرار بعدم وجود تضارب محتمل فى المصالح لأعمال الاستشاري.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة.
وفى حالة إذا ما تعذر على الجهة الإدارية توفير الكوادر الفنية من العاملين بها لإعداد كراسة الشروط والمواصفات يجوز لها الاستعانة بذوي الخبرة من العاملين بالجهات الإدارية الأخرى، وإذا تعذر ذلك يجوز التعاقد مع استشاري بذاته لإعدادها وفقا لحكم المادة (73) من القانون.$m260$,'e5ceb20d0337361254b5eafd7998ea33'),
(154,0,$m260$المادة 154$m260$,$m260$تقدم العطاءات وفقا لأحكام المادة (23) من القانون، وطبقا للمدد المنصوص عليها بالمادة (45) من هذه اللائحة والمحددة بكراسة الشروط والمواصفات.$m260$,'9f1a63c986eaca45c5805b8e70b52234'),
(155,0,$m260$المادة 155$m260$,$m260$يجب أن يحتوى المظروف الفنى فى عمليات الدراسات الاستشارية كحد أدنى على الآتى:
1- ما يفيد سداد التأمين المؤقت المطلوب طبقا لكراسة الشروط والمواصفات.
2- بيان الشكل القانوني للاستشاري والمستندات الدالة على ذلك.
3- بيانات القيد بالنقابات المهنية وفقا لطبيعة العملية.
4- ما يفيد شراء كراسة الشروط والمواصفات.
5- الاشتراطات والمتطلبات الفنية الواردة بكراسة الشروط والمواصفات ووفقا لما تضمنته المادة (153) من هذه اللائحة.$m260$,'5ffa3e4e66149e67329964f12ca0ee96'),
(156,0,$m260$المادة 156$m260$,$m260$فى عمليات الدراسات الاستشارية يتعين أن يحتوى المظروف المالى للاستشاري على تكلفة أداء المهمة، ومنها أتعاب فريق العمل والكوادر وتكاليف الوقت المستغرق فى تنفيذ المهمة والمخرجات من خرائط وتقارير وغيرها من عناصر التكلفة أو متطلبات، ووفقا لما تضمنه الجهة الادارية بكراسة الشروط والمواصفات.$m260$,'636c8aa2a653dd75c34b8f63fb2185b3'),
(157,0,$m260$المادة 157$m260$,$m260$بمراعاة أحكام الفقرة الأولى من المادة (73) من القانون والمادة (72) من هذه اللائحة، يكون تقييم العطاءات بنظام النقاط وذلك بغرض الوصول إلى معايير الجودة الفنية والسعر مجتمعين على أن تتضمن شروط الطرح أسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول، ومنها على سبيل المثال الآتى:
1- الاستجابة لشروط الطرح.
2- المؤهلات العلمية والأكاديمية للاستشاري.
3- حجم الأعمال المماثلة.
4- عدد سنوات الخبرة.
5- الجدول الزمنى لتسليم المخرجات المطلوبة.
وغيرها من أسس وعناصر التقييم التى تراها الجهة الإدارية ضرورية.
واستثناء من ذلك، وبمراعاة أحكام الفقرة الثانية من المادة (73) من القانون، تكون الترسية على الأقل سعرا من العروض المقبولة فنيا، أما في الحالات الواردة بالفقرة الثالثة من المادة ذاتها تكون الترسية فيها إما بنظام النقاط، أو الاقل سعرا بحسب الاحوال.$m260$,'b2c335819511f03b84b0e081b1998429'),
(158,0,$m260$المادة 158$m260$,$m260$يتعين على الاستشاري الالتزام بأعلى معايير النزاهة والشفافية عند التقدم بعطائه، أو اثناء تنفيذ العقد، كما يلتزم بتجنب تعارض المصالح فى المهام التى سوف يقوم بها ومهامه الأخرى، أو سابق تعاملاته مع أصحاب العطاءات الأخرين.
وتتولى ادارة التعاقدات الحصول على إقرار من الاستشاري يفيد تعهده بتجنب تعارض المصالح، وأنه فى حالة مخالفته لذلك فسوف يتم استبعاده، أو فسخ العقد، بحسب الأحوال، واتخاذ الإجراءات المنصوص عليها بالقانون وهذه اللائحة، ويحفظ الاقرار فى ملف العملية.$m260$,'a298476b5e51189458143b9bf708206d'),
(159,0,$m260$المادة 159$m260$,$m260$يسرى على التعاقد على الدراسات الاستشارية ذات الإجراءات المنصوص عليها بهذه اللائحة بشأن عقود شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية، فيما لم يرد فى شأنه نص خاص، وذلك كله بما لا يتعارض مع طبيعة الدراسات الاستشارية.$m260$,'2f196eae9ae467eb2d214c47152babca'),
(160,0,$m260$المادة 160$m260$,$m260$تتولى إدارة التعاقدات رفع مذكرة للسلطة المختصة للموافقة على التعاقد بالاتفاق المباشر مع مقدمى الخدمات الاساسية التى تمتلك الدولة فيها حصة حاكمة تسمح لها بتعيين أغلبية أعضاء مجلس إدارتها، أو التحكم على أى نحو فى القرارات الصادرة من مجلس إدارتها، أو من الجمعية العامة لها على تقديم الخدمات الأساسية ومن ذلك الكهرباء، والمياه، والغاز وغيرها من الخدمات الأساسية اللازمة لتسيير المرفق العام ذات الطبيعة المماثلة والمحددة أسعارها من الدولة، على أن تتضمن المذكرة الأسباب ومبررات هذا التعاقد وأسماء مقدمى تلك الخدمات، وغيرها من إجراءات منصوص عليها بالمادة.
تتولى إجراءات التعاقد لجنة تشكل بقرار من السلطة المختصة تضم عناصر فنية مالية وقانونية وعضو من إدارة التعاقدات، ويكون اعتماد أعمالها من السلطة المختصة أو من تفوضه.$m260$,'c74a9aa16470a808136319995c171284'),
(161,0,$m260$المادة 161$m260$,$m260$يجب على إدارة التعاقدات مراعاة إمكانيات المشروعات المتوسطة والصغيرة والمتناهية الصغر، وذلك بهدف تعظيم حجم الفرص المتاحة لهم من خلال تبسيط الإجراءات اللازمة لتسجيلهم ومراعاة تحديد أسس ومعايير موضوعية مسبقة عند اتخاذ إجراء التأهيل المسبق لهم وبما يتماشى مع طبيعة العملية.
ويتعين عند اعداد كراسات الشروط والمواصفات مراعاة الآتى:
1- اعداد مواصفات فنية تراعى امكانيات المشروعات المتوسطة، والصغيرة، والمتناهية الصغر وبما يتلاءم مع الاداء والغرض المطلوب، ودون أن يؤثر ذلك على تكافؤ الفرص والالتزام بمعايير الجودة والأداء فى التنفيذ.
2- الاعفاء من سابقة الأعمال وميزانية سنوات سابقة ما دامت طبيعة العملية لا تتطلب ذلك.
3- عدم المبالغة فى تحديد مبلغ التأمين المؤقت، أو الإعفاء منه وفقا لحكم المادة (59) من القانون.
وغير ذلك من إجراءات تهدف إلى تعظيم حجم الفرص المتاحة لهم.
ويجب على إدارة التعاقدات الالتزام بالنسبة المحددة بالمادة (75) من القانون، واعداد تقارير ربع سنوية ترفع إلى السلطة المختصة متضمنة قيمة ما تم ترسيته من عمليات على تلك المشروعات خلال تلك الفترة وفقا لخطة احتياجات الجهة الإدارية المعتمدة والتوصيات اللازمة لضمان الالتزام بالنسبة المحددة.$m260$,'13912de63fd61be613e734847eb362b4'),
(162,0,$m260$المادة 162$m260$,$m260$مع عدم الإخلال بأحكام القوانين المنظمة للتعاقدات المقدمة بناء على مبادرة من القطاع الخاص، يجوز للجهة الإدارية عندما تتلقى عرض لمشروع استثماري متكامل شامل التمويل سواء كان مقدمه شخص طبيعي، أو اعتباري بناء على مبادرة منه وليس استجابة لطلب رسمي من خلال طرق التعاقد الواردة بالمادة (7) من القانون، أن تقوم بدراسة المشروع وإخطار مقدمه بذلك، أو ترفضه وتخطر مقدمة بأنها لن تأخذه في الاعتبار، دون أن يرتب ذلك علي الجهة الإدارية أى التزامات تجاه مقدمه.
وحال دراسة الجهة الادارية للمشروع ينطوي على حقوق ملكية فكرية لمقدمه وتري الجهة الإدارية أن تنفيذه يحقق الاهداف الاقتصادية والتنموية للدولة وأن له جدوى فنية واقتصادية واجتماعية، فيجوز لها أن تطلب من مقدمه تقديم عرضه متضمن كافة البيانات الفنية والاقتصادية والمالية والتعاقدية والدراسات التفصيلية ذات الصلة به، وبما يمكنها من تقييمه بشكل تفصيلي متكامل.
وإذا ما تحققت الجهة الإدارية بعد دراستها التحليلية للمشروع فى ضوء ما قدمه المستثمر من بيانات فنية واقتصادية ومالية وتعاقديه ودراسات تفصيلية، وقامت بإجراء حوار مفتوح واستطلاع وتحليل وتقييم السوق بشأنه وانتهت الى أن المشروع وشروطه يحققا الأهداف الاقتصادية والتنموية للدولة، فتطلب من مقدمه أن يتقدم بالمشروع فى شكل نهائى، ويعرض الوزير المختص بالجهة الادارية تفاصيله على وزيري المالية والتخطيط لإعمال شئونهما، على أن يخطرا الوزير المختص بالجهة الادارية بنتائج دراستهما.
وعلى الوزير المختص بالجهة الإدارية عرض المشروع وما تم بشأنه من إجراءات على مجلس الوزراء بما في ذلك نتائج الجدوى الفنية والاقتصادية والاجتماعية له والدراسة التحليلية للهيكل الفنى والمالى ودراسات السوق ونتائجها وموافقة وزيري المالية والتخطيط، وحال اعتمادها من مجلس الوزراء، يتم الترخيص للجهة الادارية بالسير في إجراءات التعاقد على المشروع بالاتفاق المباشر، اما فى حالة رفض المشروع فيتم إعادة كافة المستندات الخاصة به لمقدمه.
ويجوز للجهة الإدارية حال عدم انطواء المشروع علي حقوق ملكية فكرية حصرية لمقدمه أن تقوم بطرحه على مقدمه وغيره للحصول على عروض تنافسية له، وذلك بما لا يخل بمبادئ الشفافية والمنافسة وتكافؤ الفرص والمساواة، ويكون التعاقد وفقا للأطر العامة والإجراءات والشروط الواجب اتباعها وضوابط إبرامه التى يعرضها الوزير المختص بحسب طبيعة المشروع والتى تقرها لجنة المؤشرات والتغيرات الاقتصادية المنصوص عليها فى المادة (4) من القانون.$m260$,'873852fd4510b7399a8a66796f3d8099'),
(163,0,$m260$المادة 163$m260$,$m260$يجوز للجهة الإدارية استثناء من أحكام القانون التعاقد على الصفقات التى تتطلب السرعة فى اتخاذ قرار التعاقد عليها بحكم طبيعتها أو التقلبات فى أسعارها وكمياتها الاقتصادية، أو التى تغطى مدى زمنى مستقبلي، أو العمليات المتعلقة بالمعاملات المنجزة فى الأسواق المالية الدولية، أو عقود المشتقات المالية والمشتريات الآجلة والمستقبلية وما يرتبط بها، وذلك كله وفقا للممارسات التجارية الدولية المطبقة التى تحددها السلطة المختصة بالجهة الإدارية.
وتتولي السلطة المختصة بالجهة الإدارية طالبة التعاقد تحديد الممارسات التجارية الدولية ذات الصلة بالموضوع محل طلبها والتى ستتبعها عند اتخاذها إجراءات التعاقد استثناء من أحكام القانون، على أن يتم عرضها على اللجنة الوزارية للمؤشرات والتغيرات الاقتصادية المنصوص عليها فى المادة (4) من القانون لدراستها واعداد تقرير بنتائج أعمالها وتوصياتها يعرضه مقرر اللجنة على مجلس الوزراء لاعتماده واتخاذه ما يلزم من إجراءات لتنفيذ ما ورد به.
كما يجوز للجهة الإدارية استثناء من أحكام القانون إبرام أي من التعاقدات الواردة بالفقرة الثانية من المادة (79) من القانون إذا كانت تحقق لها أهدافها الاقتصادية والتنموية العاجلة، أو استلزمت الظروف الاقتصادية، أو الاجتماعية سرعة إتمامها فى توقيت معين.
وبمراعاة الأطر العامة والإجراءات والشروط الواجب اتباعها والضوابط التى تعدها لجنة المؤشرات والتغيرات الاقتصادية المنصوص عليها فى المادة (4) من القانون والتى يعتمدها مجلس الوزراء ويصدر بشأنها دليل إجرائي ينظم إبرام أي من تلك العقود، يتعين على الجهة الإدارية عند النظر في التعاقد على أى منها التحقق من استيفاء دراسات الاحتياج للمشروع محل التعاقد وأولوية تنفيذه، وتوافر دراسات جدوى اقتصادية دقيقة ومقبولة لكافة الاطراف المعنية، ودراسات الجدارة الائتمانية للشركاء ومصادر التمويل والمخاطر ذات الصلة وغيرها، ووجود خطة أو برنامج مالي واضح يبرر تكلفة المشروع، وكيفية السداد وحجم رأس المال المقدم من القائمين عليه، والتأكد من توافر مواصفات معيارية فنية للمشروع كاملا ، ودراسات لاقتصاديات التنفيذ والتشغيل طوال مدة المشروع أو مدة العقد، وإمكانية توفير جميع الموافقات والتراخيص اللازمة للتنفيذ، ودراسات تؤكد ربحية المشروع مع الاخذ في الاعتبار صيانته واستبدال الأصول المتقادمة خاصة في السنوات الأخيرة من مدة المشروع أو العقد، وتكوين احتياطيات من إيراداته لاستخدامها في عمليات التجديد والصيانة والاحلال وبما يتماشى مع طبيعة المشروع والعقد، وغيرها من أمور ذات صله ترتبط بطبيعة المشروع.
ويكون التعاقد على أي من هذه المشروعات إما بالإعلان عنه أو توجيه الدعوة لقائمة مختصرة من المستثمرين المرشحين لتقديم عروضهم، أو بطريق الاتفاق المباشر في حالة عدم تقدم أكثر من مستثمر مؤهل، أو إذا وصل أكثر من مستثمر مؤهل إلى قائمة المرشحين ولم يقدم أكثر من واحد منهم عرض يستوفي المتطلبات، أو في حالة وجود مصدر واحد فقط مؤهل لتنفيذ المشروع، أو إذا كانت هناك حاجة عاجلة لتنفيذه مثل التأكد من استمرار تقديم الخدمات العامة، أو غيرها مما يجعل اللجوء إلى تنفيذ إجراءات الاختيار التنافسية أمرا غير عملي، وفي جميع الحالات يجب أن تحتوى كراسة الشروط والمواصفات على كافة المعايير والمتطلبات والاشتراطات الفنية والمالية والتعاقدية.
ويتولى الوزير المختص بالجهة الإدارية المتعاقدة وضع القواعد الخاصة بكل مشروع على حدا بالاتفاق مع وزيري المالية والتخطيط، ويجب اعتماد هذه القواعد الخاصة من مجلس الوزراء بناء على عرض الوزير المختص بالجهة الإدارية، وذلك بما لا يتعارض مع الأطر العامة والإجراءات والشروط الواجب اتباعها وضوابط إبرام أى من تلك العقود والمعتمدة من مجلس الوزراء والصادر بشأنها دليل إجرائي ينظمها.$m260$,'29e39576b97ce174ad2c28ab64fabcce'),
(164,0,$m260$المادة 164$m260$,$m260$مع مراعاة الحالات التى حظر فيها القانون التفويض، يجوز للسلطة المختصة أن تفوض فى أى من اختصاصاتها لشاغلى الوظائف القيادية دون غيرهم، على أن يكونوا ممن يشهد لهم بالكفاءة والخبرة والتمتع بصفات النزاهة والأمانة وحسن السمعة والخبرة اللازمة لممارسة الاختصاصات المفوضة لهم، شريطة أن يصدر قرار من السلطة المختصة يتضمن أسم المفوض ووظيفته وموضوع التفويض ومدته وشروطه ومتطلباته، وينتهى التفويض بإلغاء القرار الصادر بشأنه أو انتهاء مدة التفويض أو الغرض منه.
ويحظر على المفوض تفويض الأخرين فى الاختصاصات المفوض فيها، ويجب على المفوض اعداد تقارير يعرضها على السلطة المختصة بشأن ما اتخذه من إجراءات مفوض فيها، كما يجب على السلطة المختصة الأصيلة مراجعة نتائج أعمال المفوض بشكل دائم للوقوف على مستوى أدائه واتخاذ ما يلزم بشأنه.$m260$,'9a99a83cf4c9695fc89d6cca25d7ded9'),
(165,0,$m260$المادة 165$m260$,$m260$تلتزم إدارة التعاقدات بالحفاظ على المستندات والبيانات المتعلقة بإجراءات كل عملية وتوثيقها وأرشفتها بصورة منتظمة ومرتبة يسهل الرجوع إليها، والعمل على سلامة ملف العملية من أى مخاطر، أو تلف، أو ضياع، على أن يتضمن الملف بصفة خاصة الآتى:
1- صورة نموذج خطة الاحتياجات المتضمن العملية.
2- مستندات طلب المعلومات، ابداء الاهتمام، التأهيل المسبق، المسابقة إن وجدت.
3- تقرير لجنة اعداد المواصفات الفنية.
4- تقرير لجنة اعداد القيمة التقديرية أو الثمن الأساسى.
5- صورة من الموافقات والتصاريح والتراخيص اللازمة للطرح إن وجدت.
6- كراسة الشروط والمواصفات وملحقاتها.
7- مذكرة الطرح وقرارات تشكيل اللجان.
8- صورة قرار تفويض السلطة المختصة إن وجدت.
9- صورة ما يثبت نشر العملية على بوابة التعاقدات العامة.
10- أصل الإعلان بالصحيفة أو صور خطابات الدعوة بحسب الأحوال.
11- الاستفسارات إن وجدت، والرد عليها ومحضر لجنة الاستفسارات.
12- صور العطاءات المقدمة.
13- محاضر فتح المظاريف.
14- محاضر لجنة البت، أو الممارسة، أو المزايدة، أو الاتفاق المباشر بحسب الأحوال.
15- ما يثبت نشر نتائج قرارات اللجان على بوابة التعاقدات العامة.
16- جميع الإخطارات والمراسلات والمكاتبات المتعلقة بالعملية.
17- صورة من أمر التوريد، أو أمر الإسناد.
18- نسخة من العقد، أو الاتفاق بحسب الأحوال.
19- الشكاوى المقدمة إن وجدت، والرد عليها.
20- المستندات المتعلقة بتنفيذ العقد.
21- نموذج تقييم المتعاقد.
22- نموذج استقصاء المتعاقد مع الجهة الإدارية.
وغير ذلك من المستندات والبيانات ذات الصلة بالعملية.$m260$,'390b92865234b36ac79825ec20a60ddd'),
(166,0,$m260$المادة 166$m260$,$m260$يتعين على كافة الجهات الإدارية والمتعاملين معها من مجتمع الأعمال والاطراف المعنية وغيرهم من جهات ذات صلة بتطبيق أحكام القانون وهذه اللائحة الاطلاع على ما تقوم الهيئة العامة للخدمات الحكومية بنشره على بوابة التعاقدات العامة من تعديلات على القانون وهذه اللائحة والأدلة والمنشورات العامة والكتب الدورية والقرارات المتعلقة بتطبيقهما، بما يهدف إلى سهولة وسرعة الوصول إلى التشريعات المنظمة للتعاقدات العامة وإرساء مبادئ الشفافية وإتاحة المعلومات.$m260$,'3548ef88fa3e29ce7121fdb6c8dba7ed'),
(167,0,$m260$المادة 167$m260$,$m260$تظل المستندات والوثائق الورقية الصادرة من الجهات الادارية أو الواردة إليها قبل تاريخ صدور قرار وزير المالية بشأن بدء إتباع اجراءات التعاقد إلكترونيا لها الحجية القانونية، على أن تحل محلها المستندات والوثائق الرقمية التى تعمل عملها، أو تكون ناسخة.
ويتعين على كافة الجهات الإدارية والاطراف المعنية وغيرهم من جهات ذات صلة بالمهام التى تتم من خلال منظومة التعاقدات الإلكترونية الالتزام التام بالتحول للعمل من خلالها.
كما يتعين على المتعاملين مع الجهات الادارية من مجتمع الاعمال أن تكون مكاتباتهم أي كان شكلها، أو محتواها في شكل محرر الكتروني ووفقا لما يتم ميكنته من إجراءات يصدر بها قرار من وزير المالية.$m260$,'9392eb2e44d591b6d0acb09e9a90d711'),
(168,0,$m260$المادة 168$m260$,$m260$يجب على الجهات الإدارية اتخاذ إجراءات التعاقد إلكترونيا وفقا لما يتم ميكنته من إجراءات على المنظومة الإلكترونية عند اكتمالها وانتظامها، والتى تتولى الهيئة العامة للخدمات الحكومية إعدادها والإشراف عليها وتقديم الدعم الفنى لمستخدميها.
تتكامل المنظومة مع بعض الأنظمة الأخرى بوزارة المالية والجهات التابعة ذات الصلة ومنها منظومة الدفع الإلكترونى وإدارة المعلومات المالية الحكومية (GFMIS) وغيرها، وتعمل الهيئة على ربطها بالأنظمة الإلكترونية الأخرى مرحليا.
تتضمن مهام المنظومة على سبيل المثال توفير إمكانية تنفيذ المهام الآتية:
1- استيفاء نماذج إعداد ونشر وتحديث خطط التعاقدات السنوية.
2- تجميع احتياجات الجهات الإدارية على مستوى الدولة.
3- اعداد نماذج الإعلان، الدعوة، الإخطارات، التقارير المطلوبة بموجب القانون وهذه اللائحة، كراسات الشروط والمواصفات والعقود بناء على الأنماط النموذجية الموحدة، نماذج أوامر التوريد أو الاسناد، وغيرها بصورة مميكنه وموحده.
4- تسجيل وتحديث بيانات الموردين والمقاولين ومقدمى الخدمات والاستشاريين على قاعدة البيانات الإلكترونية المركزية التي يمكن البحث فيها بشكل تفاعلي من قبل الجهات الإدارية وغيرها من أصحاب المصلحة والأطراف المعنية.
5- تسجيل المستخدمين الآخرين المرخص لهم باستخدام المنظومة، ومن بينهم أعضاء اللجان وممثلي كل من وزارة المالية وإدارة الفتوى المختصة بمجلس الدولة ووزارة الاسكان.
6- امكانية الربط والتبادل البيني مع قواعد بيانات الكترونية أخرى على سبيل المثال لأغراض التحقق من تسجيل الشركات وسداد الالتزامات الضريبية والتأمينات الاجتماعية.
7- تسجيل البنوك لأغراض السداد والدفع الالكتروني وغيرها من تعاملات بنكية مثل سداد التأمين المؤقت والنهائي الكترونيا، وغيرها من مهام وردت بالقانون وهذه اللائحة يمكن ميكنتها.
8- تسجيل الجهات الإدارية ويشمل ذلك مسئوليها المفوضين، بموجب تفويض من السلطة المختصة ووفقا لاختصاصاتهم ودور كل منهم في المهام التي يتم تنفيذها على المنظومة.
9- القيام بإجراءات دراسة السوق، وطلب المعلومات، وطلب إبداء الاهتمام، وطلب التأهيل المسبق، وغيرها.
10- اعداد المواصفات الفنية والتوقيع عليها من أعضاء اللجنة الفنية الكترونيا.
11- تحميل كراسة الشروط والمواصفات من على المنظومة، وامكانية سداد ثمنها الكترونيا.
12- تقديم العطاءات والطلبات وغيرها إلكترونيا، بطريقة آمنة ودون الإفصاح عن أصحابها، وحفظ العطاءات بطريقة آمنة لا تسمح بفتحها أو الاطلاع عليها قبل الموعد النهائي لتقديم العطاءات، والإقرار الآلي لمقدم العطاء باستلام عطائه.
13- فتح العطاءات إلكترونيا وتمكين أصحابها من متابعة إجراءات فتح العطاءات والاجتماعات الأخرى التى يجوز لأصحاب العطاءات، وفقا للقانون وهذه اللائحة حضورها.
14- التقييم والترسية، مع مراعاة أن تكون قرارات الترسية من قبل أشخاص طبيعيين وليس المنظومة.
15- الإعلان والإخطار عن قرارات اللجان ونتائج أعمالها.
16- شاشات معلومات لتمكين المشاركين من الموردين والمقاولين ومقدمى الخدمات والاستشاريين، والجهات الإدارية وممثلي كل من وزارة المالية وإدارة الفتوى المختصة بمجلس الدولة ووزارة الاسكان من الوصول إلى وظائف المنظومة وتأدية مهامهم من خلالها.
17- إخطار وترشيح ممثلي كل من وزارة المالية وإدارة الفتوى المختصة بمجلس الدولة ووزارة الاسكان للمشاركة في اللجان المختلفة وفقا لأحكام القانون وهذه اللائحة.
18- توجيه المهام أو إرسال المستندات لاتخاذ الاجراءات وفقا لدورة سير العمل، ويشمل ذلك المراجعات الادارية والمالية والقانونية.
19- تتبع الإجراءات وموقف التنفيذ.
20- إعداد وإدارة الاتفاقيات الإطارية، وتسجيل الجهات الإدارية من أجل استخدامها، وإصدار أوامر التوريد أو الاسناد.
21- إجراء الممارسات والمزايدات بأنواعها إلكترونيا.
22- تقديم الشكاوى ونشر نتائج دراستها.
23- إجراءات إخطار الترسية.
24- إعداد العقود، وتوقيعها الكترونيا متى توافرت خدمة التوقيع الإلكترونى.
25- إحصائيات التعاقدات ومنها على سبيل المثال ما تم التعاقد عليه مع المشروعات المتوسطة والصغيرة والمتناهية الصغر.
26- مهام إدارة وتنفيذ العقود، ويشمل ذلك تتبع عمليات الاستلام وتعديلات العقود واستخراج الفواتير والدفع الإلكترونى.
27- الاحتفاظ بالبيانات الإلكترونية وحفظ السجلات، وحفظ نظام معلومات إدارة التعاقدات الذي يسجل المعلومات عن كل مرحلة وكل خطوة في كل معاملات التعاقدات، ويشمل ذلك هوية الموظفين المعنيين ومتخذي القرار والموافقات، ونشر بيانات عن أنشطة التعاقدات في قاعدة بيانات التعاقدات التي يمكن البحث فيها بصورة تفاعلية، ويشمل ذلك البحث التفاعلي عن فرص التعاقدات المقبلة.
28- إعداد تقارير عن الخطوات والتوقيتات والنتائج لكل إجراء من إجراءات التعاقد، ويشمل ذلك معلومات عن مقدمي العطاءات المقبولين والمرفوضين والقرارات الصادرة في كل مرحلة وغيرها.
29- تجميع بيانات التعاقدات العامة بشكل يمكن من مراجعتها بصورة آلية بما في ذلك كل ما تم من إجراءات من خلال النظام والبيانات المدخلة التى تمت بهدف إنشاء السجلات، أو تعديلها، أو حذفها وقراءة المعلومات السرية، ويشمل ذلك الاعتمادات، وتحديد نوع وتوقيت كل إجراء ومتخذه.
وغير ذلك من مهام يتم إقرارها أثناء إعداد المنظومة، أو تتطلب حاجة العمل إضافتها اليها.$m260$,'9360daf5d63ef274f528e19aaeedf08e'),
(169,0,$m260$المادة 169$m260$,$m260$تتولي الهيئة العامة للخدمات الحكومية توفير الدعم الفني والتدريب اللازم للعاملين بإدارات التعاقدات في الجهات الادارية، وكذلك التنسيق في هذا الشأن بالنسبة للمتعاملين والمتعاقدين، علي أن تصدر الهيئة دليل المستخدم الإرشادي وإتاحته لكافة مستخدمي المنظومة، وتكون خدمة التسجيل متاحة في أي وقت وبشكل مستمر، وفي حالة ما إذا لم يستوف طالب التسجيل بياناته ولم تستكمل إجراءات التسجيل يتم إخطاره لحظيا من خلال المنظومة بالأسباب ليتم استكمال ما نقص من بيانات، أو معلومات، أو مستندات.
وتتضمن المعلومات الواردة في الملف التعريفي الخاص بالمتعاملين بحد أدنى البيانات الآتية:
1- اسم المتعامل.
2- الرقم القومي لصاحب المنشأة، وغير ذلك من بيانات الهوية.
3- أسماء المفوضين للتعامل مع الجهات الادارية نيابة عنهم .
4- العنوان المسجل بالسجل التجاري والبطاقة الضريبية/ المدينة/ المحافظة/ الكود البريدي.
5- عنوان البريد الإلكتروني والتليفون الأرضي والمحمول للشخص المسئول/ المفوض.
6- رقم الفاكس.
7- عنوان الموقع الالكتروني الخاص بالمتعامل.
8- المكاتب الأخرى أو الفروع التابعة للمتعامل.
9- كود تصنيف المنتجات/الخدمات.
وغيرها من بيانات يتم تضمنها بدليل المستخدم الإرشادي.$m260$,'f173517f51f38416c8b6f6e9af1d0135'),
(170,0,$m260$المادة 170$m260$,$m260$يتعين على كافة المستخدمين للمنظومة تحديث البيانات الخاصة بهم في ملفات التعريف الشخصية لكل منهم عند الاقتضاء، وإبلاغ الهيئة العامة للخدمات الحكومية بأى تغييرات في المعلومات أو البيانات التي على أساسها تم منحه حق التسجيل، وفي حالة ما إذا لم يستوف طالب تحديث البيانات متطلبات التحديث، يتم إخطاره لحظيا من خلال المنظومة بأسباب ذلك، ليقوم باستكمال ما نقص من بيانات أو معلومات أو مستندات.$m260$,'2efb63902e1b2174d5c3137a3c71ef83'),
(171,0,$m260$المادة 171$m260$,$m260$يلتزم مستخدمي المنظومة بالحفاظ على سرية المعلومات اللازمة للدخول على المنظومة، ويكون كل منهم مسئولا عن الإجراءات التي يتخذها على المنظومة، وكذلك الإجراءات التي يتخذها الغير الذي استخدام المعلومات السرية الخاصة بالمستخدم بناء على تصريح منه، والتأكد من عدم إلحاق أي ضرر بها بسبب الاستخدام غير المصرح به لمعلومات الدخول على المنظومة.
ويجوز للهيئة العامة للخدمات الحكومية سحب تصاريح الدخول على المنظومة في الحالات التى يحددها دليل المستخدم الارشادي، ويتم سحب هذا التصريح بموجب إخطار كتابي يتم إرساله إلى المستخدم.
ويجوز في الظروف الطارئة أن تقوم المنظومة بوقف التصريح، بعد إرسال إخطار الكتروني إلى المستخدم على عنوان بريده الإلكتروني المثبت في ملف التعريف الشخصي له.$m260$,'c90a7eef4591edc3a7e9c2ec46e6a91c'),
(172,0,$m260$المادة 172$m260$,$m260$لا يجوز للجهة الإدارية التعامل مع المسجلين لديها بسجلاتها أو غيرهم إلا بعد تسجيلهم لبياناتهم على بوابة التعاقدات العامة، أو تحديثها حال تعديلها، وأن تطابق الجهة الإدارية تلك البيانات واعتمادها من واقع قاعدة البيانات، على أن تتضمن بياناتهم رقم السجل التجاري، أو الصناعى، أو المهني، أو سجل مزاولة المهنة بحسب الأحوال، ورقم البطاقة الضريبية، أو أى بيانات أخرى ليتم من خلاله التعامل معهم، كما يتعين عليها أن تراعى الكتب الدورية الصادرة عن الهيئة العامة للخدمات الحكومية فيما يتعلق منها بالشطب، أو إعادة القيد.$m260$,'c2239cf32c40b24060922777f6deba9f'),
(173,0,$m260$المادة 173$m260$,$m260$يجب على إدارة التعاقدات مراجعة الإدارات الطالبة، أو المستفيدة، أو إدارة المخازن، أو مسئول إدارة العقد بالجهة الإدارية أو من اختارته الجهة الإدارية للإشراف على تنفيذ العقد للتأكد من توثيقها لأداء المتعاقد أولا بأول، على أن يجرى تقييما نهائيا له قبل نهاية العام المالى، أو بعد انتهاء المتعاقد من تنفيذ العقد وفقا للنماذج والمعايير المحددة من الهيئة العامة للخدمات الحكومية بالتنسيق مع الوزارات والجهات المعنية وفقا لاختصاصاتها وطبيعة عملها والمتاحة على بوابة التعاقدات العامة.
ويجب على إدارة التعاقدات اخطار المتعاقدين بنتيجة تقييم أدائهم، بالإضافة إلى نشرها على بوابة التعاقدات العامة وإخطار الهيئة العامة للخدمات الحكومية به لإعمال شئونها، ويستثنى من النشر العمليات التى تتطلب اعتبارات الأمن القومى أن تتم بطريقة سرية وفقا لما تقدره السلطة المختصة.
ويتعين على إدارة التعاقدات إتاحة استقصاء مع المتعاقدين مع الجهة الإدارية بغرض إظهار الإيجابيات والوقوف على الإجراءات السلبية التى واجهتهم فى تعاملاتهم مع الإدارة الطالبة، أو المستفيدة، أو الإدارة المشرفة واتخاذ الإجراءات الواجبة لتحسين أداء العاملين وفقا للنموذج المعد من الهيئة العامة للخدمات الحكومية.$m260$,'9c11acbdcc715f784d88cc98d1988242'),
(174,0,$m260$المادة 174$m260$,$m260$تلتزم الهيئة العامة للخدمات الحكومية بحصر وتحليل بيانات العقارات المملوكة للجهات الإدارية، وما تم التصرف فيه منها وأسلوب التصرف وقيمته والبيانات الكافية عن المتصرف إليهم وإعداد تقارير سنوية بشأنها وتقديمها إلى وزير المالية لعرضها على مجلس الوزراء.$m260$,'abe793f92c4795d70ff0769e2396db67'),
(175,0,$m260$المادة 175$m260$,$m260$يتعين على الجهاز المركزي للتنظيم والادارة ولجان الموارد البشرية ولجان الاختيار بالجهات الادارية التأكد من اجتياز المتقدمين لشغل وظائف التعاقدات العامة أو الاستمرار فيها وبرامج التدريب اللازمة التى تعدها الهيئة العامة للخدمات الحكومية ويعتمدها وزير المالية ويتم موافاة الجهاز المركزى للتنظيم والإدارة بها.
وتكون مستويات البرامج التدريبية لشغل وظائف التعاقدات العامة أو الاستمرار فيها على النحو الآتى:
1- المستوي الأول: أساسيات التعاقدات العامة.
2- المستوي الثاني: استراتيجيات التعاقد.
3- المستوي الثالث: التعاقدات التخصصية.
ويتعين على إدارات التعاقد بالجهات الادارية قبل بداية السنة المالية بستة أشهر تحديد احتياجاتها التدريبية للمرشحين لشغل وظائف التعاقدات العامة، أو المطلوب استمرارهم فيها في ضوء مستويات البرامج التدريبية المشار اليها.
ويعتمد وزير المالية البرامج التدريبية السنوية ومراكز التدريب المؤهلة التي تقترحها الهيئة العامة للخدمات الحكومية وشروط التدريب وكافة الترتيبات التنظيمية ذات الصلة، على أن تقوم الهيئة فور اعتمادهم الاعلان عنهم على بوابة التعاقدات العامة وإخطار الجهات الادارية بهم.
وتتولى الهيئة العامة للخدمات الحكومية ومركز تدريبها ومراكز التدريب الأخرى المعتمدة تلقى طلبات التدريب من الجهات الادارية وفقا للإجراءات التي يتم تحديدها مسبقا بمعرفة الهيئة وموافاة الجهات بها، علي أن تقوم مراكز التدريب بالتنسيق مع الهيئة باتخاذ ما يلزم بشأن الترتيبات الادارية والتنظيمية لاستيفاء طلبات التدريب وإخطار الجهات بالتفاصيل.
وتلتزم كافة مراكز التدريب فى نهاية كل برنامج تدريبي بتقييم أداء المتدربين وتقديم تقرير للهيئة العامة للخدمات الحكومية بشأنه والتنسيق معها لإصدار الشهادات الدالة على استيفائهم التدريب اللازم لشغل وظائف التعاقدات العامة أو الاستمرار فيها، وكذا موافاة السلطة المختصة بكل جهة إدارية بنتائج تدريب من قام بترشيحهم.
تتولي الهيئة العامة للخدمات الحكومية إعداد تقارير دورية متضمنه توصياتها بشأن العملية التدريبية للعاملين بالتعاقدات بالجهات الادارية وعرضها على وزير المالية.$m260$,'fbef539de998aba75277b75aca8560d5'),
(176,0,$m260$المادة 176$m260$,$m260$يتعين على كافة المتعاملين بالقانون وهذه اللائحة الالتزام بأحكامهما وغيرها من القوانين واللوائح والقرارات والتعليمات المنفذة لها، وما يصدر من قرارات تنظيمية، أو تعليمات، أو نشرات، أو كتب دورية في هذا الشأن، ومدونات السلوك الوظيفي للعاملين بالدولة والعاملين بالتعاقدات العامة، ويجازي تأديبيا كل من يخالفهم، ودون الإخلال بحق إقامة الدعوى المدنية أو الجنائية ضد المخالفين عند الاقتضاء.$m260$,'e57b3b963433ab07ef5a3e64bc3cc699'),
(177,0,$m260$المادة 177$m260$,$m260$تلتزم الجهات الإدارية باستخدام أنماط العقود وكراسات الشروط النموذجية والأدلة الإرشادية وغيرها المنصوص عليها بالمادة (19) من القانون والتى قامت إدارة الفتوى المختصة بمجلس الدولة بمراجعتها واصدرتها الهيئة العامة للخدمات الحكومية، ولا يجوز الإضافة، أو الحذف، أو التعديل فى أى من الاشتراطات العامة الواردة فى انماط العقود وكراسات الشروط النموذجية إلا بعد الرجوع لإدارة الفتوى المذكورة لمراجعتها.$m260$,'fbeb960cfc6e8626e789ba10b8f16bff'),
(178,0,$m260$المادة 178$m260$,$m260$مع عدم الإخلال بأحكام المادة (51) من القانون على طرفى العقد بذل أقصى جهد للالتزام ببنود التعاقد طوال مدة تنفيذه طبقا لما اشتمل عليه وبطريقة تتفق ما يوجبه حسن النية.
وبمراعاة أحكام المادة (91) من القانون، يجوز أن تتضمن شروط الطرح والعقد مراحل وآليات تسوية الخلافات والمنازعات بين طرفيه، وفى هذه الحالة يتعين على الجهة الإدارية قبل مباشرة إجراءات فسخ العقد مع المتعاقد اتخاذ الإجراءات الآتية:
1- فحص شروط التعاقد بكل دقة واتخاذ الحل المناسب للمشكلة.
2- قيام إدارة التعاقدات اعداد تصور عن موضوع الخلاف وتقديم رأى فنى ومالي وقانوني للسلطة المختصة، ويجوز لها الاستعانة باستشاري متخصص للمساعدة فى دراسة الخلاف وتقديم الرأي.
3- تسوية الخلافات التى نشأت بالطرق الودية بما لا يخل بحقوق والتزامات طرفى العقد، وإذا ترتب على التسوية الودية أى أعباء مالية فيجب الاتفاق عليها وعرضها على السلطة المختصة للموافقة عليها بعد تقديم كافة المستندات والبيانات والمبررات لتسوية الخلاف.
4- يتم توجيه الدعوة للمتعاقد لعقد اجتماع مع مسئول إدارة العقد أو ممثل الجهة الإدارية بحسب الأحوال خلال مدة خمسة عشر يوما من تاريخ ظهور الخلاف وذلك لمناقشته.
5- إذا لم يتم التوصل إلى اتفاق يتم اللجوء إلى القضاء أو التحكيم بحسب ما تنص عليه شروط التعاقد.$m260$,'30a4ddd19cd500987322e8eb01d10128'),
(179,0,$m260$المادة 179$m260$,$m260$تلتزم الهيئة العامة للخدمات الحكومية بتسجيل من يتم اخطارهم بصدور أحكام نهائية فى إحدى الجرائم المنصوص عليها فى الباب الرابع من الكتاب الثانى من قانون العقوبات، أو فى جرائم التهرب الضريبي، أو الجمركي فى سجل قيد أسماء الممنوعين من التعامل معهم، بالإضافة إلى نشر بياناتهم على بوابة التعاقدات العامة.$m260$,'02cd79995bd47d29c3a51e74873c2391');

INSERT INTO m260_ver VALUES
(0,0,1,$m260$اللائحة التنفيذية لقانون تنظيم التعاقدات التى تبرمها الجهات العامة الصادر بالقانون رقم 182 لسنة 2018$m260$,'fb4d9583b60c36e00b170dbd6da73c53',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(1,0,1,$m260$يكون للتعاريف الواردة بقانون تنظيم التعاقدات التى تبرمها الجهات العامة المعنى ذاته فى تطبيق أحكام هذه اللائحة.
ويقصد فى تطبيق أحكام هذه اللائحة بالكلمات والعبارات التالية المعنى المبين قرين كل منها:
القانون: قانون تنظيم التعاقدات التى تبرمها الجهات العامة الصادر بالقانون رقم 182 لسنة 2018.
الوظائف القيادية: وظائف المستويات الثلاثة التالية للسلطة المختصة والتى يرأس شاغلوها وحدات تقسيمات تنظيمية بالجهة الإدارية من مستوى إدارة عامة أو إدارة مركزية أو قطاعات وذلك بالجهات المخاطبة بقانون الخدمة المدنية الصادر بالقانون رقم (81) لسنة 2016، أو ما يعادل تلك الوظائف بالجهات الأخرى غير المخاطبة بالقانون المشار إليه.
إدارة التعاقدات: التقسيم الإدارى المنشأ بموجب حكم المادة (3) من القانون أيا كان مستواه الوظيفى بالهيكل التنظيمى للجهة الإدارية الذى يتبعها.
الادارة الطالبة/المستفيدة: الإدارة المسئولة عن تحديد المتطلبات المرتبطة بمحل التعاقد طبقا لمهامها أو احتياجاتها.
مجتمع الأعمال: المتعاملون مع الجهات الإدارية من الموردين والمقاولين ومقدمى الخدمات والاستشاريين والمتزايدين وغيرهم.
مستندات الطرح: ما تعده الجهة الإدارية من كراسة الشروط والمواصفات، طلب المعلومات، طلب ابداء الاهتمام، طلب التأهيل المسبق وغير ذلك.
الاعتماد المالى: المبلغ المخصص للجهة الإدارية من وزارة المالية والمدرج بموازنتها لتوفير احتياجاتها.
صاحب العطاء: كل شخص طبيعي أو معنوي يقدم عرضا بغرض التعاقد مع الجهة الإدارية وفقا لأحكام القانون وهذه اللائحة.
مقدم العطاء: صاحب العطاء أو من يفوضه فى تقديم عطائه للجهة الإدارية.
العطاء الفائز: العطاء الأفضل شروطا والأقل سعرا أو الذى يتم ترجيحه وفقا لنظام النقاط والذى تم اخطاره بترسية العملية عليه.
العملية: ما طرحته الجهة الإدارية بإحدى طرق التعاقد المنصوص عليها بالقانون.
طريق التعاقد: المناقصة أو الممارسة أو المزايدة بأنواعهم المختلفة أو الاتفاق المباشر.
لجنة البت: اللجنة المسئولة عن فحص وتفريغ ومراجعة ودراسة العروض الفنية والمالية المقدمة فى العمليات المطروحة والتحقق من مطابقتها لشروط الطرح والتوصية بالبت فيها بالإرساء أو الاستبعاد أو الإلغاء.
تكلفة دورة الحياة: معيار تقييم لقياس تكلفة محل العقد، بما فى ذلك تكلفة التعاقد وتكاليف الإنشاء أو التركيب أو التشغيل أو الصيانة طوال العمر الافتراضي له، وقيمته البيعيه بعد استهلاكه.
التعاقد المستدام: توفير احتياجات الجهة الإدارية بطريقة تحقق القيمة الأفضل للمال العام على مدار دورة حياة محل العقد مع مراعاة سياسات الدولة الاقتصادية والاجتماعية والبيئية.$m260$,'2ac1d0200d0578e7ad673a115710442a',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(2,0,1,$m260$تتولى الهيئة العامة للخدمات الحكومية أداء المهام والاختصاصات الآتية:
1- الإعداد والاشراف على بوابة التعاقدات العامة وتحديثها.
2- اعداد مقترحات لتطوير السياسات والتشريعات الخاصة بالتعاقدات وعرضها على وزير المالية.
3- إصدار التوجيهات والإرشادات والتعليمات ذات الصلة بالتعاقدات العامة وفقا لأحكام القانون وهذه اللائحة وتعميمها على كافة الجهات الإدارية للعمل بمقتضاها.
4- القيام بمراجعة إجراءات التعاقد بالجهات الادارية للتأكد من سلامتها وفقا لأحكام القانون وهذه اللائحة، من خلال زيارات ميدانية وفقا لخطة عمل سنوية أو كلما استدعى الأمر ذلك، على أن يتم إعداد تقارير بنتائج المراجعة فور إتمامها وإخطار السلطة المختصة بالجهات الإدارية بها؛ لاتخاذ الإجراءات اللازمة بشأنها ومتابعة تنفيذها إذ تطلب الأمر ذلك، علي أن ترفع الهيئة تقريرا ربع سنوي بشأن ما تسفر عنه تلك المراجعات لوزير المالية.
5- جمع البيانات المتعلقة بالتعاقدات التى تقوم بها الجهات العامة بشكل منتظم وتحليلها واستخراج التقارير والمعلومات الخاصة بها ونشر نتائجها على بوابة التعاقدات العامة.
6- وضع البرامج التدريبية ومناهجها لمقدمى خدمات التدريب والمراكز التدريبية، اللازمة لشغل وظائف التعاقدات بالجهات الإدارية أو الاستمرار فيها، والتنسيق بشكل مستمر معهما قبل بداية كل سنة مالية بشأن الخطة السنوية التدريبية وكافة الترتيبات التنظيمية ذات الصلة، على أن يعتمدها وزير المالية وترفع الهيئة تقريرا ربع سنوي بأداء الخطة التدريبية لوزير المالية.
7- نشر كل ما تخطر به مما يدخل ضمن التصنيف الصادر عن الاتحاد المصرى لمقاولى التشييد والبناء، والمعتمد من وزير الإسكان والمرافق والمجتمعات العمرانية وذلك على بوابة التعاقدات العامة.
8- نشر القانون وهذه اللائحة وأى تعديلات تطرأ عليهما، وكذلك المنشورات العامة والكتب الدورية والقرارات، وغيرها المتعلقة بتطبيقهم فور صدورها، وذلك على بوابة التعاقدات العامة.
9- إعداد نماذج خطة الاحتياجات السنوية للجهات الخاضعة لأحكام القانون والتنسيق مع قطاع الموازنة العامة للدولة بوزارة المالية بشأنها.
10- إصدار نماذج كراسات الشروط والمواصفات، وأنماط العقود النموذجية والأدلة الإرشادية، وغيرها التى تعدها الوزارات والجهات المعنية وفقا لاختصاصاتها وطبيعة عملها، على أن تقوم بتحديثها بشكل دوري ونشرها على بوابة التعاقدات العامة.
11- إعداد نماذج محاضر فتح المظاريف والبت والممارسة والمزايدة وأوامر التوريد وأوامر الإسناد وغير ذلك من النماذج المنصوص عليها بهذه اللائحة أو التى تتخذها الجهات ذات الصلة.
12- إعداد نماذج وتحديد معايير تقييم أداء المتعاقدين مع الجهات الإدارية، ونماذج استقصاء المتعاقدين مع الجهات الإدارية بالتنسيق مع الوزارات والجهات المعنية وفقا لاختصاصاتها وطبيعة عملها واتاحتهما على بوابة التعاقدات العامة، وكذا تحليل نتائج التقييم والاستقصاء واتخاذ ما يلزم بشأنهما ونشرهما على بوابة التعاقدات العامة.
13- إعداد نماذج حصر للعقارات المملوكة للجهات الادارية وإدخال ما يرد لها من بيانات بقاعدة البيانات المركزية المنشأة لديها وتحديثها بصفة دورية.
14- إمساك سجل مركزي للمتعاملين مع الجهات الإدارية أو الممنوعين من التعامل معها وتسجيل بيانات من يتم إخطارها بشطبهم أو إعادة قيدهم وفقا للإجراءات الواردة بهذه اللائحة ونشر قرار الشطب أو إعادة القيد بإصدار كتاب دوري يعمم بطريق النشرات المصلحية وينشر على بوابة التعاقدات العامة.
15- التنسيق مع الجهات التى تسرى عليها أحكام القانون وهذه اللائحة بشأن إجراءات التصرف فى العقارات لتحقيق اعتبارات المصلحة العامة وبين مهام اللجنة العليا للتقييم بها.
ويتعين على الهيئة أن تؤدي مهامها واختصاصاتها باستقلالية وشفافية وحيادية كاملة، ويتعين على كافة العاملين بها تجنب تضارب المصالح بكافة أشكاله، ويحظر عليهم الدخول في المناقصات والممارسات والمزايدات بأنواعها، سواء بالذات أو بالواسطة مع أي من الجهات الادارية إلا إذا كانت الأصناف المشتراة لاستعمالهم الخاص، وكانت مطروحة للبيع عن طريق جهات عامة أخرى.$m260$,'2eb5e0ca7cf9f98f97034fb781410f89',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(3,0,1,$m260$على السلطة المختصة مراجعة الهياكل التنظيمية بالجهات العامة للتأكد من وجود إدارة للتعاقدات بكل منها يتناسب تشكيلها الوظيفى مع أداء مهامها الواردة بالقانون وهذه اللائحة، وفى حال عدم وجودها بالهيكل التنظيمى، تتخذ الإجراءات اللازمة لإنشائها، وفى جميع الأحوال يجب الفصل بين اختصاصاتها واختصاصات أية إدارات أخرى.
ويتعين لشغل وظائف إدارة التعاقدات أو الاستمرار في شغلها اجتياز التدريب والحصول على الشهادات اللازمة، ويتعين على العاملين بها أن يؤدوا مهامهم بفعالية وكفاءة، ويراعى التأكد من تمتعهم بصفات النزاهة والأمانة وحسن السمعة.
وبمراعاة المهام الواردة بالقانون وهذه اللائحة تتولى إدارة التعاقدات القيام بالآتي:
1- التنسيق والتكامل مع كافة الإدارات بالجهة الإدارية في كل ما يتعلق بالتعاقدات، والتواصل مع الجهات الإدارية الأخرى ذات الصلة بإجراءات التعاقد.
2- التواصل مع المتعاملين والمتعاقدين مع الجهة الإدارية.
3- توثيق كافة المكاتبات، وإمساك السجلات ذات الصلة، وحفظ المستندات.
4- تسجيل المتعاملين وتحديث بياناتهم، وتوثيقها أولا بأول.
5- إعداد دراسات الجدوى الاقتصادية تمهيدا للطرح إذا تطلبت طبيعة العملية ذلك.
6- التعامل مع بوابة التعاقدات العامة.
7- تخطيط التعاقدات، بما في ذلك إعداد خطة الاحتياجات السنوية للجهة، وخطط التعاقدات وعمليات التعاقد.
8- الإعلان أو الدعوة عن العمليات المزمع طرحها.
9- التأكد من توافر الاعتمادات المالية المطلوبة للعمليات محل الطرح.
10- إعداد وإتاحة مستندات الطرح وغيرها المنصوص عليها بالقانون وهذه اللائحة.
11- إعداد قوائم مختصرة وقوائم المؤهلين مسبقا في الحالات التى تتطلب ذلك.
12- استلام العطاءات وغيرها، وحفظها والحفاظ عليها.
13- اقتراح تشكيل اللجان المنصوص عليها بالقانون وهذه اللائحة واعتمادها من السلطة المختصة، والتنسيق مع رؤسائها لمعاونتهم فى أداء مهام لجانهم.
14- عرض أسلوب تقييم العطاءات لاعتماده من السلطة المختصة.
15- إعداد الإخطارات وغيرها المنصوص عليها بالقانون وهذه اللائحة.
16- إعداد العقود، ومتابعة تنفيذها مع الإدارة الطالبة أو المستفيدة.
17- تقييم أداء المتعاقدين في تنفيذ تعاقداتهم أولا بأول.
18- اتاحة نماذج الاستقصاء للمتعاقدين مع الجهة الإدارية.
19- إعداد التقارير المنصوص عليها بالقانون وهذه اللائحة، وغيرها ذات الصلة التى تطلبها السلطة المختصة.
20- التعامل مع الشكاوي بالرد عليها، وتقديم المعلومات، واتخاذ الاجراءات اللازمة بشأنها.
21- تحديد احتياجات التدريب للعاملين بالإدارة والتنسيق بشأنها مع الهيئة العامة للخدمات الحكومية أو من تحددهم.$m260$,'1f23ec348ac8541de4b38d7a025a251a',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(4,0,1,$m260$تخضع إجراءات وطرق وأساليب التعاقد لمبادئ الشفافية، وحرية المنافسة، والمساواة، وتكافؤ الفرص.
ويلتزم العاملون بالجهات الإدارية بإنفاذ ما ورد بأحكام القانون وهذه اللائحة من معايير ومبادئ الشفافية، ويحظر تعارض المصالح فيما يؤدونه من إجراءات التعاقد، وعليهم مراعاة مدونة السلوك الوظيفى التى تصدر عن وزير المالية.
ويجب على كافة المتعاملين من مجتمع الأعمال مراعاة ممارسات الأعمال الجيدة والمعايير المتعارف عليها فى مجالات التعاقدات، وذلك فى كافة تعاملاتهم أثناء مراحل إجراءات التعاقد بما في ذلك دراسة وإعداد وتقديم العطاءات وتنفيذ العقود، ويسأل قانونيا كل من يخالف القوانين واللوائح النافذة ذات الصلة.$m260$,'129d2ef5b9a6b15f8b9bab3fc1ad6842',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(5,0,1,$m260$تلتزم إدارة التعاقدات بدراسة الشكاوى المقدمة لها، ويجوز لها الاستعانة بمن تراه من المختصين بحسب طبيعة الشكوى المقدمة، وترفع تقريرا مفصلا للسلطة المختصة بنتيجة ما انتهت إليه دراستها من قرارات لاعتمادها وذلك كله خلال مدة لا تجاوز خمسة أيام من تاريخ استلام الشكوى المستوفاة.
وفى حال صحة الشكوى يجب أن يتضمن القرار المعتمد من السلطة المختصة التدابير الواجب تنفيذها لإزالة اسبابها واتخاذ أى إجراءات يوصى بها.
وفور اعتماد السلطة المختصة لقرارات نتيجة دراسة الشكوى تلتزم إدارة التعاقدات بإخطار مقدم الشكوى بها، كما يخطر مكتب شكاوى التعاقدات العمومية بتلك القرارات، بالإضافة إلى نشرها على بوابة التعاقدات العامة.$m260$,'feaa0f98eb1f74a9f7e8f9f829d0ecf1',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(6,0,1,$m260$اللغة العربية هي اللغة المعتمدة فى كراسة الشروط والمواصفات والعقود وجميع المحاضر والمراسلات وغيرها من المستندات ذات الصلة بموضوع الطرح والتعاقد.
وفى العمليات التى يتعذر فيها وضع المواصفات الفنية باللغة العربية بمستندات الطرح يجوز أن تكون المواصفات الفنية بلغة أخرى، بناء على رأى اللجنة الفنية المختصة بوضعها فى تقريرها متضمنا الأسباب التى أدت إلى ذلك، وأن تقدم المواصفات الفنية بالعطاءات بذات اللغة الأخرى.
وفى حالة طرح عمليات بالخارج تكون مستندات الطرح بلغة أخرى أو أكثر مع ترجمتها إلى العربية مع ذكر أن النص العربى هو المعول عليه فى حالة الخلاف أو الالتباس فى مضمونها.$m260$,'bf66569bee443cfb612345d9c73961c0',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(7,0,1,$m260$يجب أن تكون كافة المخاطبات والمراسلات المتبادلة من وإلى الجهات الإدارية والمتعاملين والمتعاقدين معها بما فى ذلك الإخطارات والقرارات، ومحاضر الجلسات، وغيرها كتابة وبشكل يمكن الرجوع إليه لاحقا، على أن تكون صادرة من الأشخاص المخول لهم ذلك من الطرفين، ويجب الاحتفاظ بما يثبت تسلمها، ويكون تبادلها بالوسائل الواردة بالقانون وهذه اللائحة والمنصوص عليها مسبقا بمستندات الطرح.
ويتعين على الجهة الإدارية عند التواصل مع المتعاملين أو المتعاقدين معها تضمين الطلبات ومستندات الطرح وغيرها البيانات الآتية:
1- شكل المخاطبات والمراسلات.
2- الوسائل المستخدمة في إيصال المعلومات.
3- الوسائل التي يمكن استخدامها لعقد الجلسات.
4- طريقة حصول المتعاملين من مجتمع الأعمال على المعلومات اللازمة عن اجراءات تقديم العطاءات الكترونيا، بما في ذلك أية تدابير تتعلق بتكنولوجيا المعلومات.
وبمراعاة البنود المنصوص عليها فى الفقرة الثانية من هذه المادة يتعين على إدارة التعاقدات عدم التمييز بين المتعاملين والمتعاقدين مع الجهة الإدارية فى اختيار وسيلة وأسلوب التواصل وإيصال المعلومات ومحتواه، وتلتزم بنشر بيانات الاتصال بها على بوابة التعاقدات العامة من عنوان، وتليفون، ورقم فاكس، وبريد الكرتوني واسم المخول له التواصل مع المتعاملين والمتعاقدين، وفى حالة تعديل تلك البيانات يجب إعادة نشرها بذات الوسيلة لإعلامهم بها، كما يلتزم المتعاملون والمتعاقدون مع الجهة العامة بإخطار إدارة التعاقدات بأى تعديل يطرأ على بياناتهم المسجلة لديها فور التعديل.
وأنه حال ميكنة أى من الإجراءات المتبعة فى القانون وهذه اللائحة يتم استبدالها بالإجراءات التى جرى ميكنتها.$m260$,'5d7420a102eb26a07bdbbfcb4f8a26bb',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(8,0,1,$m260$يجب على الجهة الإدارية عند تطبيق أحكام القانون وهذه اللائحة اتخاذ ما يلزم من تدابير لضمان تحقيق معايير ومبادئ تكافؤ الفرص وتعزيز الشفافية والنزاهة والعدالة والمساواة فى المنافسة، ويتعين بصفة خاصة الالتزام بالآتي:
1- إتاحة الفرصة لكافة الراغبين من المتعاملين المستوفين للشروط الواردة بالقانون وهذه اللائحة للمشاركة في المناقصات والممارسات، والمزايدات بأنواعها والاتفاق المباشر، وطلب المعلومات، وإبداء الاهتمام، والتأهيل المسبق، والمسابقة، وأن تستند الإجراءات على مبادئ العلانية والمساواة وتكافؤ الفرص؛ إعمالا لحكم المادة (85) من القانون.
2- المساواة بين المتقدمين فى المعاملة وعدم التحيز لأى منهم أو التمييز بينهم، وافساح المجال للمنافسة بين من تتوافر فيهم الشروط المطلوبة للتقدم وفقا للاشتراطات التي تحدد مسبقا بمستندات الطرح.
3- إعداد كراسة للشروط والمواصفات تتضمن الإحالة لجميع القواعد والأحكام والإجراءات والشروط المنصوص عليها بالقانون وهذه اللائحة، وكذلك الحال عند التعاقد بطريق الاتفاق المباشر إذا تطلبت طبيعة العملية وذلك قبل الإعلان أو الدعوة للاشتراك فى جميع طرق التعاقد الواردة بالقانون.
4- النشر عن العمليات التى يتم طرحها بجميع طرق التعاقد المنصوص عليها بالمادة (7) من القانون على بوابة التعاقدات العامة، عدا العمليات التى تتطلب اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة، على أن يتضمن النشر طريق التعاقد وشروطه والأسباب المبررة لاتباع هذا الطريق، وأسلوب التقييم الفنى والمالى، وغيرها من البيانات التى يحددها القانون وهذه اللائحة.
5- عند إدخال تعديلات على كراسة الشروط والمواصفات إذا اقتضت المصلحة العامة ذلك أو بناء على جلسة الاستفسارات، إخطار من قاموا بشرائها ومقدمى الاستفسارات بتلك التعديلات دون الإفصاح عن مقدميها، بالإضافة إلى نشرها على بوابة التعاقدات العامة.
6- تحديد أسباب القرارات الصادرة بشأن أي من إجراءات التعاقد ونشرها على موقع بوابة التعاقدات العامة.$m260$,'24c2a2be37f785785c1e3b9e9b1fd0b7',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(9,0,1,$m260$يجب على الجهة الادارية عند التخطيط للتعاقدات والاعداد لها أن تأخذ في الاعتبار المبادئ والأسس الآتية:
1- بدء التخطيط للتعاقدات منذ نشأة الحاجة لمحل التعاقد.
2- تحديد طريق وأسلوب التعاقد، والمؤهلات والاشتراطات المطلوبة فى المتعاقد، ومعايير دراسة السوق وإعداد القيمة التقديرية.
3- وضع برنامج زمنى متوقع لإجراءات العملية محل الطرح، على أن يتضمن توقيتات واقعية وغير مبالغ فيها أخذا فى الاعتبار وضع حد زمني أدنى وأقصى لكل خطوة من خطواته بما فى ذلك الاستفسارات، وتعديل مستندات العملية، إذا لزم الأمر، وتبادل المخاطبات والمراسلات ذات الصلة وبما يتماشى مع أحكام القانون وهذه اللائحة.
4- تعظيم العائد الاقتصادي والكفاءة إلى أقصى حد ممكن من خلال تحليل الاحتياجات بدقة، أو توقيتات التعاقد عليها، أو المفاضلة بين الاساليب المختلفة لتوفيرها، أو تجميع الاحتياجات فى مجموعات متجانسة، وغيرها من الاجراءات ذات الصلة.
5- تحديد مدة التوريد أو التنفيذ والتي يتم تضمينها مسبقا بشروط العملية لتكون ملبية لاحتياجاتها وبناء على محددات واضحة، وأن تكون واقعية تسمح للمتعاقد التنفيذ الجيد لبنود العقد، وأن تأخذ فى الاعتبار الظروف السائدة في موقع التنفيذ.$m260$,'de54d34043431c000f16292668770d3d',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(10,0,1,$m260$على إدارة التعاقدات لترجيح الاختيار بين الشراء أو الاستئجار أن تستند فى توصياتها على دراسة تحليلية تتضمن العوامل المؤثرة فيها، بما في ذلك طبيعة محل التعاقد والغرض منه والجدوى الاقتصادية ومدة ومعدلات استخدامه واستهلاكه وتكلفة تشغيله وغيرها، والمقارنة بين التكاليف الكلية للعقد حال الشراء أو الاستئجار والعرض على السلطة المختصة بهذه الدراسة لتقرير ما تراه بشأنها.$m260$,'335f8b2da1bac80ee7aab40c30c4d6f0',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(11,0,1,$m260$يتعين على الجهة الإدارية مراعاة سياسات الدولة الاقتصادية والاجتماعية والبيئية المعلنة من مجلس الوزراء بدءا من مرحلة تحديد الاحتياجات، مرورا بإعداد المواصفات الفنية ودراسة السوق والقيمة التقديرية، ومستندات الطرح ومعايير التأهيل والتقييم ومتابعة تنفيذ العقود بغرض تحقيق التنمية المستدامة الاقتصادية والاجتماعية والبيئية.$m260$,'44cb58358216d1149ae7430b879500d2',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(12,0,1,$m260$يجب على إدارة التعاقدات مخاطبة كافة القطاعات والإدارات والوحدات وغيرها التابعة للجهة الإدارية لحصر احتياجاتها المطلوبة للسنة المالية التالية وفقا للنماذج التى تعدها الهيئة العامة للخدمات الحكومية لهذا الغرض، ويجب التأكد من أن الاحتياجات المطلوبة فعلية وضرورية لسير العمل أو الإنتاج بناء على دراسات واقعية وموضوعية، وذلك كله بعد اتخاذ واستيفاء ما يلزم من دراسات السوق وطلب المعلومات لتحديد احتياجاتها بكل دقة من حيث الكميات والمواصفات والاعتمادات المالية المطلوبة لها دون تزايد أو مبالغة، وبعد مراجعة مستويات التخزين ومعدلات الاستهلاك ومقررات الصرف والقيام بتجميع الاحتياجات وتقسيمها إلى مجموعات متجانسة، ويحظر تضمين خطة الاحتياجات أصناف يوجد بالمخازن أنواع مماثلة لها أو بديلة عنها تفي بالغرض.
ويكون تقدير قيمة الاحتياجات المدرجة بالخطة وفقا للأسس المنصوص عليها بالمواد (26)، (27)، (152) من هذه اللائحة وبما يتماشى مع طبيعة العملية.
ويجب على إدارة التعاقدات الانتهاء من اعداد خطة احتياجات الجهة العامة قبل تقديم مشروع موازنتها لوزارة المالية بوقت كاف، وعرضها على السلطة المختصة لاعتمادها، ويتم نشرها على بوابة التعاقدات العامة، وتخطر وزارة المالية بخطة الاحتياجات المعتمدة لمناقشتها وإدراجها ضمن موازنة الجهة الإدارية وذلك فى الموعد المحدد لتقديم مشروع الموازنة.
وعلى إدارة التعاقدات تعديل خطة احتياجاتها فى ضوء ما يتم تخصيصه وإقراره لها من اعتمادات مالية، وإعادة عرضها على السلطة المختصة لاعتمادها في شكلها النهائي ونشرها على بوابة التعاقدات العامة فور بداية السنة المالية، وتخطر الهيئة العامة للخدمات الحكومية بهذه الخطة لإعمال شئونها.
ويستثنى من النشر على بوابة التعاقدات العامة الحالات التى تقتضى اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة.
وعلى الجهة الإدارية مراعاة عدم تجاوز الاعتمادات المخصصة لها لتدبير احتياجاتها وفقا لخطتها، والالتزام بالفترات الزمنية المحددة للطرح وطرق التعاقد الواردة بها.$m260$,'219b422fa2ba03fe7c5651845b852314',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(13,0,1,$m260$يتعين عند التخطيط والإعداد لأي عملية الاخذ في الاعتبار العوامل والخطوات الآتية:
1- التحقق من الحاجة إلى محل التعاقد وبالتنسيق مع القطاعات والادارات والوحدات وغيرها داخل الجهة وتحديد متطلباتها بشكل واضح، ويشمل ذلك التحقق من توافر محل التعاقد بمخازن الجهة أو الجهات التابعة لها، أو توفيرها بموجب أية اتفاقية إطارية ذات صلة متى كانت شروطها تسمح بذلك.
2- إجراء دراسات السوق لتحديد مختلف الحلول الفنية وحجم المسجلين المتخصصين أو المؤهلين المشتغلين بالنشاط موضوع التعاقد وتحديد أفضل الشروط التعاقدية المواكبة لآليات السوق والمناسبة للجهة، ويشمل ذلك أيضا الرجوع إلى العمليات السابقة سواء بالجهة ذاتها أو غيرها من الجهات للاسترشاد.
3- التأكد من وجود تقديرات مالية محدثة ودقيقة لمحل التعاقد، وتوافر التمويل المطلوب لها بموازنة الجهة.
مراعاة سياسات الدولة الاقتصادية والاجتماعية والبيئية المعلنة من مجلس الوزراء، واعتبارات الجودة والتكلفة، وتحقيق أفضل قيمة للمال العام على أساس كامل دورة الحياة لموضوع التعاقد، وتضمين متطلبات التعاقد المستدام، شروط ومعايير التأهيل والتقييم الفنى والمالى ومؤشرات الأداء وغيرها.
ويقصد بتحقيق أفضل قيمة للمال العام تحقيق أكبر قدر من المنفعة للجهة الإدارية مقابل المال المدفوع لمحل التعاقد، من خلال إدارة عملية التعاقد بكفاءة وفعالية.
4- النظر في تقسيم الاحتياجات إلى مجموعات متجانسة فى العملية الواحدة، إن أمكن، لتعظيم المنافسة وتوسيع المشاركة، وبصفة خاصة مشاركة المشروعات المتوسطة والصغيرة والمتناهية الصغر.
5- اختيار الطريق الامثل للتعاقد وفقا لأحكام القانون وهذه اللائحة.
6- تحديد معايير تقييم العطاءات من الناحية الفنية والمالية، وغيرها بهدف تعظيم القيمة مقابل المال.
7- تحديد المهام غير النمطية المطلوبة من إدارة التعاقدات لموضوع التعاقد.
8- تحديد خطوات التعاقد وتحديثها إن تطلب الأمر ذلك، ويجب أن تتضمن كحد أدنى ما يلي:
أ- وصفا واضحا لمحل التعاقد.
ب- اختيار نموذج كراسة الشروط والمواصفات، ونمط العقد النموذجي المراجع من إدارة الفتوى المختصة بمجلس الدولة وإضافة أى اشتراطات أخرى يرى تضمينها بهما، وبما يتناسب مع طبيعة العملية محل الطرح.
ج- إعداد الجدول الزمني المتوقع لإجراءات العملية.$m260$,'22895db9acfbe944a272ff2ae76dd03b',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(14,0,1,$m260$يحظر على الجهات الخاضعة لأحكام القانون وهذه اللائحة النشر على بوابة التعاقدات العامة والإعلان أو توجيه الدعوات، بحسب الأحوال، لأى عملية للتعاقد على شراء أو استئجار المنقولات أو العقارات أو التعاقد على مقاولات الأعمال أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية ما لم يكن لها اعتماد مالي.
ويجوز للجهة الإدارية في الحالات الطارئة أو العاجلة أو التكليفات التى تقتضيها المصلحة العامة أن تجري التعاقدات ذات الصلة بالتنسيق أولا مع وزارة المالية أو التخطيط، بحسب الأحوال، والتأكد من توافر التمويل اللازم.
ويجوز إبرام عقود التوريدات والخدمات الدورية لمدة تجاوز السنة المالية بشرط ألا يترتب عليها زيادة الالتزامات فى إحدى السنوات المالية التالية عما هو مقرر فى سنة التعاقد.
ويكون التعاقد بالنسبة للمشروعات الاستثمارية المدرجة بالخطة فى حدود التكاليف الكلية المعتمدة، على أن يتم الصرف فى حدود الاعتمادات المالية المقررة.
ويحظر اتخاذ أى من إجراءات التعاقد في الشهر الأخير من السنة المالية بقصد استنفاد الاعتمادات المالية، إلا فى الحالات الاستثنائية التى تقتضيها ضرورة العمل، وبموافقة السلطة المختصة.$m260$,'57908d88fdae84f54f6d8f5880b55c60',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(15,0,1,$m260$على الجهة الإدارية قبل طرح العملية للتعاقد الحصول على الموافقات والتصاريح والتراخيص اللازمة ذات الصلة بموضوع الطرح من الجهات المعنية وفقا للقوانين والقرارات التى تقضى بذلك.$m260$,'9a170b7ee08adb0ca181235fe4ea5da4',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(16,0,1,$m260$يجوز لإدارة التعاقدات أن تصدر طلبا بدون مقابل للحصول على المعلومات أو المقترحات أو المواصفات المستجدة فى السوق، بما يمكنها من اتخاذ القرار المناسب لتحديد احتياجات الجهة الإدارية بدقة أو لإعداد خطة الاحتياجات السنوية، ولا يجوز أن يؤدى طلب المعلومات إلى الإخلال بمبادئ عدم التمييز أو الشفافية أو الحد من عدد المشاركين حال الطرح، وعلى الجهة العامة الحفاظ على سرية المعلومات المقدمة.
وتشكل بقرار من السلطة المختصة لجنة تضم الخبرات المطلوبة بحسب طبيعة محل طلب المعلومات، ويضم لها عضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع الطلب، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها.
ويتم النشر عن طلب المعلومات على بوابة التعاقدات العامة والإعلان عنه بإحدى الصحف اليومية واسعة الانتشار، أو توجيه الدعوة لأكبر عدد ممكن من المشتغلين بنوع النشاط المطلوب من المسجلين المتخصصين على بوابة التعاقدات العامة، بحسب الأحوال، ويكون إصدار طلب المعلومات وفقا للنموذج الذى تعده الهيئة العامة للخدمات الحكومية وأن تتخذ إدارة التعاقدات ما يلزم لتضمينه موضوع الطلب والشروط والقواعد اللازمة لتقديمه والبيانات الأساسية المطلوبة من المشتغلين بنوع النشاط محل طلب المعلومات، على أن يتضمن الطلب بصفة خاصة البيانات الآتية:
1- الغرض من طلب المعلومات.
2- المعلومات الفنية والمالية والادارية المطلوبة من مقدم المعلومات.
3- الموعد والمكان المحددين لتلقى الردود.
4- أية معلومات أو بيانات إضافية تري الجهة الإدارية أهمية الحصول عليها.
وتتولى إدارة التعاقدات استلام وحصر ما يرد لها من ردود؛ وتسليمها للجنة لدراستها، ويجوز للجنة استيضاح ما تراه مع من قام بالرد على طلب المعلومات؛ وذلك بغرض استكمال دراستها.
ويتعين على إدارة التعاقدات توثيق كافة ما تم اتخاذه من إجراءات، وإعمال شئونها في ضوء ما تعتمده السلطة المختصة من نتائج أعمال اللجنة.$m260$,'db54a5c26e1f22914bd170d8bcf6caa6',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(17,0,1,$m260$لإدارة التعاقدات حال رغبتها فى معرفة المشاركين المحتملين أو المهتمين بالدخول فى عملية معينة تنوى طرحها بأى من طرق التعاقد أن تصدر طلبا بدون مقابل لإبداء الاهتمام قبل الشروع فى طرح العملية.
وتشكل بقرار من السلطة المختصة لجنة تضم عناصر فنية ومالية وقانونية ويضم لها عضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع الطلب، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها.
ويتم الإعلان عن طلب إبداء الاهتمام بإحدى الصحف اليومية واسعة الانتشار، وذلك بالإضافة للنشر عنه على بوابة التعاقدات العامة، ويكون اصدار طلب ابداء الاهتمام وفقا للنموذج الذى تعده الهيئة العامة للخدمات الحكومية على أن تتخذ إدارة التعاقدات ما يلزم لتضمينه الآتى:
1- الغرض من طلب ابداء الاهتمام.
2- الشروط والقواعد اللازمة لتقديم الطلب.
3- البيانات الأساسية المطلوبة من المشتغلين بالنشاط محل ابداء الاهتمام.
4- الإشارة إلى أن طلب ابداء الاهتمام لا يترتب عليه أى حقوق لمن قاموا بالرد.
5- أى بيانات تراها الجهة الإدارية لازمة.
وتتولى إدارة التعاقدات استلام وحصر ما يرد إليها من ردود، وتسليمها للجنة لفحصها ودراسة المستندات المرفقة بها وفقا للأسس والمعايير المحددة مسبقا لإبداء الاهتمام بما يتناسب مع طبيعة العملية، وترفع اللجنة تقريرا للسلطة المختصة بنتائج أعمالها مرفقا به بيان بالمشاركين المحتملين أو المهتمين، فإذا ما تقدم عدد كاف منهم فيتم الإعلان عن العملية حال طرحها، وفى غير ذلك فيتم اعداد قائمة مختصرة بالمشتغلين اللذين تتناسب قدراتهم وخبراتهم مع موضوع الطلب.
ويتعين على إدارة التعاقدات توثيق كافة ما تم اتخاذه من إجراءات، وإعمال شئونها في ضوء ما تعتمده السلطة المختصة من نتائج أعمال اللجنة، وإخطار المشاركين المحتملين أو المهتمين بالدخول فى العملية بنتيجة طلب ابداء الاهتمام بالإضافة إلى النشر عن ذلك على بوابة التعاقدات العامة.$m260$,'c3c7fe7bd0700b8162dd89be7c49361e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(18,0,1,$m260$تشكل بقرار من السلطة المختصة لجنة فنية متخصصة من العاملين بالجهة الإدارية من ذوى الخبرة الفنية ذات الصلة بموضوع التعاقد، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى أو من المكاتب الاستشارية، على ألا يقل عدد أعضاء اللجنة عن ثلاثة أعضاء ولا يجاوز سبعة وبما يتناسب مع طبيعة وحجم موضوع التعاقد – ما لم تري السلطة المختصة غير ذلك بناء على أسباب واضحة وموثقة، وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها.
وتتولى اللجنة وضع المواصفات الفنية وعليها فى أداء عملها مراعاة معايير التنمية المستدامة والجودة والخصائص الفنية والنوعية المطلوبة لموضوع التعاقد، بما فى ذلك الاختبارات وأسلوب تقييم العطاءات، وأى بيانات أخرى ترى اللجنة أنها لازمة لمحل التعاقد وبما يلبى احتياجات الجهة الإدارية بفعالية وكفاءة.
وتعد اللجنة تقريرا بنتائج أعمالها متضمنا الأسباب التى ارتأتها والمعايير التى استندت إليها فى عملها، ويتم التوقيع عليه من جميع أعضاءها، وتسلمه إلى إدارة التعاقدات لإعمال شئونها.
ويجوز لإدارة التعاقدات بعد موافقة السلطة المختصة طرح عملياتها ذات الطبيعة النمطية طبقا للمواصفات القياسية الموحدة.$m260$,'8562e6915dd18b48f4adf38473af0e63',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(19,0,1,$m260$بمراعاة طبيعة الأصناف المطلوبة يجب أن تشتمل المواصفات الفنية على الخصائص الوظيفية أو الفنية أو الكيميائية أو معايير الأداء المطلوبة لها أو غيرها، ونوع ومدة الصيانة طوال فترة استهلاكها وخدمات ما بعد البيع والتدريب وما يلزم توفيره من ضمان وقطع غيار، وما يلزم تقديمه بالعرض الفنى من كتالوجات أو عينات وشهادات الجودة مع تحديد الاختبارات المطلوبة للفحص الفنى.
وفى الحالات التى يتم فيها الطرح على أساس عينات فيجب النص على وزنها أو مقاسها أو حجمها، وفى الأصناف التى يلزم توريدها داخل عبوات يجب بيان نوع هذه العبوات وسعتها ومواصفاتها.
ويتعين تجنب الإشارة إلى علامة تجارية معينة أو اسم تجارى أو براءة اختراع أو تصميم أو نوع أو منتج أو بلد معين أو الرقم الوارد فى قوائم الموردين أو مواصفات تنطبق على نماذج خاصة أو مميزة أو إدراج إشارة إلى أى منها، ويستثنى من ذلك الأصناف التى يتعذر توصيفها بإضافة عبارة ما يعادلها أو ما يماثلها أو ما يكافئها فى الأداء.
وفي العمليات التى تتطلب طبيعتها توريدا وتركيبا وتشغيلا وتدريبا فيجب تحديد وتوصيف كافة المهام ذات الصلة من النواحي الفنية وغيرها لكل جزء، وكذا في العمليات التى تتطلب طبيعتها التعاقد مع طرف آخر للقيام بإجراءات الفحص أو الاستلام لمحل التعاقد فيجب تضمين التفاصيل الفنية ذلك ضمن شروط الطرح.$m260$,'2b9871fe29824eb7fefc0c77635e3cdf',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(20,0,1,$m260$يجب توصيف العقار المطلوب شراءه أو استئجاره توصيفا فنيا دقيقا، بما فى ذلك الموقع وحدود المساحة ومستوى التجهيزات والتشطيبات المطلوبة، وذلك كله بما يتناسب مع الغرض من الاستخدام.$m260$,'a475cc62e91c96993886354a52d4a4d5',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(21,0,1,$m260$يكون التعاقد على مقاولات الأعمال بناء على رسومات أو مواصفات فنية دقيقة ومفصلة، ومن ذلك الرسومات المساحية والمعمارية والإنشائية والكهربائية والصحية والميكانيكية وغيرها بحسب طبيعة العملية، وجداول كميات الأعمال المطلوبة بشكل تفصيلي من واقع الرسومات ولجميع بنود المقايسة، وتحديد مدة التنفيذ أو البرنامج الزمنى اللازم للتنفيذ، والبنود المتغيرة أو مكوناتها إذا تطلبت طبيعة العملية ذلك وفقا للقائمة التى تصدرها وزارة الاسكان والمرافق والمجتمعات العمرانية، وبما يتناسب مع طبيعة موضوع التعاقد، ويجب تجنب وضع بنود بالمقطوعية قدر الإمكان.$m260$,'7f5a21d4d1e17c2889024bcba9f7f838',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(22,0,1,$m260$يجب توصيف الخدمة أو العمل الفنى موضوع التعاقد توصيفا عاما، وأن يشمل المهام والتوقيتات المحددة لها ومعايير الأداء والجودة المطلوبة للتنفيذ، والظروف التى سيتم التنفيذ فيها، والاشتراطات المطلوبة فى طاقم التنفيذ أو التدريب أو الإشراف، وتحديد معايير الجودة التى يمكن على أساسها تقييم التنفيذ، وغيرها طبقا لطبيعة العملية.$m260$,'89f0d606a7abf1e625b1b95e77001054',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(23,0,1,$m260$فى حالات البيع أو التأجير للمنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو بالاستغلال تشكل بقرار من السلطة المختصة لجان متخصصة لتصنيف وتلطيط وتوصيف موضوع التعاقد من ذوى الخبرة الفنية ذات الصلة بموضوع التعاقد، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى أو من المكاتب الاستشارية، على ألا يقل عدد أعضاء اللجنة عن ثلاثة أعضاء ولا يجاوز سبعة وبما يتناسب مع طبيعة وحجم موضوع التعاقد، ما لم تري السلطة المختصة غير ذلك بناء على أسباب واضحة وموثقة، وتحدد السلطة المختصة موعد انتهاء تلك اللجان من أعمالها.$m260$,'af97400aa134a632c41c15d9c1ec4f2f',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(24,0,1,$m260$فى حالات بيع المنقولات يجب تقسيم الأصناف المعروضة للبيع إلى لوطات من أصناف متجانسة وإعطاء توصيف كاف ودقيق لمنع أى تغيير يمكن أن يحدث فى مكونات اللوطات، ويراعى فى تقسيم الأصناف إلى لوطات أن يكون حجم كل لوط مناسبا بحيث يسمح باشتراك أكبر عدد من المتزايدين بما يحول دون قيام احتكارات.$m260$,'56c20728e4a3bfea362bc780363e18ec',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(25,0,1,$m260$فى حالة بيع أو تأجير العقارات أو الترخيص بالانتفاع أو باستغلال العقارات والمشروعات التى ليس لها الشخصية الاعتبارية، بما فى ذلك المنشآت السياحية والمقاصف يجب وضع وصف دقيق لموضوع التعاقد ومراعاة أهمية وتميز موقع محل التعاقد ومساحته وحالته وعمره وتكلفة انشائه واستهلاكاته واسم الشهرة إن وجد.$m260$,'40eca949dc1143be416edebf3a7fc9cd',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(26,0,1,$m260$تشكل بقرار من السلطة المختصة لجنة تضم عناصر فنية ومالية من العاملين بالجهة الإدارية من أهل الخبرة بموضوع التعاقد، ويجوز لها الاستعانة بمن تراه مناسبا لأداء مهمتها من الجهات الإدارية الأخرى أو من المكاتب الاستشارية، لدراسة السوق ووضع القيمة التقديرية أو الثمن الأساسى وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها شريطة مراعاة حظر تعارض المصالح.
وتتولى اللجنة إعداد القيمة التقديرية أو الثمن الأساسى للعملية محل الطرح وفقا لدراسة السوق والأسعار المعلنة والسائدة وقت إعدادها ومؤشرات التطور المحتمل فيها، ومقارنة الأسعار للعمليات المماثلة السابق التعاقد عليها، على أن يؤخذ فى الاعتبار تكلفة المواد والعمالة والتكاليف الأخرى، بما في ذلك المعدات والنقل وغيرها من الرسوم والضرائب والتأمينات وأي مصاريف أخرى لها ارتباط بالعملية، ويكون لها أن تأخذ فى الاعتبار ما انتهت إليه أعمال اللجان الخاصة بطلب المعلومات المنصوص عليها بالمادة (16) من هذه اللائحة.
وتعد اللجنة تقريرا بنتائج أعمالها موقعا من أعضاءها، يتضمن الإجراءات التى اتخذتها والأسس والمعايير التى استندت إليها للوصول للقيمة التقديرية أو الثمن الأساسى، والنصاب المنصوص عليه بالمادة (29) من القانون لاشتراك ممثل عن وزارة المالية أو عضو من إدارة الفتوى المختصة بمجلس الدولة، بحسب الأحوال، وترفع اللجنة تقريرها للسلطة المختصة للاعتماد مع مراعاة سريته عند اتخاذ إجراءات العرض عليها، ويحفظ تقرير اللجنة بعد اعتماده فى ظرف مغلق بطريقة محكمة يسلم لمدير إدارة التعاقدات ولا يفتح إلا بمعرفة رئيس لجنة البت عند دراسة العروض المالية، وفى المزايدات يفتح ظرف الثمن الأساسى بمعرفة رئيس لجنة المزايدة ويكشف عن الثمن الأساسى لمحل التزايد لأعضاء اللجنة بعد انتهاء عملية التزايد عليه، ثم ما يليه بالتتابع إن وجد.
على أن تقوم السلطة المختصة بإخطار إدارة التعاقدات لإعمال شئونها المنصوص عليها بالمادة (59) من هذه اللائحة إذا كانت العملية محل الطرح تتطلب اشتراك ممثل عن وزارة المالية أو عضو من إدارة الفتوى المختصة بمجلس الدولة بحسب الأحوال.$m260$,'e800c7b052a41249aa34074ca1102ebd',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(27,0,1,$m260$يكون تحديد القيمة التقديرية لشراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية بما يتماشى مع طبيعة كل عملية وفقا للأسس الآتية:
1- تحليل سعر الوحدة من حيث التكلفة المباشرة وغير المباشرة بما فى ذلك تكلفة المواد، العمالة، النقل، والتكنولوجيا وأية تكاليف أخرى.
2- معايير القيمة مقابل المال المدفوع.
3- المدة الزمنية لتنفيذ العقد.
4- المنافسة المتوقعة عند طرح العملية.
5- توافر خدمات ما بعد البيع.
6- مخاطر وهامش الربح والرسوم والضرائب والتأمين وأى مصروفات أخرى.
7- ما إذا كان محل العقد متوافرا بالأسواق أم ينتج خصيصا للجهة الإدارية.
وغير ذلك من معايير ترى اللجنة أخذها فى الاعتبار.
وتكون القيمة التقديرية على هيئة بنود فى حالة ترسية العملية كل بند على حدة، وتكون إجمالية فى الحالات التى تقتضى طبيعتها ذلك.
وفى حالات شراء أو استئجار العقارات يجب تحديد القيمة التقديرية وفقا لتميز وصقع الموقع ومستوى تجهيزات العقار، ومساحته مع الأخذ فى الاعتبار قيمة الأرض المقام عليها العقار.$m260$,'5410130facac01eb13a7d351d2ce41f8',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(28,0,1,$m260$يتم تحديد الثمن الأساسى لبيع أو تأجير المنقولات وفقا لحالة محل العقد وتكلفة الحصول عليه وعمره الاستعمالى والاسترشاد بأسعار البيع أو التأجير السابقة.
وفى حالات بيع أو تأجير العقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات، بما فى ذلك المنشآت السياحية والمقاصف يكون تحديد الثمن الأساسى وفقا لتميز وصقع الموقع ومستوى التجهيزات، ومساحته وحالته وعمره الاستعمالى وتكلفة إنشاءه واستهلاكاته واسم الشهرة إن وجد وقيمة التجهيزات والمحتويات والعائد الذى يدره تشغيله أو استغلاله وغيرها من العناصر المؤثرة فى تحديد الثمن الأساسى بما يتماشى مع طبيعة محل التعاقد.$m260$,'76089787d4c2024a816fb3398dcb2f76',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(29,0,1,$m260$فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية والدراسات الاستشارية يكون مبلغ التأمين المؤقت بأى قيمة بما يتماشى مع طبيعة العملية وحجمها شريطة ألا يصل الحد الأقصى له ما يجاوز نسبة (1.5%) من القيمة التقديرية.
وفى عمليات شراء أو استئجار العقارات يكون مبلغ التأمين المؤقت بأى قيمة شريطة ألا يصل الحد الأقصى له ما يجاوز نسبة (0.5%) من القيمة التقديرية.
وفى عمليات بيع وتأجير المنقولات والعقارات والترخيص بالانتفاع أو باستغلال العقارات والمشروعات التى ليس لها الشخصية الاعتبارية يكون تحديد مبلغ التأمين المؤقت حسب طبيعة وأهمية المزايدة.
وفى جميع الحالات يجب عدم المبالغة فى تحديد التأمين المؤقت لإتاحة الفرصة لأكبر عدد من المشتغلين بنوع النشاط للمشاركة فى العملية محل الطرح، وعلى لجنة اعداد القيمة التقديرية أو الثمن الأساسى، بحسب الاحوال، اقتراح مبلغ التأمين المؤقت بكتاب مستقل موقع من رئيسها وأعضاءها يرفق بتقريرها، ويتم تحديد مبلغ التأمين المؤقت واعتماده من السلطة المختصة ويخطر به مدير إدارة التعاقدات لاتخاذ الإجراءات اللازمة، على أن يتم تضمين مستندات الطرح مبلغ التأمين المؤقت.$m260$,'c833d6af8ad2707f553718b41af971fa',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(30,0,1,$m260$يؤدى التأمين المؤقت بأى من الوسائل التى يصدر بتحديدها قرار من وزير المالية، ومنها وسائل الدفع الإلكترونى من خلال منظومة الدفع والتحصيل الإلكترونى أو بأية صورة من الصورتين الآتيتين:
1- بموجب خطاب ضمان مصدرا من أحد المصارف المحلية المعتمدة وألا يقترن بأى قيد أو شرط وأن يقر فيه المصرف بأن يدفع تحت أمر الجهة الإدارية مبلغا يوازى التأمين المطلوب.
وعندما يرد لإحدى الجهات الإدارية خطابات ضمان عن التأمين المستحق من أحد المصارف المرخص لها فى إصدار خطابات الضمان أو أحد فروعها عليها أن تتحقق من أن المصرف أو الفرع قد أعطى إقرارا على خطابات الضمان بأنه لم يجاوز الحد الأقصى المحدد لمجموع خطابات الضمان المرخص للمصرف فى إصدارها.
فإذا تبين عند مراجعة الإخطارات لدى البنك المركزى أن المصرف قد تعدى الحد الأقصى المحدد له أخطرت الجهة الإدارية فورا لمطالبة المصرف بأن يؤدى إليها فى ميعاد لا يجاوز ثلاثة أيام عمل قيمة خطاب الضمان.
وتقبل خطابات الضمان من البنوك الخارجية بشرط التأشير عليها بالقبول من أحد المصارف المحلية المعتمدة على أن يتعهد المصرف المحلى بأن يدفع للجهة الإدارية مبلغا يوازى التأمين المطلوب وأنه ملتزم بأدائه بأكمله عند أول طلب منها دون الالتفات إلى أى معارضة من صاحب العطاء.
2- يجوز لصاحب العطاء طلب سداد التأمين المؤقت خصما من مستحقاته التى تقر الجهة العامة صلاحيتها للصرف من عمليات أخرى فى ذات الجهة الإدارية وفى تاريخ جلسة فتح المظاريف الفنية.
كما يجوز بموافقة السلطة المختصة وبناء على طلب صاحب العطاء استبدال التأمين المؤقت المسدد منه بأحد صور السداد الأخرى المنصوص عليها بهذه المادة بشرط ألا تنقطع مدة سريان التأمين وعدم الإخلال بمسئوليته طبقا للغرض المقدم عنه التأمين.
ويتم رد التأمين المؤقت فى الحالات المنصوص عليها بالقانون وهذه اللائحة بذات الوسيلة التى تم أدائه بها.
ويجب أن تتضمن مستندات الطرح صور سداد ورد التأمين المؤقت على وجه التحديد.$m260$,'97135dd58b40703195335d9932beead9',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(31,0,1,$m260$تتولى إدارة التعاقدات إعداد مذكرة للعرض على السلطة المختصة متضمنة موضوع وطريق التعاقد المناسب والإدارة الطالبة أو المستفيدة منه، والإجراءات السابق اتخاذها للإعداد للعملية محل الطرح، للموافقة على اتخاذ إجراءات الطرح وفقا للآتى:
1- توافر الاعتماد المالى.
2- الإعلان عن العملية أو الدعوة إليها.
3- مقترح تشكيل لجنة الرد على الاستفسارات إذا تطلب الأمر، واللجان المختصة بمباشرة إجراءات طرح العملية، على أن يتضمن قرار تشكيل تلك اللجان مواعيد انتهاءها من عملها.
4- البرنامج الزمنى المقترح لإجراءات العملية.
5- إمكانية السماح بصرف دفعة مقدمة من قيمة التعاقد، مع تحديد نسبتها.
6- تحديد أسلوب تقييم العطاءات وأسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول فى حالة التقييم بنظام النقاط.
7- مدة صلاحية سريان العطاءات.
8- البنود المتغيرة أو مكوناتها فى مقاولات الأعمال فى العمليات التى تتطلب ذلك.
9- استخدام اسلوب الاتفاقية الاطارية إذا رأت الجهة العامة ذلك ونمطها ومدتها.
10- تضمين كراسة الشروط والمواصفات البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن إذا تطلبت طبيعة العملية ذلك.
11- ثمن نسخة كراسة الشروط والمواصفات وفقا للشرائح المحددة بالمادة (35) من هذه اللائحة.
12- تقصير مدة تقديم العطاءات إذا تطلب موضوع التعاقد ذلك مع بيان السبب.
13- مدة توريد أو تنفيذ العقد.
14- تحديد آلية تسوية المنازعات والخلافات وفقا لحكم المادة (91) من القانون.
وغير ذلك من بيانات تراها إدارة التعاقدات يلزم عرضها على السلطة المختصة.
على أن ترفق بمذكرة الطرح الآتى:
1- صورة من نموذج خطة الاحتياجات المعتمدة، والمتضمنة العملية محل الطرح.
2- صورة الموافقات والتراخيص اللازمة ذات الصلة بالعملية محل الطرح.
3- نسخة من تقرير لجنة اعداد المواصفات الفنية.
4- نسخة من مستندات الطرح، وصيغة الإعلان أو خطابات الدعوة.$m260$,'6575948f94420342a126e2b15fc7bcfe',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(32,0,1,$m260$تلتزم إدارة التعاقدات بكراسات الشروط والمواصفات النموذجية الصادرة عن الهيئة العامة للخدمات الحكومية، وأن تكون كراسات الشروط والمواصفات كاملة وواضحة ومرتبة ومرقمة بالتسلسل وأن تتضمن تحديد ما إذا كانت العملية قابلة للتجزئة من عدمه، وتحديد مراحل وتوقيتات تقديم الشكاوى وآلية تسوية الخلافات والمنازعات، والحظر المنصوص عليه بالمادة (33) من القانون، وما يفيد أن يكون صاحب العطاء أو المتزايد بحسب الأحوال لديه الامكانيات والقدرة على تنفيذ كافة التزاماته الواردة بكراسة الشروط والمواصفات بما فى ذلك تلبية كافة اشتراطات مزاولة النشاط موضوع التعاقد وعنوانه الدائم ويعتبر إعلامه صحيحا متى تم مخاطبته عليه فيما لو رست عليه العملية محل الطرح على أن يتم نشرها على بوابة التعاقدات العامة عدا العمليات التى تتطلب اعتبارات الأمن القومى عدم النشر عنها وفقا لما تقدره السلطة المختصة.
ويرد ثمن كراسة الشروط والمواصفات لمن قام بشرائها متى توافرت أى من حالات إلغاء العملية المنصوص عليها بالمادة (37) من القانون، فيما عدا الحالات التى يتبين وجود تواطؤ أو ممارسات احتيال أو فساد أو احتكار فيها.
وفي العمليات التى تقتضى طبيعتها المعاينة التامة النافية للجهالة يتم تضمين ذلك بكراسة الشروط والمواصفات ويتعين فى هذه الحالة قيام إدارة التعاقدات بالتنسيق مع الإدارات الطالبة أو المستفيدة بالجهة الإدارية لتحديد موعد زيارة لمكان التوريد أو التنفيذ أو موقع المشروع أو مكان تواجد محل البيع أو التأجير أو الترخيص على أن يكون موعد المعاينة قبل انعقاد جلسة فتح المظاريف الفنية أو جلسة المزايدة بوقت كاف، بما يمكن من قام بشراء كراسة الشروط والمواصفات من اعداد عطائه بشكل جيد.
وتلتزم إدارة التعاقدات بإخطار أو موافاة، بحسب الأحوال، لجنة تفضيل المنتج الصناعى المصرى بنسخة من شروط ومواصفات الطرح أو العقود وفقا لما هو منصوص عليه بأحكام القانون رقم 5 لسنة 2015 فى شأن تفضيل المنتجات المصرية فى العقود الحكومية.$m260$,'f959c36cc48a00c7fc0a899f3458c513',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(33,0,1,$m260$تلتزم إدارة التعاقدات بتضمين كراسة الشروط والمواصفات فى عمليات شراء أو استئجار المنقولات والعقارات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية، بحسب الأحوال، البيانات الآتية:
1- ما يفيد توافر الاعتماد المالى المخصص للعملية محل الطرح.
2- وسيلة وأسلوب التواصل مع الجهة، بما في ذلك عنوان وتليفون ورقم فاكس وبريد الكرتوني واسم المخول له التواصل مع المتعاملين.
3- البيانات الواجب توافرها فى أصحاب العطاءات ومعايير التحقق من توافر شروط الكفاءة الفنية والملاءة المالية وحسن السمعة لهم، والتصنيف المطلوب للمقاولين في مقاولات الاعمال وشهادات مزاولة النشاط ذات الصلة.
4- وصفا لموضوع التعاقد بما في ذلك أي وصف فني ضروري، والمخرجات المطلوبة ومستويات الأداء وغيرها من المواصفات والبيانات الإحصائية لمعدلات الطلب، ومعدلات الاستهلاك التاريخية، والمؤشرات المستقبلية الاسترشادية لمحل الطرح والتعاقد أو أطر الأعمال أو الخدمات، بحسب الأحوال.
5- أسلوب تقييم العطاءات وأسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول فى حالة التقييم بنظام النقاط.
6- معايير ومحددات دورة الحياة التى يمكن تقيمها عند البت ووفقا لطبيعة العملية.
7- صور سداد ورد التأمين المؤقت ومبلغه والتأمين النهائى ونسبته.
8- إقرار التأمين على العمالة إذا تطلبت طبيعة العملية ذلك.
9- تحديد البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن إذا تطلبت طبيعة العملية ذلك، وكذا المحددات والاشتراطات الأخرى ذات الصلة.
10- شروط تطبيق أفضلية المنتج المحلي عن توريدات مستوفية لنسبة المكون الصناعى المصرى، أو الخدمات أو الأعمال الفنية التى تقوم بها جهات مصرية؛ إعمالا لحكم المادة (35) من القانون.
11- المدة اللازمة لصلاحية سريان العطاءات.
12- مدة التوريد أو التنفيذ أو أداء الخدمة.
13- نسبة الدفعة المقدمة إن وجدت، وطلب تحديد أوجه صرفها.
14- تحديد البنود المتغيرة أو مكوناتها بالنسبة لمقاولات الأعمال فى العمليات التى تتطلب ذلك.
15- تحديد مدة الضمان، ومدة الصيانة ونوعها، شاملة أو غير شاملة قطع الغيار، فى الحالات التى تتطلب ذلك.
16- ما يفيد تعديل حجم العقد بالزيادة أو النقص إذا طرأت مستجدات تستوجب ذلك وبما لا يجاوز النسب ووفقا للأحكام الواردة بالقانون.
17- النص على استخدام اسلوب الاتفاقية الاطارية ونمطها فى العمليات التى يتقرر فيها ذلك.
18- التأكيد على أن جميع التعاقدات تكون بالجنيه المصري ما لم يذكر صراحة غير ذلك، وأنه يجوز فى حالة تقديم العطاء من فرد أو شركة فى الخارج أن تكتب الأسعار بالعملة الأجنبية، ولغرض المقارنة تتم معادلتها بالجنيه المصري بالسعر المعلن بالبنك المركزي المصري فى تاريخ فتح المظاريف الفنية.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة بما يتماشى مع طبيعة العملية.$m260$,'929c00d4065562ee52842de6df334c03',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(34,0,1,$m260$تلتزم إدارة التعاقدات بتضمين كراسة الشروط والمواصفات لبيع وتأجير المنقولات والعقارات، والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف البيانات الآتية:
1- توصيف محل التعاقد.
2- الاشتراطات الواجب توافرها فى المتزايدين.
3- صور سداد ورد التأمين المؤقت ومبلغه والتأمين النهائى ونسبته.
4- طلب التراخيص اللازمة في حالة بيع الأصناف التى تتطلب ذلك مثل المخلفات الإلكترونية والخطرة وما يماثلها.
5- تحديد البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن إذا تطلبت طبيعة العملية ذلك، وكذا المحددات والاشتراطات الأخرى ذات الصلة.
6- طلب تحديد القيمة الإيجارية أو مقابل الترخيص بالانتفاع أو بالاستغلال وتاريخ سدادهما، والإجراءات التى تتخذ حال عدم السداد فى المواعيد المحددة.
7- ما يفيد أن الكميات والأوزان المعروضة للبيع تحت العجز والزيادة والعبرة بما يسفر عنه التسليم الفعلي.
8- الموعد المحدد لاستلام الأصناف المباعة وقيمة المصروفات التى سيتحملها المتعاقد فى حالة تأخره عن هذا الموعد.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة بما يتماشى مع طبيعة العملية.$m260$,'9e691409cee5e3882caae8fb64a0a000',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(35,0,1,$m260$على الجهة الإدارية تحديد ثمن كراسة الشروط والمواصفات وفقا للشرائح الأتية:
مبلغ التأمين المؤقت (بالألف جنيه مصرى) | ثمن شراء كراسة الشروط والمواصفات (بالجنيه المصرى)
حتى 100 | 299
أكثر من 100 وحتى 200 | 399
أكثر من 200 وحتى 300 | 499
أكثر من 300 وحتى 400 | 599
أكثر من 400 وحتى 500 | 699
أكثر من 500 وحتى 600 | 799
أكثر من 600 وحتى 700 | 899
أكثر من 700 وحتى 800 | 999
أكثر من 800 وحتى 900 | 1500
أكثر من 900 وحتى مليون | 2000
أكثر من مليون | من 3000 إلى 50000
وفى العمليات التى يكون مبلغ التأمين المؤقت فيها أكثر من مليون جنيه يجب عدم المغالاة فى تحديد ثمن كراسة الشروط والمواصفات لإتاحة الفرصة لاشتراك أكبر عدد ممكن من المتعاملين فى العملية محل الطرح.$m260$,'e7eeea12c0f1772fc1c691875b2f25eb',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(36,0,1,$m260$بمراعاة أحكام المادة (20) من القانون يجب على إدارة التعاقدات فور موافقة السلطة المختصة على ما تضمنته مذكرة الطرح النشر عن العملية على بوابة التعاقدات العامة، وكذا الإعلان عنها أو الدعوة إليها، بحسب الأحوال، على أن يتضمن الإعلان أو الدعوة البيانات الآتية:
1- اسم الجهة الإدارية الطارحة، وعنوان إدارة التعاقدات بها ورقم التليفون والفاكس والبريد الإلكترونى للإدارة.
2- أسم العملية ورقمها وطريق التعاقد.
3- وصفا موجزا وواضحا لموضوع التعاقد.
4- مكان وميعاد الحصول على كراسة الشروط والمواصفات وثمنها، والإشارة إلى إمكانية الاطلاع على بيانات العملية ومستندات الطرح الخاصة بها على بوابة التعاقدات العامة دون مقابل.
5- موعد ومكان انعقاد جلسة الاستفسارات إن وجدت، وجلسة فتح المظاريف أو الممارسة أو جلسة المزايدة، بحسب الأحوال.
6- مبلغ التأمين المؤقت ونسبة التأمين النهائى.
وإذا تقرر طرح أكثر من عملية فى تاريخ واحد أو تواريخ متقاربة فعلى إدارة التعاقدات مراعاة الإعلان عنها فى إعلان واحد.$m260$,'b178b9268893e2e95d47c939aff3d8b9',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(37,0,1,$m260$يجوز فى العمليات التى تتطلب طبيعتها التأكد من توافر القدرات الفنية والإمكانيات المالية والإدارية والبشرية وغيرها لدى الموردين أو المقاولين أو مقدمى الخدمات أو الاستشاريين للقيام بتنفيذ أحد العقود بالكفاءة المطلوبة قبل دعوتهم لتقديم العطاءات حال الطرح أن تقوم إدارة التعاقدات بإصدار طلب للتأهيل المسبق دون مقابل للمشتغلين بنوع النشاط محل العملية المزمع طرحها، على أن يتم الإعلان عن التأهيل المسبق بإحدى الصحف اليومية واسعة الانتشار، بالإضافة للنشر عنه على بوابة التعاقدات العامة، ويجب أن يتضمن الإعلان الآتى:
1- اسم ورقم العملية المطلوب التأهيل لها كما هو مدرج في خطة الاحتياجات السنوية.
2- اسم الجهة الإدارية الطارحة، وعنوان إدارة التعاقدات بها ورقم التليفون والفاكس والبريد الإلكترونى للإدارة.
3- وصفا موجزا وواضحا للعملية المطلوب التأهيل لها.
4- بيان كيفية الحصول على مستندات التأهيل المسبق، والإشارة إلى إمكانية الاطلاع عليها على بوابة التعاقدات العامة دون مقابل.
5- مكان وأخر موعد لتلقى الطلبات.
6- تحديد الخبرات المطلوبة.$m260$,'82aab586be1a6f357892202cdc7cd7cb',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(38,0,1,$m260$تشكل بقرار من السلطة المختصة لجنة تضم عناصر فنية ومالية وقانونية ويضم لها عضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع التأهيل المسبق، ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، وتحدد السلطة المختصة موعد انتهاء تلك اللجنة من أعمالها، وتختص بالآتي:
1- إعداد مستندات التأهيل المسبق، ووضع معاييره، وبيان المستندات اللازمة له.
2- الرد على استفسارات طالبى التأهل، مع إتاحة مضمون الرد لكافة طالبى التأهل فى العملية المزمع طرحها دون الافصاح عن مقدم الاستفسار الذي طلب التوضيح.
3- دراسة طلبات التأهيل المسبق بعد استيفائها، وتحديد المؤهل منها طبقا لمعايير التأهيل الموضوعة واستبعاد الغير مؤهل.$m260$,'25710a934b1621db3d8e4c350a089f3f',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(39,0,1,$m260$يكون إصدار طلب التأهيل المسبق وفقا للنموذج الذى تعده الهيئة العامة للخدمات الحكومية على أن تتخذ لجنة التأهيل المسبق ما يلزم لتضمينه المعايير التى يمكن على أساسها تنفيذ العملية المزمع طرحها، من متطلبات الأهلية والتأهيل، والمعلومات والمستندات الواجب تقديمها من مقدمي طلبات التأهيل لإثبات استيفائهم لهذه المتطلبات، والخبرات المطلوبة لهم، بما فى ذلك خبرات العنصر البشرى أو التكنولوجي، وحجم المشاركة فى عمليات مماثلة، والكفاءة الفنية والملاءة المالية، وغير ذلك من المتطلبات الفنية والمالية والإدارية والبشرية، على أن يراعى الآتى:
1- عمليات توريد المنقولات:
أ- سابقة الخبرة فى توريدات مماثلة كمتعاقد أو متعاقد من الباطن.
ب- كفاءة المهنيين المشاركين في أعمال التركيبات إذا كانت طبيعة العملية تتطلب ذلك.
ج- إمكانية التشغيل دون أعطال للأصناف.
د- أعمال الصيانة، والضمان، وخدمة ما بعد البيع، وتوافر قطع الغيار.
2- التعاقد على مقاولات الأعمال:
أ- القدرات المهنية وكذا الملاءة المالية.
ب- سابقة الأعمال فى عقود مماثلة فى الطبيعة والتكنولوجيا الإنشائية للعملية المزمع طرحها، وسابقة التقاضي، والخبرة الإجمالية للعمليات السابق تنفيذها كمتعاقد أو متعاقد من الباطن.
ج- التصنيف وفقا للاتحاد المصرى لمقاولى التشييد والبناء طبقا لحجم الأعمال وطبيعتها.
د- متوسط حجم الأعمال المنفذة سنويا.
ه- توافر المعدات وحالتها التشغيلية المناسبة.
و- توافر الكوادر الفنية المؤهلة بشكل مناسب للوظائف الرئيسية المذكورة في مستندات طلب التأهيل.
3- عمليات تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية:
أ- الخبرة الأكاديمية والعملية للعنصر البشرى كمتعاقد أو متعاقد من الباطن.
ب- الخبرة المؤسسية والأداء وسابقة الخبرة في الاعمال المماثلة.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة.$m260$,'43d5783e2867e5babc5c3a887367e074',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(40,0,1,$m260$يجب على المتقدمين للتأهيل المسبق استيفاء نموذج طلب التأهيل وتقديم المستندات والوثائق المطلوبة والمذكورة في طلب التأهيل، ويجب تقديم الطلبات في ظرف مغلق في الوقت والمكان المحددين في الاعلان، ويرفض الطلب في حال عدم تقديم المعلومات والوثائق المطلوبة في مستندات التأهيل المسبق.
وتتولى إدارة التعاقدات تلقى طلبات التأهيل المسبق، وقيدها فى السجل المعد لذلك بحسب تاريخ تقديمها، ويسلم مدير إدارة التعاقدات رئيس لجنة التأهيل المسبق الطلبات الواردة لفحصها، والتأكد من استيفائها للبيانات والمستندات المطلوبة.
ويجوز للجنة التأهيل المسبق وبما لا يخل بمبدأ تكافؤ الفرص أن تطلب كتابة الإيضاحات والمستندات التى تراها لازمة لدراسة طلبات التأهيل المقدمة على أن يتضمن طلب اللجنة تحديد موعد نهائى للرد عليه، كما يجوز لها أن تستطلع رأى الجهات الإدارية السابق تعاملهم معها، وإجراء الزيارات الميدانية إذا تطلب الأمر ذلك.
يجب أن تكون توصيات لجنة التأهيل المسبق باستبعاد طلبات التأهيل غير المستوفاة لمعايير التأهيل الموضوعة مسببه، وعلى إدارة التعاقدات بعد اعتماد السلطة المختصة لتوصيات اللجنة بالقبول أو الاستبعاد إخطار المتقدمين بنتيجة التأهيل بالإضافة إلى النشر عن ذلك على بوابة التعاقدات العامة، ويجوز لمن لم يتم تأهيلهم التقدم بشكواهم وفقا للقواعد المعمول بها بشأن الشكاوى.
ويتم توجيه الدعوة لمقدمي الطلبات الذين اجتازوا مرحلة التأهيل المسبق للمشاركة في العملية حال الطرح، وتقديم عطاءاتهم على أن لا يقل العدد عن ثلاثة مؤهلين، ويجوز للسلطة المختصة في حالة ما اذا كان عدد المؤهلين اقل من ثلاثة اعادة اجراءات التأهيل المسبق بعد اعادة النظر في متطلبات التأهيل السابقة.
ويتعين على إدارة التعاقدات توثيق كافة ما تم اتخاذه من إجراءات.$m260$,'407983da700ce43d647e8e54f04a8000',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(41,0,1,$m260$يجب أن تتضمن كراسة الشروط والمواصفات مواعيد تقديم الايضاحات والرد عليها، على أن يؤخذ في الاعتبار التاريخ المحدد لتقديم العطاءات ومراعاة إتاحة الفرصة لإجراء الزيارات الميدانية اللازمة، إذا تطلبت طبيعة العملية ذلك.
ولصاحب العطاء المحتمل أو من قاموا بشراء كراسة الشروط والمواصفات الحق في طلب أى إيضاحات كتابة بشأن ما ورد بها بداية من تاريخ النشر عن العملية على موقع بوابة التعاقدات العامة وبحد أقصى عشرة أيام قبل التاريخ المحدد لانعقاد جلسة فتح المظاريف والموضح بمستندات الطرح.
وعلى إدارة التعاقدات الرد قبل موعد فتح المظاريف الفنية بمدة لا تقل عن سبعة أيام.$m260$,'acd6c78fc253415d7374dd87e81fbc4d',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(42,0,1,$m260$يجب على السلطة المختصة فى الحالات التى تقرر فيها عقد جلسة للاستفسارات أن تقوم بتشكيل لجنة من عناصر فنية ومالية وقانونية وعضو من إدارة التعاقدات، تكون مهمتها تلقى الاستفسارات كتابة وذلك قبل الموعد المحدد لانعقاد جلسة الاستفسارات، ووفقا للمدد الزمنية المحددة لذلك بكراسة الشروط والمواصفات.
وتتولى اللجنة المشار إليها دراسة ما يقدم إليها من استفسارات ويتعين عليها أن تعد محضرا للجلسة يتضمن الأسئلة والايضاحات التي أثيرت خلالها، وما تم الرد بشأنه، وبناء على ما تسفر عنه نتيجة دراستها تقوم برفع محضرها بما انتهت إليه متضمنا أى تعديلات بكراسة الشروط والمواصفات أو الجدول الزمنى إذا تطلب الأمر ذلك.
وفور اعتماد السلطة المختصة لمحضر اللجنة يجب على إدارة التعاقدات اخطار مقدمى الاستفسارات أو الايضاحات ومن قاموا بشراء كراسة الشروط والمواصفات كتابة، دون الافصاح عن مقدم الاستفسار الذي طلب التوضيح، وذلك خلال ثلاثة أيام على الأكثر من تاريخ إجراء التعديلات أو جلسة الاستفسارات ولا يجوز أن تقل المدة بين الإخطار والموعد المحدد لفتح المظاريف الفنية عن سبعة أيام شاملا ما يلزم من إيضاحات وتعديلات وكذا نشرها على بوابة التعاقدات العامة على أن تعتبر هذه التعديلات جزءا لا يتجزأ من كراسة الشروط والمواصفات، وتسرى فى مواجهة جميع أصحاب العطاءات.$m260$,'003a7653f80cb7394139edb2ce4aa19d',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(43,0,1,$m260$يتحمل صاحب العطاء كافة تكاليف إعداد وتقديم عطائه، وكل ما يتعلق به من مهام، ولا تتحمل الجهة الإدارية بأي حال من الأحوال أية مسئولية عن تلك التكاليف بغض النظر عن نتيجة العملية.
وتقدم العطاءات موقعة من أصحابها وفقا للشروط المحددة بمستندات الطرح ويجب تقديمها على نموذج العطاء المدرج بكراسة الشروط والمواصفات، ويجب أن يثبت على كل من مظروفي العطاء الفنى والمالى نوعه من الخارج، ويوضع المظروفين داخل ظرف مغلق بطريقة محكمة ويوضح عليه اسم الجهة الإدارية وعنوان إدارة التعاقدات وما يفيد أن ما بداخله المظروف الفنى والمظروف المالى ويذكر اسم العملية ورقمها وتاريخ جلسة فتح المظاريف الفنية كما يذكر أسم صاحب العطاء.$m260$,'9de10d3be0cbdf0dd5589bfb4e42d9d7',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(44,0,1,$m260$تسلم العطاءات لإدارة التعاقدات قبل التاريخ أو الموعد المحدد لفتح المظاريف الفنية إما باليد أو عن طريق البريد السريع من خلال الهيئة القومية للبريد أو عن طريق الوسائل الإلكترونية إذا ما سمحت بذلك شروط العملية.
وعلى صاحب العطاء عدم شطب أى بند من بنود العطاء أو من المواصفات الفنية أو إجراء تعديل فيه مهما كان نوعه بعد تسليمه، وإذا رغب فى إبداء أية ملاحظات خاصة بالنواحي الفنية فيثبتها فى كتاب مستقل ويسلمها لإدارة التعاقدات قبل الموعد المحدد لفتح المظاريف الفنية، ويبقى العطاء نافذ المفعول وغير جائز الرجوع فيه من وقت تسليمه بغض النظر عن ميعاد استلامه بمعرفة الجهة الإدارية وحتى نهاية المدة المحددة لسريان العطاءات.
وفي حالة تقديم العطاء من صاحبه أو من يفوضه شريطة تقديم التفويض الدال على ذلك أو وكيله، فيتعين على إدارة التعاقدات التوقيع على ايصال يفيد الاستلام يحدد به موعد وتاريخ استلام العطاءات، وفى حالة استلام إدارة التعاقدات العطاءات عن طريق البريد السريع من خلال الهيئة القومية للبريد، فيجب على موظف الإدارة التوقيع على ايصال الهيئة بالاستلام والاحتفاظ بصورة منه.$m260$,'55cf21b066db1dda000dba3772924927',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(45,0,1,$m260$على إدارة التعاقدات عند تحديد مدة تقديم العطاءات أن تراعى اعطاء الوقت الكافى لأصحاب العطاءات لدراستهم لكراسة الشروط والمواصفات واستيفاء المستندات اللازمة لتقديم عطاءاتهم ووفقا لطبيعة وحجم العملية محل الطرح، على أن يتم تحديد مدة تقديم العطاءات وفقا للآتى:
1- المناقصة العامة والممارسة العامة والمزايدة العلنية العامة والمزايدة بالمظاريف المغلقة خلال مدة لا تقل عن عشرين يوما تحتسب من تاريخ الإعلان بإحدى الصحف اليومية، ويجوز استثناء بموافقة السلطة المختصة فى حالة الاستعجال المبررة والموثقة تقصير تلك المدة بحيث لا تقل عن أربعة عشر يوما.
2- المناقصة المحدودة والمناقصة المحلية والممارسة المحدودة والمزايدة المحدودة والمزايدة المحلية خلال مدة لا تقل عن أربعة عشر يوما تحتسب من تاريخ توجيه الدعوة ويجوز استثناء بموافقة السلطة المختصة فى حالة الاستعجال المبررة والموثقة تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام.$m260$,'d6e25c7387d56e4b4366e0d8e5b0de7e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(46,0,1,$m260$يجوز للجهة الإدارية، إذا ارتأت ضرورة، أن تقوم بتأجيل موعد فتح المظاريف أو المزايدة، بحسب الأحوال.
كما يجوز لمن قام بشراء كراسة الشروط والمواصفات قبل التاريخ المحدد لفتح المظاريف الفنية أو جلسة المزايدة بثلاثة أيام على الأقل أن يتقدم كتابة لإدارة التعاقدات بطلب مسبب لمد مدة تقديم العطاءات، وتلتزم إدارة التعاقدات بالعرض على السلطة المختصة بنتيجة دراستها والحصول على موافقتها حال اقتراح مد المدة وتأجيل موعد فتح المظاريف أو المزايدة، بحسب الأحوال، أو الأسباب التى تراها مناسبة لعدم تأجيل الموعد.
وفى جميع حالات تأجيل تاريخ فتح المظاريف أو المزايدة، بحسب الأحوال، يتعين الحصول على موافقة السلطة المختصة وإعادة النشر على بوابة التعاقدات العامة والإعلان أو توجيه الدعوات، بحسب الأحوال، على ألا تقل مدة التأجيل عن نصف المدة المحددة مسبقا لفتح المظاريف الفنية من تاريخ الإعلان أو الدعوة.$m260$,'37d1aa3a5167ed6d1535a23ee0a408b6',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(47,0,1,$m260$على مدير إدارة التعاقدات التأكد من أن جميع العطاءات والعينات التى استلمها محفوظة بطريقة أمنة لا تسمح بالاطلاع على مضمونها أو فتحها ولو بطريق الخطأ، ويحظر فتح العطاءات قبل الموعد المحدد لجلسة فتح المظاريف، ولا يجوز الكشف عن عدد العطاءات المستلمة أو أية معلومات بشأن أصحاب العطاءات قبل انعقاد جلسة فتح المظاريف الفنية.
ويتعين على مدير إدارة التعاقدات تسليم العينات لإدارة المخازن لحفظها، وينبغي أن يتم التعامل معها بطريقة سرية ومضمونة لا تؤدى إلى الكشف عن خصائصها قبل فتح المظاريف.$m260$,'16bb7aee28183a56b53ec074abbb7991',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(48,0,1,$m260$فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية يجب أن يحتوى المظروف الفنى على ما يفيد سداد التأمين المؤقت المطلوب بالإضافة إلى البيانات والمستندات المنصوص عليها بكراسة الشروط والمواصفات، وعلى الأخص وبحسب طبيعة العملية المطروحة الآتى:
1- بيان الشكل القانوني لصاحب العطاء والمستندات الدالة على ذلك.
2- بيانات القيد فى السجلات الخاصة بالنشاط موضوع التعاقد كالقيد فى السجل التجاري أو الصناعى أو سجل المستوردين وغيرها من السجلات التى يكون القيد فيها واجبا قانونا.
3- بيانات وخبرات صاحب العطاء ومن قد يعهد إليهم ببعض بنود العملية من الباطن وفقا لما تضمنته كراسة الشروط والمواصفات.
4- المستندات الدالة على سابقة الأعمال لذات موضوع التعاقد.
5- بيانات عن أسماء ووظائف وخبرات الكوادر التى سيسند إليها التنفيذ والإشراف على تنفيذ العملية.
6- المستندات الدالة على وجود مركز صيانة معتمد ساري.
7- بيان مصادر ونوع المواد والمهمات والأجهزة التى تستخدم فى التنفيذ.
8- البطاقة الضريبية سارية، وأخر إقرار ضريبي.
9- بطاقة الاتحاد المصرى لمقاولى التشييد والبناء سارية.
10- تعهد بألا تقل نسبة المكون الصناعى المصرى عن (40%) فى عقود مقاولات الأعمال.
11- إقرار الالتزام بالتأمين على العمالة إذا تطلبت طبيعة العملية ذلك.
12- إقرار بالالتزام بما جاء بكراسة الشروط والمواصفات ومحتوياتها.
13- ما يفيد شراء كراسة الشروط والمواصفات.
14- نسبة الدفعة المقدمة المطلوبة لتنفيذ محل العقد وأوجه صرفها إذا نصت كراسة الشروط والمواصفات على ذلك.
15- طريقة التنفيذ والبرنامج الزمنى للتوريد أو التنفيذ ومدته.
16- الكتالوجات والبيانات الخاصة بمصادر ونوع المواد والمهمات والمعدات والأجهزة المقدمة عن العرض.
17- قائمة بقطع الغيار ومستلزمات التشغيل مع بيان معدلات استهلاكها.
18- معاملات تغير الأسعار للبنود أو مكوناتها الواردة بكراسة الشروط والمواصفات فى عقود مقاولات الأعمال التى تتطلب ذلك.
وغير ذلك من بيانات تضمنتها كراسة الشروط والمواصفات.$m260$,'310e36396851db699bfd15251d606d22',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(49,0,1,$m260$فى عمليات شراء أو استئجار العقارات يجب أن يحتوى المظروف الفنى على الآتى:
1- صورة معتمدة من المستندات الدالة على الملكية.
2- شهادة سلبية تفيد خلو العقار من أية رهون أو حجوزات أو حقوق للغير.
3- تقرير معتمد من مهندس استشاري يفيد سلامة العقار من كافة النواحى الإنشائية والمعمارية وصلاحيته للغرض المطلوب من أجله.
4- صورة من التراخيص الصادرة من الجهات المختصة بإنشاء العقار.
5- نسخة من الرسومات الهندسية معتمدة من مهندس استشاري تفيد أنها تطابق ما هو موجود على الطبيعة ومقدم عنه العرض.
6- شهادة من الجهة الإدارية المختصة بشئون التخطيط والتنظيم الواقع بدائرتها العقار تفيد عدم وجود أية مخالفات على العقار.
7- بيان بمواصفات العقار المعروض وما يشتمل عليه من تجهيزات.
8- المدة التى يتم خلالها تسليم العقار للجهة الادارية صالحا للاستخدام وفقا لمتطلباتها.
9- اقرار بتحمل صاحب العقار المسئولية عن سلامة العقار بالكامل، والموافقة على تنفيذ أى تعديلات أو أعمال إضافية على العقار قد تطلبها الجهة الإدارية بغرض توحيد المسئولية، وأن يلتزم بتنفيذ هذه الأعمال وفقا لتعليمات الجهات الفنية المختصة، وأن تتم المحاسبة استرشادا بأسعار السوق.
وغير ذلك من بيانات تضمنتها كراسة الشروط والمواصفات.$m260$,'22ab886926c9e78caafc79f80c673603',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(50,0,1,$m260$فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية يجب أن يحتوى المظروف المالى على الآتى:
1- قوائم الأسعار وجداول الفئات وكمياتها.
2- أسلوب السداد وقيم الصيانة وقطع الغيار ومستلزمات التشغيل وغيرها من العناصر التى تؤثر فى القيمة المالية للعرض.
3- شهادة استيفاء نسبة المكون الصناعى المصرى سارية فى عقود شراء المنقولات.
وغير ذلك من بيانات تضمنتها كراسة الشروط والمواصفات.$m260$,'3f62ef1c66b89508d00411aac734ea5c',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(51,0,1,$m260$فى عمليات شراء أو استئجار العقارات يجب أن يحتوى المظروف المالى على الآتى:
1- سعر البيع أو القيمة الإيجارية وملحقاتها التى تتحملها الجهة الإدارية.
2- طريقة السداد.
وغير ذلك من بيانات تضمنتها كراسة الشروط والمواصفات.$m260$,'ffb03363ea8810f20bb6e4503627a76e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(52,0,1,$m260$فى عمليات شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية على صاحب العطاء عند إعداده لقائمة الأسعار وجدول الفئات التى يتم وضعها داخل المظروف المالى مراعاة الآتى:
1- كتابة الأسعار رقما وحروفا باللغة العربية ويكون سعر الوحدة فى كل صنف بحسب ما هو مدون بجدول الفئات عددا أو وزنا أو مقاسا أو غير ذلك دون تغيير أو تعديل فى الوحدة.
ويجوز فى حالة تقديم العطاء من فرد أو شركة فى الخارج أن تكتب الأسعار بالعملة الأجنبية ولغرض المقارنة تتم معادلتها بالجنيه المصري بالسعر المعلن بالبنك المركزي المصري فى تاريخ فتح المظاريف الفنية.
2- أن تكون قائمة الأسعار وجداول الفئات مؤرخة وموقعة من صاحب العطاء.
3- عدم الكشط أو المحو أو التحشير فى جدول الفئات، وكل تصحيح فى الأسعار أو غيرها يجب إعادة كتابته رقما وحروفا والتوقيع بجانبه.
4- إذا سكت صاحب العطاء فى عرضة المالى عن تحديد سعر صنف من الأصناف المطلوب توريدها بقائمة الأسعار المقدمة منه فيعتبر ذلك امتناعا منه عن الدخول فى هذا الصنف، أما فى مقاولات الأعمال فللجهة الإدارية مع الاحتفاظ بحقها فى استبعاد العطاء أن تضع للبند الذى سكت صاحب العطاء عن تحديد فئته أعلى فئة لهذا البند فى العطاءات المقبولة وذلك للمقارنة بينه وبين سائر العطاءات فإذا أرسيت عليه العملية فيعتبر أنه ارتضى المحاسبة على أساس أقل فئة لهذا البند فى العطاءات المقبولة دون أن يكون له حق المنازعة فى ذلك.
5- الفئات التى حددها صاحب العطاء بجدول الفئات تشمل وتغطى جميع المصروفات والالتزامات أيا كان نوعها التى يتكبدها بالنسبة إلى كل بند من البنود وكذلك تشمل القيام بإتمام توريد الأصناف وتنفيذ محل العقد وتسليمها للجهة العامة والمحافظة عليها أثناء مدة الضمان طبقا لشروط العقد وتتم المحاسبة النهائية بالتطبيق لهذه الفئات بصرف النظر عن تقلبات السوق والعملة والتعريفة الجمركية وغيرها من الضرائب والرسوم الأخرى.
وفي جميع الأحوال لن يلتفت إلى أى ادعاء من صاحب العطاء بحصول خطأ فى عطائه إذا قدم بعد فتح المظاريف الفنية.$m260$,'f3fae34aed53fc8cbdd61ffb78f3e36b',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(53,0,1,$m260$يكون توريد الأصناف الواردة من الخارج فى المواعيد والأماكن المبينة بقائمة الأسعار وفقا لشروط الطرح وعلى صاحب العطاء أن يراعى عند وضع أسعاره شروط التجارة الدولية (INCOTERMS) ومنها على سبيل المثال الآتى:
1- إذا كان تسليم الأصناف بميناء الشحن على ظهر المركب فوب (FOB) فيجب أن يشمل السعر المبين بالعطاء العبوات بكافة أنواعها وكذا مصروفات النقل إلى ظهر المركب.
2- إذا كان التسليم C&F أو CIF أو بميناء الوصول فيشمل السعر علاوة على المبين بالبند (1) نولون الشحن البحري أو الجوي ومصروفات التفريغ من المركب أو الطائرة كما يشمل قيمة التأمين فى حالة CIF أو ميناء الوصول.
وفى كلتا الحالتين إذا اشترط صاحب العطاء قيام الجهة الإدارية بدفع الثمن بموجب اعتماد مستندي يفتح بواسطتها لحسابه أو لحساب عملائه فى الخارج أو فى الداخل فإنه يتحمل مصاريف فتح الاعتماد المستندي وعليه أن يبين المبالغ المطلوب تحويلها إلى الخارج مع بيان نوع العملة والجهة التى سيتم الاستيراد منها.
ومع ذلك يجوز للسلطة المختصة بعد عرض لجنة البت الموافقة على تحمل الجهة العامة بمصروفات فتح الاعتماد المستندي إذا اشترط صاحب العطاء ذلك على أن يؤخذ هذا الشرط فى الاعتبار عند المقارنة والمفاضلة بين مختلف العروض من حيث الشروط المقدمة والأسعار.
وإذا كان التسليم بمخازن الجهة الإدارية فيجب أن يشمل السعر علاوة على المبين بالبند (2) رسوم الجمارك وجميع أنواع الرسوم الأخرى وضريبة القيمة المضافة وغيرها من الضرائب السارية وقت تقديم العطاء ومصروفات النقل الداخلي بحيث تسلم الأصناف لمخازن الجهة العامة خالصة من جميع الضرائب والرسوم والمصروفات.$m260$,'ed49e906a068cb93e754cfac3ab05bad',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(54,0,1,$m260$فى حالة وفاة صاحب العطاء إذا كان شخصا طبيعيا، أو مالك شركة الشخص الواحد، أو الشريك مع الغير بحصة حاكمة تسمح له بالتأثير فى اتخاذ قرار ذى صلة بالعطاء قبل البت، جاز للسلطة المختصة بعد عرض ادارة التعاقدات استبعاد العطاء المقدم منه ورد التأمين المؤقت، أو السماح للورثة بالاستمرار فى الإجراءات بشرط أن يعينوا عنهم وكيلا بتوكيل مصدقا على التوقيعات فيه، وتوافق عليه السلطة المختصة، ويظل هو دون غيره مسئولا أمام الجهة العامة عن تنفيذ الإجراءات.$m260$,'a0a625e9bde23e902a3e617db5f4e293',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(55,0,1,$m260$فى العمليات التى ترى الجهة الإدارية مناسبة إسناد المتعاقد لبعض بنودها من الباطن، فعلى إدارة التعاقدات من واقع دراستها للسوق ووفقا لطبيعة العملية تضمين كراسة الشروط والمواصفات البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن، على ألا تمثل تلك البنود الجانب الأكبر أو الجوهري من العملية، وبما يتفق مع المحددات والاشتراطات الواردة بكراسة الشروط والمواصفات ومنها الآتى:
1- بيانات وخبرات من سيعهد إليه من الباطن والمستندات الدالة على ذلك.
2- تحديد ما إذا كانوا من المشروعات المتوسطة أو الصغيرة أو المتناهية الصغر مع تقديم ما يثبت ذلك.
3- ألا يكون من المسجلين بسجل قيد أسماء الممنوعين من التعامل الذى تمسكه الهيئة العامة للخدمات الحكومية.
4- أن يكونوا من المؤهلين والمصرح لهم بمزاولة العمل محل التعاقد.
5- إقرار يفيد الالتزام بالتأمين على العمالة وفقا لقوانين التأمينات السائدة إذا تطلبت طبيعة العملية ذلك.
وغير ذلك من المحددات والاشتراطات التى تراها الجهة الإدارية لازمة.
ويجوز للمتعاقد أثناء فترة التعاقد أن يقوم بتغيير من أسند إليهم بعض بنود من الباطن إذا وجد مبررات لذلك، شريطة أن يكون بذات الكفاءة الفنية والخبرة وأن توافق عليه السلطة المختصة.
ولا يعفى المتعاقد من مسئوليته التعاقدية ويظل مسئولا وحدة عن أية أفعال أو أعمال أو أخطاء فى تنفيذ العقد، كما يلتزم باطلاع من أسند إليهم بعض بنود العملية من الباطن على ما يخصهم من شروط العقد.$m260$,'f4f698321123d38009db7d6db2bef268',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(56,0,1,$m260$عند تعاقد الجهة الإدارية مع أحد الموظفين أو العاملين بها على شراء كتب من تأليفهم أو تكليفهم بأعمال فنية أو شرائها منهم إذا كانت ذات صلة بالأعمال المصلحية يتعين مراعاة الحدود والقواعد الآتية:
1- إتاحة الفرصة لهم ولغيرهم لتقديم عروضهم.
2- عدم وجود من يمكنه أداء العمل المطلوب من بين الموظفين أو العاملين ويدخل فى نطاق أعماله الوظيفية.
3- ألا يدخل العمل المطلوب ضمن الاختصاص الوظيفى للموظف أو العامل ولا يعتبر امتدادا له.
4- الحصول على الموافقة اللازمة من السلطة المختصة فيما لا يجاوز عشرين ألف جنيه وبعد أخذ رأى الهيئة العامة للخدمات الحكومية فيما يزيد على ذلك، وبالنسبة للكتب الدراسية فيكون لوزير التربية والتعليم سلطة الموافقة على شرائها طبقا لأحكام هذه اللائحة ما لم يكن الموظف أو العامل قد باع حق الطبع والنشر إلى مكتبة أو فرد بعقد ثابت التاريخ قبل الشراء بستة أشهر على الأقل.
وبالنسبة لشراء حق المؤلف أو الطبع أو النشر فيشترط أن يكون المؤلف وثيق الصلة بأعمال الجهة الإدارية وأن تكون الحاجة ماسة إلى الحصول عليه وألا تقل النسخ اللازمة منه عن ثلاث ألاف نسخة – ما لم يكن المؤلف قد وضع خصيصا بناء على طلب الجهة الإدارية فيجوز عند الضرورة أن يقل العدد عن ذلك - كما يشترط قيام لجنة تشكل من أخصائيين فى المادة التى تناولها المؤلف بفحص الكتاب وتقدير قيمته العلمية واقتراح المبلغ الذى تقدره مقابل هذا الشراء على أن يراعى فى تقدير القيمة عدد النسخ المطلوبة ومدة الانتفاع بهذا الحق ويصدر بهذا الشراء قرار من السلطة المختصة فيما لا يجاوز عشرين ألف جنيه، وبعد أخذ رأى الهيئة العامة للخدمات الحكومية فيما يزيد على ذلك.
ويكون شراء حق المؤلف أو الترجمة أو الطبع أو النشر بالنسبة إلى الأزهر الشريف ووزارة التربية والتعليم وفقا للقواعد التى يصدر بها قرار من رئيس مجلس الوزراء.$m260$,'58ea71a409eb75f69947409fc3f890ed',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(57,0,1,$m260$بمراعاة المدد المنصوص عليها بالمادة (27) من القانون، تلتزم إدارة التعاقدات من خلال تنسيقها مع اللجان المعنية تضمين كراسة الشروط والمواصفات المدة المناسبة واللازمة لسريان العطاءات بحيث تكون كافية ومناسبة بحسب طبيعة وحجم العملية لتمكين اللجان الفنية والمالية من إتمام فحص ودراسة وتقييم ومقارنة العطاءات بالقدر الذى يمكنها من إتمام إجراءات الطرح والتعاقد وفقا للبرنامج الزمنى المحدد، وبما يتناسب مع التوقيتات اللازمة لتوفير محل العقد.$m260$,'df490255f72ae811ab688e82fe3994e8',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(58,0,1,$m260$يكون تشكيل اللجان وفقا لما نصت عليه المادة (28) من القانون على أن تكون برئاسة موظف تتناسب درجته الوظيفية وخبراته مع قيمة وأهمية وطبيعة العملية ويضم إليها عضو من إدارة التعاقدات، وعضو من الإدارة الطالبة أو المستفيدة، ويجوز للسلطة المختصة ضم عضو أو أكثر من الجهة الإدارية أو غيرها وبحد أقصى ثلاثة أعضاء حسب طبيعة وأهمية العملية، وفى جميع الحالات يجب ألا يجاوز عدد أعضاء اللجنة خمسة عشر عضوا وتكون للجان البت أمانة فنية من ضمن أعضائها.
ويتعين على إدارة التعاقدات اخطار من تم ترشيحه بموافقة السلطة المختصة كتابة للبدء في إعمال شئونه، على أن يتضمن الإخطار موضوع العملية، موعد ومكان انعقاد اللجان، والجدول الزمنى للانتهاء من أعمالها.$m260$,'6421f932c86d26ded7f9f2714cb03a8e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(59,0,1,$m260$بمراعاة النصاب المالى المنصوص عليه بالمادة (29) من القانون يتم الرجوع للهيئة العامة للخدمات الحكومية بالنسبة لطلبات ترشيح ممثلي وزارة المالية فى لجان فتح المظاريف والبت فى المناقصات ولجنة الممارسة بأنواعهما وكذا لجان البيع أو التأجير أو الترخيص بالانتفاع أو بالاستغلال والتى تنعقد بكافة الجهات الإدارية والمصالح الواقعة داخل نطاق محافظات القاهرة والجيزة والقليوبية.
وبالنسبة لدواوين الوزارات ووحدات الإدارة المحلية والجامعات الإقليمية والكليات التابعة لها وفروع الهيئات العامة بالمحافظات وغيرها من الجهات الإدارية الواقعة فى نطاق كل محافظة بخلاف محافظات القاهرة والجيزة والقليوبية فيتم الترشيح فيها بمعرفة السادة المراقبين الماليين للوزارات والمديرين الماليين للمحافظات بحسب الأحوال.
ويتعين الأخذ فى الاعتبار تناسب المستوى الوظيفى والخبرة لممثلي وزارة المالية مع أهمية وطبيعة كل عملية والتأكد من الفصل بين عضوية وزارة المالية فى اللجان ومراجعة إجراءاتها، وعليهم التحقق من سلامة إجراءات التعاقد التى تقوم بها الجهات الادارية وفقا لأحكام القانون وهذه اللائحة.
ويجب على إدارة التعاقدات إخطار ممثل وزارة المالية أو عضو إدارة الفتوى المختصة بمجلس الدولة بحسب الأحوال أو ممثل وزارة الاسكان بالمواعيد المحددة لعمل تلك اللجان قبل الموعد المحدد لانعقادها بعشرة أيام على الأقل للبدء في إعمال شئونهم، على أن يرفق بالإخطار صورة من مستندات العملية وأن يتضمن تاريخ وساعة ومكان انعقاد اللجنة، وبالنسبة للمواعيد الخاصة باستكمال أعمال اللجنة فيراعى تحديدها كتابة بالتنسيق معهم قبل الموعد المحدد لانعقاد هذه اللجان بوقت كاف.
وفى حالة عدم صحة انعقاد اللجنة فى الموعد المحدد يتم استلام العطاءات والاحتفاظ بها مغلقة لدى مدير إدارة التعاقدات وإثبات ذلك فى محضر يوقع عليه من رئيس اللجنة وأعضاءها يرفع إلى السلطة المختصة لطلب تعديل موعد انعقاد اللجنة ليوم العمل التالى مباشرة مع إخطار أعضاء اللجنة وأصحاب العطاءات بالموعد الجديد بالإضافة للنشر على بوابة التعاقدات العامة.$m260$,'a8a45fb558ea277cc0e1c9393a623c1c',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(60,0,1,$m260$يكون فتح المظاريف الفنية فى الوقت والمكان المحددين بكراسة الشروط والمواصفات فى جلسة علنية عامة بحضور من يرغب من أصحاب العطاءات، ويجوز لهم تفويض من يرونه لحضور الجلسة بدلا منهم شريطة تقديم التفويض الدال على ذلك.
ويقوم مدير إدارة التعاقدات بتسليم رئيس لجنة فتح المظاريف ملف العملية والعطاءات المحفوظة لديه، ويلتزم أعضاء اللجنة بالاطلاع على محتويات ملف العملية قبل بدء الجلسة للتحقق من صحة وسلامة الإجراءات التى سبق اتخاذها من إدارة التعاقدات، وعلى اللجنة اتخاذ الإجراءات الآتية:
1- يقوم رئيس اللجنة بفتح المظاريف فى الوقت والمكان المحددين بكراسة الشروط والمواصفات، وإثبات الحالة التى وردت عليها العطاءات بعد التحقق من سلامتها.
2- التحقق من تقديم العطاء من صاحبه أو من يفوضه شريطة تقديم التفويض الدال على ذلك.
3- القيام بحصر العطاءات وإثبات عددها فى محضر فتح المظاريف.
4- التحقق من وجود مظروفين منفصلين مقدمين عن كل عطاء أحدهما للعرض الفنى والآخر للعرض المالى وإثبات ذلك فى محضر فتح المظاريف.
5- ترقيم العطاءات على هيئة كسر اعتيادي بسطه رقم العطاء ومقامه عدد العطاءات الواردة، وإثبات رقم كل عطاء على المظروف الفنى وعلى المظروف المالى الذى يتم التحفظ عليه مغلقا.
6- إعادة تسليم المظاريف المالية بعد التوقيع عليها دون فتحها إلى مدير إدارة التعاقدات لحفظها لديه.
7- فتح المظاريف الفنية بالتتابع وكل مظروف يفتح يثبت رئيس اللجنة رقم العطاء عليه وعلى كل ورقة بداخله.
8- ترقيم الأوراق بداخل كل مظروف وإثبات عدد تلك الأوراق.
9- قراءة اسم صاحب العطاء وقيمة التأمين المؤقت وطريقة أدائه وغيرها من محتويات المظروف الفنى على الحاضرين من أصحاب العطاءات أو من يفوضونهم.
10- التوقيع من رئيس اللجنة ومن أعضائها على المظروف الفنى وكل ورقة بداخله.
11- التأشير بدائرة حمراء حول كل كشط أو تصحيح فى البيانات الواردة بالمظروف الفنى ويجب إثبات كل كشط أو تصحيح وضع حوله دائرة حمراء تفصيلا والتوقيع من رئيس اللجنة وجميع أعضائها على هذه التأشيرات.
12- التوقيع من رئيس اللجنة ومن جميع أعضائها على محضر اللجنة بعد إثبات كافة الخطوات المتقدمة فى السجل المعد لذلك.
13- تسليم خطابات الضمان أو إشعارات سداد التأمين المؤقت أو الإقرارات البديلة عن التأمين المؤقت إلى العضو المالى باللجنة لإعمال شئونه.
14- إرفاق المظاريف الفنية وجميع الأوراق المقدمة بها بمحضر اللجنة وتسليمها لمدير إدارة التعاقدات وذلك لحفظها لديه.
15- مراجعة العينات السابق تقديمها من أصحاب العطاءات على الكشف الذى دونت به عند ورودها بعد التأكد من سلامة أختامها وأغلفتها ويوقعها رئيس اللجنة مع جميع أعضائها كما يوقعون على العينات التى ترد مع المظاريف الفنية بعد إثباتها فى كشف خاص وتسلم جميع العينات إلى مدير إدارة التعاقدات أسوة بأوراق العطاءات.
ويجب أن تتم لجنة فتح المظاريف الفنية عملها بأكمله فى الجلسة ذاتها، ولا يحق لها أن تستبعد أى عطاء أو أن تطلب من أصحاب العطاءات تصحيح الأخطاء أو تلافى الملاحظات الواردة فى عطاءاتهم، أو اتخاذ أى قرارات تتعلق بالعطاءات المقدمة وينحصر دورها في توثيق محتويات المظاريف وأية مخالفات فى الإجراءات السابقة على عملها.
وعلى إدارة التعاقدات نشر محضر فتح المظاريف الفنية على بوابة التعاقدات العامة فور الانتهاء من أعمال اللجنة وبعد التأكد من توقيع رئيس اللجنة وأعضاءها عليه.$m260$,'893e34e2ebbb3d4a4cf7454ae85fbce3',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(61,0,1,$m260$أى عطاء يرد بعد موعد فتح المظاريف الفنية المحدد بكراسة الشروط والمواصفات يجب تقديمه فور وروده إلى رئيس لجنة فتح المظاريف للتأشير عليه بساعة وتاريخ وروده دون فتحه ثم يدرج فى كشف العطاءات المتأخرة، ويتم ترقيمه على هيئة كسر اعتيادي بسطه رقم العطاء ومقامه عدد العطاءات المتأخرة.
وتستبعد لجنة البت العطاءات المتأخرة ويتم ردها إلى أصحابها بمعرفة إدارة التعاقدات خلال مدة لا تجاوز يومين من قرار اللجنة.$m260$,'4524883d5094a5d7dc5e6b60d9ba0b78',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(62,0,1,$m260$تتولى إدارة التعاقدات بالتنسيق مع إدارة المخازن فرز عينات كل صنف وقيده بالسجل الخاص بالعينات ويجب أن يبين بهذا السجل تاريخ العملية ونوعها وعلى مدير إدارة التعاقدات أن يرسل فورا أو فى خلال اليومين التاليين على الأكثر من تاريخ قيام لجنة البت بالفحص الشكلي ما يقتضى إرساله منها إلى الجهة الفنية المختصة؛ حتى يتسنى إجراء الفحص الفنى المطلوب على وجه السرعة ومراعاة مدة صلاحية العطاءات والوقت المطلوب لإتمام إجراءات البت والاخطار بالترسية، وعند ورود التقارير الخاصة بها تدون جميع البيانات بالسجل المذكور أمام كل عينة ليعرض على لجنة البت.
ويجب التحقق من مطابقة العينات المقدمة مع العطاءات للمواصفات ومدى ملاءمتها للغرض المطلوبة من أجله وذلك بالفحص النظري أو الفنى أو بالتحليل المعملي أو بالتجربة العملية، بحسب الأحوال، وذلك بمعرفة الجهة الإدارية أو بأى من الجهات الخاضعة لأحكام القانون - وعلى مدير إدارة التعاقدات أن يضع على العينات أرقاما سرية مع مراعاة تعليمات الجهة الفاحصة، ويرسل معها كشفا تفصيليا ببيان مفرداتها والغرض الذى من أجله يراد توريد الصنف ومقدار الكمية المطلوبة منه.
ويجب توضيح ما قد يوضع عليها من أرقام سرية وأختام وتوقيعات لتميزها ولضمان عدم استبدال غيرها بها مع ذكر التاريخ المحدد للبت فى العملية وذلك لكى تقوم الجهة الفاحصة بفحصها وموافاة إدارة التعاقدات بالنتيجة قبل التاريخ المذكور بوقت كاف يسمح بدراسة العطاءات على ضوء نتيجة فحص العينات ورفع التوصيات اللازمة للجنة البت فى العملية فى الميعاد المحدد، وعلى جهة الفحص الفنى أن تقوم بفحص العينات واختبارها بالتتابع، وأن تختمها وتضع عليها أرقاما سرية أخرى لتميزها، وترسل عنها تقريرا وافيا بالنتيجة من حيث مطابقتها للمواصفات من عدمه، ويبين به نسبة الجودة مئوية لكل عينة تم تحليلها وعلى مدير إدارة التعاقدات أن يتحقق من حفظ تقارير المعمل الفنى التى ترد تباعا بملفات العمليات بعد إثباتها فى السجل الخاص بذلك وقبل عرضها على لجنة البت وكذلك التأشير أمام كل تقرير برقم الملف المحفوظة فيه.$m260$,'1191c7eaeb426674966bf2371902935a',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(63,0,1,$m260$يقوم مدير إدارة التعاقدات بتسليم رئيس لجنة البت العطاءات المحفوظة لديه ومحضر فتح المظاريف الفنية، وعلى اللجنة اتخاذ الإجراءات الآتية:
1- الفحص الشكلي للعطاءات والتأكد من أنها قد استوفت الشكل القانوني وفقا لمتطلبات شروط الطرح.
2- استبعاد العطاءات المتأخرة، وغيرها من عطاءات غير صالحة للنظر فيها، ومنها العطاءات غير الموقعة من أصحابها، أو الغير مكتملة وفقا للشروط، أو العطاءات غير المستوفاة للتأمين المؤقت، أو العطاءات التى يتبين أن أصحابها من غير المسجلين على بوابة التعاقدات العامة، أو أنهم من المسجلين بسجل قيد أسماء الممنوعين من التعامل الذى تمسكه الهيئة العامة للخدمات الحكومية، أو العطاءات التى لم تضمن معاملات تغير الأسعار في مقاولات الأعمال طبقا لشروط الطرح، أو العطاءات المقدمة بالمخالفة للحظر المنصوص عليه بالمادة (33) من القانون.
وتعد لجنة البت محضرا بنتيجة الفحص الشكلي، متضمنا أسباب استبعاد العطاءات، يتم توقيعه من رئيس اللجنة وأعضاءها ويحفظ بملف العملية.
3- يكلف رئيس لجنة البت الأمانة الفنية للقيام بتفريغ العروض الفنية للعطاءات المستوفية للشكل القانوني، وذلك على الاستمارة المعدة لذلك من ثلاث صور على أن يتم حفظ العروض الفنية محل التفريغ فى آخر كل يوم لحين الانتهاء من تفريغها، وتدون جميع ملاحظات واشتراطات أصحاب العطاءات، وتعمل مطابقة للعروض على كشوف التفريغ من اثنين من أعضاء لجنة البت يحددهما رئيسها وتوقع بما يفيد هذه المطابقة، ويجب أن يتم ذلك فى أقل وقت ممكن؛ حتى يتسنى البت فى العملية قبل انقضاء مدة سريان العطاءات، وتقدم الأمانة الفنية كشوف تفريغ العروض الفنية إلى رئيس لجنة البت.$m260$,'d402a2606e59976597a0f139d7acbab9',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(64,0,1,$m260$على لجنة البت الاطلاع على كشوف تفريغ العروض الفنية للعطاءات المستوفية للشكل القانوني، وتتولى الإجراءات الآتية:
1- التأكد من توافر الكفاءة الفنية وفقا للمعايير المحددة بكراسة الشروط والمواصفات، من خلال الاطلاع على سابقة الأعمال، ومعدلات الأداء فيما تم توريده أو تنفيذه، وعدد العمليات المشترك فيها حاليا صاحب العطاء.
2- التحقق من توافر الملاءة المالية لصاحب العطاء وما إذا كان لديه المقدرة المالية من سيولة وغيرها من عدمه لتنفيذ العملية من خلال دراسة ميزانيته وقائمة المركز المالى، والتدفقات النقدية بحسب طبيعة محل التعاقد، وغيرها من أمور ذات صلة.
ويجب عند دراسة العروض الفنية مراعاة ما ورد بكراسة الشروط والمواصفات ومنها:
أ- مدى قدرة صاحب العطاء على الالتزام بالتوريد أو التنفيذ بالمواعيد المحددة بشروط الطرح.
ب- الالتزام بمدة سريان العطاءات المنصوص عليها بشروط الطرح.
ج- مدى تلبية العطاءات للمواصفات الفنية الجوهرية أو لمعايير الاداء المحددة بشروط الطرح.
د- الالتزام بالبنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن، وكذا المحددات والاشتراطات الأخرى ذات الصلة.
وفى جميع الحالات يتعين على اللجنة للوقوف على قدرة وكفاءة أصحاب العطاءات وبما لا يخل بمبدأ تكافؤ الفرص أن تستطلع رأى الجهات الإدارية السابق تعاملهم معها، وإجراء الزيارات الميدانية إذا تطلب الأمر ذلك.
إذا تبين للجنة البت أن صاحب العطاء قد استعمل بنفسه أو بواسطة غيره الغش أو التلاعب فى تعامله مع الجهة الإدارية للحصول على العقد وجب على اللجنة استبعاد عطائه، ويصبح التأمين المؤقت من حق الجهة الإدارية، ويتم شطب اسمه من سجل المتعاملين بعد أخذ رأى إدارة الفتوى المختصة بمجلس الدولة، وتخطر الهيئة العامة للخدمات الحكومية بذلك لنشر قرار الشطب بطريق النشرات المصلحية وعلى بوابة التعاقدات العامة.
ويجوز للجنة البت أن تشكل من بين أعضاءها أو غيرهم من أهل الخبرة لجنة فنية فرعية تعهد إليها باتخاذ الإجراءات السابقة، على أن ترفع تقريرا بنتائج دراستها للعروض الفنية إلى لجنة البت خلال المدد المحددة لها بالبرنامج الزمنى.$m260$,'ad130b38f951b6a53dea238d9ce0787c',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(65,0,1,$m260$يجوز لإدارة التعاقدات بناء على طلب لجنة البت استيفاء البيانات أو المستندات التى تساعد اللجنة على استيضاح ما غمض من أمور فنية من أصحاب العطاءات بما يعينها فى اعداد التقرير الفنى اللازم وذلك خلال مدة لا تجاوز ثلاثة أيام من تاريخ اخطارهم ودون أن يخل ذلك بمبدأ تكافؤ الفرص والمساواة بين جميع أصحاب العطاءات.
ولا يعتد بأي توضيح يقدم من صاحب العطاء اذا لم تطلبه اللجنة، ويجب ان يكون طلب استيفاء البيانات أو المستندات اللازمة لاستيضاح الامور الفنية والرد عليه كتابة، وان لا يؤدي أو يوحي أو يسمح ذلك بأي تغيير في العطاء المقدم أو طبيعته.
وفي حالة عدم استجابة صاحب العطاء لطلب استيفاء البيانات أو المستندات لاستيضاح الامور الفنية بعطائه خلال المدة المحددة من اللجنة والموضحة بطلبها اليه، يتم استبعاد عطائه باعتباره غير واضح أو غير قابل للمقارنة مع العطاءات الأخرى.$m260$,'f9ad2bf878faac4cab9c6deca708f4ae',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(66,0,1,$m260$تقوم لجنة البت بإعداد محضر يتضمن ما انتهت إليه توصياتها بناء على دراستها من قبول، أو استبعاد للعطاءات مع ذكر أسباب عدم القبول تفصيلا وترفع محضرها للسلطة المختصة للاعتماد.$m260$,'4fa1c11cc7b4333f6809b8311e02ee0f',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(67,0,1,$m260$على إدارة التعاقدات فور اعتماد السلطة المختصة لتوصيات لجنة البت اخطار أصحاب العطاءات بنتائج قرارات اللجان بالقبول أو أسباب الاستبعاد، أو الإلغاء بخطابات ترسل بخدمة البريد السريع عن طريق الهيئة القومية للبريد مع تعزيزه فى الوقت ذاته بالبريد الإلكترونى، أو الفاكس، بحسب الأحوال، وفقا لعناوينهم وبياناتهم الواردة بالعطاء ويكون لهم الحق فى التقدم بشكواهم كتابة خلال سبعة أيام تبدأ من اليوم التالى لإخطارهم بالقرار.
وفور ارسال الإخطارات يتم نشر النتيجة فى لوحة الإعلانات المخصصة لهذا الغرض ولمدة سبعة أيام، كما يتم النشر على بوابة التعاقدات العامة، وبعد انقضاء هذه المدة يتم اخطار أصحاب العطاءات المقبولة فنيا بموعد ومكان جلسة فتح المظاريف المالية ما لم يكن هناك شكاوى محل دراسة.$m260$,'710b0a3d717a056e56538d4d19e49582',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(68,0,1,$m260$تجتمع لجنة فتح المظاريف بتشكيلها السابق ذاته فى الموعد والمكان المحددين لفتح المظاريف المالية للعروض المقبولة فنيا فقط، وتتولى اللجنة مباشرة إجراءاتها فى جلسة علنية عامة بحضور من يرغب من أصحاب العطاءات المقبولة عروضهم الفنية، ويجوز لهم تفويض من يرونه لحضور الجلسة شريطة تقديم التفويض الدال على ذلك.
ويقوم مدير إدارة التعاقدات بتسليم رئيس اللجنة المظاريف المالية وعليه التحقق من سلامتها ووجود رقم العطاء وتوقيع أعضاء اللجنة السابق إثباته على كل مظروف بجلسة فتح المظاريف الفنية، وعلى اللجنة اتخاذ الإجراءات الآتية:
1- فتح المظاريف المالية بالتتابع وكل ظرف يفتح يثبت رئيس اللجنة عدد أوراقه التى بداخله.
2- التوقيع من رئيس اللجنة وأعضائها على كل ورقة بداخل المظروف المالى.
3- التأشير بدائرة حمراء حول كل كشط أو تصحيح أو تحشير فى الأرقام أو الإجماليات الواردة بالظرف والتوقيع بجانبه من رئيس اللجنة وأعضائها على هذه التأشيرات.
4- قراءة اسم صاحب العطاء ومحتويات المظروف المالى على الحاضرين من أصحاب العطاءات أو من يفوضونهم.
5- التوقيع من رئيس اللجنة وجميع أعضاءها على محضر اللجنة بعد اثبات كافة الخطوات السابقة.
6- إرفاق المظاريف المالية وجميع الأوراق المقدمة بها بمحضر اللجنة وتسليمها لمدير إدارة التعاقدات، وذلك لحفظها لديه.
ويجب أن تتم لجنة فتح المظاريف المالية عملها بأكمله فى الجلسة ذاتها، ولا يحق لها أن تستبعد أى عطاء، أو أن تطلب من أصحاب العطاءات تصحيح الأخطاء، أو تلافى الملاحظات الواردة فى عطاءاتهم أو اتخاذ أى قرارات تتعلق بالعطاءات المقدمة، وينحصر دورها فى تنفيذ الإجراءات المنصوص عليها بهذه المادة وتوثيق محتويات المظاريف.
وعلى إدارة التعاقدات نشر محضر فتح المظاريف المالية على بوابة التعاقدات العامة فور الانتهاء من أعمال اللجنة وبعد التأكد من توقيع رئيس اللجنة وأعضاءها عليه.$m260$,'884ecfdf9f0a173b6a99974032a68028',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(69,0,1,$m260$تجرى عملية تفريغ العروض المالية وفقا للبند (3) من المادة (63) من هذه اللائحة بالنسبة لتفريغ العروض الفنية.
ويكلف رئيس لجنة البت اثنين من أعضاء اللجنة لمراجعة العروض المالية بعد تفريغها مراجعة حسابية تفصيلية والتوقيع عليها بما يفيد هذه المراجعة، وتكون نتيجة هذه المراجعة هي الأساس الذى يعول عليه فى تحديد سعر العطاء، وإذا تبين من المراجعة وجود أخطاء حسابية فيجب تصحيحها وفقا لأى من الحالات الآتية:
1- اختلاف بين سعر الوحدة وإجمالي سعر الوحدات يعول على سعر الوحدة.
2- اختلاف بين السعر المبين بالتفقيط وبين السعر المبين بالأرقام يعول على السعر المبين بالتفقيط.
3- تقديم أكثر من نسخة للعطاء طبقا للكراسة وتبين وجود اختلاف فى السعر بين النسخ المقدمة يعول على ما جاء بالنسخة الأصلية.$m260$,'e461f933b43cea955e745bd8c8ae6c1d',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(70,0,1,$m260$بعد الانتهاء من تفريغ ومراجعة العروض المالية تقوم لجنة البت بإعمال شئونها، ويجوز لها أن تعهد إلى لجنة مالية فرعية متخصصة من بين أعضائها أو غيرهم بدراسة وتحليل وتقييم العروض ماليا، واعداد تقرير بنتيجة أعمالها يقدم إلى لجنة البت، وعليها القيام بإجراء المقارنة والمفاضلة بين العروض بعد توحيد أسس المقارنة من جميع النواحى الفنية والمالية مع مراعاة تكاليف دورة حياة المنتج وفقا لما هو وارد بكراسة الشروط والمواصفات، وكذا أى اشتراطات أخرى وردت بها وبحسب ظروف وطبيعة موضوع التعاقد مع الأخذ فى الاعتبار الآتى:
1- شروط السداد والاستلام، والضمان، والصيانة وقطع الغيار ومستلزمات التشغيل، وغيرها من العناصر التى تؤثر فى تحديد القيمة المالية المقارنة للعطاءات.
2- تقييم العناصر غير السعرية وتحويلها إلى قيمة مالية مثل تكاليف التشغيل، القدرات، الكفاءة، الأداء وفقا لما هو وارد بكراسة الشروط والمواصفات.
3- حساب نسبة الدفعة المقدمة وذلك بغرض المقارنة والمفاضلة بإضافة فائدة تعادل سعر الفائدة المعلن من البنك المركزى فى تاريخ جلسة فتح المظاريف الفنية إلى قيمة العطاءات المقترنة بالدفعة المقدمة إذا أقرت كراسة الشروط والمواصفات ذلك، وذلك عن المبالغ المطلوب دفعها مقدما وتحسب الفائدة عن المدة من تاريخ أداء هذه المبالغ حتى تاريخ استحقاقها الفعلي.
4- حساب نسبة الأفضلية الممنوحة للمنتج المستوفى لنسبة المكون الصناعى المصرى.
5- حساب نسبة الأفضلية الممنوحة للخدمات أو الأعمال الفنية التى تقوم بها جهات مصرية.
6- فى حالة تقديم العطاء بعملات أجنبية يتم معادلتها بالعملة المصرية بالسعر المعلن من البنك المركزى فى تاريخ فتح المظاريف الفنية.
7- إذا سكت صاحب العطاء فى عرضة المالى عن تحديد سعر صنف من الأصناف المطلوب توريدها بقائمة الأسعار المقدمة منه فيعتبر ذلك امتناعا منه عن الدخول فى هذا الصنف، أما فى مقاولات الأعمال فللجهة الإدارية مع الاحتفاظ بالحق فى استبعاد العطاء أن تضع للبند الذى سكت صاحب العطاء عن تحديد فئته أعلى فئة لهذا البند فى العطاءات المقبولة وذلك للمقارنة بينه وبين سائر العطاءات فإذا أرسيت عليه العملية فيعتبر أنه ارتضى المحاسبة على أساس أقل فئة لهذا البند فى العطاءات المقبولة دون أن يكون له حق المنازعة فى ذلك.
8- لا يعتد بالعطاء المبنى على خفض نسبة مئوية عن قيمة أقل عطاء مقدم فى العملية.
9- فى حالة تساوى الأسعار بين عطاءين أو أكثر من المقبولين ماليا فيحق للجنة البت ترجيح أحداهما وفقا لمبررات تبديها بمحضرها بناء على ما اشتمل عليه كل عطاء، ويجوز تجزئة المقادير المعلن عنها بين مقدميها إذا كان ذلك فى مصلحة العمل وتضمنت مستندات الطرح ما يفيد ذلك.
وغيرها من العناصر التى تؤثر فى تحديد القيمة المقارنة للعطاءات بحسب ظروف وطبيعة موضوع التعاقد وفقا لما هو وارد بكراسة الشروط والمواصفات.$m260$,'b78b7bf961bed67192d0f6b4a625a6b2',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(71,0,1,$m260$يجوز لإدارة التعاقدات بناء على طلب لجنة البت أن تستوفى البيانات، أو المستندات التى تساعد اللجنة على استيضاح ما غمض من أمور مالية من أصحاب العطاءات المقبولة عروضهم فنيا بما يعينها فى اعداد التقرير المالى اللازم، وذلك خلال مدة لا تجاوز ثلاثة أيام من تاريخ اخطارهم ودون أن يخل ذلك بمبدأ تكافؤ الفرص والمساواة بين جميع أصحاب العطاءات.
ولا يعتد بأي توضيح يقدم من صاحب العطاء اذا لم تطلبه اللجنة، ويجب ان يكون طلب استيفاء البيانات، أو المستندات اللازمة لاستيضاح الامور المالية والرد عليه كتابة، وان لا يؤدي، أو يوحي، أو يسمح ذلك بأي تغيير في الأرقام والمبالغ وشكل العطاء المقدم، أو طبيعته.
وفي حالة عدم استجابة صاحب العطاء لطلب استيفاء البيانات أو المستندات المطلوبة لاستيضاح الامور المالية بعطائه خلال المدة المحددة من اللجنة والموضحة بطلبها اليه، يتم استبعاد عطائه باعتباره غير واضح، أو غير قابل للمقارنة مع العطاءات الأخرى.$m260$,'4753157d2ee93dab6d3a085685313a4c',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(72,0,1,$m260$فى حالات التعاقد التى تتطلب الطبيعة الفنية فيها تقييم العروض بنظام النقاط يتم تضمين شروط الطرح أسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول ومنها على سبيل المثال وبحسب طبيعة العملية الآتى:
1- المواصفات الفنية أو معايير الأداء.
2- خدمة ما بعد البيع.
3- مدة الخبرة فى المجال المطلوب تنفيذه.
4- الكوادر الفنية والإدارية العاملة لدى صاحب العطاء بشكل دائم.
5- المشروعات التى تم تنفيذها بنجاح، وقيمة أعلى مشروع.
6- الملاءة المالية لصاحب العطاء من خلال ميزانية مدققة.
7- المعدات والآلات والأجهزة المتوفرة لدى صاحب العطاء، والضرورية لإنجاز العمل المطلوب.
8- أى بيانات أو معلومات ترى الجهة الإدارية أنها ضرورية وتكون محل تقييم.
وغيرها من أسس وعناصر تراها الجهة الإدارية وفقا لطبيعة كل عقد.
ويكون البت المالى وفقا لألية التقييم المحددة بشروط الطرح ومنها ترتيب أولوية العطاءات بقسمة القيمة المالية المقارنة لكل عطاء على مجموع النقاط الفنية الحاصل عليها، وذلك للحصول على تكلفة الدرجة الفنية لكل عطاء ويتم الترسية على العطاء الذى حصل على أقل قيمة مقارنة.$m260$,'d6218859ff54bbccf322de90bf3ce9e5',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(73,0,1,$m260$على مدير إدارة التعاقدات عند دراسة العروض المالية تسليم رئيس لجنة البت ظرف القيمة التقديرية المحفوظ لديه، ويلتزم أعضاء اللجنة بالاطلاع عليه قبل بدء أعمالها للتحقق من غلقة بطريقة محكمة، والتأكد من توقيع أعضاء لجنة وضع القيمة التقديرية واعتماد السلطة المختصة لها.
ويجب أن تقوم لجنة البت باستبعاد العطاءات غير المطابقة للشروط، وتتولى المقارنة بين قيمة العطاءات المقبولة بما يناظره بالقيمة التقديرية، مع مراعاة الإجراءات المنصوص عليها بالمواد (68)، (69)، (70)، (71)، و(72) من هذه اللائحة.$m260$,'b5a286a1bcbef920f1e5dc1e0abb7b13',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(74,0,1,$m260$إذا ما تبين للجنة البت عند دراسة العروض المالية أن العطاء الأقل سعرا منخفض انخفاضا غير عادي مقارنة بالعطاءات الأخرى والقيمة التقديرية فعليها أن توثق ذلك فى محضرها.
ولغرض ضمان تنفيذ محل العقد تطلب من إدارة التعاقدات مخاطبة صاحب العطاء المنخفض كتابة لموافاتها بتفاصيل ومعلومات عطائه والأسس التى استند عليها فى وضع أسعاره وغيرها من العناصر التى أثرت فى إعداد عطائه.
وعلى صاحب العطاء خلال مدة لا تجاوز ثلاثة أيام من تاريخ إخطاره موافاة إدارة التعاقدات بكافة التفاصيل والمعلومات التى استند عليها فى التسعير كتابة، وعلى اللجنة دراسة ما ورد منه، فإذا ما تبين لها أن الأسس التى استند عليها مقبولة يمكنها قبول العطاء، وإذا ما تبين لها أن الأسس التى استند عليها غير واقعية ويتعذر التوريد أو التنفيذ بها، وجب عليها التوصية باستبعاد عطائه والترسية على العطاء التالى فى الترتيب بشرط أن يكون مناسبا للقيمة التقديرية.$m260$,'9fd2c164ed060080b133fb12b3465945',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(75,0,1,$m260$بمراعاة الحالة المبينة بالبند (3) من المادة (37) من القانون على لجنة البت قبل التوصية باتخاذ قرار الإلغاء دراسة الآثار المترتبة عليه أخذا فى الاعتبار الآتى:
1- جدوى إعادة الطرح.
2- احتمالات الوصول إلى سعر أقل من عدمه.
3- ما يمكن أن تتكبده الجهة الإدارية من نفقات لإعادة الطرح.
وغير ذلك من اعتبارات تؤثر فى قرار الإلغاء.
وعلى اللجنة أن تضمن محضرها ما اتخذته من اجراءات وتوصيات إما باستكمال إجراءات إلغاء العملية أو ارسائها.$m260$,'b07cd3d5d248e942b1112c8c0046ca4c',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(76,0,1,$m260$على إدارة التعاقدات فور اعتماد السلطة المختصة لمحضر لجنة البت اتباع الإجراءات ذاتها المنصوص عليها بالمادة (67) من هذه اللائحة.$m260$,'2f6b6c40e35139540d717a4a27893328',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(77,0,1,$m260$بمراعاة إجراءات البت المالى، وبعد التأكد من عدم وجود أية شكاوى لم يفصل فيها، سواء عن طريق الجهة الإدارية أو مكتب شكاوى التعاقدات العمومية، ترفع لجنة البت محضرا بتوصياتها النهائية للسلطة المختصة بإرساء العملية على صاحب العطاء الفائز للاعتماد أو تقرير ما تراه.$m260$,'6120a134d45e91ef328b6281a5f7c522',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(78,0,1,$m260$تتولى إدارة التعاقدات بعد انقضاء السبعة أيام المنصوص عليها بالمادة (39) من القانون وخلال مدة لا تجاوز يومين إخطار صاحب العطاء الفائز بترسية العملية عليه، وكذا إخطار باقى أصحاب العطاءات بذلك على أن يتضمن الإخطار البيانات الآتية:
1- طريق التعاقد ورقم واسم العملية.
2- تاريخ فتح المظاريف الفنية.
3- اسم صاحب العطاء الفائز وعنوانه.
4- قيمة الترسية.
5- التأمين النهائى المطلوب سداده.
وعلى صاحب العطاء الفائز سداد قيمة التأمين النهائى خلال المدة المحددة لذلك، وفور سداده يتم اخطاره بأمر التوريد، أو أمر الإسناد، بحسب الأحوال، والموعد المحدد للتوقيع على العقد.$m260$,'a3061ead958f44cec7acbe38fe3f29cb',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(79,0,1,$m260$فى عقود شراء أو استئجار المنقولات، أو العقارات، أو التعاقد على مقاولات الأعمال، أو تلقى الخدمات، أو الأعمال الفنية، أو الدراسات الاستشارية وحال عدم التزام صاحب العطاء الفائز بأداء التأمين النهائى خلال المدة المحددة لسداده على إدارة التعاقدات إعداد مذكرة للعرض على السلطة المختصة باقتراح منح صاحب العطاء الفائز مهلة إضافية بما لا يجاوز عشرة أيام عمل.
وإذا لم يقم صاحب العطاء الفائز بسداد التأمين النهائى يتم اتخاذ أحد الإجراءين التاليين وبما يحقق مصلحة الجهة الإدارية وهما:
1- الغاء العقد.
2- التنفيذ بواسطة أحد العطاءات التالية له فى الترتيب بشرط أن يكون فى حدود القيمة التقديرية.
وفى جميع حالات عدم سداد التأمين النهائى يكون التأمين المؤقت من حق الجهة الإدارية، كما يكون لها أن تخصم قيمة أية خسائر فعليه تلحق بها تسبب فيها صاحب العطاء الفائز وفى حالة عدم كفايتها لديها؛ يتم خصمها لدى أية جهة إدارية أخرى مع عدم الإخلال بحقها فى الرجوع عليه قضائيا بما لم تتمكن من استيفائه من حقوق بالطريق الإدارى.$m260$,'99fc60daea7f43b7411510d03ecc677e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(80,0,1,$m260$يكون التأمين النهائى ضامنا لتنفيذ العقد، ويتم الاحتفاظ به إلى أن يتم تنفيذ العقد بصفة نهائية بما فى ذلك مدة الضمان طبقا للشروط، ويتم سداده بأية وسيلة يصدر بشأنها قرار من وزير المالية ومنها وسائل الدفع الإلكترونى من خلال منظومة الدفع والتحصيل الإلكترونى أو بأية صورة من الصورتين الآتيتين:
1- بموجب خطاب ضمان صادر من أحد المصارف المحلية المعتمدة وألا يقترن بأى قيد، أو شرط وأن يقر فيه المصرف بأن يدفع تحت أمر الجهة الإدارية مبلغا يوازى التأمين المطلوب.
وعندما يرد لإحدى الجهات الإدارية خطابات ضمان عن التأمين المستحق من أحد المصارف المرخص لها فى إصدار خطابات الضمان أو أحد فروعها عليها أن تتحقق من أن المصرف أو الفرع قد أعطى إقرارا على خطابات الضمان بأنه لم يجاوز الحد الأقصى المحدد لمجموع خطابات الضمان المرخص للمصرف فى إصدارها.
فإذا تبين عند مراجعة الإخطارات لدى البنك المركزى أن المصرف قد تعدى الحد الأقصى المحدد له أخطرت الجهة الإدارية فورا لمطالبة المصرف بأن يؤدى إليها فى ميعاد لا يجاوز ثلاثة أيام عمل قيمة خطاب الضمان.
وتقبل خطابات الضمان من البنوك الخارجية بشرط التأشير عليها بالقبول من أحد المصارف المحلية المعتمدة على أن يتعهد المصرف المحلى بأن يدفع للجهة الإدارية مبلغ يوازى التأمين المطلوب وأنه ملتزم بأدائه بأكمله دون الالتفات إلى أى معارضة من صاحب العطاء.
2- يجوز لصاحب العطاء الفائز سداد التأمين النهائى خصما من مستحقاته الصالحة للصرف من عمليات أخرى فى ذات الجهة الإدارية وفى الوقت المحدد للسداد.
ويكون التأمين النهائى ساريا لمدة تبدأ من وقت إصداره إلى ما بعد انتهاء مدة العقد بثلاثة أشهر إلا إذا اتفق على غير ذلك.
كما يجوز بموافقة السلطة المختصة وبناء على طلب صاحب العطاء استبدال التأمين النهائى المسدد منه بأحد صور السداد الأخرى المنصوص عليها بهذه المادة بشرط ألا تنقطع مدة سريان التأمين وعدم الإخلال بمسئوليته طبقا للغرض المقدم عنه التأمين.
ويتم رد التأمين النهائى فى الحالات المنصوص عليها بالقانون وهذه اللائحة بالوسيلة ذاتها التى تم أداؤه بها.
ويجب أن تتضمن مستندات الطرح صور سداد ورد التأمين النهائى على وجه التحديد.$m260$,'32689c9724ff8cbe84dd3b401fcaed8f',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(81,0,1,$m260$على الجهات الإدارية تضمين شروط الطرح الحظر المنصوص عليه بالمادة (33) من القانون، وفى حالة مخالفته يجب على الجهة الإدارية استبعاد العطاءات المخالفة وأيلولة التأمين المؤقت لصالح الجهة الإدارية، أو فسخ العقد، أو تنفيذه على حساب المتعاقد وأيلولة التأمين النهائى للجهة الإدارية وتحميل المتعاقد بأى خسائر تلحق بها، وإخطار جهاز حماية المنافسة ومنع الممارسات الاحتكارية بأية مخالفة لهذا الحظر، أو أى من المخالفات ذات الصلة المنصوص عليها بأحكام قانون حماية المنافسة ومنع الممارسات الاحتكارية الصادر بالقانون رقم 3 لسنة 2005 ولائحته التنفيذية على أن يتضمن الإخطار بيان المخالفة التى تبينت للجهة الإدارية وما يدعمها من أدلة إن وجدت وكامل مستندات العملية وخاصة الآتى:
1- صورة من كراسة الشروط والمواصفات.
2- صورة الإعلان أو الدعوة بحسب الأحوال.
3- صورة قرار السلطة المختصة بتشكيل لجان العملية.
4- قائمة بأسماء من حصل على كراسة الشروط.
5- قائمة بمقدمي العطاءات موضحا بها المنسحبين أو المستبعدين.
6- صورة من العطاءات المقدمة.
7- صورة من محاضر اللجان.
8- قائمة بأسماء العاملين بإدارة التعاقدات.
9- الإفادة بكون العطاء متكرر من عدمه، وفى حالة كون العطاء متكرر يجب توفير صورة من العطاءات السابقة المتقدمة فى العمليات وتاريخ تقدم هذه العطاءات وأرقامها.$m260$,'3a478a1cbc6dc3586a6b62b585bcc7e9',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(82,0,1,$m260$لا يعتد بأى عطاء أو تعديل فيه يرد بعد الموعد المحدد لجلسة فتح المظاريف الفنية، ويحظر التعديل فى أسعار العطاءات المقدمة بعد هذا الموعد، ويسرى هذا الحظر على صاحب العطاء الفائز.$m260$,'f4f96f1eb9931d61f70d1cf4089480c3',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(83,0,1,$m260$إذا اختلف أعضاء لجنة البت فى الرأي حول قبول أو رفض أى من العطاءات فيتم إثبات ذلك تفصيلا فى محضر اللجنة ويكون الفصل فيه للسلطة المختصة.$m260$,'b7a0c8ac4c9d4d749a4f7c1e77cab0e6',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(84,0,1,$m260$يجب على مدير إدارة التعاقدات عقد اجتماع لمن يطلب من أصحاب العطاءات غير المقبولة بعد انتهاء أعمال لجنة البت لإيضاح أسباب عدم قبولهم، وذلك بغرض تلافى كل منهم الأسباب التى أدت إلى ذلك ولتحسين أدائهم فى العمليات اللاحقة.$m260$,'a14869fcc5afdfc1b72fad03eeb5d27d',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(85,0,1,$m260$يجوز أن تصدر السلطة المختصة قرارا بتكليف من تراه مناسبا من ذوى الخبرة بالجهة الإدارية لإدارة العقد فى العمليات التى تم التعاقد عليها، وله الاستعانة بمن يرى من ذوي الخبرات والتخصصات المختلفة لمعاونته في مهامه ويتعين على إدارة التعاقدات اخطار المتعاقد كتابة بهذا القرار.
وبمراعاة المادة (43) من القانون يتولى مسئول إدارة العقد المهام الآتية:
1- مراجعة شروط العقد والبرنامج الزمنى للتوريد، أو التنفيذ والتأكد من تنفيذه وفقا للشروط والمواصفات الفنية والمتطلبات الأخرى وفى المواعيد المحددة به.
2- التأكد من قيام المتعاقد بالوفاء بالتزاماته التعاقدية وحل أى خلافات تطرأ أولا بأول.
3- حل المشاكل الفنية والمالية والقانونية ذات الصلة بالعقد ودون تأخير.
4- الحفاظ على علاقات عمل جيدة بين طرفى العقد.
5- التأكد من أن إجراءات استلام المستحقات المالية تتم دون تأخير وفى حالة التأخير يقوم برفع مذكرة للسلطة المختصة مبينا فيها مبررات التأخير ومقترح إزالة أسبابه.
6- دراسة كل المراسلات أثناء تنفيذ العقد والرد عليها وفقا لصلاحيته الممنوحة له من السلطة المختصة وفى كل الأحوال يجب ألا تتعارض الردود مع أحكام القانون وهذه اللائحة.
7- المحافظة على الوثائق الخاصة بتنفيذ العقد.
8- توثيق كافة المراسلات بين طرفى العقد.
9- القيام بكافة الإجراءات وفقا للقانون وهذه اللائحة.
وأية مهام أخري ذات صلة يكلف بها من السلطة المختصة.$m260$,'8e33263ea6327a7ce5a5bb808081836e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(86,0,1,$m260$على إدارة التعاقدات قبل إبرام العقد أو الاتفاق، بحسب الأحوال، التأكد من عدم وجود أية شكاوى لم يفصل فيها، سواء عن طريق الجهة الإدارية أو مكتب شكاوى التعاقدات العمومية.
وتلتزم السلطة المختصة خلال مدة لا تجاوز خمسة عشر يوما من تاريخ سداد التأمين النهائى بتوقيع العقد، أو الاتفاق مع المتعاقد.
وتحرر العقود متى بلغت قيمة التعاقد مائة ألف جنيه فأكثر أما فيما يقل عن ذلك فيجب ابرام اتفاق بين المتعاقد والجهة الإدارية متضمنا كافة الضمانات اللازمة للتنفيذ، وذلك كله وفقا للنماذج الصادرة عن الهيئة العامة للخدمات الحكومية، ويحرر العقد أو الاتفاق من أصل وأربع نسخ على الأقل يسلم الأصل للإدارة المالية مرفقا به كافة المستندات، ونسخة لإدارة التعاقدات لحفظها بملف العملية، ونسخة للمتعاقد، ونسخة للإدارة الطالبة أو المستفيدة، ونسخة للإدارة المشرفة على التنفيذ بحسب الأحوال.
ويجب على إدارة التعاقدات إبلاغ مصلحة الضرائب المصرية بقيمة العقد، أو الاتفاق ومدة تنفيذهما، على أن يتضمن الإخطار الآتى:
1- اسم المتعاقد ثلاثيا وصفته وعنوانه بالكامل.
2- الرقم القومى.
3- رقم السجل التجاري أو الصناعى، أو سجل المستوردين، أو بيانات القيد فى الاتحاد المصرى لمقاولى التشييد والبناء.
4- رقم التسجيل بمصلحة الضرائب المصرية.
5- قيمة العقد ونوعه.
كما يجب إبلاغ المصلحة بأى تعديلات تطرأ على قيمة، أو مدة تنفيذ العقد، أو الاتفاق وجميع المبالغ التى تصرف للمتعاقد بمجرد صرفها كما يجب على إدارة التعاقدات إبلاغ مصلحة الجمارك بالبيانات المشار إليها بالنسبة للعقود أو الاتفاقات التى يدخل فى مشمولها أصناف أو مهمات مستوردة.$m260$,'da2603bf7f1ff4dafec5a38635be4a43',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(87,0,1,$m260$يجب على المسئولين الماليين وممثلي وزارة المالية بالوحدات الحسابية فى الجهات الإدارية المختلفة قبل صرف مستحقات المتعاقدين مع تلك الجهات التحقق من تحصيل، أو سداد جميع مستحقات الخزانة العامة من ضرائب ودمغات ورسوم جمركية وتأمينات اجتماعية ومقابل التأخير وغيرها من المستحقات الواجب سدادها وفقا للقوانين والقرارات المنظمة لذلك.$m260$,'10416cdb13b98ea3535de8881a106a53',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(88,0,1,$m260$مع مراعاة أحكام المادة (95) من هذه اللائحة، يعتبر سعر العقد ثابتا طوال مدة تنفيذه.$m260$,'c107bcb84a9883559747b433d4ffa4d2',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(89,0,1,$m260$فى حال حدوث تغيير فى التعريفة الجمركية، أو الرسوم، أو الضرائب الأخرى التى تحصل عن الأصناف الموردة وفقا للعقد فى المدة الواقعة بين تقديم العطاء وآخر موعد للتوريد، وكان التوريد قد تم فى غضون المدة المحددة له فيسوى الفرق تبعا لذلك بشرط أن يثبت المورد أنه أدى الرسوم والضرائب على الأصناف الموردة على أساس الفئات المعدلة بالزيادة، أما فى حالة ما إذا كان التعديل بالنقص فتخصم قيمة الفرق من العقد إلا إذا أثبت المورد أنه أدى الرسوم على أساس الفئات الأصلية قبل التعديل.
وفى حالة التأخير فى التوريد عن المواعيد المحددة فى العقد، وكان تعديل فئات الضرائب والرسوم قد تم بعد هذه المواعيد فإن المورد يتحمل عن الكميات المتأخرة كل زيادة فى الرسوم والضرائب المشار إليها إلا إذا أثبت أن التأخير يرجع إلى القوة القاهرة أما النقص فيها فتخصم قيمته من قيمة العقد.$m260$,'826fec720a45053fe8c222c851249a18',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(90,0,1,$m260$يجوز بموافقة السلطة المختصة صرف دفعة مقدمة فى العقود التى تتطلب طبيعتها ذلك وفقا لشروط الطرح، وعلى النحو الآتى:
1- بما لا يجاوز (25%) من قيمة التعاقد فى التعاقدات التى ترى الجهة الإدارية ضرورة لذلك.
2- بما لا يجاوز (50%) من قيمة التعاقد فى التعاقدات التى تتم مع المشروعات المتوسطة والصغيرة ومتناهية الصغر.
على أن تكون الدفعة المقدمة مقابل خطاب ضمان بنكى معتمد بالقيمة والعملة ذاتهما وغير مقترن بأى قيد أو شرط ويكون ساري المفعول حتى تاريخ الاستحقاق الفعلي لتلك المبالغ.
3- بما لا يجاوز (25%) من قيمة التعاقد فى التعاقدات التى تتم وفقا للمادة (74) من القانون.
4- بما لا يجاوز (25%) من قيمة التعاقد فى التعاقدات التى تتم وفقا للمادة (78) من القانون.
ويجوز تجاوز النسب الواردة بهذه المادة فى الحالات التى ترى الجهة الإدارية ضرورة لذلك شريطة الحصول على موافقة وزير المالية قبل الطرح.
ويجب على الجهة الإدارية تضمين نسبة الدفعة المقدمة بكراسة الشروط والمواصفات وطلب تحديد أوجه صرفها وفى حالة عدم تضمينها فيعد ذلك بمثابة عزوف منها عن مبدأ إقرارها ويتعين على أصحاب العطاءات عدم تجاوز تلك النسبة، ويستبعد كل عطاء يخالف ذلك، وفى حالة إذا ما تبين للجهة الإدارية أثناء التنفيذ عدم الالتزام بأوجه الصرف المحددة للدفعة المقدمة يتم تسييل خطاب الضمان مقابل الدفعة المقدمة، ويراعى فى مقاولات الأعمال عدم صرف فروق الأسعار لما يتم شراؤه من قيمة الدفعة المقدمة فى العقود التى تتطلب ذلك.
وفى الحالات التى تكون فيها بداية العقد معلقة على تحقق أكثر من واقعة من بينها صرف الدفعة المقدمة فيراعى ألا يتم صرفها إلا بعد تحقق جميع الوقائع الأخرى، ويجب فى جميع الحالات أن تكون الدفعة المقدمة فى حدود الاعتمادات المدرجة بموازنة الجهة الإدارية عن السنة المالية التى يتم فيها التعاقد، وعليها التأكد من ذلك مسبقا وقبل الطرح.$m260$,'6d30f05e8649cd8c438a5518dcd74f0e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(91,0,1,$m260$تلتزم إدارة التعاقدات بمتابعة تنفيذ العقود للتأكد من توريد أو تنفيذ محل التعاقد والتحقق من إجراءات الفحص والاستلام وتسجيل الفواتير والمستندات ومتابعة إرسالها إلى الإدارة المالية لاتخاذ إجراءات الصرف.
ويصرف ثمن الأصناف الموردة، أو الخدمات المؤداة فى أقرب وقت ممكن، وبما لا يجاوز ثلاثين يوما تحسب من تاريخ الفحص والقبول والاعتماد، وفى الحالات التى يتضمن فيها التعاقد أن يتم سداد الثمن مقابل استلام الأصناف، فيجب على الجهة الإدارية اتخاذ ما يلزم نحو إجراء فحص الأصناف والتحقق من مطابقتها للمواصفات المتعاقد على أساسها وذلك قبل الاستلام وسداد الثمن.
وفى مقاولات الأعمال تصرف للمقاول دفعات تحت الحساب تبعا لتقدم العمل وذلك خلال ستين يوما من تاريخ تقديمه المستخلص لها تلتزم خلالها بمراجعة المستندات على النحو الوارد بشروط التعاقد وفى حالة قبولها الوفاء بقيمة ما يتم اعتماده، ويكون صرف الدفعات تحت الحساب على النحو الآتى:
1- بواقع نسبة (95%) من القيمة المقررة للأعمال التى تم تنفيذها فعلا مطابقة للشروط والمواصفات وذلك من واقع الفئات الواردة بالجدول المقدم من صاحب العطاء، ويجوز صرف نسبة ال(5%) الباقية والمحتجزة لمواجهة أية عيوب أو ملاحظات فى الأعمال يقصر المقاول فى اصلاحها، أو تلافيها لحين الاستلام المؤقت وذلك نظير خطاب ضمان معتمد من أحد البنوك المحلية ينتهى سريانه بعد مضى ثلاثين يوما من تاريخ حصول الاستلام المؤقت.
2- بواقع نسبة (75%) من القيمة المقررة للمواد التى وردها المقاول لاستعمالها فى العمل الدائم والتى يحتاجها العمل فعلا وفقا للبرنامج الزمنى المتفق عليه بالعقد بشرط أن تكون مطابقة للشروط وموافقا عليها، وأن تكون مشونة بموقع العمل فى حالة جيدة بعد إجراء الجرد الفعلي اللازم، وذلك من واقع فئات العقد، وتعامل كالمشونات المواد التى تورد لموقع العمل صالحة للتركيب إلى أن يتم تركيبها.
3- بعد استلام الأعمال مؤقتا تقوم اللجنة المختصة بالإشراف بتحرير الكشوف الختامية بقيمة جميع الأعمال التى تمت فعلا ويصرف للمقاول عقب ذلك مباشرة ما تستحقه بعد خصم المبالغ التى سبق صرفها على الحساب أو أى مبالغ أخرى مستحقة عليه.
وعند استلام الأعمال نهائيا بعد مدة الضمان وتقديم المقاول المستندات الدالة على ذلك يسوى الحساب النهائى ويدفع للمقاول باقى حسابه بما فى ذلك التأمين النهائى أو ما تبقى منه.
أما بالنسبة لباقى العقود يكون الصرف وفقا لما اشتملت عليه شروط التعاقد.
وفى جميع الأحوال، إذا لم يتم الوفاء بالمبالغ المستحقة للمتعاقد فى المواعيد المحددة بالعقد تلتزم الجهة الإدارية بأن تؤدى للمتعاقد ما يعادل تكلفة التمويل لقيمة المطالبة، أو المستخلص المعتمد عن فترة التأخير وفقا لسعر الائتمان والخصم المعلن من البنك المركزى وقت المحاسبة شريطة تقديم مستندات رسمية بالمبلغ المطالب به، ويحال المتسبب للتحقيق مع تحميله بقيمة ذلك.$m260$,'d24396f531b58c6630f5f8bab46e084f',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(92,0,1,$m260$فى عقود بيع المنقولات يجب على من يرسو عليه المزاد أن يسدد (30%) من ثمن البيع بمجرد رسو المزاد، وفى حالة عدم السداد يكون التأمين المؤقت من حق الجهة الإدارية، ويسدد باقى الثمن خلال خمسة عشر يوما من تاريخ اليوم التالى لرسو المزاد عليه، فيما عدا الحالات التى تتطلب بحسب طبيعتها أن يتم تسليم المبيع على دفعات فيتم سداد قيمة كل دفعة بالكامل قبل الموعد المحدد لاستلامها ولا تسوى نسبة ال(30%) المشار إليها بالبند السابق إلا عند استلام آخر دفعة من المبيع على أن ينص على ذلك فى شروط المزايدة.
وفى عقود بيع العقارات والمشروعات التى ليس لها الشخصية الاعتبارية يجب على من يرسو عليه المزاد سداد (10%) من القيمة الراسى بها عملية البيع فور الرسو عليه ويستكمل باقى الثمن خلال فترة لا تجاوز ثلاثة أشهر من تاريخ إخطاره باعتماد البيع.
ويجوز استثناء وبموافقة السلطة المختصة بالنسبة للعقارات والمشروعات الكبرى أن تتضمن شروط الطرح سداد باقى الثمن على دفعات يتم تحديدها وفى هذه الحالة يستحق عنها عائد يعادل سعر الفائدة المعلن من البنك المركزى وقت السداد وذلك عن المدة من تاريخ الاستحقاق وحتى تاريخ السداد مع مراعاة عدم اتخاذ إجراءات نقل الملكية إلا بعد سداد كافة مستحقات الجهة الإدارية.
فإذا تأخر من رسا عليه المزاد عن أداء باقى الثمن خلال المدة المحددة بهذه المادة يصبح العقد مفسوخا دون حاجة إلى اتخاذ أى إجراءات قضائية مع تحميله بمقابل تأخير يعادل الفائدة وفقا للقواعد المقررة فى القانون المدني فى تاريخ السداد، وفى حالة عدم السداد يتم اتخاذ الإجراءات المنصوص عنها بالمادة (51) من القانون، ودون الإخلال بحق الجهة الإدارية فى الرجوع على المشترى بالتعويض اللازم.$m260$,'4c298e9b713b470328df0080bbdc13f3',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(93,0,1,$m260$فى عقود تأجير المنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية، أو الترخيص بالانتفاع، أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف يجب على من يرسو عليه المزاد فى العقود التى لا تزيد مدتها عن ثلاث سنوات أن يقدم تأمينا نهائيا بما يعادل (10%) من القيمة الكلية الراسى بها المزاد عن مدة العقد بالكامل وذلك فور رسو المزاد، ويجب أن يظل التأمين ساريا طوال مدة العقد، فإذا زادت مدة العقد على ثلاث سنوات يحسب التأمين النهائى الواجب تقديمه بواقع (10%) من قيمة العقد عن الثلاث سنوات الأولى، ويجدد هذا التأمين قبل بداية الثلاث سنوات التالية أو الفترة المتبقية من العقد أيهما أقل، وذلك بمراعاة الزيادة السنوية فى قيمة التعاقد المنصوص عليها بالعقد.
ويراعى تضمين شروط الطرح طريقة سداد القيمة الإيجارية، أو مقابل الانتفاع، أو الاستغلال على أن يتم السداد خلال ثلاثة أيام عمل على الأكثر من بداية المدة المحددة لذلك، وفى حالة تجاوز هذه المهلة تستحق الجهة الإدارية تعويضا يعادل الفائدة وفقا للقواعد المقررة فى القانون المدني، وذلك عن الفترة من تاريخ الاستحقاق وحتى تاريخ السداد، وفى حالة عدم السداد يتم اتخاذ الإجراءات المنصوص عنها بالمادة (51) من القانون، ودون الإخلال بحق الجهة الإدارية فى الرجوع على المتعاقد بالتعويض اللازم.$m260$,'0cd35bd96d6b6678329a592ac9c6283e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(94,0,1,$m260$يجب على الجهة الإدارية تحديد احتياجاتها الفعلية والضرورية لسير العمل على أساس دراسة واقعية وموضوعية، ومع ذلك إذا استجد أثناء التنفيذ ما يوجب تعديل العقد فيتم التعديل بما لا يجاوز (25%) من كمية كل بند لعقود المقاولات، وبما لا يجاوز (15%) من كمية كل بند لباقى العقود مع تضمين شروط الطرح مضمون ذلك مع تعديل المدة المناسبة أو البرنامج الزمنى، بحسب الأحوال، للتوريد، أو التنفيذ وبما يتناسب مع حجم التعديل على أن تراعى إدارة التعاقدات الآتى:
1- وجود ضرورة وأسباب داعمة لتلك التعديلات.
2- الحصول على موافقة السلطة المختصة، أو مجلس الوزراء، بحسب الأحوال، على التعديل.
3- أن تكون تلك التعديلات على بنود العقد الأصلى ذاته وبالشروط والمواصفات ذاتها والأسعار المتعاقد عليها.
4- إعداد ملحق للعقد متضمنا تلك التعديلات.
5- الحصول من الادارة المالية على سماح البند فى حالة التعديل بالزيادة.
6- أن يكون التعديل خلال مدة تنفيذ العقد، ولا يدخل فيها مدة الضمان.
7- على ألا يؤثر ذلك على أولوية المتعاقد فى ترتيب عطائه.
على أن تتولى إدارة التعاقدات توثيق تلك التعديلات والمستندات المؤيدة لها وحفظها بملف العملية، ويتم النشر عن القيمة النهائية للعقد بعد التعديل على بوابة التعاقدات العامة.$m260$,'0cda4dc0c17d5e099356374102470cb8',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(95,0,1,$m260$فى عقود مقاولات الأعمال التى تكون مدة تنفيذها ستة أشهر فأكثر، تلتزم إدارة التعاقدات فى نهاية كل ثلاثة أشهر تعاقدية بتعديل قيمة العقد وفقا للزيادة، أو الخفض فى تكاليف بنود العقد التى طرأت بعد التاريخ المحدد لفتح المظاريف الفنية، أو بعد تاريخ التعاقد المبنى على أمر الإسناد بالاتفاق المباشر، بحسب الأحوال، ويكون هذا التعديل ملزما للطرفين ويقع باطلا كل اتفاق يخالف ذلك.
ويكون حساب التغير فى الأسعار ومحاسبة المقاول على فروق الأسعار رفعا أو خفضا وفقا للتعريفات والمعادلة والقواعد الآتية:
أولا: التعريفات:
مدة التنفيذ: المدة المحددة لإنجاز الأعمال محسوبة من تاريخ تسليم الموقع خاليا من الموانع أو استلام المقاول الدفعة المقدمة، أو الرسومات المعتمدة اللازمة لبدء التنفيذ أيهما أبعد.
البنود المتغيرة: البنود أو مكوناتها الخاضعة للتعديل التى تحددها إدارة التعاقدات بمستندات الطرح (عمالة – مواد خام ......إلخ) من واقع القائمة التى تعدها وزارة الاسكان.
المعامل: النسبة التى يحددها المقاول بعطائه لكل بند أو مكوناته من البنود المتغيرة، بمراعاة ألا تساوى (صفرا) ويقل مجموعها عن 100% أو الواحد الصحيح بالنسبة لكل بند أو مشتملاته.
قيمة التعويض أو الخصم: المبلغ المستحق للمقاول، أو المبلغ الواجب خصمه من مستحقاته نتيجة احتساب التغير فى أسعار البنود المتغيرة ارتفاعا، أو انخفاضا.
نسبة الزيادة أو الخفض فى الأسعار: الرقم القياسي لسعر البند، أو مكوناته عند المحاسبة مطروحا منه الرقم القياسي للسعر عند تاريخ فتح المظاريف الفنية، أو الإسناد المباشر، بحسب الأحوال، مقسوما على الرقم القياسي للسعر عند فتح المظاريف الفنية، أو الإسناد المباشر، بحسب الأحوال، وذلك من واقع نشرة الأرقام القياسية للمنتجين الصادرة من الجهاز المركزى للتعبئة العامة والإحصاء.
ثانيا: المعادلة:
قيمة التعويض أو الخصم= قيمة الأعمال الخاضعة للتعديل من واقع عطاء المقاول عند التعاقد x معاملاتها × نسبة الزيادة أو الخفض فى الأسعار.
ثالثا: قواعد المحاسبة على فروق الأسعار:
1- تقوم إدارة التعاقدات بتحديد البنود المتغيرة، أو مكوناتها ضمن شروط الطرح من واقع القائمة التى تصدرها وزارة الاسكان، وفى حالة عدم تحديدها تلغى المناقصة أو الممارسة، أو أمر الإسناد المباشر قبل البت فيها.
2- يجب أن يتضمن عطاء المقاول فى المظروف الفنى معاملات تمثل أوزان عناصر التكلفة للبنود المتغيرة أو مكوناتها والتى حددتها إدارة التعاقدات ضمن شروط الطرح ويتم التعاقد على أساسها، وفى حالة عدم تضمين المقاول عطاءه تلك المعاملات يتم استبعاد العطاء.
3- تصرف قيمة المستخلص المعتمد فى المواعيد المحددة وفقا لأسعار العقد دون انتظار لتطبيق معادلة فروق الأسعار.
4- يحاسب المقاول على التعديل فى الأسعار رفعا، أو خفضا بالنسبة للبنود المتغيرة، أو مكوناتها كل ثلاثة أشهر تعاقدية من تاريخ فتح المظاريف الفنية، أو الإسناد المباشر، بحسب الأحوال، مع مراعاة البرنامج الزمنى للتنفيذ وتعديلاته الذى يتفق عليه الطرفان.
5- يحاسب المقاول على فروق الأسعار رفعا، أو خفضا خلال ستين يوما على الأكثر من تاريخ تقديم المطالبة، يتم خلالها مراجعة وصرف تلك الفروق، ويجب احتساب اولوية المتعاقد فى ترتيب عطائه وذلك بعد تطبيق المعادلة ذاتها على باقى العطاءات الأخرى.
6- لا تسرى معادلة تغير الأسعار وقواعد تطبيقها فى أى من الحالات الآتية:
أ- العقود التى تكون مدة تنفيذها أقل من ستة أشهر ويتأخر تنفيذها لسبب يرجع إلى المقاول.
ب- العقود التى تكون مدة تنفيذها أقل من ستة أشهر، ويتأخر تنفيذها لسبب يرجع إلى الجهة الإدارية، وفى هذه الحالة، تتم محاسبة المقاول على الكميات التى تم تنفيذها بعد الستة أشهر وفقا لمعدلات التضخم الصادرة من الجهاز المركزى للتعبئة العامة والإحصاء.$m260$,'31e54ff10e574fe7ca0b0c2b3865e880',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(96,0,1,$m260$يتعين على مسئول إدارة العقد، بقدر الإمكان، العمل على إزالة أية عقبات أو مشكلات قد تؤدى إلى التأخير فى تنفيذ العقد سواء كان بسبب راجع للجهة الإدارية أو المتعاقد، وفى حالة حدوث تأخير فى البرنامج الزمنى، أو فى تنفيذ العقد خارج عن إرادة المتعاقد فيجوز للسلطة المختصة لدواعى المصلحة العامة إعطائه مهلة لإتمام التنفيذ دون تحصيل مقابل تأخير منه، أما إذا كان التأخير راجع للمتعاقد فيحصل منه مقابل للتأخير يحسب من بداية المهلة وبما لا يجاوز النسب الواردة بالقانون وذلك على النحو الآتى:
1- فى مقاولات الأعمال:
أ- إذا لم تجاوز مدة التأخير نسبة (1%) من المدة الكلية للتنفيذ يحصل مقابل تأخير بنسبة (1%) من قيمة الأعمال أو الختامي، أو من قيمة الجزء المتأخر بحسب الأحوال.
ب- تزاد نسبة تحصيل مقابل التأخير من قيمة الأعمال أو الختامي، أو من قيمة الجزء المتأخر، بحسب الأحوال، بنسبة مدة التأخير ذاتها وإلى أن تصل إلى (10%) من المدة الكلية للتنفيذ.
ج- إذا جاوزت مدة التأخير نسبة (10%) من المدة الكلية للتنفيذ يحصل مقابل التأخير بنسبة (15%) من قيمة الأعمال أو الختامي، أو من قيمة الجزء المتأخر بحسب الأحوال.
2- فى باقى العقود:
أ- إذا لم تجاوز مدة التأخير نسبة (3%) من المدة الكلية لتنفيذ محل العقد يحصل مقابل تأخير بنسبة (1%) من قيمة العقد، أو من قيمة الجزء المتأخر بحسب الأحوال.
ب- إذا لم تجاوز مدة التأخير نسبة (6%) من المدة الكلية لتنفيذ محل العقد يحصل مقابل تأخير بنسبة (2%) من قيمة العقد، أو من قيمة الجزء المتأخر بحسب الأحوال.
ج- إذا لم تجاوز مدة التأخير نسبة (10%) من المدة الكلية لتنفيذ محل العقد يحصل مقابل تأخير بنسبة (3%) من قيمة العقد، أو من قيمة الجزء المتأخر بحسب الأحوال.
د- إذا جاوزت مدة التأخير نسبة (10%) من المدة الكلية لتنفيذ محل العقد يحصل مقابل التأخير بنسبة (5%) من قيمة العقد، أو من قيمة الجزء المتأخر بحسب الأحوال.$m260$,'3f3f676475bab1f2b8df6c0a1e6f3d18',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(97,0,1,$m260$يجب على الجهة الإدارية استلام محل التعاقد فى المواعيد المحددة بالعقد حال مطابقتها للمواصفات والشروط المتفق عليها بالعقد، وللمتعاقد حال تقاعس الجهة المتعاقدة عن الاستلام التقدم بطلب للسلطة المختصة لتشكيل لجنة محايدة لدراسة أسباب التقاعس، وصورة منه لمكتب شكاوى التعاقدات العمومية وذلك للمتابعة.
وتلتزم السلطة المختصة خلال سبعة أيام من تاريخ استلامها للطلب بتشكيل لجنة ثلاثية متخصصة من جهات محايدة منها الوزارات، أو الهيئات، أو النقابات المهنية وغيرها من جهات، ويكون اختيار أعضاء اللجنة بناء على ترشيح من جهة عملهم ويراعى ألا يكونوا قد سبق أن أبدوا رأيا فى العملية ولو فى هيئة تقرير استشاري، وألا يكون قد اتصل عملهم بالعملية خلال جميع مراحلها، وتكون الجهة المتعاقدة طرفا فى اللجنة، ويجب أن يتضمن قرار السلطة المختصة موعد انتهاء اللجنة من أعمالها.
تبدأ اللجنة أعمالها فور صدور قرار تشكيلها وسداد المتعاقد الأتعاب التى تحددها الجهات الخارجية المشاركة فيها وتخطره الجهة بها، وتقدم اللجنة تقريرها خلال مدة زمنية أقصاها ثلاثون يوما من تاريخ تشكيلها ما لم تتطلب طبيعة العملية وحجمها مدة تتجاوز ذلك، ولها فى سبيل أداء عملها طلب أى بيانات، أو معلومات، أو الاطلاع على مستندات واستيضاح ما تراه من طرفى التعاقد، كما يجوز لها أن تقوم بمعاينة محل العقد إذا تطلب الأمر ذلك، ويكون تقريرها ملزما للطرفين.
وتعرض اللجنة تقريرها بنتيجة عملها على السلطة المختصة لاعتماده وإصدار القرار فى ضوء ما انتهى إليه، وتتولى إدارة التعاقدات فور صدور القرار إخطار المتعاقد بكتاب يرسل بالبريد السريع عن طريق الهيئة القومية للبريد، ويعزز فى الوقت ذاته بالبريد الإلكترونى أو الفاكس، بحسب الأحوال، ومتابعة الإجراءات اللازمة لتنفيذ قرار السلطة المختصة وإنهاء إجراءات الاستلام فى مدة زمنية لا تجاوز مدة الفحص والاستلام المتفق عليها مسبقا بشروط الطرح والتعاقد، على أن يرد للمتعاقد أتعاب اللجنة حال تبين تقاعس الجهة الإدارية، مع إحالة المتسبب للتحقيق وتحميله بأتعاب اللجنة.
وإذا تبين للجنة عدم التزام المتعاقد، تتخذ الجهة الإدارية حياله الإجراءات ذات الصلة الواردة بالقانون وهذه اللائحة.$m260$,'e663e8c0ecf8c06a3cf5407ebfed9de2',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(98,0,1,$m260$يجب على المتعاقد مع الجهة الإدارية تجنب موجبات فسخ العقد، وبصفة خاصة الآتى:
1- تقديم أى بيانات أو مستندات غير صحيحة بالذات أو الواسطة وذلك بغرض الغش أو التلاعب.
2- المخالفة للحظر المنصوص عليه بالمادة (33) من القانون أو التورط فى أية ممارسات احتيال، أو فساد، أو احتكار ومن ذلك التواطؤ، أو منع أية منافسة لأحد أصحاب العطاءات الآخرين، أو الاتفاق معهم على أغراض غير مشروعة، وذلك بما يخل بعدالة المنافسة المشروعة والاخلال بمبادئ الشفافية والمنافسة وتكافؤ الفرص، وغير ذلك من ممارسات تخل بتطبيق أحكام القانون وهذه اللائحة.
تتولى إدارة التعاقدات فسخ التعاقد تلقائيا فى هاتين الحالتين واعداد مذكرة للسلطة المختصة لمخاطبة إدارة الفتوى المختصة بمجلس الدولة للوقوف على رأيها فى شطب أسم المتعاقد، على أن تتولى الإدارة فور ورود رأى مجلس الدولة إخطار الهيئة العامة للخدمات الحكومية بقرار الشطب لتتولى الهيئة إصدار كتاب دوري متضمنا الآتى:
أ- أسم الجهة مصدرة القرار وتاريخ صدوره.
ب- أسباب الشطب.
ج- بيانات كتاب إدارة الفتوى المختصة بمجلس الدولة من رقم وتاريخ ورقم الملف ورقم السجل.
د- أسم صاحب العطاء أو المتعاقد المشطوب وبياناته.
وغير ذلك من البيانات التى تراها الهيئة لازمة.
وتنشر الهيئة العامة للخدمات الحكومية الكتاب الدوري من خلال النشرات المصلحية وعلى بوابة التعاقدات العامة وقيده فى سجل الممنوعين من التعامل، وتلتزم جميع الجهات الإدارية بقيد الممنوعين من التعامل فى السجل الخاص بذلك ويحظر التعامل معهم.
ويتم بناء على طلب المتعاقد الذى شطب اسمه إعادة قيده إذا انتفى سبب الشطب بصدور قرار من النيابة العامة بألا وجه لإقامة الدعوى الجنائية ضده أو بحفظها إداريا، أو بصدور حكم نهائى ببراءته مما نسب إليه، على أن يعرض قرار إعادة القيد على الهيئة العامة للخدمات الحكومية لنشره بطريق النشرات المصلحية وعلى بوابة التعاقدات العامة.$m260$,'d7f5ec88443c2e3938d76c39c0fe7cd4',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(99,0,1,$m260$يتعين على المتعاقد بذل أقصى جهد للالتزام بتنفيذ التزاماته التعاقدية وفقا لما اشتمل عليه العقد، وفى حاله إخلاله بأى شرط جوهرى تضمنته شروط العقد، فعلى إدارة التعاقدات استنفاد كافة البدائل الممكنة للوصول إلى حلول تتفق مع شروط العقد، وفى حالة عدم إمكانية التوصل إلى حلول منطقية فعلى الإدارة المذكورة بما يحقق المصلحة العامة اتخاذ أحد الإجراءين الآتيين:
1- فسخ العقد وفى هذه الحالة فلا يجوز إعادة طرح العملية فى السنة المالية ذاتها المقرر التنفيذ فيها.
2- التنفيذ على حساب المتعاقد ما دام أن الحاجة إلى تنفيذ هذه العملية ما زالت قائمة على أن يتم التنفيذ بالشروط والمواصفات ذاتها المعلن عنها والمتعاقد على أساسها، وذلك بإحدى الطرق القانونية المنصوص عليها بالمادة (7) من القانون.$m260$,'e756c7982b5a11d7e0a6f12873aaa2d8',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(100,0,1,$m260$فى حالة فسخ العقد، أو التنفيذ على الحساب يتم عمل جرد وتحرير كشف بالأعمال التى تمت وبالآلات والأدوات التى استحضرت والمهمات التى لم تستعمل والتى يكون قد وردها المتعاقد بمكان العمل، ويتم ذلك الجرد خلال شهر من تاريخ موافقة السلطة المختصة على الفسخ أو التنفيذ على الحساب ويكون بمعرفة مسئول إدارة العقد، من الجهة الإدارية أو مندوبيها، بحسب الأحوال، وبحضور المتعاقد بعد إخطاره بالحضور هو أو من يفوضه، ويثبت هذا الجرد بموجب محضر يوقعه كل من مسئول إدارة العقد، أو مندوبي الجهة الإدارية، بحسب الأحوال، والمتعاقد، أو من يفوضه فإذا لم يحضر، أو لم يرسل مندوبا عنه فيجرى الجرد فى غيابه، وفى هذه الحالة يخطر المتعاقد بنتيجة الجرد، فإذا لم يبد ملاحظاته خلال أسبوع من تاريخ وصول الإخطار إليه كان ذلك بمثابة إقرار منه بصحة البيانات الواردة فى محضر الجرد، والجهة الإدارية غير ملزمة بأخذ شئ من هذه المهمات إلا بالقدر الذى يلزم لإتمام الأعمال فقط شريطة أن تكون صالحة للاستعمال أما ما يزيد على ذلك فيكلف المتعاقد بنقله من محل العمل.
وفى حالة عدم قيام المتعاقد بنقل المتبقي من مهماته فتقوم الجهة الإدارية ببيعها لحسابه وخصم ما تكبدته من مصروفات فى سبيل ذلك.$m260$,'0cc48a3d090615ed4acd48817c1c7ff8',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(101,0,1,$m260$فى حالة وفاة المتعاقد أثناء تنفيذ العقد، يحق للجهة الإدارية إنهاء العقد ورد التأمين النهائى للورثة ما لم يكن لها مطالبات قبل المتعاقد.
وتشكل بقرار من السلطة المختصة لجنة لحصر الأعمال المنجزة وتكلفتها وتحديد المبالغ المنصرفة حتى تاريخ الوفاة والمبالغ المتبقية له والأعمال المتبقية فى العقد، ويدعى لحضور أعمال اللجنة ممثل عن ورثة المتوفى.
ويجوز السماح للورثة أو ممثلهم حال تقديمه طلب بذلك وتوافر المقدرة الفنية والمالية للاستمرار فى تنفيذ العقد بالشروط والمواصفات ذاتها المحددة به، شريطة أن يعينوا عنهم وكيلا خلال فترة لا تتجاوز شهر من تاريخ الوفاة لإتمام الجزء غير المنفذ من العقد، وفى حالة عدم مقدرتهم أو عدم رغبتهم فى اتمام العقد يتم محاسبتهم وتنفيذ الجزء المتبقي عن طريق طرح عملية أخرى وفقا لأحكام القانون وهذه اللائحة.
أما إذا كان العقد مبرم مع أكثر من متعاقد كشريك وتوفى احدهم، جاز للجهة الإدارية انهاء العقد مع رد التأمين النهائى ما لم يكن لها مطالبات أو السماح لبقية الشركاء بتنفيذ بنود العقد.
وفى جميع الحالات يكون إنهاء العقد دون الحاجة إلى اتخاذ أى إجراءات أخرى أو الالتجاء إلى القضاء.$m260$,'b61921e378f18e376c3cb5302fc6afda',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(102,0,1,$m260$فى عقود التوريدات تبدأ المدة المحددة للتوريد من اليوم التالى لإخطار المورد سواء بالداخل أو بالخارج بأمر التوريد إلا إذا اتفق على خلاف ذلك، على أن يتضمن أمر التوريد الأصناف والكميات والفئات ومكان التسليم ومواعيد بدء التوريد وانتهائه.
وتبدأ المدة المحددة لتنفيذ عقود الأعمال من التاريخ الذى يسلم فيه الموقع للمقاول خاليا من الموانع إلا إذا اتفق على خلاف ذلك، ويكون التسليم بموجب محضر يوقع من الطرفين ومحرر من أصل وأربعة نسخ يسلم الأصل للإدارة المالية، ونسخة لإدارة التعاقدات لحفظها بملف العملية، ونسخة للمقاول، ونسخة للإدارة الطالبة أو المستفيدة، ونسخة للإدارة المشرفة على التنفيذ، وإذا لم يحضر المقاول أو من يفوضه لتسلم الموقع فى التاريخ الذى تحدد له فى أمر الإسناد فيحرر محضر بذلك ويعتبر هذا التاريخ موعدا لبدء تنفيذ العمل.
أما بالنسبة لباقى العقود فتبدأ المدة المحددة لتنفيذ العقد وفقا لما تضمنته كراسة الشروط والمواصفات، والعقد.$m260$,'44e4937d64ff8194a7e9594c99505cfb',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(103,0,1,$m260$يلتزم المتعاقد بتنفيذ محل العقد فى الميعاد، أو المواعيد المحددة بأمر التوريد، أو الإسناد، وعليه اتباع جميع القوانين واللوائح الحكومية والمحلية ذات الصلة بتنفيذ موضوع التعاقد كما يكون مسئولا عن حفظ النظام بموقع العمل وتنفيذ أوامر الجهة الإدارية بإبعاد كل من يهمل، أو يرفض تنفيذ التعليمات، أو يحاول الغش، أو يخالف ذلك.
كما يلتزم المتعاقد باتخاذ كل ما يكفل منع الإصابات، أو حوادث الوفاة للعمال، أو أى شخص آخر، أو الإضرار بممتلكات الدولة، أو الأفراد وتعتبر مسئوليته فى هذه الحالات مباشرة دون تدخل للجهة الإدارية، وعليه أن يتحرى بنفسه طبيعة الأعمال وعمل كل ما يلزم لذلك من اختبارات وغيرها للتأكد من صلاحية المواصفات والرسومات والتصميمات المعتمدة وعليه إخطار الجهة الإدارية فى الوقت المناسب بملاحظته عليها ويكون مسئولا تبعا لذلك عن صحة وسلامة جميع ما ورد بها كما لو كانت مقدمة منه.
وفى حالة إخلاله بتلك الالتزامات يكون للجهة الإدارية الحق اتخاذ الإجراءات المنصوص عليها بالقانون وهذه اللائحة.$m260$,'7aa7dfa8168b19da40cec44be70bf196',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(104,0,1,$m260$مع عدم الإخلال بحقوق الغير حسن النية فإن جميع المواد والمشونات المعتمدة والقطع والأدوات والآلات التى تكون قد استحضرت بمعرفة المتعاقد لمنطقة العمل، أو على الأرض المشغولة بمعرفته بقصد استعمالها فى تنفيذ محل العقد وكذلك جميع الأعمال والمنشآت الوقتية الأخرى تظل كما هي، ولا يجوز نقلها، أو التصرف فيها إلا بإذن الجهة الإدارية إلى أن يتم الاستلام المؤقت على أن تبقى فى عهدة المتعاقد وتحت حراسته ومسئوليته وحده ولا تتحمل الجهة الإدارية فى شأنها أية مسئولية بسبب الضياع، أو التلف، أو السرقة، أو غير ذلك.
ويجب على المتعاقد أن يهيئ مكانا صالحا لتشوين المواد القابلة للتلف بسبب العوامل الجوية وذلك لوقايتها منها بطريقة توافق عليها الجهة الإدارية.$m260$,'4077671cc9f59248187cd944c1ad72a9',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(105,0,1,$m260$تصدر السلطة المختصة قرارا بتشكيل لجنة لفحص الأصناف الموردة برئاسة مدير المخازن أو مسئول القسم المختص على أن تضم عضوا فنيا، أو أكثر، وعضوا عن الإدارة الطالبة، أو المستفيدة وأمين المخزن المختص، ويجوز للجنة الفحص الاستعانة بفني، أو أكثر من الجهات الفنية المختصة إذا رأت ضرورة لذلك، على أن يحدد القرار مواعيد انتهاء اللجنة من أعمالها، ولا يجوز أن يشارك فى أعمال الفحص من سبق وشارك فى اعداد الشروط، أو المواصفات الفنية، أو إجراءات لجان البت، ويمكن الاستئناس برأيهم إذا تطلب الأمر ذلك.
ويكون الفحص وفقا للمتطلبات ذات الصلة الواردة بشروط الطرح والعقد.
وتفصل السلطة المختصة فى الخلافات التى تنشأ بين أعضاء لجنة الفحص، ولها أن تسترشد فى ذلك برأي لجنة فحص أخرى أو الرجوع إلى الجهة التابع لها العضو الفنى.$m260$,'0cc5cb3282fc52d7ae77fcce00bc0661',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(106,0,1,$m260$يلتزم مدير المخازن طبقا لأحكام العقد بمتابعة ورود الأصناف واستلامها وإجراءات الفحص وتسجيل الفواتير والمستندات المخزنية ومتابعة إرسال المستندات إلى الإدارة المالية لاتخاذ إجراءات الصرف وبمراعاة أحكام هذه اللائحة.
وفى حالة إخلال المورد بأى شرط من شروط التوريد يتعين على مدير المخازن إخطار إدارة التعاقدات فورا بذلك لاتخاذ الإجراءات اللازمة وفقا لأحكام هذه اللائحة.$m260$,'800b5ff62ee748ada4d44e8c15ad2629',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(107,0,1,$m260$يلتزم المورد بتوريد الأصناف المتعاقد عليها فى الميعاد، أو المواعيد المحددة بالعقد خالصة جميع المصروفات والرسوم ومطابقة لأمر التوريد وللمواصفات، أو العينات المعتمدة ويتسلم أمين المخزن المختص ما يتم توريده بالعدد، أو الوزن، أو المقاس بحضور المورد أو من يفوضه ويعطى عنه إيصالا مؤقتا مختوما بخاتم الجهة الإدارية موضحا به اليوم والساعة التى تم التوريد فيها ويقرر فيه حالة الأصناف من حيث سلامتها، وتجتمع لجنة الفحص فى موعد أقصاه يوم العمل التالى لاستلام الأصناف ويخطر المورد بموعد اجتماع اللجنة ليتمكن من حضور إجراءات الفحص والاستلام النهائى، وعلى أمين المخزن المختص فور تسلمه الأصناف الموردة إخطار رئيس لجنة الفحص بذلك لاتخاذ اللازم.
ويلتزم بأن يقدم فاتورة الأصناف الموردة من أصل وصورتين، وفى حالة قيامه بالتوريد بناء على طلب الجهة الإدارية إلى جهة غير الجهة المتعاقد على التوريد إليها يجب إرفاق الفواتير مستندات تثبت قيمة مصروفات النقل الإضافية حتى يمكن رد هذه المصروفات إليه.
كما يلتزم على حسابه بإحضار العمال اللازمين لفتح الطرود وتسليمها إلى أمين المخزن أو لجنة الفحص بحضوره، أو بحضور من يفوضه فى الموعد المحدد وفى حالة تخلفه فيكون لمدير المخازن، أو لجنة الفحص الحق فى اتخاذ الإجراءات اللازمة على حساب المورد لتسلم الأصناف وتسليمها إلى المخازن وتصحيح الفاتورة إذا اقتضى الأمر ذلك دون أن يكون للمورد حق الاعتراض.$m260$,'51bd874841bcba4197fec0fc82bf5f44',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(108,0,1,$m260$تقوم لجنة الفحص بفحص نسب مئوية مختلفة تحدد بمعرفتها وتحت مسئوليتها حسب أهمية الصنف وبحيث تكون العينة ممثلة له وتعتبر اللجنة مسئولة عن مطابقته من جميع الوجوه للمواصفات وللعينة المختومة، وتحرر محضر الفحص على النموذج المعد لذلك من أصل وصورتين تبين فيه النسب المئوية لمقادير الفحص التى فحصتها وأسماء ومواصفات ومقادير الأصناف وأسباب التوصية بالقبول، أو الرفض ثم يقدم المحضر إلى السلطة المختصة للتصرف.
ويجب على الجهات التى تقوم بفحص الأصناف أن تبين فى تقارير الفحص ما أسفر عنه عملها مقارنا بما هو مدون بالشروط والمواصفات المتعاقد على أساسها وتلتزم الجهة الإدارية بالأخذ دائما بهذه النتائج ورفض الأصناف التى لا تطابق المواصفات أو العينات المتعاقد على أساسها.
وفى حالة اعتماد قبول الصنف يرسل أصل محضر الفحص وفاتورة المورد وصورة أمر التوريد مع إذن الإضافة على النموذج المعد لذلك إلى الإدارة المالية وتحفظ صورة من محضر الفحص مع صورة الفاتورة فى ملف خاص بإدارة المخازن وترسل الصورة الثانية مع صورة إذن الإضافة إلى وحدة رقابة المخزون.$m260$,'df0199bfab1c2ee6bd5e4d0cd3a0d178',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(109,0,1,$m260$عند ورود أصناف للمخازن ويكون قد سبق إرسال عينات عنها عند تقديم العطاءات للفحص بالجهات المختصة فتؤخذ عينة منها وتقسم إن أمكن قسمتها إلى قسمين وإلا فتختار عينتان من هذه الأصناف بحضور لجنة الفحص والمورد أو من يفوضه، ويحتفظ بإحداها لدى رئيس لجنة الفحص بعد ختمها بخاتم الجهة الإدارية وخاتم المورد، أما العينة الأخرى فتختم بخاتم الجهة الإدارية ويوقعها عضوان من أعضاء لجنة الفحص ويعمل محضر توقعه اللجنة والمورد أو من يفوضه بأن هذه العينة مطابقة للعينة المحفوظة لدى رئيس لجنة الفحص ثم ترسل إلى الجهة الفنية المختصة بعد إعطائها رقما سريا مع ذكر رقم وتاريخ نتيجة الفحص للعينة الأصلية للاسترشاد بها عند الفحص وعند ورود نتيجة الفحص لعينة التوريد ترفق مع مستندات الصرف.
فإذا تلفت العينة نتيجة الفحص فتتحمل الجهة الإدارية قيمتها متى كانت مطابقة للمواصفات، أما إذا ثبت عدم مطابقتها فليس للمورد أن يطالب الجهة بقيمتها.
وإذا رفضت الأصناف الموردة الموضوع عليها اسم الجهة الإدارية فيمحى اسم الجهة منها قبل ردها للمورد.$m260$,'03d9b002a78fadc3dfa39d012e1e6252',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(110,0,1,$m260$يجوز قبول الأصناف إذا كانت نسبة التباين لا تزيد على (10%) عما هو مطلوب بالمواصفات المتعاقد على أساسها بشرط أن تكون الحاجة ماسة لقبول الصنف أو الأصناف رغم ما بها من تباين وأن يكون السعر بعد الخفض مناسبا لمثيله فى السوق.
ويجب أن تقرر لجنة الفحص صلاحية الأصناف للأغراض المطلوبة من أجلها وأنه لن يترتب على قبولها ضرر بالجهة الإدارية ولا يكون قد سبق رفض عطاءات للسبب ذاته، كما تحدد اللجنة مقدار الخفض فى الثمن المقابل للتباين.
ويجوز للجنة الفحص الاستعانة بفني أو أكثر من الجهات الفنية المختصة إذا رأت ضرورة لذلك ويراعى الآتى:
1- الأصناف التى تكون نسبة التباين فى مواصفاتها حتى (2%) يكون قبولها بخصم مقدار الخفض فى الثمن الذى قدرته اللجنة.
2- الأصناف التى تكون نسبة التباين فى مواصفاتها أكثر من (2%) حتى (5%) يكون قبولها بخصم مقدار الخفض فى الثمن الذى قدرته اللجنة مضافا إليه مقابل تباين مقداره (50%) من هذا المقدار.
3- الأصناف التى تكون نسبة التباين فى مواصفاتها أكثر من (5%) حتى (10%) يكون قبولها بخصم مقدار الخفض فى الثمن الذى قدرته اللجنة مضافا إليه مقابل تباين مقداره (100%) من هذا المقدار.
على أن يكون القبول بموافقة لجنة البت والسلطة المختصة وبشرط أن يقبل المورد كتابة هذا الخصم وإلا فيرفض الصنف وتطبق أحكام القانون وهذه اللائحة.$m260$,'08c17e6864255a33587c1b2825021d71',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(111,0,1,$m260$إذا رفضت لجنة الفحص صنفا أو أكثر من الأصناف الموردة أو وجد فيها نقص أو مخالفة للمواصفات، أو العينات المعتمدة يخطر المتعاقد بذلك كتابة بأسباب الرفض وبوجوب سحب الأصناف المرفوضة وتوريد بدل عنها ويجب أن يتم ذلك الإخطار فور صدور قرار اللجنة فى ذات اليوم أو اليوم التالى على الأكثر ويلتزم المتعاقد بسحب الأصناف المرفوضة خلال سبعة أيام على الأكثر من تاريخ اليوم التالى لإخطاره، فإذا تأخر فى سحبها فيكون للجهة الإدارية الحق فى تحصيل مصروفات تخزين بواقع (5%) من قيمة الأصناف عن كل أسبوع تأخير أو جزء منه لمدة أقصاها أربعة أسابيع وبعد انتهاء هذه المدة تتخذ إجراءات بيعها لحساب المتعاقد وتخصم من الثمن ما يكون مستحقا لها ويكون البيع وفقا لأحكام القانون وهذه اللائحة.$m260$,'c45ac482b99b52f16fc833f69b4565ec',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(112,0,1,$m260$عند ورود أصناف مباشرة من الخارج تقوم لجنة الفحص بمراجعتها على الوارد بالفاتورة بعد التأكد من سلامة الأختام والعلامات أو الصناديق الواردة بداخلها الأصناف ويحرر محضر فحص عن ذلك على النموذج المعد لذلك تثبت فيه ما قد تجده من نقص، أو كسر، أو تلف ثم يحرر عنه محضر خاص على طلب خصم الأصناف التالفة، أو المفقودة على النموذج المعد لذلك لاتخاذ الإجراءات اللازمة نحوه مع مراعاة المواعيد التى تحددها شركات التأمين فى حالة التأمين على البضاعة حفظا لحق الجهة الإدارية فى استيفاء قيمة التأمين وإلا التزم به المتسبب فى فوات هذه المواعيد.
وتضاف الأصناف بالمخزن حسب الوارد بالفاتورة بغض النظر عما تجده اللجنة فيها من نقص، أو كسر، أو تلف.
على أن يخصم مقدار النقص من العهدة بموجب طلب وإذن صرف على النموذج المعد لذلك وتجرى التسويات الحسابية اللازمة وفقا للقواعد المالية المعمول بها.
وفى حالة تعذر فتح الصناديق وإضافتها حسب الوارد بالفاتورة لأسباب اضطرارية تقرها كتابة السلطة المختصة يتبع الآتى:
1- تضاف تلك الصناديق بأذون إضافة مؤقتة بالحالة التى هي عليها إجمالا بعهدة موظفين مسئولين بعد ختمها بخاتم مدير المخازن بطريقة تضمن سلامة الأختام حتى يعاد فتحها.
2- عند استخراج أذون الإضافة المؤقتة السابق الإشارة إليها ترافق صورة منها مستندات الصرف لإمكان إزالة المبالغ السابق الخصم بها من الحساب المختص.$m260$,'65cbef768bd42c8459e712ac99ebc2dc',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(113,0,1,$m260$بعد اعتماد السلطة المختصة لأعمال اللجنة تتخذ إجراءات التعاقد على نقل الملكية أو الاستئجار وفقا للقوانين والقرارات المنظمة لذلك.
وتشكل لجنة متخصصة تضم العناصر الفنية لاستلام العقار محل التعاقد، وعليها التأكد من مطابقته من جميع الوجوه لما تم التعاقد عليه.$m260$,'94f094510d137bc7efecac74cd33fd8a',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(114,0,1,$m260$يلتزم المقاول بأن يتحرى بنفسه طبيعة الأعمال وعمل كل ما يلزم لذلك من اختبارات والجسات وغيرها للتأكد من صلاحية المواصفات الفنية والرسومات الهندسية والتصميمات المعتمدة وعليه إخطار إدارة التعاقدات فى الوقت المناسب بملاحظاته عليها ويكون مسئولا تبعا لذلك عن صحة وسلامة جميع ما ورد بها كما لو كانت مقدمة منه.$m260$,'dacbb93100314eca9550dfd146b0326a',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(115,0,1,$m260$المقادير والأوزان الواردة بجداول الفئات هي مقادير وأوزان تقريبية قابلة للزيادة أو النقص تبعا، لطبيعة العملية والغرض منها هو بيان مقدار العمل بصفة عامة والمبالغ التى تسدد للمقاول تكون على أساس الكميات التى تنفذ فعلا سواء أكانت تلك الكميات أقل أم أكثر من الواردة بالمقايسة، أو الرسومات وسواء نشأت الزيادة، أو العجز عن خطأ فى حساب المقايسة الابتدائية، أو عن تغييرات أدخلت فى العمل طبقا لبنود العقد.
ويجب فى جميع الحالات ألا يؤثر ذلك على أولوية المقاول فى ترتيب عطائه.
ويعتبر المقاول مسئولا عن التحري بنفسه عن صحة المقادير والأوزان وتعتبر كل فئة من الفئات المدرجة بجدول الفئات ملزمة للمقاول أثناء العقد وغير قابلة لإعادة النظر لأى سبب ولا يكون للمقاول حق طلب مبالغ زيادة أو تعويضات بشأنها.
ويقوم مهندس الجهة الإدارية بعملية القياس أو الوزن للأعمال أثناء سير العمل بالاشتراك مع المقاول، أو مهندسه، أو من يفوضه، ويتم التوقيع بصحة المقاسات والأوزان من الاثنين، فإذا تخلف المقاول، أو من يفوضه بعد إخطاره يلزم بالمقاسات والأوزان التى يجريها مهندس الجهة الإدارية.
على أنه بالنسبة للجهات التى لا يتوافر فيها العنصر الفنى اللازم فينتدب مهندس من مديرية الإسكان المختصة ويكون مهندس الجهة الإدارية، أو مديرية الإسكان مسئولا عن صحة وسلامة ما يثبته من بيانات فى هذا الشأن.$m260$,'70712c08a78cc75626b2ea5b5ed94878',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(116,0,1,$m260$على المقاول بمجرد إتمام العمل أن يخلى الموقع من جميع المواد والأتربة والبقايا وأن يمهده، وإلا كان للجهة الإدارية الحق بعد إخطاره فى تنفيذ ذلك على حسابه، ويخطر عندئذ بالموعد الذى حدد لإجراء المعاينة ويحرر محضر الاستلام المؤقت بعد إتمام المعاينة ويوقعه كل من المتعاقد أو من يفوضه بذلك بتوكيل مصدق عليه ومسئول إدارة العقد من الجهة الإدارية أو مندوبيها، بحسب الأحوال، الذين يخطر المقاول بأسمائهم ويكون هذا المحضر من أصل وأربع نسخ يسلم الأصل للإدارة المالية، ونسخة لإدارة التعاقدات لحفظها بملف العملية، ونسخة للإدارة الطالبة أو المستفيدة، ونسخة للإدارة المشرفة على التنفيذ، وتسلم نسخة للمتعاقد وفى حالة عدم حضوره هو أو من يفوضه فى الميعاد المحدد تتم المعاينة ويوقع المحضر من مندوبي الجهة الإدارية وحدهم وإذا تبين من المعاينة أن العمل قد تم على الوجه المطلوب اعتبر تاريخ إخطار المتعاقد للجهة الإدارية باستعداده للتسليم المؤقت موعد إنهاء العمل وبدء مدة الضمان وإذا ظهر من المعاينة أن العمل لم ينفذ على الوجه الأكمل فيثبت هذا فى المحضر ويؤجل الاستلام إلى أن يتضح أن الأعمال قد تمت بما يطابق الشروط مع عدم الإخلال بمسئولية المتعاقد طبقا لأحكام القانون المدني وتبدأ من تاريخ المعاينة الأخيرة مدة الضمان.
وبعد إتمام الاستلام المؤقت يرد للمتعاقد إذا لم توجد قبله مطالبات للجهة المتعاقدة، أو لأية جهة إدارية أخرى ما زاد من قيمة التأمين النهائى على النسبة المحددة من قيمة الأعمال التى تمت فعلا وتحتفظ الجهة المتعاقدة بهذه النسبة لحين انتهاء مدة الضمان وإتمام الاستلام النهائى.$m260$,'2ad2753174e8952e93b7666ddad7e20a',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(117,0,1,$m260$يضمن المتعاقد الأعمال موضوع العقد وحسن تنفيذها على الوجه الأكمل لمدة سنة واحدة من تاريخ الاستلام المؤقت وذلك دون إخلال بمدة الضمان المنصوص عليها فى القانون المدني أو أى قانون آخر، والمتعاقد مسئول عن بقاء جميع الأعمال سليمة أثناء مدة الضمان طبقا لشروط التعاقد فإذا ظهر بها أى خلل أو عيب يقوم بإصلاحه على نفقته وإذا قصر فى إجراء ذلك فللجهة الإدارية أن تجريه على نفقته وتحت مسئوليته.$m260$,'eb8c2ec6a08a47cf3cfac68cf9a1ba60',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(118,0,1,$m260$قبل انتهاء مدة الضمان بوقت مناسب يخطر المتعاقد الجهة الإدارية كتابة للقيام بتحديد موعد للمعاينة.
ومتى تبين أن الأعمال قد نفذت مطابقة للمواصفات بحالة جيدة فيتم تسلمها نهائيا بموجب محضر من أصل وأربع نسخ يوقعه كل من مندوبي الجهة الإدارية والمتعاقد، أو من يفوضه، ويسلم الأصل للإدارة المالية، وتسلم نسخة للمتعاقد، ونسخة لإدارة التعاقدات لحفظها بملف العملية، ونسخة للإدارة الطالبة أو المستفيدة، ونسخة للإدارة المشرفة على التنفيذ وإذا ظهر من المعاينة أن المتعاقد لم يقم ببعض الالتزامات فيؤجل الاستلام النهائى لحين قيامه باستكمال التزاماته، هذا مع عدم الإخلال بمسئوليته طبقا لأحكام القانون المدني أو أى قانون آخر.
وعند إتمام الاستلام النهائى يدفع للمتعاقد ما قد يكون مستحقا له من مبالغ ويرد إليه التأمين النهائى أو ما تبقى منه.$m260$,'07ea59a7fd6cd038ab44b4a5e3bcd84e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(119,0,1,$m260$يعمل فى شأن التعاقد بطريق المناقصة العامة على شراء أو استئجار المنقولات والعقارات، والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية بالإجراءات المنظمة لمرحلة ما قبل الطرح ومرحلة الطرح ومرحلة الترسية والتعاقد المنصوص عليها فى هذه اللائحة.$m260$,'1f8848d109484d44200cbe9e6af980a0',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(120,0,1,$m260$فيما عدا التعاقد على الدراسات الاستشارية يكون التعاقد بطريق الممارسة العامة على شراء أو استئجار المنقولات والعقارات، والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية فى الحالات التى تتوافر فيها الشروط المنصوص عليها بالمادة (54) من القانون مجتمعة، ويجب النشر عنها على بوابة التعاقدات العامة والإعلان بإحدى الصحف اليومية واسعة الانتشار بمدة لا تقل عن عشرين يوما قبل الموعد المحدد لفتح المظاريف ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير تلك المدة بحيث لا تقل عن أربعة عشر يوما تحتسب من تاريخ الإعلان.
ويجوز لتطبيق الشرط المنصوص عليه بالبند (3) من المادة المشار إليها، إصدار الجهة الإدارية طلب ابداء الاهتمام أو طلب تأهيل مسبق إذا تطلبت طبيعة العملية ذلك.$m260$,'e3450e4ca8979d64dbbc9edc924a22f8',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(121,0,1,$m260$فيما عدا التعاقد على الدراسات الاستشارية يكون اللجوء إلى طريق الممارسة المحدودة فى أى من الحالات المنصوص عليها بالمادة (55) من القانون، مع مراعاة الشرطين (1)، (2) من المادة (54) من القانون مجتمعين، ويجوز لتطبيق الشرط المنصوص عليه بالبند (1) من المادة (55) المشار إليها، إصدار الجهة الإدارية طلب ابداء الاهتمام أو طلب تأهيل مسبق بما يتفق مع طبيعة العملية.
ويجب النشر عن الممارسة المحدودة على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد ممكن من المسجلين عليها المتخصصين أو المؤهلين المشتغلين بالنشاط موضوع الطرح، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لفتح المظاريف الفنية، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.$m260$,'5db27adce0c7d2f304f4696327e0c8bd',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(122,0,1,$m260$تتولى لجنة الممارسة المشكلة بقرار من السلطة المختصة فتح المظاريف المالية للعروض المقبولة فنيا فقط وممارسة مقدميها، أو من يفوضونهم فى جولة، أو عدة جولات فى الجلسة المحددة للوصول لأفضل الشروط وأقل الأسعار، أو الذى يتم ترجيحه وفقا لنظام النقاط المحددة أسسه وعناصره والوزن النسبى بشروط الطرح والحد الأدنى للقبول وذلك بعد توحيد أسس المقارنة بين العروض من جميع النواحى الفنية والمالية للوصول إلى أقل قيمة مقارنة مع الأخذ فى الاعتبار العناصر التى تؤثر فى تحديد القيمة المالية المقارنة للعطاءات بحسب ظروف موضوع التعاقد وطبيعته.
وفى جميع الحالات يحظر إعادة فتح باب التمارس مرة أخرى لما تم الانتهاء عليه من التمارس.
ويحظر الترتيب بين المتمارسين قبل أو بعد تقديم عطاءاتهم أو أثناء جلسة الممارسة لتحقيق غرض غير مشروع أو للإخلال بمبدأي تكافؤ الفرص وحرية المنافسة بما فى ذلك التأثير بشكل مباشر، أو غير مباشر على تصرفات طرف آخر، بهدف تقسيم العقود أو تثبيت الأسعار بشكل غير تنافسى، وفى حالة ما إذا تبين ذلك فيتم إعمال أحكام المادة (50) من القانون.$m260$,'1d38ac2588c54c00e966434a0c51fc9c',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(123,0,1,$m260$يجب النشر عن المناقصة المحدودة على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد ممكن من المسجلين عليها المتخصصين أو المؤهلين المشتغلين بالنشاط موضوع الطرح، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لفتح المظاريف الفنية، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.$m260$,'169def2ddc464839cf877536c4d30bf3',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(124,0,1,$m260$يجوز للجهة الإدارية شراء أو استئجار المنقولات أو العقارات أو التعاقد على مقاولات الأعمال أو تلقى الخدمات أو الأعمال الفنية أو الدراسات الاستشارية بطريق المناقصة ذات المرحلتين شريطة توافر أى من الحالات المنصوص عليها بالمادة (58) من القانون.
وتشكل بقرار من السلطة المختصة لجنة تضم عناصر فنية ومالية وقانونية تكون مهمتها اعداد كراسة شروط ومواصفات أولية على أن تتضمن بحسب طبيعة العملية الآتى:
1- الغرض من التعاقد.
2- الأداء المتوقع.
3- الخطوط العريضة للمواصفات الفنية أو معايير الأداء المطلوبة.
4- الميزات والمهام والمواصفات التى ترغب الجهة الإدارية فى التعاقد عليها.
5- المؤهلات المطلوبة لتنفيذ العقد.
6- محددات التعامل مع الأمور المتعلقة بحقوق الملكية الفكرية.
وغير ذلك من بيانات ومعلومات قد تساعد مقدمى العروض على تقديم عروضهم الفنية الأولية بدون أسعار وكذا ملاحظاتهم على شروط العقد المقترحة وأية شروط أخرى قد يرون إضافتها.
وتتبع فى المرحلة الأولى من المناقصة ذات المرحلتين الإجراءات ذاتها المحددة فى هذه اللائحة فيما يخص تشكيل لجنة اعداد القيمة التقديرية ولجنة الرد على الاستفسارات إن وجدت، ولجنة فتح المظاريف الفنية، وتحديد مبلغ التأمين المؤقت فى الحدود المقررة قانونا.
ويجب النشر عن المناقصة ذات المرحلتين على بوابة التعاقدات العامة والإعلان عنها بإحدى الصحف اليومية واسعة الانتشار، أو توجيه الدعوة للمسجلين على بوابة التعاقدات العامة المتخصصين أو المؤهلين المشتغلين بالنشاط محل الطرح، وفى هاتين الحالتين يجب ألا تقل مدتهما عن عشرين يوما قبل الموعد المحدد لفتح العروض الفنية الأولية، وتتبع الإجراءات ذاتها المنصوص عليها بهذه اللائحة بشأن محتويات الإعلان أو الدعوة بما لا يتعارض مع طبيعة المناقصة ذات المرحلتين.
ويجوز قبل طرح المناقصة ذات المرحلتين إجراء تأهيل مسبق إذا ارتأت الجهة الإدارية مناسبة ذلك وفقا للإجراءات المنصوص عليها بهذه اللائحة.$m260$,'347c3e36186b3c3c0daf0d4f2c2930ed',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(125,0,1,$m260$يجوز فى المرحلة الأولى تلقى الاستفسارات فى الموعد المحدد إذا تضمنت شروط الطرح ذلك، ومناقشة مقدمى العروض لتوضيح موضوع العملية والوقوف على مدى استجابة عروضهم للمتطلبات والشروط التعاقدية المطلوبة، على أن يتم توثيق كافة الاستفسارات والمناقشات والرد عليها وحفظها في ملف العملية، وعلى إدارة التعاقدات إخطار كافة مقدمى العروض بالتغييرات التي تقرها الجهة الإدارية بناء على الاستفسارات.
وتشكل بقرار من السلطة المختصة لجنة لتلقى العروض الفنية الأولية ودراستها واعداد تقرير بنتائج أعمال الدراسة والمراجعة والمناقشات التى تم التوصل إليها مع مقدمى العروض المستجيبة للحد الأدنى من المتطلبات والشروط التعاقدية الواردة بكراسة الشروط وبما لا يخل بمبدأ تكافؤ الفرص بينهم، وترفع اللجنة تقريرها للسلطة المختصة لاتخاذ أى من القرارات الآتية:
1- تكليف اللجنة الفنية التي تولت إعداد كراسة الشروط والمواصفات الأولية بإعداد كراسة الشروط النهائية وفقا للنتائج التي تم التوصل إليها، وتدقيق المواصفات الفنية ومعايير التقييم وشروط العقد.
2- إلغاء إجراءات الطرح إذا كانت العروض المقدمة والتعديلات المقترحة تتطلب المزيد من التخطيط ودراسة السوق والمراجعة الفنية لموضوع الطرح على أن يتم إخطار مقدمى العروض بذلك.
وفي نهاية المرحلة الأولى يتم استبعاد العروض الفنية غير المستجيبة للمتطلبات الأساسية، وتتبع الإجراءات ذاتها المنصوص عليها بهذه اللائحة بشأن الإعلان عن النتائج وتلقى الشكاوى.$m260$,'28171cad03103f94483c85760ddd70ef',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(126,0,1,$m260$بعد إعداد كراسة الشروط والمواصفات بصورة مدققة ومتكاملة وفقا لنتائج المرحلة الأولى يجب التأكد من الآتى:
1- توافر الاعتماد المالى للعملية.
2- تدقيق القيمة التقديرية ومبلغ التأمين المؤقت فى ضوء الشروط النهائية التى تم اعدادها.
3- أن كافة المتطلبات قد تم استيعابها.
وتقوم إدارة التعاقدات فى المرحلة الثانية بتوجيه إخطار لكافة المتقدمين المستجيبين للتقدم بعطاءات متضمنة عروض فنية ومالية نهائية طبقا لكراسة الشروط والمواصفات النهائية المدققة.
وتتبع الإجراءات ذاتها المحددة في هذه اللائحة فيما يخص فتح المظاريف ودراسة وتقييم العطاءات والبت فيها، وإعلان النتائج.$m260$,'7b9621a5456b3424d0f1ad6ae856f89a',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(127,0,1,$m260$يجب النشر عن المناقصة المحلية على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد ممكن من المسجلين عليها المتخصصين أو المؤهلين المشتغلين بنوع النشاط المزمع طرحه، والذين يقع نشاطهم داخل نطاق المحافظة التى يتم فيها تنفيذ موضوع التعاقد، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لفتح المظاريف الفنية، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.
ويجوز بموافقة السلطة المختصة بالجهة الإدارية حال قصر الطرح على المشروعات المتوسطة والصغيرة ومتناهية الصغر تضمين كراسة الشروط والمواصفات نموذج إقرار بديل عن التأمين المؤقت مفادة الالتزام بالسير فى الإجراءات ويقوم صاحب العطاء بالتوقيع عليه وإرفاقه بمظروفه الفنى، وفى حالة تقاعس صاحب العطاء الفائز عن الوفاء بسداد نسبة التأمين النهائى فيتم خصم قيمة التأمين المؤقت من مستحقاته لدى الجهة الإدارية وفى حالة عدم كفايتها تلجأ إلى خصمها من مستحقاته لدى أى جهة إدارية أخرى أيا كان سبب الاستحقاق، ودون الحاجة إلى اتخاذ أى اجراء آخر يجوز لها إلغاء العقد أو تنفيذه بواسطة أحد أصحاب العطاءات التالية لعطائه بحسب ترتيب أولويتها كما يكون لها أن تخصم منه قيمة كل خسارة تلحق بها، مع عدم الإخلال بحق الجهة الإدارية فى الرجوع عليه قضائيا بما لم تتمكن من استيفائه من حقوق بالطريق الإدارى ويخطر جهاز تنمية المشروعات المتوسطة والصغيرة والمتناهية الصغر بعدم الالتزام بسداد التأمين النهائى لأخذ ذلك فى الاعتبار مستقبلا.
كما يجوز بموافقة السلطة المختصة صرف دفعة مقدمة للعطاء الفائز من تلك المشروعات وفقا للنسبة وفى الحدود المنصوص عليها بالمادة (90) من هذه اللائحة وذلك مقابل خطاب ضمان بنكى معتمد بالقيمة والعملة ذاتهما وغير مقترن بأى قيد أو شرط ويكون ساري المفعول حتى تاريخ الاستحقاق الفعلي لتلك المبالغ على أن تتضمن شروط الطرح نسبة الدفعة المقدمة وطلب تحديد أوجه صرفها.
وعلى إدارة التعاقدات بالجهة الإدارية قبل عرض مذكرة الطرح على السلطة المختصة مخاطبة فرع جهاز تنمية المشروعات المتوسطة والصغيرة والمتناهية الصغر الواقع بالمحافظة التى يتم بدائرتها تنفيذ التعاقد لإعمال شئونه وإخطار أصحاب تلك المشروعات لتسجيل بياناتهم وتحديثها على بوابة التعاقدات العامة على أن يقوم فرع الجهاز بموافاة الجهة الإدارية بأسماء وبيانات المهتمين منهم بالدخول فى العملية محل الطرح لدعوتهم وذلك خلال موعد أقصاه خمسة أيام من تاريخ تسلمه اخطار الجهة الإدارية.$m260$,'4aeff79535e5feeb500a6e802852b33b',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(128,0,1,$m260$تسرى على كل من المناقصة المحدودة والمناقصة ذات المرحلتين والمناقصة المحلية والممارسة بنوعيها، الأحكام الخاصة بالمناقصة العامة فيما لم يرد فى شأنه نص خاص فى هذه اللائحة.$m260$,'f86a369d587e15faaed0f1423b15579a',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(129,0,1,$m260$تسرى على شراء أو استئجار العقارات ذات الأحكام المنظمة لشراء أو استئجار المنقولات، وبما لا يتعارض مع طبيعتها.$m260$,'e8a0c9d50061935d0d2ed4837023a71e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(130,0,1,$m260$تتولى إجراءات التعاقد بالاتفاق المباشر على شراء، أو استئجار المنقولات، أو التعاقد على مقاولات الأعمال، أو تلقى الخدمات، أو الأعمال الفنية، أو الدراسات الاستشارية لجنة تشكل بقرار من السلطة المختصة تضم عناصر فنية ومالية وقانونية وعضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع الطلب ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، ويكون اعتماد أعمالها من السلطة المختصة دون غيرها.
على إدارة التعاقدات عرض مذكرة على السلطة المختصة تتضمن الأسباب التى أدت إلى اقتراح التعاقد بهذا الطريق وفقا للحالات الواردة بالمادة (62) من القانون كما ترفق بها صورة من خطة الاحتياجات فيما عدا الحالات المبينة قرين البنود (1)، و(4)، و(5) من المادة ذاتها.
وفور موافقة السلطة المختصة، تتولى إدارة التعاقدات النشر عن التعاقد بالاتفاق المباشر على بوابة التعاقدات العامة وفقا لما تقضى به أحكام المادة (20) من القانون على أن يتضمن النشر وصف موجز لموضوع التعاقد والمواصفات الفنية المطلوبة.
ويجوز إعداد كراسة للشروط والمواصفات لمحل التعاقد إذا تطلبت طبيعة العملية ذلك.
وعلى لجنة الاتفاق المباشر تحديد رقم مسلسل لكل عرض واثبات تاريخ ووقت استلامه ويقع على عاتقها مسئولية التحقق من مطابقة محل التعاقد من النواحى الفنية المطلوبة ومناسبة الأسعار مقارنة بأسعار السوق السائدة وقت التعاقد أو لتحديد أقل العروض سعرا، والذى يلبى جميع الشروط والمتطلبات التى حددتها الجهة الإدارية فى طلبها وذلك من واقع العرض المقدم، أو ما يتم الحصول عليه من عروض أسعار، بحسب الأحوال، وكذا أسس اختيار المتعاقد معه.
وعلى اللجنة اعداد محضر بنتيجة أعمالها تعرضه على السلطة المختصة للاعتماد وفقا لسلطات الترخيص المنصوص عليها بالمادة (63) من القانون، وتتولى إدارة التعاقدات نشر نتيجة التعاقد فور اعتماده على بوابة التعاقدات العامة واستكمال باقى الاجراءات المقررة قانونا وتوثيقها.$m260$,'2c83f4cfc5ecbb6ee54130aa10c44532',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(131,0,1,$m260$تقوم إدارة التعاقدات فى حالات التعاقد بالاتفاق المباشر بطلب عرض أو عروض أسعار من المشتغلين بنوع النشاط المطلوب التعاقد عليه ينشر عنه على بوابة التعاقدات العامة على أن يتضمن البيانات الآتية:
1- اسم الجهة الإدارية، وعنوان إدارة التعاقدات بها ورقم التليفون والفاكس والبريد الإلكترونى للإدارة.
2- أسم العملية ورقمها.
3- مكان الحصول على كراسة الشروط والمواصفات وثمنها إن وجدت.
4- ما يفيد حجز نسبة (5%) فى الحالات التى تطلب طبيعتها ضمان المتعاقد لسلامة محل العقد.
5- وصف كامل للأصناف أو الأعمال أو الخدمات المراد التعاقد عليها حسب الاقتضاء وفقا لطبيعة التعاقد، على النحو المبين بالمادة (14) من القانون.
6- الكمية، أو حجم الأعمال أو المهام المطلوبة، والبرنامج الزمنى للتوريد، أو للتنفيذ بحسب الأحوال.
7- جميع العناصر الخاصة بالسعر ويشمل ذلك شروط التسليم وتكلفة دورة الحياة إذا كانت طبيعة العملية تتطلب ذلك وتم تضمينها بشروط الطرح.
8- مدة الارتباط بالأسعار.
9- ايضاح ما إذا كانت الترسية ستتم لكل بند على حده أم لمجموعة بنود مجمعة.
10- أسلوب ومعايير تقييم العروض.
11- طريقة تقديم العروض والموعد النهائى لتقديمها.
12- حظر التقدم بأكثر من عرض، أو تقديم تعديل للأسعار فى العرض المقدم.
13- تحديد البنود المتغيرة، أو مكوناتها بالنسبة لمقاولات الأعمال فى العقود التى تتطلب ذلك.
14- تحديد البنود التى يجوز أن يعهد بها إلى الغير من الباطن إذا تطلبت طبيعة العملية ذلك، وكذا المحددات والاشتراطات الأخرى ذات الصلة.$m260$,'506d9c4b90b391b54870ffa76f884cbe',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(132,0,1,$m260$لوزير الصحة التعاقد بطريق الاتفاق المباشر بالنسبة للأمصال واللقاحات والعقاقير ذات الطبيعة الاستراتيجية وألبان الأطفال على أن تعد إدارة التعاقدات بوزارة الصحة دليل إجرائي بذلك تعتمده الهيئة العامة للخدمات الحكومية.
ويشكل وزير الصحة لجنة متخصصة تضم عناصر فنية ومالية وقانونية تتولى مباشرة إجراءات التعاقد ويقع على عاتقهم مسئولية التحقق من مطابقة الأصناف من حيث النوع والمواصفات والشروط للغرض المطلوبة من أجله وأن الأسعار مناسبة لسعر السوق من واقع ما يتم الحصول عليه من عروض متى توافرت، وترفع اللجنة تقريرا بنتائج أعمالها لوزير الصحة تضمنه كافة ما قامت به من إجراءات مع بيان أسباب ما تنتهى إليه من توصيات للاعتماد.$m260$,'46d5d91635dfe1e0f89195db32024cb7',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(133,0,1,$m260$بمراعاة حكم المادة (10) من القانون يكون التعاقد بالاتفاق المباشر على شراء، أو استئجار المنقولات، أو الأعمال، أو تلقى الخدمات منخفضة القيمة اللازمة لتسيير متطلبات العمل وفقا للضوابط الآتية:
1- أن يكون اتباع هذا الطريق هو الأمثل من بين طرق التعاقد الأخرى.
2- ألا يكون محل التعاقد ضمن اتفاقية اطارية، ولا يمكن التعاقد عليه من خلال طريق الممارسة بنوعيها.
3- الأخذ فى الاعتبار عنصر الوقت لتلبية الاحتياجات المطلوبة.
4- التحقق من مناسبة السعر لأسعار السوق السائدة وقت التعاقد من خلال دراسة السوق أو استرشادا بالأسعار السابق التعاقد بها.
5- مطابقة محل التعاقد من النواحى الفنية المطلوبة.
6- أن يتم التعاقد مع أحد المسجلين لدى مصلحة الضرائب ويستثنى من ذلك العمليات التى تكون طبيعتها لا تتطلب ذلك.
7- التحقق من أن التعاقد لا يخل بالمنافسة ويحقق معايير القيمة مقابل المال المدفوع.
على أن تتولى إجراءات التعاقد بالاتفاق المباشر لجنة دائمة تشكل بقرار من السلطة المختصة تضم عناصر فنية ومالية وقانونية وعضو من إدارة التعاقدات، ولها أن تستعين برأي من تراه من أهل الخبرة بموضوع الطلب ويجوز لها حال عدم توافرهم الاستعانة بمن تراه من الجهات الإدارية الأخرى، ويكون اعتماد أعمالها من السلطة المختصة، ويقع على عاتقها مسئولية التحقق من الالتزام بالإجراءات المنصوص عليها فى هذه المادة وتحديد أقل العروض سعرا، والذى يلبى جميع الشروط والمتطلبات التى حددتها الجهة الإدارية وذلك من واقع ما يتم الحصول عليه من عرض أو عروض أسعار، مع مراعاة عدم تكرار التعاقد مع المتعاقد ذاته فى العملية ذاتها.$m260$,'74c3470d5096ce277c34eb271ef23a29',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(134,0,1,$m260$يجوز للجهة الإدارية شراء أو استئجار العقارات فى الحالات الطارئة، أو العاجلة، أو لدواعى المصلحة العامة، وذلك باتباع الإجراءات ذاتها المنصوص عليها بالمادة (130) من هذه اللائحة والمنظمة للتعاقد بالاتفاق المباشر على شراء أو استئجار المنقولات، أو التعاقد على مقاولات الأعمال، أو تلقى الخدمات، أو الأعمال الفنية أو الدراسات الاستشارية.$m260$,'8e1a497173f663154f366a6f5ef9fcd9',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(135,0,1,$m260$يكون التعاقد بأسلوب الاتفاقية الاطارية فى أى من الحالات المنصوص عليها بالمادة (65) من القانون وصولا إلى تحديد الشروط والأسعار التى تحكم أوامر التوريد، أو الإسناد المزمع إصدارها بحسب الأحوال.
وبمراعاة أحكام المادة (19) من القانون والأحكام المنظمة لإعداد كراسة الشروط والمواصفات المنصوص عليها بهذه اللائحة يجب أن تتضمن كراسة الشروط والمواصفات الخاصة بالمناقصة، أو الممارسة بأنواعهما، أو الاتفاق المباشر بحسب الأحوال الآتى:
1- الإشارة إلى أن الإجراءات سوف تنتهى بإبرام اتفاقية اطارية مع من يتم الترسية عليه، أو عليهم.
2- الجهات الإدارية المشاركة فى الاتفاقية الاطارية والاشتراطات ذات الصلة.
3- تحديد نمط الاتفاقية الاطارية إما مفتوحة، أو مغلقة، وفى حالة الاتفاقية الاطارية المفتوحة يجب تحديد الحد الأدنى لمن سيسمح لهم بالاشتراك فيها.
4- صيغة وأحكام وشروط ومدة الاتفاقية وبما لا يقل عن عامين ماليين واستثناء يجوز مدها لمدة أخرى بما لا يجاوز أربعة أعوام شريطة موافقة السلطة المختصة بالجهة الإدارية الطارحة وتضمين كراسة الشروط والمواصفات المدة المحددة وضوابطها.
5- البيانات الاحصائية لمعدلات الطلب ومعدلات الاستهلاك التاريخية، والمؤشرات المستقبلية الاسترشادية لمحل الطرح والتعاقد.
6- أطر الأعمال، أو الخدمات، أو الدراسات الاستشارية، بحسب الأحوال.
7- تحديد ما إذا كانت الاتفاقية سوف تبرم مع واحد أو أكثر من أصحاب العطاءات الفائزين وذلك إذا كانت العملية قابلة للتجزئة.
8- ما يفيد أن التأمين المؤقت سوف يتم تأديته وفقا لما تحدده السلطة المختصة بالجهة الطارحة بناء على البيانات الاحصائية لمعدلات الطلب ومعدلات الاستهلاك التاريخية، والمؤشرات المستقبلية الاسترشادية التى سيتم تضمينها بشروط الطرح، وأن التأمين النهائى سوف يتم تأديته للجهة الإدارية مصدرة أمر التوريد، أو الاسناد بحسب الأحوال وفقا للنسبة المنصوص عليها بالقانون.$m260$,'0715cd3c4c96bf6d848adfc878195709',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(136,0,1,$m260$يكون تحديد نمط الاتفاقية الاطارية وفقا لاحتياجات الجهة، أو الجهات الإدارية بناء على دراسة السوق لمحل الاتفاق، ووفقا للآتى:
1- الاتفاقية الاطارية المغلقة يتم اختيارها لتوفير الاحتياجات بأقل الأسعار والتى تغطى مدى زمنى مستقبلي، أو يكون التوريد، أو التنفيذ على دفعات، ولا يجوز طوال مدة سريانها اشتراك غير من تم الترسية عليه، أو عليهم طوال مدة تنفيذها.
2- الاتفاقية الاطارية المفتوحة ويتم اختيارها لتوفير الاحتياجات السريعة والشائعة بشكل فعال بأقل الأسعار، ويجوز طوال مدة سريانها السماح باستلام عطاءات من الموردين، أو المقاولين، أو مقدمى خدمات، أو الاستشاريين، للدخول فيها على أن يتم اخطارهم بنتيجة دراسة الجهة الإدارية لعروضهم الفنية والمالية، ويتم تنفيذ الاتفاقية الاطارية المفتوحة من خلال المنظومة الإلكترونية حال اكتمالها وانتظامها.$m260$,'10335b11b4dbb41fbb4188df9b2dee4f',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(137,0,1,$m260$تتولى إدارة التعاقدات رفع مذكرة للسلطة المختصة للموافقة على التعاقد على عمل ابتكاري بأسلوب المسابقة.
وتشكل بقرار من السلطة المختصة لجنة فنية للتحكيم متخصصة ومحايدة ويجوز لها الاستعانة بذوي الخبرة من جهات إدارية أخرى لها خبرة بموضوع المسابقة، وتتولى اللجنة اعداد مستندات المسابقة متضمنة توصيف دقيق لموضوعها والغرض منه والجوائز، أو المكافآت، أو الامتيازات الممنوحة للفائزين وكيفية التعامل مع حقوق الملكية الفكرية للمتسابقين، واعداد أسس ومعايير الاختيار وأسلوب التواصل مع المتسابقين.
وتتولى ادارة التعاقدات الإعلان عن المسابقة مرة واحدة بإحدى الصحف اليومية واسعة الانتشار بالإضافة للنشر عنها على بوابة التعاقدات العامة، على أن يتضمن الإعلان البيانات الآتية:
1- موضوع المسابقة والغرض منها.
2- مكان وموعد الحصول على مستندات المسابقة والإشارة إلى إمكانية الاطلاع عليها على بوابة التعاقدات العامة.
3- موعد ومكان تقديم عروض المتسابقين.
4- معايير وأسس تقييم المتسابقين.
5- الجوائز أو المكافآت الممنوحة للفائزين.
وغيرها من البيانات التى تراها الجهة الإدارية ضرورية.
تتولى إدارة التعاقدات استلام وحصر العروض المقدمة من المتسابقين وإثبات عددها بموجب محضر يعد لذلك.
وتسلم العروض المقدمة من المتسابقين إلى لجنة التحكيم وذلك دون الإفصاح عن هوية المتسابقين.
تتولى لجنة التحكيم دراسة العروض المقدمة من المتسابقين طبقا للأسس والمعايير المحددة مسبقا، ولها فى سبيل ذلك طلب أى إيضاحات من المتسابقين وذلك بمعرفة إدارة التعاقدات على أن تعد اللجنة تقريرا متضمنا نتيجة دراستها للعروض المقدمة من قبول، أو استبعاد على أن يكون قرارها نافذا بعد اعتماد السلطة المختصة له.
وتتولى إدارة التعاقدات نشر نتائج المسابقة على بوابة التعاقدات العامة فور اعتماد السلطة المختصة لتلك النتائج ويجب أن توثق كافة الإجراءات التى تمت.$m260$,'2c689c68c82bedb7fba2ac81bc7f822e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(138,0,1,$m260$على الجهة الإدارية ألا تبقى بالمخازن أصناف زائدة عن حاجتها، أو مستغنى عنها، أو بطل استعمالها، أو يخشى عليها من التلف، أو غير صالحة للاستعمال، ويتم تحديد المسئولية فى حالة بقاء الأصناف التى يتقرر الاستغناء عنها لمدة تزيد على سنة من تاريخ تقرير الاستغناء عنها دون العرض على السلطة المختصة بذلك، تجنبا لتراكم الأصناف بالمخازن.
ويتعين على إدارة التعاقدات التنسيق مع إدارة المخازن لإعداد حصر بالأصناف المستغنى عنها، يتم عرضه على السلطة المختصة متضمنا مقترح التصرف، وفى حالة إذا ما قررت السلطة المختصة التصرف بالبيع تتولى إدارة التعاقدات إعداد توقيتات للتصرف بالبيع، أو التأجير، والترخيص بالانتفاع، أو بالاستغلال يتم نشرها على بوابة التعاقدات العامة، ويجوز للجهة الإدارية الاتفاق مع الهيئة العامة للخدمات الحكومية لقيامها بتولي الإجراءات نيابة عن الجهة الإدارية فى حدود أحكام القانون وهذه اللائحة.
وإذا كانت الجهة الإدارية متعاقدة مع مقدم خدمة للقيام بعملية البيع، أو التأجير، أو الترخيص بالانتفاع، أو بالاستغلال فإنه يقوم بإجراءات الإعلان على حسابه طبقا لشروط تعاقده مع الجهة الإدارية، على أن يكون من المقيدين بسجل الخبراء المثمنين، وتقتصر مهمته على القيام بأعمال الدلالة فقط دون الاشتراك فى أعمال لجان وضع الثمن الأساسى، ويراعى أن يتم التعاقد مع مقدم الخدمة فى حدود أحكام القانون وهذه اللائحة.$m260$,'f91e585f277b8e3f2eb8f7cbdb9474c5',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(139,0,1,$m260$يعمل فى شأن التعاقد بطريق المزايدة العلنية العامة على بيع وتأجير المنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف بالإجراءات المنظمة لمرحلة ما قبل الطرح ومرحلة الطرح ومرحلة الترسية والتعاقد المنصوص عليها فى هذه اللائحة.$m260$,'b767a8f419b39977740011a2c40006de',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(140,0,1,$m260$تسرى على المزايدة المحدودة والمحلية إجراءات المزايدة العلنية العامة ذاتها فيما لم يرد بشأنه نص خاص فى هذه اللائحة.$m260$,'0a97f72325e498b7589eadd996e9c839',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(141,0,1,$m260$على لجنة المزايدة أن تعلن للمتزايدين فى بداية جلسة المزايدة العلنية العامة البيانات والمواصفات الكافية عن موضوع البيع، أو التأجير، أو الترخيص بالانتفاع، أو بالاستغلال دون ذكر الثمن الأساسى، ثم تتولى إجراءات التزايد مع المتزايدين من خلال جولة أو عدة جولات فى الجلسة ذاتها للوصول لأعلى سعر مستوفى للشروط.
ويجوز فى الحالات الاستثنائية أن تكون جلسة التزايد على أكثر من يوم لكل مجموعة أو أكثر على حده، شريطة أن تتضمن شروط الطرح ذلك وأن تكون لكل مجموعة ثمن أساسي منفصل فى ظروف مغلقة.
وفى جميع الحالات يحظر إعادة فتح باب التزايد مرة أخرى لما تم الانتهاء من التزايد عليه.
كما يحظر الاتفاق بين المتزايدين قبل أو أثناء جلسة المزايدة لتحقيق غرض غير مشروع أو للإخلال بمبدأي تكافؤ الفرص وحرية المنافسة بما فى ذلك التأثير بشكل مباشر أو غير مباشر على تصرفات طرف آخر، بهدف تقسيم العقود أو تثبيت الأسعار بشكل غير تنافسى، وفى حالة تبين ذلك يتم اعمال حكم المادة (50) من القانون.
ويكون ترسية المزايدة على أعلى سعر مستوفى للشروط بشرط ألا يقل عن الثمن الأساسى، وتحرر لجنة المزايدة محضرا بإجراءاتها تبين فيه قيمة التأمينات المؤقتة المؤداة من المتزايدين وما تم رده وما تم مصادرته، ويتم التوقيع من جميع أعضاء اللجنة ورئيسها على المحضر.
وتعتمد قرارات وتوصيات لجنة المزايدة من السلطة المختصة.$m260$,'c566a81d5d21b1df7e7b91dc6a97500e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(142,0,1,$m260$فى حالة إجراء البيع، أو التأجير، أو الترخيص بطريق المزايدة بالمظاريف المغلقة تطبق الشروط والقواعد ذاتها والإجراءات المنصوص عليها بهذه اللائحة بشأن التعاقد بطريق المناقصة العامة، وبما لا يتعارض مع طبيعة البيع، أو التأجير، أو الترخيص.$m260$,'494b220bee673c175e20dbfaabe10937',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(143,0,1,$m260$يجب النشر عن المزايدة المحدودة على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد من المسجلين عليها المتخصصين، أو المؤهلين المشتغلين بنوع النشاط المزمع طرحه، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لجلسة المزايدة، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.$m260$,'9664e809f89ddaecbdf18be96b35e71b',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(144,0,1,$m260$يجب النشر عن المزايدة المحلية على بوابة التعاقدات العامة وتوجيه الدعوة لأكبر عدد ممكن من المسجلين عليها المتخصصين، أو المؤهلين المشتغلين بنوع النشاط المزمع طرحه، والذين يقع نشاطهم داخل نطاق المحافظة التى يقع فى دائرتها موضوع البيع، أو التأجير، أو الترخيص، وذلك بمدة لا تقل عن أربعة عشر يوما قبل الموعد المحدد لجلسة المزايدة، ويجوز بموافقة السلطة المختصة فى حالة الاستعجال تقصير مدة توجيه الدعوة بحيث لا تقل عن عشرة أيام وتحتسب المدة من تاريخ توجيه الدعوة.
ويجوز لإدارة التعاقدات بالجهة الإدارية قبل عرض مذكرة الطرح على السلطة المختصة إخطار فرع جهاز تنمية المشروعات المتوسطة والصغيرة والمتناهية الصغر الواقع بالمحافظة التى يتم بدائرتها موضوع البيع، أو التأجير، أو الترخيص، لحث أصحاب تلك المشروعات المتخصصين، أو المؤهلين المشتغلين بنوع النشاط المزمع طرحه لتسجيل بياناتهم، أو تحديثها على بوابة التعاقدات العامة، على أن يقوم فرع الجهاز بموافاة الجهة الإدارية بأسماء وبيانات المهتمين منهم للدخول فى المزايدة لدعوتهم وذلك خلال موعد أقصاه خمسة أيام من تاريخ تسلمه اخطار الجهة الإدارية.$m260$,'cb7629678b25a4421accdfbbe29553cd',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(145,0,1,$m260$تسرى على بيع وتأجير المنقولات والعقارات والمشروعات التى ليس لها الشخصية الاعتبارية والترخيص بالانتفاع، أو استغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف ذات القواعد والإجراءات المنظمة لشراء المنقولات، أو استئجارها فيما لم يرد بشأنه نص خاص، وذلك كله بما لا يتعارض مع طبيعة البيع، أو التأجير، أو الترخيص أو الاستغلال.$m260$,'244c0d60a4344d3aba75cfcd1e1952ca',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(146,0,1,$m260$يكون التعاقد على بيع أو تأجير المنقولات أو العقارات أو المشروعات التى ليس لها الشخصية الاعتبارية أو الترخيص بالانتفاع أو باستغلال العقارات والمشروعات بما فى ذلك المنشآت السياحية والمقاصف بطريق الاتفاق المباشر وفقا لأحكام المادة (71) من القانون، وباتباع الإجراءات ذاتها المنصوص عليها بالمادة (130) من هذه اللائحة، وبما لا يتعارض مع طبيعة البيع أو التأجير أو الترخيص.
ويشترط فى جميع الحالات ألا تقل قيمة البيع، أو التأجير، أو الترخيص عن الثمن الأساسي التى قدرتها لجنة وضع الثمن الأساسى.$m260$,'92c55fed03d469f8736bf3bbd14f0db3',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(147,0,1,$m260$يكون تسليم الأصناف المباعة بمعرفة لجنة تشكل بقرار من السلطة المختصة يرأسها موظف مسئول وعضوية أمين المخزن المختص وعضو يندبه مدير المخازن من غير أمناء المخازن بالإضافة لمن ترى السلطة المختصة أهمية ضمهم لعضوية اللجنة، وعلى اللجنة مراعاة أن يكون التسليم حسب التقسيم الذى أجرته لجنة التصنيف من حيث الكمية والمواصفات وما أسفرت عنه قرارات البيع.
ويكون تسليم محل البيع، أو التأجير، أو الترخيص بالنسبة لغير المنقولات بمعرفة لجنة يصدر بتشكيلها قرار من السلطة المختصة برئاسة موظف مسئول وتضم فى عضويتها عناصر فنية ومالية وقانونية بحسب أهمية وطبيعة محل التسليم، وعلى اللجنة أن تراعى عند التسليم التحقق من تنفيذ ما أسفرت عنه من قرارات البيع، أو التأجير، أو الترخيص.$m260$,'647141221da547a945e1295b68557171',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(148,0,1,$m260$فى عمليات تأجير المنقولات والعقارات والمشروعات والترخيص بالانتفاع أو باستغلال العقارات والمشروعات التى ليس لها الشخصية الاعتبارية يجب الحصول على موافقة السلطة المختصة بالجهة الإدارية متضمنة المدة الاقتصادية للتعاقد والأسس التى استند إليها فى تحديدها وفقا للدراسة الفنية والمالية لموضوع التعاقد.
ويجب تضمين شروط الطرح الآتى:
1- طبيعة النشاط محل الطرح بشكل محدد.
2- مدة التعاقد واشتراطات مدها إذا ارتأت الجهة الإدارية مناسبة ذلك مع بيان الحد الأقصى للمد والأسس الاقتصادية التى استندت إليها الجهة الإدارية فى تحديدهما، وفى حالات المشروعات ذات الطبيعة الخاصة التى تتطلب استثمارات ضخمة لإنجازها واستغلالها يتعين على الجهة الإدارية اعداد دراسة جدوى اقتصادية لها توضح بها الأسس التى استندت إليها فى تحديدها لمدة التعاقد والحد الأقصى لمدها، وذلك كله دون الإخلال بمبادئ العلانية والشفافية والنزاهة وحرية المنافسة وتكافؤ الفرص.
3- مواعيد السداد وجزاء عدم الالتزام بها.
4- زيادة المقابل سنويا بنسبة مئوية من قيمة التعاقد التراكمية.
5- حظر التنازل للغير عن محل العقد أو اتاحته للغير من الباطن بعد التعاقد.
6- النص على التزام المتعاقد وعلى نفقته بإجراء ما يلزم من تجهيزات وأعمال تطوير وصيانة مستمرة لمحل التعاقد ضمانا لإعادته للجهة المالكة بحالة جيدة فى نهاية المدة.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة بما يتماشى مع طبيعة العملية.
ويجوز أن تتضمن شروط الطرح تقديم تسهيلات وبما يتفق مع محل العقد وتحقيقا لاقتصاديات المشروع.
ويتعين قبل نهاية مدة التأجير أو الترخيص اتخاذ إجراءات الطرح من جديد فى الوقت المناسب بإحدى الطرق المنصوص عليها بالمادة (7) من القانون وفى حدود القواعد والإجراءات المنصوص عليها بهذه اللائحة وأن تقوم الجهة الإدارية بحصر ما تم من تجهيزات وغيرها فى نهاية كل مدة وقبل اعادة الطرح وأخذ ذلك فى الاعتبار عند تحديد القيمة الإيجارية أو مقابل الانتفاع.$m260$,'a64db6406556dce4ffec30f970895b63',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(149,0,1,$m260$يكون التعاقد على الدراسات الاستشارية وفقا لأحكام المادة (73) من القانون، ويتعين على إدارة التعاقدات اتباع طريق المناقصة المحدودة، أو المناقصة ذات المرحلتين أو المناقصة المحلية، ويكون التعاقد مع من تتوافر بشأنهم شروط الكفاءة الفنية والملاءة المالية وحسن السمعة من استشاريين.
ويجوز استثناء التعاقد بطريق المناقصة العامة، أو المحلية، أو الاتفاق المباشر على الدراسات الاستشارية فى العمليات ذات الطبيعة الروتينية، أو البسيطة، أو النمطية، أو التى لها أطر فنية ثابته، ومن ذلك أعمال المراجعة، إعداد التصميم، وغيرها من أعمال غير معقدة.
كما يجوز التعاقد مع أحد الاستشاريين بذاته من خلال مناقصة محدودة، أو مناقصة محلية، أو اتفاق مباشر، وذلك عندما يكون المؤهل والخبرة شرطين أساسيين في العملية.$m260$,'a58699f36eacc07a985f13b0e0272160',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(150,0,1,$m260$يجوز لإدارة التعاقدات إجراء تأهيل مسبق للاستشاريين المحتمل دعوتهم للاشتراك فى العملية المزمع طرحها، وذلك باتباع الإجراءات المنصوص عليها بالمادة (21) من القانون، والمواد أرقام (37)، (38)، (39)، (40) من هذه اللائحة، وبما لا يتعارض مع طبيعة الدراسات الاستشارية، مع اعداد قائمة مختصرة بمن تم تأهلهم ممن لديهم القدرة على أداء المهمة المطلوبة وفقا لمتطلبات التأهيل حال الطرح.$m260$,'e6fe0e42b14e3bb3bf28eaff5618f64e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(151,0,1,$m260$يتعين على الجهة الادارية أن تضمن مستندات الطرح متطلباتها واشتراطاتها وإطار أعمال الدراسات الاستشارية، على أن يكون من بينها البيانات الآتية:
1- وصف عام للعملية والغرض منها وأهدافها بما يتلاءم مع احتياجات الجهة الإدارية.
2- نطاق الدراسة والمهام المطلوب من الاستشاري تنفيذها والعناصر الأساسية لها والاختصاصات وغيرها من متطلبات.
3- المخرجات المطلوب تقديمها بما فى ذلك التقارير، أو البيانات، أو المعلومات، أو الخرائط، أو الاحصائيات، أو التصميمات وغيرها، والجدول الزمنى لتقديم كل منها.
4- وصف للتكنولوجيا، أو الخبرات المطلوب استخدامها فى تنفيذ موضوع التعاقد وكيفية تدريب العاملين بالجهة الإدارية عليها.
5- بيان مفصل ببيانات الكوادر الفنية الاساسية المطلوبة ومهامهم ومؤهلاتهم وخبراتهم وحجم المهام المسندة لكل منهم في العملية.
6- محل تنفيذ العملية موضوع التعاقد.
7- المدخلات والتسهيلات الفنية التى ستقدمها الجهة الإدارية المتعاقدة للاستشاري.
8- المدد الزمنية لتنفيذ المهام محل العملية على أن تكون محددة بعدد الأيام، أو الأشهر، أو السنوات بحسب طبيعة العملية، والتاريخ المقترح للبدء والانتهاء من المهام كاملة.
9- شكل التقارير المطلوب تقديمها وإجراءات وشروط تقديمها.
10- الاطار العام لمعايير التقييم.
وغيرها من البيانات التى ترى الجهة الإدارية أهمية تضمينها.
ويراعى عدم المبالغة فى التفاصيل الغير ضرورية أو وضع متطلبات مقيدة، وبما يمكن أصحاب العطاءات من تقديم عروضهم بشكل ابتكاري يحقق للجهة الادارية متطلباتها بالجودة المرجوة.$m260$,'282e5e5d60182a6788f58503aa0d1833',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(152,0,1,$m260$يكون تحديد القيمة التقديرية لعقود الدراسات الاستشارية على أساس تقدير التكاليف الكلية لأداء الاستشاري للمهمة المطلوبة، ومنها تكاليف فريق العمل والكوادر والوقت المستغرق فى تنفيذ العقد وغير ذلك من تكاليف وفقا لطبيعة العملية، ويتم تحديدها على سبيل المثال وفقا لأى من الأسس الآتية:
1- التعاقد على أساس مبلغ مقطوع، وذلك فى المهام التي يكون فيها مضمون ومدة الخدمات والنتائج المطلوبة من الاستشاري محددة، ومن ذلك على سبيل المثال عمليات التخطيط البسيطة، دراسات الجدوى، التصميمات الهندسية.
2- التعاقد المبنى على الوقت، وذلك في المهام التي يكون من الصعب تحديد نطاق الخدمات وطول مدة التنفيذ بدقة، ومن ذلك الدراسات التى تتطلب أكثر من تخصص، الإشراف على تنفيذ الأعمال، مهام التدريب، ويجب أن تتضمن هذه العقود حد أقصى لإجمالي قيمة العقد، وبصفة عامة يتطلب هذا النوع من العقود وجود فريق اشراف لديه القدرة والخبرة على تقييم الاداء.
3- التعاقد على أساس النسبة المئوية، وذلك في المهام التى منها الفحص، والمراجعة، والتدقيق، ويكون فيه احتساب النسبة وفقا لما هو سائد ومتعارف عليه في السوق لمحل موضوع التعاقد.$m260$,'e7c6c104cd0ab91d0a3d6f6e8dab2465',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(153,0,1,$m260$بمراعاة أحكام المادة (19) من القانون وكراسات الشروط النموذجية الصادرة من الهيئة العامة للخدمات الحكومية تلتزم إدارة التعاقدات بتضمين كراسات شروط عمليات التعاقد على الدراسات الاستشارية بحد أدني البيانات الآتية:
1- تحديد طريق التعاقد المناسب وفقا لما تضمنته المادة (73) من القانون.
2- وسيلة وأسلوب التواصل مع الجهة الإدارية بما في ذلك عنوان وتليفون ورقم فاكس وبريد الكرتوني واسم المخول له التواصل مع المتعاملين.
3- ما يفيد توافر الاعتماد المالى المخصص للعملية.
4- البيانات الواجب توافرها فى أصحاب العطاءات ومعايير التحقق من توافر شروط الكفاءة الفنية والملاءة المالية وحسن السمعة.
5- صور سداد التأمين المؤقت ومبلغه والتأمين النهائى ونسبته.
6- المدة المناسبة لصلاحية سريان العطاءات.
7- توصيف المهمة وإطار الاعمال الاستشارية والمتطلبات والاشتراطات وفقا لما تضمنته المادة (151) من هذه اللائحة.
8- طلب بيان بأسماء ووظائف وخبرات الكوادر التى ستقوم بالمهمة.
9- شهادات ترخيص سارية للمكاتب الاستشارية.
10- تحديد مراحل تنفيذ العمل للمهمة حسب طبيعة كل عملية (التصميم، الإشراف...إلخ).
11- تحديد التسهيلات التى ستقدم للاستشاريين، وامكانية اتاحة الفرصة لهم للاطلاع على كافة البيانات والمعلومات اللازمة لتنفيذ المهمة.
12- تحديد أسلوب السداد وفقا لطبيعة العملية وتوقيتاته.
13- تحديد المدخلات والمستلزمات التى توفرها الجهة الإدارية للاستشاري أثناء أدائه واجباته.
14- تحديد المخرجات المطلوبة من تقارير، أو بيانات، أو خرائط، أو دراسات استقصائية وغيرها من مخرجات مع تحديد الجدول الزمنى لتسليمها وتقديم التقارير المطلوبة والتاريخ الذى يبدأ فيه الاستشاري الفائز بتقديم خدماته.
15- أسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول.
16- تحديد البنود التى يجوز لصاحب العطاء أن يعهد بها إلى غيره من الباطن إذا تطلبت طبيعة العملية ذلك، وكذا المحددات والاشتراطات الأخرى ذات الصلة.
17- تقديم إقرار بعدم وجود تضارب محتمل فى المصالح لأعمال الاستشاري.
وغير ذلك من بيانات تراها الجهة الإدارية لازمة.
وفى حالة إذا ما تعذر على الجهة الإدارية توفير الكوادر الفنية من العاملين بها لإعداد كراسة الشروط والمواصفات يجوز لها الاستعانة بذوي الخبرة من العاملين بالجهات الإدارية الأخرى، وإذا تعذر ذلك يجوز التعاقد مع استشاري بذاته لإعدادها وفقا لحكم المادة (73) من القانون.$m260$,'e5ceb20d0337361254b5eafd7998ea33',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(154,0,1,$m260$تقدم العطاءات وفقا لأحكام المادة (23) من القانون، وطبقا للمدد المنصوص عليها بالمادة (45) من هذه اللائحة والمحددة بكراسة الشروط والمواصفات.$m260$,'9f1a63c986eaca45c5805b8e70b52234',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(155,0,1,$m260$يجب أن يحتوى المظروف الفنى فى عمليات الدراسات الاستشارية كحد أدنى على الآتى:
1- ما يفيد سداد التأمين المؤقت المطلوب طبقا لكراسة الشروط والمواصفات.
2- بيان الشكل القانوني للاستشاري والمستندات الدالة على ذلك.
3- بيانات القيد بالنقابات المهنية وفقا لطبيعة العملية.
4- ما يفيد شراء كراسة الشروط والمواصفات.
5- الاشتراطات والمتطلبات الفنية الواردة بكراسة الشروط والمواصفات ووفقا لما تضمنته المادة (153) من هذه اللائحة.$m260$,'5ffa3e4e66149e67329964f12ca0ee96',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(156,0,1,$m260$فى عمليات الدراسات الاستشارية يتعين أن يحتوى المظروف المالى للاستشاري على تكلفة أداء المهمة، ومنها أتعاب فريق العمل والكوادر وتكاليف الوقت المستغرق فى تنفيذ المهمة والمخرجات من خرائط وتقارير وغيرها من عناصر التكلفة أو متطلبات، ووفقا لما تضمنه الجهة الادارية بكراسة الشروط والمواصفات.$m260$,'636c8aa2a653dd75c34b8f63fb2185b3',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(157,0,1,$m260$بمراعاة أحكام الفقرة الأولى من المادة (73) من القانون والمادة (72) من هذه اللائحة، يكون تقييم العطاءات بنظام النقاط وذلك بغرض الوصول إلى معايير الجودة الفنية والسعر مجتمعين على أن تتضمن شروط الطرح أسس وعناصر التقييم والوزن النسبى والحد الأدنى للقبول، ومنها على سبيل المثال الآتى:
1- الاستجابة لشروط الطرح.
2- المؤهلات العلمية والأكاديمية للاستشاري.
3- حجم الأعمال المماثلة.
4- عدد سنوات الخبرة.
5- الجدول الزمنى لتسليم المخرجات المطلوبة.
وغيرها من أسس وعناصر التقييم التى تراها الجهة الإدارية ضرورية.
واستثناء من ذلك، وبمراعاة أحكام الفقرة الثانية من المادة (73) من القانون، تكون الترسية على الأقل سعرا من العروض المقبولة فنيا، أما في الحالات الواردة بالفقرة الثالثة من المادة ذاتها تكون الترسية فيها إما بنظام النقاط، أو الاقل سعرا بحسب الاحوال.$m260$,'b2c335819511f03b84b0e081b1998429',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(158,0,1,$m260$يتعين على الاستشاري الالتزام بأعلى معايير النزاهة والشفافية عند التقدم بعطائه، أو اثناء تنفيذ العقد، كما يلتزم بتجنب تعارض المصالح فى المهام التى سوف يقوم بها ومهامه الأخرى، أو سابق تعاملاته مع أصحاب العطاءات الأخرين.
وتتولى ادارة التعاقدات الحصول على إقرار من الاستشاري يفيد تعهده بتجنب تعارض المصالح، وأنه فى حالة مخالفته لذلك فسوف يتم استبعاده، أو فسخ العقد، بحسب الأحوال، واتخاذ الإجراءات المنصوص عليها بالقانون وهذه اللائحة، ويحفظ الاقرار فى ملف العملية.$m260$,'a298476b5e51189458143b9bf708206d',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(159,0,1,$m260$يسرى على التعاقد على الدراسات الاستشارية ذات الإجراءات المنصوص عليها بهذه اللائحة بشأن عقود شراء أو استئجار المنقولات والتعاقد على مقاولات الأعمال وتلقى الخدمات والأعمال الفنية، فيما لم يرد فى شأنه نص خاص، وذلك كله بما لا يتعارض مع طبيعة الدراسات الاستشارية.$m260$,'2f196eae9ae467eb2d214c47152babca',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(160,0,1,$m260$تتولى إدارة التعاقدات رفع مذكرة للسلطة المختصة للموافقة على التعاقد بالاتفاق المباشر مع مقدمى الخدمات الاساسية التى تمتلك الدولة فيها حصة حاكمة تسمح لها بتعيين أغلبية أعضاء مجلس إدارتها، أو التحكم على أى نحو فى القرارات الصادرة من مجلس إدارتها، أو من الجمعية العامة لها على تقديم الخدمات الأساسية ومن ذلك الكهرباء، والمياه، والغاز وغيرها من الخدمات الأساسية اللازمة لتسيير المرفق العام ذات الطبيعة المماثلة والمحددة أسعارها من الدولة، على أن تتضمن المذكرة الأسباب ومبررات هذا التعاقد وأسماء مقدمى تلك الخدمات، وغيرها من إجراءات منصوص عليها بالمادة.
تتولى إجراءات التعاقد لجنة تشكل بقرار من السلطة المختصة تضم عناصر فنية مالية وقانونية وعضو من إدارة التعاقدات، ويكون اعتماد أعمالها من السلطة المختصة أو من تفوضه.$m260$,'c74a9aa16470a808136319995c171284',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(161,0,1,$m260$يجب على إدارة التعاقدات مراعاة إمكانيات المشروعات المتوسطة والصغيرة والمتناهية الصغر، وذلك بهدف تعظيم حجم الفرص المتاحة لهم من خلال تبسيط الإجراءات اللازمة لتسجيلهم ومراعاة تحديد أسس ومعايير موضوعية مسبقة عند اتخاذ إجراء التأهيل المسبق لهم وبما يتماشى مع طبيعة العملية.
ويتعين عند اعداد كراسات الشروط والمواصفات مراعاة الآتى:
1- اعداد مواصفات فنية تراعى امكانيات المشروعات المتوسطة، والصغيرة، والمتناهية الصغر وبما يتلاءم مع الاداء والغرض المطلوب، ودون أن يؤثر ذلك على تكافؤ الفرص والالتزام بمعايير الجودة والأداء فى التنفيذ.
2- الاعفاء من سابقة الأعمال وميزانية سنوات سابقة ما دامت طبيعة العملية لا تتطلب ذلك.
3- عدم المبالغة فى تحديد مبلغ التأمين المؤقت، أو الإعفاء منه وفقا لحكم المادة (59) من القانون.
وغير ذلك من إجراءات تهدف إلى تعظيم حجم الفرص المتاحة لهم.
ويجب على إدارة التعاقدات الالتزام بالنسبة المحددة بالمادة (75) من القانون، واعداد تقارير ربع سنوية ترفع إلى السلطة المختصة متضمنة قيمة ما تم ترسيته من عمليات على تلك المشروعات خلال تلك الفترة وفقا لخطة احتياجات الجهة الإدارية المعتمدة والتوصيات اللازمة لضمان الالتزام بالنسبة المحددة.$m260$,'13912de63fd61be613e734847eb362b4',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(162,0,1,$m260$مع عدم الإخلال بأحكام القوانين المنظمة للتعاقدات المقدمة بناء على مبادرة من القطاع الخاص، يجوز للجهة الإدارية عندما تتلقى عرض لمشروع استثماري متكامل شامل التمويل سواء كان مقدمه شخص طبيعي، أو اعتباري بناء على مبادرة منه وليس استجابة لطلب رسمي من خلال طرق التعاقد الواردة بالمادة (7) من القانون، أن تقوم بدراسة المشروع وإخطار مقدمه بذلك، أو ترفضه وتخطر مقدمة بأنها لن تأخذه في الاعتبار، دون أن يرتب ذلك علي الجهة الإدارية أى التزامات تجاه مقدمه.
وحال دراسة الجهة الادارية للمشروع ينطوي على حقوق ملكية فكرية لمقدمه وتري الجهة الإدارية أن تنفيذه يحقق الاهداف الاقتصادية والتنموية للدولة وأن له جدوى فنية واقتصادية واجتماعية، فيجوز لها أن تطلب من مقدمه تقديم عرضه متضمن كافة البيانات الفنية والاقتصادية والمالية والتعاقدية والدراسات التفصيلية ذات الصلة به، وبما يمكنها من تقييمه بشكل تفصيلي متكامل.
وإذا ما تحققت الجهة الإدارية بعد دراستها التحليلية للمشروع فى ضوء ما قدمه المستثمر من بيانات فنية واقتصادية ومالية وتعاقديه ودراسات تفصيلية، وقامت بإجراء حوار مفتوح واستطلاع وتحليل وتقييم السوق بشأنه وانتهت الى أن المشروع وشروطه يحققا الأهداف الاقتصادية والتنموية للدولة، فتطلب من مقدمه أن يتقدم بالمشروع فى شكل نهائى، ويعرض الوزير المختص بالجهة الادارية تفاصيله على وزيري المالية والتخطيط لإعمال شئونهما، على أن يخطرا الوزير المختص بالجهة الادارية بنتائج دراستهما.
وعلى الوزير المختص بالجهة الإدارية عرض المشروع وما تم بشأنه من إجراءات على مجلس الوزراء بما في ذلك نتائج الجدوى الفنية والاقتصادية والاجتماعية له والدراسة التحليلية للهيكل الفنى والمالى ودراسات السوق ونتائجها وموافقة وزيري المالية والتخطيط، وحال اعتمادها من مجلس الوزراء، يتم الترخيص للجهة الادارية بالسير في إجراءات التعاقد على المشروع بالاتفاق المباشر، اما فى حالة رفض المشروع فيتم إعادة كافة المستندات الخاصة به لمقدمه.
ويجوز للجهة الإدارية حال عدم انطواء المشروع علي حقوق ملكية فكرية حصرية لمقدمه أن تقوم بطرحه على مقدمه وغيره للحصول على عروض تنافسية له، وذلك بما لا يخل بمبادئ الشفافية والمنافسة وتكافؤ الفرص والمساواة، ويكون التعاقد وفقا للأطر العامة والإجراءات والشروط الواجب اتباعها وضوابط إبرامه التى يعرضها الوزير المختص بحسب طبيعة المشروع والتى تقرها لجنة المؤشرات والتغيرات الاقتصادية المنصوص عليها فى المادة (4) من القانون.$m260$,'873852fd4510b7399a8a66796f3d8099',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(163,0,1,$m260$يجوز للجهة الإدارية استثناء من أحكام القانون التعاقد على الصفقات التى تتطلب السرعة فى اتخاذ قرار التعاقد عليها بحكم طبيعتها أو التقلبات فى أسعارها وكمياتها الاقتصادية، أو التى تغطى مدى زمنى مستقبلي، أو العمليات المتعلقة بالمعاملات المنجزة فى الأسواق المالية الدولية، أو عقود المشتقات المالية والمشتريات الآجلة والمستقبلية وما يرتبط بها، وذلك كله وفقا للممارسات التجارية الدولية المطبقة التى تحددها السلطة المختصة بالجهة الإدارية.
وتتولي السلطة المختصة بالجهة الإدارية طالبة التعاقد تحديد الممارسات التجارية الدولية ذات الصلة بالموضوع محل طلبها والتى ستتبعها عند اتخاذها إجراءات التعاقد استثناء من أحكام القانون، على أن يتم عرضها على اللجنة الوزارية للمؤشرات والتغيرات الاقتصادية المنصوص عليها فى المادة (4) من القانون لدراستها واعداد تقرير بنتائج أعمالها وتوصياتها يعرضه مقرر اللجنة على مجلس الوزراء لاعتماده واتخاذه ما يلزم من إجراءات لتنفيذ ما ورد به.
كما يجوز للجهة الإدارية استثناء من أحكام القانون إبرام أي من التعاقدات الواردة بالفقرة الثانية من المادة (79) من القانون إذا كانت تحقق لها أهدافها الاقتصادية والتنموية العاجلة، أو استلزمت الظروف الاقتصادية، أو الاجتماعية سرعة إتمامها فى توقيت معين.
وبمراعاة الأطر العامة والإجراءات والشروط الواجب اتباعها والضوابط التى تعدها لجنة المؤشرات والتغيرات الاقتصادية المنصوص عليها فى المادة (4) من القانون والتى يعتمدها مجلس الوزراء ويصدر بشأنها دليل إجرائي ينظم إبرام أي من تلك العقود، يتعين على الجهة الإدارية عند النظر في التعاقد على أى منها التحقق من استيفاء دراسات الاحتياج للمشروع محل التعاقد وأولوية تنفيذه، وتوافر دراسات جدوى اقتصادية دقيقة ومقبولة لكافة الاطراف المعنية، ودراسات الجدارة الائتمانية للشركاء ومصادر التمويل والمخاطر ذات الصلة وغيرها، ووجود خطة أو برنامج مالي واضح يبرر تكلفة المشروع، وكيفية السداد وحجم رأس المال المقدم من القائمين عليه، والتأكد من توافر مواصفات معيارية فنية للمشروع كاملا ، ودراسات لاقتصاديات التنفيذ والتشغيل طوال مدة المشروع أو مدة العقد، وإمكانية توفير جميع الموافقات والتراخيص اللازمة للتنفيذ، ودراسات تؤكد ربحية المشروع مع الاخذ في الاعتبار صيانته واستبدال الأصول المتقادمة خاصة في السنوات الأخيرة من مدة المشروع أو العقد، وتكوين احتياطيات من إيراداته لاستخدامها في عمليات التجديد والصيانة والاحلال وبما يتماشى مع طبيعة المشروع والعقد، وغيرها من أمور ذات صله ترتبط بطبيعة المشروع.
ويكون التعاقد على أي من هذه المشروعات إما بالإعلان عنه أو توجيه الدعوة لقائمة مختصرة من المستثمرين المرشحين لتقديم عروضهم، أو بطريق الاتفاق المباشر في حالة عدم تقدم أكثر من مستثمر مؤهل، أو إذا وصل أكثر من مستثمر مؤهل إلى قائمة المرشحين ولم يقدم أكثر من واحد منهم عرض يستوفي المتطلبات، أو في حالة وجود مصدر واحد فقط مؤهل لتنفيذ المشروع، أو إذا كانت هناك حاجة عاجلة لتنفيذه مثل التأكد من استمرار تقديم الخدمات العامة، أو غيرها مما يجعل اللجوء إلى تنفيذ إجراءات الاختيار التنافسية أمرا غير عملي، وفي جميع الحالات يجب أن تحتوى كراسة الشروط والمواصفات على كافة المعايير والمتطلبات والاشتراطات الفنية والمالية والتعاقدية.
ويتولى الوزير المختص بالجهة الإدارية المتعاقدة وضع القواعد الخاصة بكل مشروع على حدا بالاتفاق مع وزيري المالية والتخطيط، ويجب اعتماد هذه القواعد الخاصة من مجلس الوزراء بناء على عرض الوزير المختص بالجهة الإدارية، وذلك بما لا يتعارض مع الأطر العامة والإجراءات والشروط الواجب اتباعها وضوابط إبرام أى من تلك العقود والمعتمدة من مجلس الوزراء والصادر بشأنها دليل إجرائي ينظمها.$m260$,'29e39576b97ce174ad2c28ab64fabcce',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(164,0,1,$m260$مع مراعاة الحالات التى حظر فيها القانون التفويض، يجوز للسلطة المختصة أن تفوض فى أى من اختصاصاتها لشاغلى الوظائف القيادية دون غيرهم، على أن يكونوا ممن يشهد لهم بالكفاءة والخبرة والتمتع بصفات النزاهة والأمانة وحسن السمعة والخبرة اللازمة لممارسة الاختصاصات المفوضة لهم، شريطة أن يصدر قرار من السلطة المختصة يتضمن أسم المفوض ووظيفته وموضوع التفويض ومدته وشروطه ومتطلباته، وينتهى التفويض بإلغاء القرار الصادر بشأنه أو انتهاء مدة التفويض أو الغرض منه.
ويحظر على المفوض تفويض الأخرين فى الاختصاصات المفوض فيها، ويجب على المفوض اعداد تقارير يعرضها على السلطة المختصة بشأن ما اتخذه من إجراءات مفوض فيها، كما يجب على السلطة المختصة الأصيلة مراجعة نتائج أعمال المفوض بشكل دائم للوقوف على مستوى أدائه واتخاذ ما يلزم بشأنه.$m260$,'9a99a83cf4c9695fc89d6cca25d7ded9',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(165,0,1,$m260$تلتزم إدارة التعاقدات بالحفاظ على المستندات والبيانات المتعلقة بإجراءات كل عملية وتوثيقها وأرشفتها بصورة منتظمة ومرتبة يسهل الرجوع إليها، والعمل على سلامة ملف العملية من أى مخاطر، أو تلف، أو ضياع، على أن يتضمن الملف بصفة خاصة الآتى:
1- صورة نموذج خطة الاحتياجات المتضمن العملية.
2- مستندات طلب المعلومات، ابداء الاهتمام، التأهيل المسبق، المسابقة إن وجدت.
3- تقرير لجنة اعداد المواصفات الفنية.
4- تقرير لجنة اعداد القيمة التقديرية أو الثمن الأساسى.
5- صورة من الموافقات والتصاريح والتراخيص اللازمة للطرح إن وجدت.
6- كراسة الشروط والمواصفات وملحقاتها.
7- مذكرة الطرح وقرارات تشكيل اللجان.
8- صورة قرار تفويض السلطة المختصة إن وجدت.
9- صورة ما يثبت نشر العملية على بوابة التعاقدات العامة.
10- أصل الإعلان بالصحيفة أو صور خطابات الدعوة بحسب الأحوال.
11- الاستفسارات إن وجدت، والرد عليها ومحضر لجنة الاستفسارات.
12- صور العطاءات المقدمة.
13- محاضر فتح المظاريف.
14- محاضر لجنة البت، أو الممارسة، أو المزايدة، أو الاتفاق المباشر بحسب الأحوال.
15- ما يثبت نشر نتائج قرارات اللجان على بوابة التعاقدات العامة.
16- جميع الإخطارات والمراسلات والمكاتبات المتعلقة بالعملية.
17- صورة من أمر التوريد، أو أمر الإسناد.
18- نسخة من العقد، أو الاتفاق بحسب الأحوال.
19- الشكاوى المقدمة إن وجدت، والرد عليها.
20- المستندات المتعلقة بتنفيذ العقد.
21- نموذج تقييم المتعاقد.
22- نموذج استقصاء المتعاقد مع الجهة الإدارية.
وغير ذلك من المستندات والبيانات ذات الصلة بالعملية.$m260$,'390b92865234b36ac79825ec20a60ddd',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(166,0,1,$m260$يتعين على كافة الجهات الإدارية والمتعاملين معها من مجتمع الأعمال والاطراف المعنية وغيرهم من جهات ذات صلة بتطبيق أحكام القانون وهذه اللائحة الاطلاع على ما تقوم الهيئة العامة للخدمات الحكومية بنشره على بوابة التعاقدات العامة من تعديلات على القانون وهذه اللائحة والأدلة والمنشورات العامة والكتب الدورية والقرارات المتعلقة بتطبيقهما، بما يهدف إلى سهولة وسرعة الوصول إلى التشريعات المنظمة للتعاقدات العامة وإرساء مبادئ الشفافية وإتاحة المعلومات.$m260$,'3548ef88fa3e29ce7121fdb6c8dba7ed',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(167,0,1,$m260$تظل المستندات والوثائق الورقية الصادرة من الجهات الادارية أو الواردة إليها قبل تاريخ صدور قرار وزير المالية بشأن بدء إتباع اجراءات التعاقد إلكترونيا لها الحجية القانونية، على أن تحل محلها المستندات والوثائق الرقمية التى تعمل عملها، أو تكون ناسخة.
ويتعين على كافة الجهات الإدارية والاطراف المعنية وغيرهم من جهات ذات صلة بالمهام التى تتم من خلال منظومة التعاقدات الإلكترونية الالتزام التام بالتحول للعمل من خلالها.
كما يتعين على المتعاملين مع الجهات الادارية من مجتمع الاعمال أن تكون مكاتباتهم أي كان شكلها، أو محتواها في شكل محرر الكتروني ووفقا لما يتم ميكنته من إجراءات يصدر بها قرار من وزير المالية.$m260$,'9392eb2e44d591b6d0acb09e9a90d711',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(168,0,1,$m260$يجب على الجهات الإدارية اتخاذ إجراءات التعاقد إلكترونيا وفقا لما يتم ميكنته من إجراءات على المنظومة الإلكترونية عند اكتمالها وانتظامها، والتى تتولى الهيئة العامة للخدمات الحكومية إعدادها والإشراف عليها وتقديم الدعم الفنى لمستخدميها.
تتكامل المنظومة مع بعض الأنظمة الأخرى بوزارة المالية والجهات التابعة ذات الصلة ومنها منظومة الدفع الإلكترونى وإدارة المعلومات المالية الحكومية (GFMIS) وغيرها، وتعمل الهيئة على ربطها بالأنظمة الإلكترونية الأخرى مرحليا.
تتضمن مهام المنظومة على سبيل المثال توفير إمكانية تنفيذ المهام الآتية:
1- استيفاء نماذج إعداد ونشر وتحديث خطط التعاقدات السنوية.
2- تجميع احتياجات الجهات الإدارية على مستوى الدولة.
3- اعداد نماذج الإعلان، الدعوة، الإخطارات، التقارير المطلوبة بموجب القانون وهذه اللائحة، كراسات الشروط والمواصفات والعقود بناء على الأنماط النموذجية الموحدة، نماذج أوامر التوريد أو الاسناد، وغيرها بصورة مميكنه وموحده.
4- تسجيل وتحديث بيانات الموردين والمقاولين ومقدمى الخدمات والاستشاريين على قاعدة البيانات الإلكترونية المركزية التي يمكن البحث فيها بشكل تفاعلي من قبل الجهات الإدارية وغيرها من أصحاب المصلحة والأطراف المعنية.
5- تسجيل المستخدمين الآخرين المرخص لهم باستخدام المنظومة، ومن بينهم أعضاء اللجان وممثلي كل من وزارة المالية وإدارة الفتوى المختصة بمجلس الدولة ووزارة الاسكان.
6- امكانية الربط والتبادل البيني مع قواعد بيانات الكترونية أخرى على سبيل المثال لأغراض التحقق من تسجيل الشركات وسداد الالتزامات الضريبية والتأمينات الاجتماعية.
7- تسجيل البنوك لأغراض السداد والدفع الالكتروني وغيرها من تعاملات بنكية مثل سداد التأمين المؤقت والنهائي الكترونيا، وغيرها من مهام وردت بالقانون وهذه اللائحة يمكن ميكنتها.
8- تسجيل الجهات الإدارية ويشمل ذلك مسئوليها المفوضين، بموجب تفويض من السلطة المختصة ووفقا لاختصاصاتهم ودور كل منهم في المهام التي يتم تنفيذها على المنظومة.
9- القيام بإجراءات دراسة السوق، وطلب المعلومات، وطلب إبداء الاهتمام، وطلب التأهيل المسبق، وغيرها.
10- اعداد المواصفات الفنية والتوقيع عليها من أعضاء اللجنة الفنية الكترونيا.
11- تحميل كراسة الشروط والمواصفات من على المنظومة، وامكانية سداد ثمنها الكترونيا.
12- تقديم العطاءات والطلبات وغيرها إلكترونيا، بطريقة آمنة ودون الإفصاح عن أصحابها، وحفظ العطاءات بطريقة آمنة لا تسمح بفتحها أو الاطلاع عليها قبل الموعد النهائي لتقديم العطاءات، والإقرار الآلي لمقدم العطاء باستلام عطائه.
13- فتح العطاءات إلكترونيا وتمكين أصحابها من متابعة إجراءات فتح العطاءات والاجتماعات الأخرى التى يجوز لأصحاب العطاءات، وفقا للقانون وهذه اللائحة حضورها.
14- التقييم والترسية، مع مراعاة أن تكون قرارات الترسية من قبل أشخاص طبيعيين وليس المنظومة.
15- الإعلان والإخطار عن قرارات اللجان ونتائج أعمالها.
16- شاشات معلومات لتمكين المشاركين من الموردين والمقاولين ومقدمى الخدمات والاستشاريين، والجهات الإدارية وممثلي كل من وزارة المالية وإدارة الفتوى المختصة بمجلس الدولة ووزارة الاسكان من الوصول إلى وظائف المنظومة وتأدية مهامهم من خلالها.
17- إخطار وترشيح ممثلي كل من وزارة المالية وإدارة الفتوى المختصة بمجلس الدولة ووزارة الاسكان للمشاركة في اللجان المختلفة وفقا لأحكام القانون وهذه اللائحة.
18- توجيه المهام أو إرسال المستندات لاتخاذ الاجراءات وفقا لدورة سير العمل، ويشمل ذلك المراجعات الادارية والمالية والقانونية.
19- تتبع الإجراءات وموقف التنفيذ.
20- إعداد وإدارة الاتفاقيات الإطارية، وتسجيل الجهات الإدارية من أجل استخدامها، وإصدار أوامر التوريد أو الاسناد.
21- إجراء الممارسات والمزايدات بأنواعها إلكترونيا.
22- تقديم الشكاوى ونشر نتائج دراستها.
23- إجراءات إخطار الترسية.
24- إعداد العقود، وتوقيعها الكترونيا متى توافرت خدمة التوقيع الإلكترونى.
25- إحصائيات التعاقدات ومنها على سبيل المثال ما تم التعاقد عليه مع المشروعات المتوسطة والصغيرة والمتناهية الصغر.
26- مهام إدارة وتنفيذ العقود، ويشمل ذلك تتبع عمليات الاستلام وتعديلات العقود واستخراج الفواتير والدفع الإلكترونى.
27- الاحتفاظ بالبيانات الإلكترونية وحفظ السجلات، وحفظ نظام معلومات إدارة التعاقدات الذي يسجل المعلومات عن كل مرحلة وكل خطوة في كل معاملات التعاقدات، ويشمل ذلك هوية الموظفين المعنيين ومتخذي القرار والموافقات، ونشر بيانات عن أنشطة التعاقدات في قاعدة بيانات التعاقدات التي يمكن البحث فيها بصورة تفاعلية، ويشمل ذلك البحث التفاعلي عن فرص التعاقدات المقبلة.
28- إعداد تقارير عن الخطوات والتوقيتات والنتائج لكل إجراء من إجراءات التعاقد، ويشمل ذلك معلومات عن مقدمي العطاءات المقبولين والمرفوضين والقرارات الصادرة في كل مرحلة وغيرها.
29- تجميع بيانات التعاقدات العامة بشكل يمكن من مراجعتها بصورة آلية بما في ذلك كل ما تم من إجراءات من خلال النظام والبيانات المدخلة التى تمت بهدف إنشاء السجلات، أو تعديلها، أو حذفها وقراءة المعلومات السرية، ويشمل ذلك الاعتمادات، وتحديد نوع وتوقيت كل إجراء ومتخذه.
وغير ذلك من مهام يتم إقرارها أثناء إعداد المنظومة، أو تتطلب حاجة العمل إضافتها اليها.$m260$,'9360daf5d63ef274f528e19aaeedf08e',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(169,0,1,$m260$تتولي الهيئة العامة للخدمات الحكومية توفير الدعم الفني والتدريب اللازم للعاملين بإدارات التعاقدات في الجهات الادارية، وكذلك التنسيق في هذا الشأن بالنسبة للمتعاملين والمتعاقدين، علي أن تصدر الهيئة دليل المستخدم الإرشادي وإتاحته لكافة مستخدمي المنظومة، وتكون خدمة التسجيل متاحة في أي وقت وبشكل مستمر، وفي حالة ما إذا لم يستوف طالب التسجيل بياناته ولم تستكمل إجراءات التسجيل يتم إخطاره لحظيا من خلال المنظومة بالأسباب ليتم استكمال ما نقص من بيانات، أو معلومات، أو مستندات.
وتتضمن المعلومات الواردة في الملف التعريفي الخاص بالمتعاملين بحد أدنى البيانات الآتية:
1- اسم المتعامل.
2- الرقم القومي لصاحب المنشأة، وغير ذلك من بيانات الهوية.
3- أسماء المفوضين للتعامل مع الجهات الادارية نيابة عنهم .
4- العنوان المسجل بالسجل التجاري والبطاقة الضريبية/ المدينة/ المحافظة/ الكود البريدي.
5- عنوان البريد الإلكتروني والتليفون الأرضي والمحمول للشخص المسئول/ المفوض.
6- رقم الفاكس.
7- عنوان الموقع الالكتروني الخاص بالمتعامل.
8- المكاتب الأخرى أو الفروع التابعة للمتعامل.
9- كود تصنيف المنتجات/الخدمات.
وغيرها من بيانات يتم تضمنها بدليل المستخدم الإرشادي.$m260$,'f173517f51f38416c8b6f6e9af1d0135',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(170,0,1,$m260$يتعين على كافة المستخدمين للمنظومة تحديث البيانات الخاصة بهم في ملفات التعريف الشخصية لكل منهم عند الاقتضاء، وإبلاغ الهيئة العامة للخدمات الحكومية بأى تغييرات في المعلومات أو البيانات التي على أساسها تم منحه حق التسجيل، وفي حالة ما إذا لم يستوف طالب تحديث البيانات متطلبات التحديث، يتم إخطاره لحظيا من خلال المنظومة بأسباب ذلك، ليقوم باستكمال ما نقص من بيانات أو معلومات أو مستندات.$m260$,'2efb63902e1b2174d5c3137a3c71ef83',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(171,0,1,$m260$يلتزم مستخدمي المنظومة بالحفاظ على سرية المعلومات اللازمة للدخول على المنظومة، ويكون كل منهم مسئولا عن الإجراءات التي يتخذها على المنظومة، وكذلك الإجراءات التي يتخذها الغير الذي استخدام المعلومات السرية الخاصة بالمستخدم بناء على تصريح منه، والتأكد من عدم إلحاق أي ضرر بها بسبب الاستخدام غير المصرح به لمعلومات الدخول على المنظومة.
ويجوز للهيئة العامة للخدمات الحكومية سحب تصاريح الدخول على المنظومة في الحالات التى يحددها دليل المستخدم الارشادي، ويتم سحب هذا التصريح بموجب إخطار كتابي يتم إرساله إلى المستخدم.
ويجوز في الظروف الطارئة أن تقوم المنظومة بوقف التصريح، بعد إرسال إخطار الكتروني إلى المستخدم على عنوان بريده الإلكتروني المثبت في ملف التعريف الشخصي له.$m260$,'c90a7eef4591edc3a7e9c2ec46e6a91c',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(172,0,1,$m260$لا يجوز للجهة الإدارية التعامل مع المسجلين لديها بسجلاتها أو غيرهم إلا بعد تسجيلهم لبياناتهم على بوابة التعاقدات العامة، أو تحديثها حال تعديلها، وأن تطابق الجهة الإدارية تلك البيانات واعتمادها من واقع قاعدة البيانات، على أن تتضمن بياناتهم رقم السجل التجاري، أو الصناعى، أو المهني، أو سجل مزاولة المهنة بحسب الأحوال، ورقم البطاقة الضريبية، أو أى بيانات أخرى ليتم من خلاله التعامل معهم، كما يتعين عليها أن تراعى الكتب الدورية الصادرة عن الهيئة العامة للخدمات الحكومية فيما يتعلق منها بالشطب، أو إعادة القيد.$m260$,'c2239cf32c40b24060922777f6deba9f',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(173,0,1,$m260$يجب على إدارة التعاقدات مراجعة الإدارات الطالبة، أو المستفيدة، أو إدارة المخازن، أو مسئول إدارة العقد بالجهة الإدارية أو من اختارته الجهة الإدارية للإشراف على تنفيذ العقد للتأكد من توثيقها لأداء المتعاقد أولا بأول، على أن يجرى تقييما نهائيا له قبل نهاية العام المالى، أو بعد انتهاء المتعاقد من تنفيذ العقد وفقا للنماذج والمعايير المحددة من الهيئة العامة للخدمات الحكومية بالتنسيق مع الوزارات والجهات المعنية وفقا لاختصاصاتها وطبيعة عملها والمتاحة على بوابة التعاقدات العامة.
ويجب على إدارة التعاقدات اخطار المتعاقدين بنتيجة تقييم أدائهم، بالإضافة إلى نشرها على بوابة التعاقدات العامة وإخطار الهيئة العامة للخدمات الحكومية به لإعمال شئونها، ويستثنى من النشر العمليات التى تتطلب اعتبارات الأمن القومى أن تتم بطريقة سرية وفقا لما تقدره السلطة المختصة.
ويتعين على إدارة التعاقدات إتاحة استقصاء مع المتعاقدين مع الجهة الإدارية بغرض إظهار الإيجابيات والوقوف على الإجراءات السلبية التى واجهتهم فى تعاملاتهم مع الإدارة الطالبة، أو المستفيدة، أو الإدارة المشرفة واتخاذ الإجراءات الواجبة لتحسين أداء العاملين وفقا للنموذج المعد من الهيئة العامة للخدمات الحكومية.$m260$,'9c11acbdcc715f784d88cc98d1988242',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(174,0,1,$m260$تلتزم الهيئة العامة للخدمات الحكومية بحصر وتحليل بيانات العقارات المملوكة للجهات الإدارية، وما تم التصرف فيه منها وأسلوب التصرف وقيمته والبيانات الكافية عن المتصرف إليهم وإعداد تقارير سنوية بشأنها وتقديمها إلى وزير المالية لعرضها على مجلس الوزراء.$m260$,'abe793f92c4795d70ff0769e2396db67',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(175,0,1,$m260$يتعين على الجهاز المركزي للتنظيم والادارة ولجان الموارد البشرية ولجان الاختيار بالجهات الادارية التأكد من اجتياز المتقدمين لشغل وظائف التعاقدات العامة أو الاستمرار فيها وبرامج التدريب اللازمة التى تعدها الهيئة العامة للخدمات الحكومية ويعتمدها وزير المالية ويتم موافاة الجهاز المركزى للتنظيم والإدارة بها.
وتكون مستويات البرامج التدريبية لشغل وظائف التعاقدات العامة أو الاستمرار فيها على النحو الآتى:
1- المستوي الأول: أساسيات التعاقدات العامة.
2- المستوي الثاني: استراتيجيات التعاقد.
3- المستوي الثالث: التعاقدات التخصصية.
ويتعين على إدارات التعاقد بالجهات الادارية قبل بداية السنة المالية بستة أشهر تحديد احتياجاتها التدريبية للمرشحين لشغل وظائف التعاقدات العامة، أو المطلوب استمرارهم فيها في ضوء مستويات البرامج التدريبية المشار اليها.
ويعتمد وزير المالية البرامج التدريبية السنوية ومراكز التدريب المؤهلة التي تقترحها الهيئة العامة للخدمات الحكومية وشروط التدريب وكافة الترتيبات التنظيمية ذات الصلة، على أن تقوم الهيئة فور اعتمادهم الاعلان عنهم على بوابة التعاقدات العامة وإخطار الجهات الادارية بهم.
وتتولى الهيئة العامة للخدمات الحكومية ومركز تدريبها ومراكز التدريب الأخرى المعتمدة تلقى طلبات التدريب من الجهات الادارية وفقا للإجراءات التي يتم تحديدها مسبقا بمعرفة الهيئة وموافاة الجهات بها، علي أن تقوم مراكز التدريب بالتنسيق مع الهيئة باتخاذ ما يلزم بشأن الترتيبات الادارية والتنظيمية لاستيفاء طلبات التدريب وإخطار الجهات بالتفاصيل.
وتلتزم كافة مراكز التدريب فى نهاية كل برنامج تدريبي بتقييم أداء المتدربين وتقديم تقرير للهيئة العامة للخدمات الحكومية بشأنه والتنسيق معها لإصدار الشهادات الدالة على استيفائهم التدريب اللازم لشغل وظائف التعاقدات العامة أو الاستمرار فيها، وكذا موافاة السلطة المختصة بكل جهة إدارية بنتائج تدريب من قام بترشيحهم.
تتولي الهيئة العامة للخدمات الحكومية إعداد تقارير دورية متضمنه توصياتها بشأن العملية التدريبية للعاملين بالتعاقدات بالجهات الادارية وعرضها على وزير المالية.$m260$,'fbef539de998aba75277b75aca8560d5',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(176,0,1,$m260$يتعين على كافة المتعاملين بالقانون وهذه اللائحة الالتزام بأحكامهما وغيرها من القوانين واللوائح والقرارات والتعليمات المنفذة لها، وما يصدر من قرارات تنظيمية، أو تعليمات، أو نشرات، أو كتب دورية في هذا الشأن، ومدونات السلوك الوظيفي للعاملين بالدولة والعاملين بالتعاقدات العامة، ويجازي تأديبيا كل من يخالفهم، ودون الإخلال بحق إقامة الدعوى المدنية أو الجنائية ضد المخالفين عند الاقتضاء.$m260$,'e57b3b963433ab07ef5a3e64bc3cc699',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(177,0,1,$m260$تلتزم الجهات الإدارية باستخدام أنماط العقود وكراسات الشروط النموذجية والأدلة الإرشادية وغيرها المنصوص عليها بالمادة (19) من القانون والتى قامت إدارة الفتوى المختصة بمجلس الدولة بمراجعتها واصدرتها الهيئة العامة للخدمات الحكومية، ولا يجوز الإضافة، أو الحذف، أو التعديل فى أى من الاشتراطات العامة الواردة فى انماط العقود وكراسات الشروط النموذجية إلا بعد الرجوع لإدارة الفتوى المذكورة لمراجعتها.$m260$,'fbeb960cfc6e8626e789ba10b8f16bff',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(178,0,1,$m260$مع عدم الإخلال بأحكام المادة (51) من القانون على طرفى العقد بذل أقصى جهد للالتزام ببنود التعاقد طوال مدة تنفيذه طبقا لما اشتمل عليه وبطريقة تتفق ما يوجبه حسن النية.
وبمراعاة أحكام المادة (91) من القانون، يجوز أن تتضمن شروط الطرح والعقد مراحل وآليات تسوية الخلافات والمنازعات بين طرفيه، وفى هذه الحالة يتعين على الجهة الإدارية قبل مباشرة إجراءات فسخ العقد مع المتعاقد اتخاذ الإجراءات الآتية:
1- فحص شروط التعاقد بكل دقة واتخاذ الحل المناسب للمشكلة.
2- قيام إدارة التعاقدات اعداد تصور عن موضوع الخلاف وتقديم رأى فنى ومالي وقانوني للسلطة المختصة، ويجوز لها الاستعانة باستشاري متخصص للمساعدة فى دراسة الخلاف وتقديم الرأي.
3- تسوية الخلافات التى نشأت بالطرق الودية بما لا يخل بحقوق والتزامات طرفى العقد، وإذا ترتب على التسوية الودية أى أعباء مالية فيجب الاتفاق عليها وعرضها على السلطة المختصة للموافقة عليها بعد تقديم كافة المستندات والبيانات والمبررات لتسوية الخلاف.
4- يتم توجيه الدعوة للمتعاقد لعقد اجتماع مع مسئول إدارة العقد أو ممثل الجهة الإدارية بحسب الأحوال خلال مدة خمسة عشر يوما من تاريخ ظهور الخلاف وذلك لمناقشته.
5- إذا لم يتم التوصل إلى اتفاق يتم اللجوء إلى القضاء أو التحكيم بحسب ما تنص عليه شروط التعاقد.$m260$,'30a4ddd19cd500987322e8eb01d10128',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$),
(179,0,1,$m260$تلتزم الهيئة العامة للخدمات الحكومية بتسجيل من يتم اخطارهم بصدور أحكام نهائية فى إحدى الجرائم المنصوص عليها فى الباب الرابع من الكتاب الثانى من قانون العقوبات، أو فى جرائم التهرب الضريبي، أو الجمركي فى سجل قيد أسماء الممنوعين من التعامل معهم، بالإضافة إلى نشر بياناتهم على بوابة التعاقدات العامة.$m260$,'02cd79995bd47d29c3a51e74873c2391',DATE '2019-11-01',NULL,'active',NULL,NULL,$m260$نص اللائحة كما ورد فى نسخة PDF مؤرخة 9/10/2019 (إنتاج Word) بالصيغة المعروضة بعد تعقيب قسم التشريع بمجلس الدولة، وليس نص الوقائع المصرية (العدد 244 تابع (ب) فى 31/10/2019) الذى يلزم مطابقته قبل الاستناد إليه. لا تعديلات لاحقة مطبقة. التواريخ تقريبية.$m260$);

DO $m260$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m260_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m260_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[260] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m260_art) <> 180 OR (SELECT sum(char_length(body)) FROM m260_art) <> 178376 OR (SELECT count(*) FROM m260_ver) <> 180 THEN
    RAISE EXCEPTION '[260] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=692 AND law_year=2019 AND kind='regulation';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%التعاقدات%' THEN
    RAISE EXCEPTION '[260] يوجد مستند آخر برقم 692 لسنة 2019 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (692, 2019, $t260$قرار وزير المالية رقم 692 لسنة 2019 بإصدار اللائحة التنفيذية لقانون تنظيم التعاقدات التى تبرمها الجهات العامة الصادر بالقانون رقم 182 لسنة 2018 (نص نسخة 9/10/2019 بعد تعقيب قسم التشريع بمجلس الدولة؛ ليس نص الوقائع المصرية)$t260$, $t260$اللائحة التنفيذية لقانون التعاقدات العامة 692/2019$t260$, 'other', 'in_force', NULL, DATE '2019-10-31', NULL, 'EG', 'regulation', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m260_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m260_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m260_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 180 THEN
    RAISE EXCEPTION '[260] عدد صفوف النص % بدل 180', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 180 THEN
    RAISE EXCEPTION '[260] عدد نسخ النص % بدل 180', v_vcnt;
  END IF;
  RAISE NOTICE '[260] لائحة 692/2019: جديد=%, صفوف مضافة=%, نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m260$;
